object ListenData001 { val text = ListeningText(id = "de-listen-cafe-morning", languageID = "de", title = "Ein Kaffee vor der Arbeit", level = "A1", topic = "Alltag", unitID = "de-foundations-u1", text = "Jeden Morgen geht Marta zu einem kleinen Café in der Nähe ihrer Wohnung. Der Kellner kennt ihren Namen, deshalb muss sie nie bestellen. Heute sitzt sie am Fenster mit einem Kaffee und einem Croissant. Ihr Bus fährt um halb neun ab, aber sie macht sich keine Sorgen. Das Café ist zu dieser Stunde sehr ruhig. Sie trinkt ihren Kaffee langsam und sieht zu, wie die Stadt aufwacht.", questions = listOf(Exercise(id = "de-listen-cafe-morning-q1", kind = "choice", prompt = "Wohin geht Marta jeden Morgen?", options = listOf("In ein kleines Café", "In ihr Büro", "Zum Busbahnhof", "In einen Park"), answers = listOf("In ein kleines Café"), explain = "Sie geht zu einem kleinen Café in der Nähe ihrer Wohnung."), Exercise(id = "de-listen-cafe-morning-q2", kind = "choice", prompt = "Was frühstückt sie heute?", options = listOf("Einen Kaffee und ein Croissant", "Tee und Toast", "Orangensaft", "Nichts"), answers = listOf("Einen Kaffee und ein Croissant"), explain = "Sie sitzt am Fenster mit einem Kaffee und einem Croissant."), Exercise(id = "de-listen-cafe-morning-q3", kind = "written", prompt = "Wann fährt ihr Bus ab?", options = listOf(), answers = listOf("um halb neun", "halb neun"), explain = "Ihr Bus fährt um halb neun ab."), Exercise(id = "de-listen-cafe-morning-q4", kind = "choice", prompt = "Wie fühlt sie sich wegen der Zeit?", options = listOf("Sie macht sich keine Sorgen", "Sie ist sehr spät dran", "Sie ist wütend", "Sie ist müde"), answers = listOf("Sie macht sich keine Sorgen"), explain = "Im Text steht: sie macht sich keine Sorgen."), Exercise(id = "de-listen-cafe-morning-q5", kind = "choice", prompt = "Wer kennt ihren Namen?", options = listOf("Der Kellner", "Der Busfahrer", "Ihr Chef", "Ein Nachbar"), answers = listOf("Der Kellner"), explain = "Der Kellner kennt ihren Namen, deshalb muss sie nie bestellen."), Exercise(id = "de-listen-cafe-morning-q6", kind = "written", prompt = "Wo sitzt sie heute?", options = listOf(), answers = listOf("am fenster", "neben dem fenster", "ans fenster"), explain = "Heute sitzt sie am Fenster.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")) }

object ListenData002 { val text = ListeningText(id = "de-listen-language-class", languageID = "de", title = "Der Sprachkurs", level = "A1", topic = "Vorstellungen", unitID = "de-foundations-u1", text = "Marta besucht ihren ersten Portugiesischkurs in einem kleinen Institut. Im Kurs sind sechs Personen, und alle möchten sprechen. Die Lehrerin bittet um Vorstellungen. „Ich heiße Marta und ich bin aus Bolivien“, sagt eine Dame. „Ich bin Andrés, ich komme aus Peru und arbeite in einem Restaurant“, sagt ein junger Mann. Marta stellt sich auch vor: „Ich bin Marta, ich bin Argentinierin und ich bin Krankenschwester.“ Die Lehrerin ist aus Madrid und unterrichtet mit viel Humor. Am Ende des Kurses tauschen die Teilnehmer ihre Telefonnummern aus. Sie sind noch keine Freunde, aber nächste Woche gehen sie zusammen einen Kaffee trinken und üben.", questions = listOf(Exercise(id = "de-listen-language-class-q1", kind = "choice", prompt = "Wie viele Personen sind im Kurs?", options = listOf("Sechs", "Drei", "Zehn", "Vierzehn"), answers = listOf("Sechs"), explain = "Im Kurs sind sechs Personen."), Exercise(id = "de-listen-language-class-q2", kind = "choice", prompt = "Woher kommt Andrés?", options = listOf("Aus Peru", "Aus Bolivien", "Aus Argentinien", "Aus Mexiko"), answers = listOf("Aus Peru"), explain = "Andrés kommt aus Peru und arbeitet in einem Restaurant."), Exercise(id = "de-listen-language-class-q3", kind = "choice", prompt = "Was ist Marta von Beruf?", options = listOf("Krankenschwester", "Lehrerin", "Kellnerin", "Studentin"), answers = listOf("Krankenschwester"), explain = "Marta ist Argentinierin und sie ist Krankenschwester."), Exercise(id = "de-listen-language-class-q4", kind = "written", prompt = "Woher ist die Lehrerin?", options = listOf(), answers = listOf("madrid", "aus madrid", "sie ist aus madrid"), explain = "Die Lehrerin ist aus Madrid."), Exercise(id = "de-listen-language-class-q5", kind = "choice", prompt = "Was machen sie am Ende des Kurses?", options = listOf("Sie tauschen ihre Telefonnummern aus", "Sie gehen allein nach Hause", "Sie schreiben einen Test", "Sie essen im Restaurant"), answers = listOf("Sie tauschen ihre Telefonnummern aus"), explain = "Die Teilnehmer tauschen ihre Telefonnummern aus."), Exercise(id = "de-listen-language-class-q6", kind = "written", prompt = "Was machen sie nächste Woche?", options = listOf(), answers = listOf("kaffee trinken", "zusammen einen kaffee trinken", "einen kaffee trinken"), explain = "Nächste Woche gehen sie zusammen einen Kaffee trinken und üben.")), skills = listOf("listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself")) }

object ListenData003 { val text = ListeningText(id = "de-listen-little-sister", languageID = "de", title = "Meine kleine Schwester", level = "A1", topic = "Familie", unitID = "de-foundations-u1", text = "Meine kleine Schwester heißt Carla und ist neun Jahre alt. Sie ist sehr nett und sehr gesprächig. Carla ist nicht schüchtern: Sie spricht mit allen, mit den Nachbarn, mit den Lehrern und mit den Hunden im Park. Sie ist blond, wie unsere Mutter, und hat braune Augen wie unser Vater. Sie ist nicht groß für ihr Alter, aber sie ist sehr schnell und spielt riesig gern Fußball. Ihre Mannschaft ist nicht sehr gut, aber das ist ihr egal. „Ich bin keine Profispielerin“, sagt sie, „ich bin nur glücklich mit dem Ball.“ Meine Schwester ist klein, aber ihre Freude ist riesig.", questions = listOf(Exercise(id = "de-listen-little-sister-q1", kind = "choice", prompt = "Wie alt ist Carla?", options = listOf("Neun", "Neunzehn", "Sieben", "Zehn"), answers = listOf("Neun"), explain = "Carla ist neun Jahre alt."), Exercise(id = "de-listen-little-sister-q2", kind = "choice", prompt = "Wie ist Carla?", options = listOf("Nett und gesprächig", "Schüchtern und still", "Ernst", "Traurig"), answers = listOf("Nett und gesprächig"), explain = "Sie ist sehr nett und sehr gesprächig."), Exercise(id = "de-listen-little-sister-q3", kind = "written", prompt = "Welche Augenfarbe hat sie?", options = listOf(), answers = listOf("braun", "braune augen"), explain = "Sie hat braune Augen wie ihr Vater."), Exercise(id = "de-listen-little-sister-q4", kind = "choice", prompt = "Welche Haare hat sie?", options = listOf("Blond, wie ihre Mutter", "Dunkel, wie ihr Vater", "Rot", "Kurz und schwarz"), answers = listOf("Blond, wie ihre Mutter"), explain = "Sie ist blond, wie unsere Mutter."), Exercise(id = "de-listen-little-sister-q5", kind = "choice", prompt = "Was spielt sie riesig gern?", options = listOf("Fußball", "Schwimmen", "Musik", "Videospiele"), answers = listOf("Fußball"), explain = "Sie ist sehr schnell und spielt riesig gern Fußball."), Exercise(id = "de-listen-little-sister-q6", kind = "written", prompt = "Wie ist ihre Freude?", options = listOf(), answers = listOf("riesig", "sehr groß", "groß"), explain = "Ihre Freude ist riesig.")), skills = listOf("listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family")) }

object ListenData004 { val text = ListeningText(id = "de-listen-new-flatmate", languageID = "de", title = "Ein neuer Mitbewohner", level = "A1", topic = "Wohnung", unitID = "de-foundations-u1", text = "Tom hat einen neuen Mitbewohner. Er heißt Leo und ist dreiundzwanzig Jahre alt. Leo kommt aus einem kleinen Dorf im Norden, arbeitet aber jetzt in der Stadt. Er hat zwei Kartons, eine Gitarre und ein Fahrrad. Die Wohnung hat zwei Zimmer und eine helle Küche. Tom hofft, dass Leo gern kocht, denn Tom kocht überhaupt nicht gern.", questions = listOf(Exercise(id = "de-listen-new-flatmate-q1", kind = "choice", prompt = "Wie alt ist Leo?", options = listOf("Dreiundzwanzig", "Zweiunddreißig", "Zwanzig", "Dreißig"), answers = listOf("Dreiundzwanzig"), explain = "Leo ist dreiundzwanzig Jahre alt."), Exercise(id = "de-listen-new-flatmate-q2", kind = "choice", prompt = "Was hat Leo NICHT?", options = listOf("Einen Fernseher", "Zwei Kartons", "Eine Gitarre", "Ein Fahrrad"), answers = listOf("Einen Fernseher"), explain = "Er hat zwei Kartons, eine Gitarre und ein Fahrrad — keinen Fernseher."), Exercise(id = "de-listen-new-flatmate-q3", kind = "written", prompt = "Was macht Tom ungern?", options = listOf(), answers = listOf("kochen", "er kocht nicht gern", "tom kocht nicht gern"), explain = "Tom kocht überhaupt nicht gern."), Exercise(id = "de-listen-new-flatmate-q4", kind = "choice", prompt = "Wie ist die Wohnung?", options = listOf("Zwei Zimmer und eine helle Küche", "Ein Zimmer und ein Balkon", "Ein Garten", "Zwei Badezimmer"), answers = listOf("Zwei Zimmer und eine helle Küche"), explain = "Die Wohnung hat zwei Zimmer und eine helle Küche."), Exercise(id = "de-listen-new-flatmate-q5", kind = "choice", prompt = "Wo arbeitet Leo jetzt?", options = listOf("In der Stadt", "In einem kleinen Dorf", "Im Norden", "Er arbeitet nicht"), answers = listOf("In der Stadt"), explain = "Er kommt aus einem kleinen Dorf, arbeitet aber jetzt in der Stadt."), Exercise(id = "de-listen-new-flatmate-q6", kind = "written", prompt = "Welches Instrument hat Leo?", options = listOf(), answers = listOf("eine gitarre", "gitarre"), explain = "Leo hat eine Gitarre.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")) }

object ListenData005 { val text = ListeningText(id = "de-listen-new-neighbour", languageID = "de", title = "Die neue Nachbarin", level = "A1", topic = "Leute", unitID = "de-foundations-u1", text = "Im Haus gibt es eine neue Nachbarin. Sie heißt Amélie und kommt aus Frankreich. Sie ist keine Studentin; sie ist Fotografin. Sie arbeitet nicht in einem Büro: Sie arbeitet von zu Hause und reist viel. Die Nachbarn sind neugierig, aber sie sind auch schüchtern, deshalb sprechen sie nicht mit ihr. Dann trifft Ben sie eines Morgens an der Tür. „Bist du die neue Nachbarin?“, fragt er. „Ja, das bin ich“, antwortet sie, „und ich bin froh, hier zu sein.“ Jetzt sind sie Freunde, und sie ist nicht mehr allein im Haus.", questions = listOf(Exercise(id = "de-listen-new-neighbour-q1", kind = "choice", prompt = "Woher kommt Amélie?", options = listOf("Aus Frankreich", "Aus Italien", "Aus Japan", "Aus Brasilien"), answers = listOf("Aus Frankreich"), explain = "Amélie kommt aus Frankreich."), Exercise(id = "de-listen-new-neighbour-q2", kind = "choice", prompt = "Was ist ihr Beruf?", options = listOf("Fotografin", "Studentin", "Büroangestellte", "Lehrerin"), answers = listOf("Fotografin"), explain = "Sie ist keine Studentin; sie ist Fotografin."), Exercise(id = "de-listen-new-neighbour-q3", kind = "choice", prompt = "Arbeitet sie in einem Büro?", options = listOf("Nein, sie arbeitet von zu Hause", "Ja, jeden Tag", "Nur im Sommer", "Das sagt sie nicht"), answers = listOf("Nein, sie arbeitet von zu Hause"), explain = "Sie arbeitet nicht in einem Büro: Sie arbeitet von zu Hause."), Exercise(id = "de-listen-new-neighbour-q4", kind = "written", prompt = "Warum sprechen die Nachbarn nicht mit ihr?", options = listOf(), answers = listOf("sie sind schüchtern", "weil sie schüchtern sind", "schüchtern"), explain = "Sie sind neugierig, aber sie sind auch schüchtern."), Exercise(id = "de-listen-new-neighbour-q5", kind = "choice", prompt = "Wo trifft Ben sie?", options = listOf("An der Tür", "Im Aufzug", "Auf der Straße", "Im Café"), answers = listOf("An der Tür"), explain = "Eines Morgens trifft Ben sie an der Tür."), Exercise(id = "de-listen-new-neighbour-q6", kind = "written", prompt = "Wie fühlt sich Amélie am Ende?", options = listOf(), answers = listOf("froh", "glücklich", "sie ist froh"), explain = "Sie sagt, sie ist froh, hier zu sein.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")) }

object ListenData006 { val text = ListeningText(id = "de-listen-sunday-market", languageID = "de", title = "Der Sonntagsmarkt", level = "A1", topic = "Einkaufen", unitID = "de-foundations-u1", text = "Sonntags gibt es einen Markt auf dem Dorfplatz. Anna und ihr Vater gehen um neun Uhr dorthin, bevor er voll wird. Sie kaufen Obst, Brot und Blumen. Anna möchte Erdbeeren, aber ihr Vater sagt, sie sind diese Woche zu teuer. Am Ende nehmen sie eine große Tüte Orangen und weiße Rosen für den Küchentisch mit nach Hause.", questions = listOf(Exercise(id = "de-listen-sunday-market-q1", kind = "choice", prompt = "Wann gehen Anna und ihr Vater zum Markt?", options = listOf("Um neun Uhr", "Um zwölf Uhr", "Am Nachmittag", "Um halb sieben"), answers = listOf("Um neun Uhr"), explain = "Sie gehen um neun Uhr, bevor er voll wird."), Exercise(id = "de-listen-sunday-market-q2", kind = "written", prompt = "Warum bekommt Anna keine Erdbeeren?", options = listOf(), answers = listOf("sie sind zu teuer", "zu teuer", "weil sie zu teuer sind"), explain = "Ihr Vater sagt, sie sind diese Woche zu teuer."), Exercise(id = "de-listen-sunday-market-q3", kind = "choice", prompt = "Was nehmen sie mit nach Hause?", options = listOf("Orangen und Rosen", "Erdbeeren und Brot", "Äpfel und Tulpen", "Brot und Käse"), answers = listOf("Orangen und Rosen"), explain = "Sie nehmen Orangen und weiße Rosen mit."), Exercise(id = "de-listen-sunday-market-q4", kind = "choice", prompt = "Wo ist der Markt?", options = listOf("Auf dem Dorfplatz", "Am Fluss", "Am Bahnhof", "In einem Supermarkt"), answers = listOf("Auf dem Dorfplatz"), explain = "Sonntags gibt es einen Markt auf dem Dorfplatz."), Exercise(id = "de-listen-sunday-market-q5", kind = "choice", prompt = "Was kaufen sie?", options = listOf("Obst, Brot und Blumen", "Fisch und Gemüse", "Käse und Fleisch", "Nur Blumen"), answers = listOf("Obst, Brot und Blumen"), explain = "Sie kaufen Obst, Brot und Blumen."), Exercise(id = "de-listen-sunday-market-q6", kind = "written", prompt = "Was möchte Anna?", options = listOf(), answers = listOf("erdbeeren", "sie möchte erdbeeren"), explain = "Anna möchte Erdbeeren.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")) }

object ListenData007 { val text = ListeningText(id = "de-listen-wohnung-gewaehlt", languageID = "de", title = "Die gewählte Wohnung", level = "A2", topic = "wohnungen", unitID = "de-foundations-u4", text = "Anna und Ben suchen eine Wohnung. Die erste ist billiger, aber sie liegt weiter vom Bahnhof: vierzig Minuten zu Fuß. Die zweite kostet hundert Euro mehr im Monat, aber sie ist heller und hat einen Balkon. Für Anna ist das Licht am wichtigsten, weil sie von zu Hause arbeitet. Am Ende bitten sie um eine Besichtigung der zweiten: sie ist teurer, aber für sie die beste von beiden.", questions = listOf(Exercise(id = "de-listen-wohnung-gewaehlt-q1", kind = "choice", prompt = "Wie viele Wohnungen vergleichen sie ?", options = listOf("Zwei", "Drei", "Vier"), answers = listOf("Zwei"), explain = "Sie vergleichen zwei Wohnungen."), Exercise(id = "de-listen-wohnung-gewaehlt-q2", kind = "choice", prompt = "Was ist das Problem der billigeren ?", options = listOf("Sie liegt weit vom Bahnhof", "Sie hat keinen Balkon", "Sie ist sehr teuer", "Sie ist klein"), answers = listOf("Sie liegt weit vom Bahnhof"), explain = "Vierzig Minuten zu Fuß."), Exercise(id = "de-listen-wohnung-gewaehlt-q3", kind = "written", prompt = "Wie viel kostet die zweite mehr pro Monat ?", options = listOf(), answers = listOf("hundert euro", "100 euro"), explain = "Hundert Euro mehr im Monat."), Exercise(id = "de-listen-wohnung-gewaehlt-q4", kind = "choice", prompt = "Was ist für Anna am wichtigsten ?", options = listOf("Das Licht", "Der Preis", "Der Balkon", "Die Küche"), answers = listOf("Das Licht"), explain = "Sie arbeitet von zu Hause."), Exercise(id = "de-listen-wohnung-gewaehlt-q5", kind = "choice", prompt = "Was beschließen sie am Ende ?", options = listOf("Eine Besichtigung der zweiten", "Bei der ersten bleiben", "Weiter suchen", "Rabatt fragen"), answers = listOf("Eine Besichtigung der zweiten"), explain = "Die beste von beiden für sie.")), skills = listOf("listening:gist", "listening:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")) }

object ListenData008 { val text = ListeningText(id = "de-listen-samstag-geplant", languageID = "de", title = "Der geplante Samstag", level = "A2", topic = "pläne", unitID = "de-foundations-u4", text = "Mia ruft ihren Bruder an, um den Samstag zu planen. Er schlägt den Berg vor, aber es wird regnen, deshalb schlägt Mia das neue Museum vor. Sie treffen sich um zehn Uhr am Haupteingang und essen im Markt nebenan, der billiger ist als die Restaurants im Zentrum. Am Abend haben sie keinen Plan: sie entscheiden vor Ort, wenn sie das Wetter kennen.", questions = listOf(Exercise(id = "de-listen-samstag-geplant-q1", kind = "choice", prompt = "Wer schlägt den Berg vor ?", options = listOf("Der Bruder", "Mia", "Die Mutter", "Ein Freund"), answers = listOf("Der Bruder"), explain = "Ihr Bruder schlägt den Berg vor."), Exercise(id = "de-listen-samstag-geplant-q2", kind = "choice", prompt = "Warum nicht der Berg ?", options = listOf("Es wird regnen", "Sie sind müde", "Das Museum ist gratis", "Der Berg ist weit"), answers = listOf("Es wird regnen"), explain = "Es wird regnen, deshalb Museum."), Exercise(id = "de-listen-samstag-geplant-q3", kind = "written", prompt = "Um wie viel Uhr treffen sie sich ?", options = listOf(), answers = listOf("um zehn uhr", "zehn uhr"), explain = "Um zehn Uhr am Haupteingang."), Exercise(id = "de-listen-samstag-geplant-q4", kind = "choice", prompt = "Wo essen sie ?", options = listOf("Im Markt nebenan", "In einem Restaurant im Zentrum", "Zu Hause", "Im Museum"), answers = listOf("Im Markt nebenan"), explain = "Billiger als die Restaurants im Zentrum."), Exercise(id = "de-listen-samstag-geplant-q5", kind = "choice", prompt = "Was machen sie am Abend ?", options = listOf("Vor Ort entscheiden", "Ins Kino gehen", "Früh heimgehen", "Freunde treffen"), answers = listOf("Vor Ort entscheiden"), explain = "Je nach Wetter.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("grammar:future-forms")) }

object ListenData009 { val text = ListeningText(id = "de-listen-nie-gemacht", languageID = "de", title = "Was ich nie gemacht habe", level = "B1", topic = "reisen", unitID = "de-foundations-u6", text = "In der Küche einer Herberge vergleichen drei Reisende ihr Leben. Jonas ist in zwanzig Ländern gewesen, aber er hat nie schwimmen gelernt: « Ich weiß, es ist lächerlich ». Amira ist schon zweimal mit Schildkröten getaucht, aber sie hat Afrika vor dieser Reise nie verlassen. Und Coco, die seit sechs Jahren unterwegs ist, ist noch nie geflogen: sie überquert die Ozeane mit dem Schiff und die Grenzen mit dem Bus. « Nie ? » fragt Jonas. « Nie. Die Angst ist älter als ich. » Sie lachen über die Dinge, die sie nicht gemacht haben, und Coco sagt einen Satz, der bleibt: « Man muss nicht alles gemacht haben. Man muss nur noch wollen ».", questions = listOf(Exercise(id = "de-listen-nie-gemacht-q1", kind = "choice", prompt = "Was hat Jonas nie gemacht ?", options = listOf("Schwimmen lernen", "Zwanzig Länder besuchen", "Mit dem Schiff fahren", "Afrika verlassen"), answers = listOf("Schwimmen lernen"), explain = "Er ist in zwanzig Ländern gewesen, aber nie schwimmen gelernt."), Exercise(id = "de-listen-nie-gemacht-q2", kind = "written", prompt = "Wie oft ist Amira getaucht ?", options = listOf(), answers = listOf("zweimal", "2 mal", "zwei mal"), explain = "Amira ist schon zweimal mit Schildkröten getaucht."), Exercise(id = "de-listen-nie-gemacht-q3", kind = "choice", prompt = "Wie überquert Coco die Ozeane ?", options = listOf("Mit dem Schiff", "Mit dem Flugzeug", "Mit dem Bus", "Zu Fuß"), answers = listOf("Mit dem Schiff"), explain = "Sie überquert die Ozeane mit dem Schiff."), Exercise(id = "de-listen-nie-gemacht-q4", kind = "choice", prompt = "Was sagt Coco über die Angst ?", options = listOf("Sie ist älter als sie", "Sie ist jünger", "Es ist lächerlich", "Sie ist weg"), answers = listOf("Sie ist älter als sie"), explain = "Die Angst ist älter als ich."), Exercise(id = "de-listen-nie-gemacht-q5", kind = "written", prompt = "Was reicht, laut Coco ?", options = listOf(), answers = listOf("noch wollen", "man muss noch wollen"), explain = "Man muss nur noch wollen.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")) }

object ListenData010 { val text = ListeningText(id = "de-listen-stadt-dorf", languageID = "de", title = "Von der Stadt ins Dorf", level = "B1", topic = "veränderungen", unitID = "de-foundations-u6", text = "Lukas erzählt, warum er Berlin verlassen hat. Früher hat er in einer kleinen Wohnung gewohnt und elf Stunden am Tag gearbeitet: « Ich habe gut verdient, aber kein Leben gehabt ». Einen Winter wurde er krank, und da hat er verstanden: so konnte es nicht weitergehen. Heute wohnt er in einem Dorf mit tausend Einwohnern, arbeitet morgens von zu Hause und gartelt nachmittags. « Ich verdiene weniger, aber ich habe Zeit. » Am Anfang haben seine Eltern es nicht verstanden; heute kommen sie jeden Monat. « Bereust du etwas ? » fragt seine Freundin. « Dass ich es nicht früher gemacht habe ».", questions = listOf(Exercise(id = "de-listen-stadt-dorf-q1", kind = "choice", prompt = "Wo hat Lukas früher gewohnt ?", options = listOf("In Berlin", "In einem Dorf", "In Hamburg", "In einer Herberge"), answers = listOf("In Berlin"), explain = "Lukas erzählt, warum er Berlin verlassen hat."), Exercise(id = "de-listen-stadt-dorf-q2", kind = "written", prompt = "Wie viele Stunden hat er am Tag gearbeitet ?", options = listOf(), answers = listOf("elf stunden", "11 stunden", "elf"), explain = "Elf Stunden am Tag."), Exercise(id = "de-listen-stadt-dorf-q3", kind = "choice", prompt = "Was hat ihn verändert ?", options = listOf("Er wurde krank", "Er verlor seinen Job", "Er gewann im Lotto", "Er traf jemanden"), answers = listOf("Er wurde krank"), explain = "Einen Winter wurde er krank, und da hat er verstanden."), Exercise(id = "de-listen-stadt-dorf-q4", kind = "choice", prompt = "Was macht er nachmittags ?", options = listOf("Er gartelt", "Er arbeitet mehr Stunden", "Er reist jeden Monat", "Er lernt"), answers = listOf("Er gartelt"), explain = "Er arbeitet morgens und gartelt nachmittags."), Exercise(id = "de-listen-stadt-dorf-q5", kind = "written", prompt = "Was bereut Lukas ?", options = listOf(), answers = listOf("dass ich es nicht frueher gemacht habe", "dass ich es nicht früher gemacht habe", "nicht frueher", "nicht früher"), explain = "« Dass ich es nicht früher gemacht habe ».")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions")) }

object ListenData011 { val text = ListeningText(id = "de-listen-handel-tisch", languageID = "de", title = "Das Feilschen um den Tisch", level = "B2", topic = "verhandeln", unitID = "de-foundations-u7", text = "Auf einer Gebraucht-App will Lena einen Holztisch für 80 Euro. « Wären Sie bei 60 dabei ? », fragt sie. Der Verkäufer lehnt ab: « Nur wenn Sie ihn heute abholen ». Lena überlegt: « Ich würde 65 geben, wenn Sie den Stuhl dazugeben ». « Unmöglich », lacht er, « aber ich würde Ihnen den Tisch für 70 lassen und ihn Ihnen hochtragen ». Lena zögert nicht: « Würden Sie ihn allein hochtragen ? ». « Ich habe einen Handwagen », antwortet er. « Abgemacht », sagt sie, und fügt hinzu: « Wenn er so schön ist wie auf dem Foto, gibt es fünf Sterne ».", questions = listOf(Exercise(id = "de-listen-handel-tisch-q1", kind = "choice", prompt = "Wie viel verlangt der Verkäufer ?", options = listOf("80 Euro", "60 Euro", "70 Euro", "65 Euro"), answers = listOf("80 Euro"), explain = "Der Tisch kostet 80 Euro."), Exercise(id = "de-listen-handel-tisch-q2", kind = "written", prompt = "Was schlägt Lena zuerst vor ?", options = listOf(), answers = listOf("60 euro", "bei 60 dabei", "sechzig euro"), explain = "« Wären Sie bei 60 dabei ? »."), Exercise(id = "de-listen-handel-tisch-q3", kind = "choice", prompt = "Welche Bedingung stellt der Verkäufer ?", options = listOf("Heute abholen", "Bar bezahlen", "Fünf Sterne geben", "Morgen kommen"), answers = listOf("Heute abholen"), explain = "« Nur wenn Sie ihn heute abholen »."), Exercise(id = "de-listen-handel-tisch-q4", kind = "choice", prompt = "Was bietet der Verkäufer für 70 ?", options = listOf("Den Tisch hochtragen", "Den Stuhl dazugeben", "Auf 60 sinken", "Einen Handwagen leihen"), answers = listOf("Den Tisch hochtragen"), explain = "« Ich würde ihn Ihnen hochtragen »."), Exercise(id = "de-listen-handel-tisch-q5", kind = "written", prompt = "Was verspricht Lena, wenn der Tisch gefällt ?", options = listOf(), answers = listOf("funf sterne", "fünf sterne", "5 sterne"), explain = "Fünf Sterne.")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors")) }

object ListenData012 { val text = ListeningText(id = "de-listen-nachricht-viertel", languageID = "de", title = "Die Nachricht im Viertel", level = "B2", topic = "nachrichten", unitID = "de-foundations-u8", text = "Am Markt besprechen Hannah und Tom, was man sagt. « Man sagt, sie machen die Hauptstraße autofrei », erzählt Hannah. « Schon wieder ? », lacht Tom. « Die Nachricht, die ich gelesen habe, sagt, dass es im Frühling beginnt ». Laut Rathaus wäre es nur am Samstag, aber die Händler, deren Umsatz vom Tourismus abhinge, haben schon demonstriert. « Es stimmt, dass der Lärm sinken würde », räumt Tom ein, « aber, und die Parkplätze ? ». Hannah verteidigt die Maßnahme: « Einerseits würden mehr Leute laufen; andererseits hielten die Busse direkt vor der Tür ». Sie entscheiden es nicht, aber versprechen, wieder darüber zu sprechen, wenn der Plan veröffentlicht wird.", questions = listOf(Exercise(id = "de-listen-nachricht-viertel-q1", kind = "choice", prompt = "Was sagt man über die Hauptstraße ?", options = listOf("Dass sie autofrei wird", "Dass sie breiter wird", "Dass sie geschlossen wird", "Dass sie umbenannt wird"), answers = listOf("Dass sie autofrei wird"), explain = "« Man sagt, sie machen die Hauptstraße autofrei »."), Exercise(id = "de-listen-nachricht-viertel-q2", kind = "written", prompt = "Wann würde es beginnen ?", options = listOf(), answers = listOf("im fruhling", "im frühling", "frühling"), explain = "« …dass es im Frühling beginnt »."), Exercise(id = "de-listen-nachricht-viertel-q3", kind = "choice", prompt = "Was sagt das Rathaus ?", options = listOf("Nur am Samstag", "An allen Tagen", "Nur im Sommer", "An Feiertagen"), answers = listOf("Nur am Samstag"), explain = "Laut Rathaus wäre es nur am Samstag."), Exercise(id = "de-listen-nachricht-viertel-q4", kind = "choice", prompt = "Wer hat demonstriert ?", options = listOf("Die Händler", "Die Anwohner", "Die Taxifahrer", "Das Rathaus"), answers = listOf("Die Händler"), explain = "Die Händler haben schon demonstriert."), Exercise(id = "de-listen-nachricht-viertel-q5", kind = "written", prompt = "Was versprechen Hannah und Tom ?", options = listOf(), answers = listOf("daruber zu sprechen", "darüber zu sprechen", "wieder daruber sprechen"), explain = "Sie versprechen, wieder darüber zu sprechen.")), skills = listOf("listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors")) }

object ListenData013 { val text = ListeningText(id = "de-listen-radio-debatte", languageID = "de", title = "Radio-Debatte: Vier Tage", level = "C1", topic = "arbeit", unitID = "de-foundations-u9", text = "Im Studio diskutiert die Moderatorin Karin Brandt mit dem Unternehmer Sven Ostermann über die Vier-Tage-Woche. « Zunächst eine Zahl », beginnt Brandt, « in der Pilotfirma stieg die Zufriedenheit um zwanzig Prozent ». Ostermann bleibt skeptisch: « Zwar arbeiten alle konzentrierter, aber vier Tage reichen selten, um Projekte ordentlich abzuschließen ». Brandt widerspricht: « Genau deshalb braucht es Struktur, sozusagen weniger Meetings, mehr Fokus ». Der Unternehmer räumt ein: « Es stimmt, dass der Meeting-Wahnsinn Zeit frisst ». Seine Sorge bleibt: Wer betreut am fünften Tag die Kunden ? Die Moderatorin hält dagegen: « Aus meiner Sicht entscheiden am Ende die Zahlen, nicht die Gefühle ». Zusammenfassend bittet sie beide zu einer Pilotrechnung. Nächste Woche debattiert das Studio die Bürokratie.", questions = listOf(Exercise(id = "de-listen-radio-debatte-q1", kind = "choice", prompt = "Welche Zahl nennt Brandt zuerst ?", options = listOf("Zwanzig Prozent mehr Zufriedenheit", "Zwanzig Prozent mehr Umsatz", "Vier Tage weniger Urlaub", "Fünfzig Prozent weniger Meetings"), answers = listOf("Zwanzig Prozent mehr Zufriedenheit"), explain = "« …stieg die Zufriedenheit um zwanzig Prozent »."), Exercise(id = "de-listen-radio-debatte-q2", kind = "choice", prompt = "Warum ist Ostermann skeptisch ?", options = listOf("Vier Tage reichen selten für Projekte", "Die Pilotfirma war zu klein", "Ihm sind Zahlen egal", "Kunden wollen keine Zahlen"), answers = listOf("Vier Tage reichen selten für Projekte"), explain = "« Vier Tage reichen selten, um Projekte ordentlich abzuschließen »."), Exercise(id = "de-listen-radio-debatte-q3", kind = "written", prompt = "Was nennt Brandt als Struktur ?", options = listOf(), answers = listOf("weniger meetings, mehr fokus", "weniger meetings mehr fokus"), explain = "« …sozusagen weniger Meetings, mehr Fokus »."), Exercise(id = "de-listen-radio-debatte-q4", kind = "written", prompt = "Worauf räumt Ostermann ein ?", options = listOf(), answers = listOf("dass der meeting-wahnsinn zeit frisst", "dass meetings zeit fressen", "meeting-wahnsinn frisst zeit"), explain = "« Es stimmt, dass der Meeting-Wahnsinn Zeit frisst »."), Exercise(id = "de-listen-radio-debatte-q5", kind = "written", prompt = "Wovon soll am Ende entschieden werden ?", options = listOf(), answers = listOf("den zahlen", "von den zahlen", "zahlen, nicht gefuhlen", "zahlen, nicht gefühlen"), explain = "« Aus meiner Sicht entscheiden am Ende die Zahlen, nicht die Gefühle ».")), skills = listOf("listening:inference", "listening:gist", "grammar:connectors", "function:express-opinion")) }

object ListenData014 { val text = ListeningText(id = "de-listen-podcast-nuancen", languageID = "de", title = "Podcast: Feines Deutsch", level = "C1", topic = "sprache", unitID = "de-foundations-u9", text = "Im Podcast « Feines Deutsch » sprechen Wiebke und Tarek darüber, wie man Meinungen abschwächt, ohne an Profil zu verlieren. « Irgendwie klingt alles weicher, wenn man eher sagt », meint Wiebke. Tarek hält dagegen: « Wenn du alles abschwächst, nimmt dich niemand mehr ernst ». Sozusagen einigen sie sich auf eine Regel: Bei Fakten darf man schärfen, bei Menschen sollte man abschwächen. Wiebke ergänzt eine Farbe aus dem Büroalltag: « Aus meiner Sicht » klinge sachlicher als « Ich finde ». Tarek lacht: « Und nicht unbedingt ist die höflichste Form von Nein ». Zum Schluss empfehlen sie den Hörern eine Woche Übung: erst bewusst abschwächen, dann bewusst schärfen – und auf die Reaktionen achten.", questions = listOf(Exercise(id = "de-listen-podcast-nuancen-q1", kind = "choice", prompt = "Wovor warnt Tarek ?", options = listOf("Dass ständiges Abschwächen unglaubwürdig macht", "Dass « eher » unhöflich klingt", "Dass Fakten weicher werden", "Dass Podcasts zu kurz sind"), answers = listOf("Dass ständiges Abschwächen unglaubwürdig macht"), explain = "« Wenn du alles abschwächst, nimmt dich niemand mehr ernst »."), Exercise(id = "de-listen-podcast-nuancen-q2", kind = "written", prompt = "Auf welche Regel einigen sich die beiden ?", options = listOf(), answers = listOf("bei fakten schärfen, bei menschen abschwächen", "bei fakten scharfen, bei menschen abschwachen", "bei fakten darf man schärfen"), explain = "« Bei Fakten darf man schärfen, bei Menschen sollte man abschwächen »."), Exercise(id = "de-listen-podcast-nuancen-q3", kind = "choice", prompt = "Wie klingt « Aus meiner Sicht » laut Wiebke ?", options = listOf("Sachlicher als « Ich finde »", "Freundlicher als « Ich finde »", "Unsicherer als « Ich finde »", "Härter als « Ich finde »"), answers = listOf("Sachlicher als « Ich finde »"), explain = "« …klinge sachlicher als « Ich finde » »."), Exercise(id = "de-listen-podcast-nuancen-q4", kind = "written", prompt = "Was ist laut Tarek die höflichste Form von Nein ?", options = listOf(), answers = listOf("nicht unbedingt"), explain = "« Nicht unbedingt ist die höflichste Form von Nein »."), Exercise(id = "de-listen-podcast-nuancen-q5", kind = "written", prompt = "Was üben die Hörer eine Woche lang ?", options = listOf(), answers = listOf("erst abschwächen, dann schärfen", "erst abschwachen dann scharfen", "bewusst abschwächen und schärfen"), explain = "« erst bewusst abschwächen, dann bewusst schärfen ».")), skills = listOf("listening:inference", "function:express-opinion", "vocab:social-expressions", "vocab:collocations")) }

object ListenData015 { val text = ListeningText(id = "de-listen-vortrag-schluessel", languageID = "de", title = "Vortrag: Schlüsselkompetenzen", level = "C1", topic = "bildung", unitID = "de-foundations-u9", text = "Herzlich willkommen zur Vorlesung « Berufe von morgen ». Ich teile meinen Vortrag in drei Schritte. Zunächst kläre ich den Begriff: Schlüsselkompetenzen sind Fähigkeiten, die über Fachwissen hinausgehen, etwa im Team kommunizieren oder komplexe Informationen sortieren. Im Folgenden vergleiche ich zwei Studien. Die erste zeigt, dass Arbeitgeber Durchhaltevermögen und Lernbereitschaft höher bewerten als Notendurchschnitte. Die zweite warnt: Wer nur Spezialist bleibt, verliert im Berufsalltag schnell den Anschluss. Daraus folgt meine These: Universitäten sollten Projektarbeit verpflichtend machen. Zusammenfassend merken Sie sich drei Dinge: erstens Transfer, zweitens Kommunikation, drittens Neugier. Zum Schluss öffne ich die Fragerunde; präzise Fragen bekommen präzisere Antworten.", questions = listOf(Exercise(id = "de-listen-vortrag-schluessel-q1", kind = "choice", prompt = "Wie beginnt der Vortrag ?", options = listOf("Mit einer Begriffsklärung", "Mit zwei Studien", "Mit der Fragerunde", "Mit einer These"), answers = listOf("Mit einer Begriffsklärung"), explain = "« Zunächst kläre ich den Begriff… »."), Exercise(id = "de-listen-vortrag-schluessel-q2", kind = "choice", prompt = "Was bewerten Arbeitgeber laut erster Studie höher ?", options = listOf("Notendurchschnitte", "Durchhaltevermögen und Lernbereitschaft", "Auslandserfahrung", "Gehaltsvorstellungen"), answers = listOf("Durchhaltevermögen und Lernbereitschaft"), explain = "« …höher bewerten als Notendurchschnitte »."), Exercise(id = "de-listen-vortrag-schluessel-q3", kind = "choice", prompt = "Wovor warnt die zweite Studie ?", options = listOf("Dass reine Spezialisten den Anschluss verlieren", "Dass Noten alles entscheiden", "Dass Teams zu groß werden", "Dass Universitäten schließen"), answers = listOf("Dass reine Spezialisten den Anschluss verlieren"), explain = "« Wer nur Spezialist bleibt, verliert … den Anschluss »."), Exercise(id = "de-listen-vortrag-schluessel-q4", kind = "written", prompt = "Welche These vertritt der Dozent ?", options = listOf(), answers = listOf("universitäten sollten projektarbeit verpflichtend machen", "universitaten sollten projektarbeit verpflichtend machen", "projektarbeit sollte verpflichtend sein"), explain = "« Universitäten sollten Projektarbeit verpflichtend machen »."), Exercise(id = "de-listen-vortrag-schluessel-q5", kind = "written", prompt = "Nenne die drei Merkdinge in Kurzform.", options = listOf(), answers = listOf("transfer, kommunikation, neugier", "transfer kommunikation neugier"), explain = "« erstens Transfer, zweitens Kommunikation, drittens Neugier ».")), skills = listOf("listening:detail", "listening:connected-speech", "vocab:work", "grammar:connectors")) }

object ListenData016 { val text = ListeningText(id = "de-listen-neue-wohnung", languageID = "de", title = "Die neue Wohnung", level = "A1", topic = "Wohnen", unitID = "de-foundations-u10", text = "Lena hat eine neue Wohnung. Sie ist klein, aber sie gefällt Lena sehr. Es gibt ein Wohnzimmer, ein Schlafzimmer und eine Küche. Das Bad ist sehr klein. Im Wohnzimmer gibt es ein Sofa und einen Tisch. Der Tisch steht neben dem Fenster. Auf dem Sofa liegt eine grüne Decke. Der Schrank ist im Schlafzimmer, neben dem Bett. Am Samstag bringt Jonas eine Lampe. Lena freut sich.", questions = listOf(Exercise(id = "de-listen-neue-wohnung-q1", kind = "choice", prompt = "Was hat Lena ?", options = listOf("Eine kleine Wohnung", "Ein großes Haus", "Ein Zimmer im Hotel", "Ein Haus im Dorf"), answers = listOf("Eine kleine Wohnung"), explain = "Lena hat eine neue Wohnung. Sie ist klein, aber sie gefällt ihr."), Exercise(id = "de-listen-neue-wohnung-q2", kind = "choice", prompt = "Wie viele Zimmer gibt es ?", options = listOf("Zwei", "Drei", "Vier", "Eins"), answers = listOf("Zwei"), explain = "Es gibt ein Wohnzimmer und ein Schlafzimmer: zwei Zimmer."), Exercise(id = "de-listen-neue-wohnung-q3", kind = "written", prompt = "Wo steht der Tisch ?", options = listOf(), answers = listOf("neben dem fenster", "Neben dem Fenster."), explain = "Der Tisch steht neben dem Fenster."), Exercise(id = "de-listen-neue-wohnung-q4", kind = "choice", prompt = "Wo ist der Schrank ?", options = listOf("Im Schlafzimmer", "In der Küche", "Im Bad", "Auf dem Balkon"), answers = listOf("Im Schlafzimmer"), explain = "Der Schrank ist im Schlafzimmer, neben dem Bett."), Exercise(id = "de-listen-neue-wohnung-q5", kind = "written", prompt = "Was liegt auf dem Sofa ?", options = listOf(), answers = listOf("eine grüne decke", "eine gruene decke"), explain = "Auf dem Sofa liegt eine grüne Decke."), Exercise(id = "de-listen-neue-wohnung-q6", kind = "choice", prompt = "Was bringt Jonas am Samstag ?", options = listOf("Eine Lampe", "Einen Tisch", "Einen Stuhl", "Blumen"), answers = listOf("Eine Lampe"), explain = "Am Samstag bringt Jonas eine Lampe.")), skills = listOf("listening:gist", "listening:detail", "grammar:there-is-are", "grammar:prepositions-place", "vocab:home")) }

object ListenData017 { val text = ListeningText(id = "de-listen-viertel-spaziergang", languageID = "de", title = "Spaziergang im Viertel", level = "A1", topic = "Im Viertel", unitID = "de-foundations-u11", text = "Miguel ist neu im Viertel. Er fragt Mia: „Gibt es hier einen Supermarkt ?“ „Ja“, sagt Mia, „in der Bahnhofstraße, neben der Apotheke.“ „Und wo kann ich Obst kaufen ?“ „Am Obststand, um die Ecke.“ Sie gehen zusammen los: geradeaus bis zum Park, dann links. Der Obststand ist klein, aber die Äpfel sind lecker. Miguel kauft ein Kilo. Jetzt kennt er sein neues Viertel besser.", questions = listOf(Exercise(id = "de-listen-viertel-spaziergang-q1", kind = "choice", prompt = "Was fragt Miguel zuerst ?", options = listOf("Nach einem Supermarkt", "Nach dem Bahnhof", "Nach einer Schule", "Nach dem Park"), answers = listOf("Nach einem Supermarkt"), explain = "Er fragt: Gibt es hier einen Supermarkt ?"), Exercise(id = "de-listen-viertel-spaziergang-q2", kind = "choice", prompt = "Wo ist der Supermarkt ?", options = listOf("In der Bahnhofstraße", "Am Park", "Um die Ecke", "Im ersten Stock"), answers = listOf("In der Bahnhofstraße"), explain = "Der Supermarkt ist in der Bahnhofstraße, neben der Apotheke."), Exercise(id = "de-listen-viertel-spaziergang-q3", kind = "written", prompt = "Wo kann Miguel Obst kaufen ?", options = listOf(), answers = listOf("am obststand", "Am Obststand.", "am obststand um die ecke"), explain = "Obst gibt es am Obststand, um die Ecke."), Exercise(id = "de-listen-viertel-spaziergang-q4", kind = "choice", prompt = "Wo gehen sie nach dem Park hin ?", options = listOf("Nach links", "Nach rechts", "Geradeaus weiter", "Nach Hause"), answers = listOf("Nach links"), explain = "Sie gehen geradeaus bis zum Park, dann links."), Exercise(id = "de-listen-viertel-spaziergang-q5", kind = "written", prompt = "Was kauft Miguel ?", options = listOf(), answers = listOf("ein kilo äpfel", "ein kilo aepfel"), explain = "Miguel kauft ein Kilo Äpfel."), Exercise(id = "de-listen-viertel-spaziergang-q6", kind = "choice", prompt = "Wie sind die Äpfel ?", options = listOf("Lecker", "Zu teuer", "Nicht reif", "Klein"), answers = listOf("Lecker"), explain = "Der Obststand ist klein, aber die Äpfel sind lecker.")), skills = listOf("listening:gist", "listening:detail", "grammar:there-is-are", "vocab:town", "function:ask-for-directions")) }

object ListenData018 { val text = ListeningText(id = "de-listen-anruf-oma", languageID = "de", title = "Anruf bei Oma", level = "A1", topic = "Familie", unitID = "de-foundations-u12", text = "Nadia ruft ihre Oma an. Oma Helga nimmt ab. „Hallo, hier ist Nadia!“ — „Nadia! Du rufst nie an! Wie geht es dir ?“ „Gut, Oma. Ist Opa da ?“ — „Nein, er ist nicht da. Er geht oft im Park spazieren. Und du ? Was machst du ?“ — „Ich lese viel und gehe manchmal ins Kino.“ „Schön. Rufst du mich nächste Woche wieder an ?“ — „Ja, Oma. Bis dann!“", questions = listOf(Exercise(id = "de-listen-anruf-oma-q1", kind = "choice", prompt = "Wen ruft Nadia an ?", options = listOf("Ihre Oma", "Ihre Mutter", "Ihren Onkel", "Ihre Schwester"), answers = listOf("Ihre Oma"), explain = "Nadia ruft ihre Oma an."), Exercise(id = "de-listen-anruf-oma-q2", kind = "choice", prompt = "Was sagt Oma zuerst über Nadias Anrufe ?", options = listOf("Du rufst nie an!", "Du rufst immer an!", "Du rufst oft an!", "Du rufst manchmal an!"), answers = listOf("Du rufst nie an!"), explain = "Oma sagt: Du rufst nie an!"), Exercise(id = "de-listen-anruf-oma-q3", kind = "choice", prompt = "Wo ist Opa ?", options = listOf("Im Park", "Im Kino", "Zu Hause", "In der Schule"), answers = listOf("Im Park"), explain = "Er geht oft im Park spazieren."), Exercise(id = "de-listen-anruf-oma-q4", kind = "written", prompt = "Was macht Opa oft ?", options = listOf(), answers = listOf("er geht spazieren", "spazieren", "er geht im park spazieren"), explain = "Er geht oft im Park spazieren."), Exercise(id = "de-listen-anruf-oma-q5", kind = "written", prompt = "Was macht Nadia manchmal ?", options = listOf(), answers = listOf("ins kino", "sie geht ins kino", "sie geht manchmal ins kino"), explain = "Ich gehe manchmal ins Kino."), Exercise(id = "de-listen-anruf-oma-q6", kind = "choice", prompt = "Wann ruft Nadia wieder an ?", options = listOf("Nächste Woche", "Heute Abend", "Morgen", "Am Wochenende"), answers = listOf("Nächste Woche"), explain = "Rufst du mich nächste Woche wieder an ? — Ja.")), skills = listOf("listening:gist", "listening:detail", "vocab:family", "vocab:daily-routine", "grammar:frequency-adverbs")) }

object ListenData019 { val text = ListeningText(id = "de-listen-regnerisches-wochenende", languageID = "de", title = "Ein regnerisches Wochenende", level = "A1", topic = "Wetter", unitID = "de-foundations-u13", text = "Es ist Samstagmorgen. Kim sieht aus dem Fenster: Es regnet. „Oh nein“, sagt Sam, „das Wetter ist schlecht.“ — „Ja, kalt und nass“, sagt Kim. „Wir gehen oft in den Park, aber heute nicht. Was machen wir ?“ „Ich lese nicht gern bei Regen“, sagt Sam, „aber ich koche gern.“ „Super, wir kochen zusammen und spielen Karten.“ — „Und morgen ?“ „Morgen ist es sonnig und warm.“", questions = listOf(Exercise(id = "de-listen-regnerisches-wochenende-q1", kind = "choice", prompt = "Wie ist das Wetter heute ?", options = listOf("Es regnet", "Es schneit", "Es ist sonnig", "Es ist warm"), answers = listOf("Es regnet"), explain = "Kim sieht aus dem Fenster: Es regnet."), Exercise(id = "de-listen-regnerisches-wochenende-q2", kind = "choice", prompt = "Wohin gehen sie oft ?", options = listOf("In den Park", "Ins Kino", "In die Schule", "Zum Markt"), answers = listOf("In den Park"), explain = "Wir gehen oft in den Park, aber heute nicht."), Exercise(id = "de-listen-regnerisches-wochenende-q3", kind = "written", prompt = "Was macht Sam gern ?", options = listOf(), answers = listOf("kochen", "koche", "er kocht gern"), explain = "Ich lese nicht gern bei Regen, aber ich koche gern."), Exercise(id = "de-listen-regnerisches-wochenende-q4", kind = "written", prompt = "Wie ist das Wetter morgen ?", options = listOf(), answers = listOf("sonnig und warm", "es ist sonnig und warm", "warm"), explain = "Morgen ist es sonnig und warm."), Exercise(id = "de-listen-regnerisches-wochenende-q5", kind = "choice", prompt = "Was machen sie heute zusammen ?", options = listOf("Kochen und Karten", "Lesen und Laufen", "Einkaufen und Kino", "Schwimmen"), answers = listOf("Kochen und Karten"), explain = "Wir kochen zusammen und spielen Karten."), Exercise(id = "de-listen-regnerisches-wochenende-q6", kind = "choice", prompt = "Warum gehen sie heute nicht in den Park ?", options = listOf("Es regnet", "Sie sind müde", "Kim muss arbeiten", "Sie haben keine Zeit"), answers = listOf("Es regnet"), explain = "Heute regnet es — deshalb bleiben sie zu Hause.")), skills = listOf("listening:gist", "listening:detail", "vocab:weather", "vocab:daily-routine", "grammar:frequency-adverbs", "function:talk-about-weather")) }

object ListenData020 { val text = ListeningText(id = "de-listen-ubahn-verlaufen", languageID = "de", title = "Im falschen Zug", level = "A1", topic = "Unterwegs", unitID = "de-foundations-u14", text = "Sam ist neu in Berlin. Er möchte zu Kim, aber er sitzt im falschen Zug. „Oh nein — das ist die U8, nicht die U2 !“ Er fragt eine Frau: „Entschuldigung, wann fährt die nächste Bahn ?“ — „Um Viertel nach zehn, von Gleis 3“, sagt die Frau. Sam fährt zurück zum Alexanderplatz. Dort steigt er in die U2. Um halb elf klingelt er bei Kim. „Du bist spät !“ — „Ab jetzt nehme ich immer die U2“, sagt Sam.", questions = listOf(Exercise(id = "de-listen-ubahn-verlaufen-q1", kind = "choice", prompt = "Wo ist Sam neu ?", options = listOf("In Berlin", "In Bonn", "In Köln", "In Wien"), answers = listOf("In Berlin"), explain = "Sam ist neu in Berlin."), Exercise(id = "de-listen-ubahn-verlaufen-q2", kind = "choice", prompt = "Welche Bahn möchte Sam nehmen ?", options = listOf("Die U2", "Die U8", "Die U3", "Die S7"), answers = listOf("Die U2"), explain = "Das ist die U8, nicht die U2 — er möchte die U2."), Exercise(id = "de-listen-ubahn-verlaufen-q3", kind = "written", prompt = "Wann fährt die nächste Bahn ?", options = listOf(), answers = listOf("um viertel nach zehn", "Viertel nach zehn", "10:15 Uhr"), explain = "Um Viertel nach zehn, von Gleis 3."), Exercise(id = "de-listen-ubahn-verlaufen-q4", kind = "choice", prompt = "Wo steigt Sam in die U2 ?", options = listOf("Am Alexanderplatz", "Am Hauptbahnhof", "Bei Kim", "In Bonn"), answers = listOf("Am Alexanderplatz"), explain = "Sam fährt zurück zum Alexanderplatz. Dort steigt er in die U2."), Exercise(id = "de-listen-ubahn-verlaufen-q5", kind = "written", prompt = "Wann ist Sam bei Kim ?", options = listOf(), answers = listOf("um halb elf", "halb elf", "10:30", "10:30 Uhr"), explain = "Um halb elf klingelt er bei Kim."), Exercise(id = "de-listen-ubahn-verlaufen-q6", kind = "choice", prompt = "Was nimmt Sam ab jetzt immer ?", options = listOf("Die U2", "Die U8", "Die Bahn von Gleis 3", "Ein Fahrrad"), answers = listOf("Die U2"), explain = "Ab jetzt nehme ich immer die U2, sagt Sam.")), skills = listOf("listening:gist", "listening:detail", "vocab:transport", "function:tell-time")) }

object ListenData021 { val text = ListeningText(id = "de-listen-apotheke-samstag", languageID = "de", title = "Samstag in der Apotheke", level = "A1", topic = "Gesundheit", unitID = "de-foundations-u15", text = "Es ist Samstagmorgen. Mia hat Kopfschmerzen und Fieber. Kim geht mit ihr in die Apotheke. „Guten Tag, meine Freundin fühlt sich nicht gut“, sagt Kim. „Sie braucht etwas gegen die Schmerzen.“ — „Nehmen Sie diese Tabletten“, sagt der Apotheker. „Zweimal am Tag, mit Wasser.“ — „Was kostet das ?“ — „Neun Euro.“ Mia nimmt die Tabletten und trinkt viel Wasser. Am Abend fühlt sie sich besser. Kim sagt: „Gute Besserung und schlaf gut !“", questions = listOf(Exercise(id = "de-listen-apotheke-samstag-q1", kind = "choice", prompt = "Was hat Mia ?", options = listOf("Kopfschmerzen und Fieber", "Husten und Schnupfen", "Nur Müdigkeit", "Bauchschmerzen"), answers = listOf("Kopfschmerzen und Fieber"), explain = "Mia hat Kopfschmerzen und Fieber."), Exercise(id = "de-listen-apotheke-samstag-q2", kind = "written", prompt = "Wohin gehen die Freundinnen ?", options = listOf(), answers = listOf("in die apotheke", "zur apotheke", "Apotheke"), explain = "Kim geht mit ihr in die Apotheke."), Exercise(id = "de-listen-apotheke-samstag-q3", kind = "choice", prompt = "Wie oft soll Mia die Tabletten nehmen ?", options = listOf("Zweimal am Tag", "Dreimal am Tag", "Einmal am Tag", "Nie"), answers = listOf("Zweimal am Tag"), explain = "Zweimal am Tag, mit Wasser."), Exercise(id = "de-listen-apotheke-samstag-q4", kind = "written", prompt = "Was kostet das ?", options = listOf(), answers = listOf("neun euro", "9 euro", "9"), explain = "Neun Euro."), Exercise(id = "de-listen-apotheke-samstag-q5", kind = "written", prompt = "Was trinkt Mia ?", options = listOf(), answers = listOf("wasser", "viel wasser"), explain = "Mia nimmt die Tabletten und trinkt viel Wasser."), Exercise(id = "de-listen-apotheke-samstag-q6", kind = "choice", prompt = "Wie fühlt sich Mia am Abend ?", options = listOf("Besser", "Schlechter", "Gleich", "Sehr krank"), answers = listOf("Besser"), explain = "Am Abend fühlt sie sich besser.")), skills = listOf("listening:gist", "listening:detail", "vocab:health", "grammar:frequency-adverbs")) }

object ListenData022 { val text = ListeningText(id = "de-listen-ueberraschungsfest", languageID = "de", title = "Das Überraschungsfest", level = "A1", topic = "essen", unitID = "de-foundations-u16", text = "Es ist Freitag. Sascha hat morgen Geburtstag, aber er weiß nichts. Anna ruft im Restaurant Adler an: « Wir möchten einen Tisch für zehn Personen reservieren. » — « Kein Problem », sagt der Kellner. « Was möchten Sie essen ? » — « Zehn Pizzen, bitte. Und was ist in der Pizza Funghi ? » — « Pilze und Käse. » Am Samstag kommen alle um sechs, Sascha um sieben. Alle rufen: « Überraschung ! » Sascha freut sich sehr: « Ihr seid die besten Freunde ! »", questions = listOf(Exercise(id = "de-listen-ueberraschungsfest-q1", kind = "choice", prompt = "Wann hat Sascha Geburtstag ?", options = listOf("Morgen", "Heute", "Am Freitag", "Nächste Woche"), answers = listOf("Morgen"), explain = "Es ist Freitag, und Sascha hat morgen Geburtstag."), Exercise(id = "de-listen-ueberraschungsfest-q2", kind = "written", prompt = "Wen ruft Anna an ?", options = listOf(), answers = listOf("im restaurant adler", "restaurant adler", "das restaurant adler"), explain = "Anna ruft im Restaurant Adler an."), Exercise(id = "de-listen-ueberraschungsfest-q3", kind = "written", prompt = "Was möchten sie essen ?", options = listOf(), answers = listOf("zehn pizzen", "10 pizzen", "zehn pizza"), explain = "« Zehn Pizzen, bitte », sagt Anna."), Exercise(id = "de-listen-ueberraschungsfest-q4", kind = "choice", prompt = "Was ist in der Pizza Funghi ?", options = listOf("Pilze und Käse", "Schinken und Käse", "Tomaten und Salat", "Nur Käse"), answers = listOf("Pilze und Käse"), explain = "« Pilze und Käse », sagt der Kellner."), Exercise(id = "de-listen-ueberraschungsfest-q5", kind = "written", prompt = "Wann kommen die Freunde ?", options = listOf(), answers = listOf("um sechs", "um 6", "um sechs uhr"), explain = "Am Samstag kommen alle um sechs."), Exercise(id = "de-listen-ueberraschungsfest-q6", kind = "choice", prompt = "Wie findet Sascha die Party ?", options = listOf("Er freut sich sehr", "Er ist müde", "Er möchte zahlen", "Er geht nach Hause"), answers = listOf("Er freut sich sehr"), explain = "Er freut sich sehr und dankt seinen Freunden.")), skills = listOf("listening:gist", "listening:detail", "vocab:food", "function:order-food")) }

object ListenData023 { val text = ListeningText(id = "de-listen-geburtstagsplan", languageID = "de", title = "Der Geburtstagsplan", level = "A2", topic = "geschenke", unitID = "de-foundations-u17", text = "Mia und Paul planen Emmas Geburtstag am Samstag. « Was werden wir ihr schenken ? », fragt Mia. « Ich werde ein Kochbuch kaufen — sie kocht so gern », sagt Paul. « Gute Idee ! Ich bestelle eine Kerze und Ballons. » Dann wird Mia still: « Ich kann leider nicht kommen, weil ich am Samstag arbeiten muss. » « Schade », sagt Paul, « aber am Abend feiern wir in der Pizzeria Sonne. Kommst du danach ? » « Klar, ab acht Uhr bin ich dabei. » Am Ende lachen sie: Emma weiß von nichts.", questions = listOf(Exercise(id = "de-listen-geburtstagsplan-q1", kind = "choice", prompt = "Was wird Paul Emma schenken ?", options = listOf("Ein Kochbuch", "Kerzen und Ballons", "Eine Kette", "Konzertkarten"), answers = listOf("Ein Kochbuch"), explain = "« Ich werde ein Kochbuch kaufen — sie kocht so gern »."), Exercise(id = "de-listen-geburtstagsplan-q2", kind = "written", prompt = "Was bestellt Mia ?", options = listOf(), answers = listOf("eine kerze und ballons", "kerze und ballons", "eine kerze, ballons"), explain = "« Ich bestelle eine Kerze und Ballons. »"), Exercise(id = "de-listen-geburtstagsplan-q3", kind = "written", prompt = "Warum kann Mia nicht kommen ?", options = listOf(), answers = listOf("weil sie arbeiten muss", "sie muss arbeiten", "arbeiten"), explain = "Sie muss am Samstag arbeiten."), Exercise(id = "de-listen-geburtstagsplan-q4", kind = "choice", prompt = "Wo feiern sie am Abend ?", options = listOf("In der Pizzeria Sonne", "Zu Hause", "Im Restaurant Adler", "Im Park"), answers = listOf("In der Pizzeria Sonne"), explain = "« … am Abend feiern wir in der Pizzeria Sonne »."), Exercise(id = "de-listen-geburtstagsplan-q5", kind = "written", prompt = "Wann ist Mia dabei ?", options = listOf(), answers = listOf("ab acht uhr", "ab 8 uhr", "nach acht uhr"), explain = "« Ab acht Uhr bin ich dabei. »"), Exercise(id = "de-listen-geburtstagsplan-q6", kind = "choice", prompt = "Was erfährt Emma noch nicht ?", options = listOf("Von der Party", "Von dem Kochbuch", "Von der Arbeit", "Von den Ballons"), answers = listOf("Von der Party"), explain = "Emma weiß von nichts — sie soll überrascht sein.")), skills = listOf("listening:gist", "listening:inference", "grammar:going-to", "vocab:social-expressions")) }

object ListenData024 { val text = ListeningText(id = "de-listen-sommerepisode", languageID = "de", title = "Die Sommerepisode", level = "B1", topic = "erlebnisse", unitID = "de-foundations-u18", text = "Kim trifft Tim im Park. « Du wolltest doch was erzählen », sagt Kim. Tim nickt: « Letzten Sommer arbeitete ich in einem Café am See. Einmal bestellte ein Gast elfmal Cappuccino — einen nach dem anderen. » « Nicht zu fassen ! », ruft Kim. « Und dann ? » « Ich brachte alle Tassen hinaus. Plötzlich stand seine ganze Familie auf und verteilte den Kaffee an die Passanten am Weg. » « Was ? Warum ? » « Es stellte sich heraus, dass er seinen siebzigsten Geburtstag feierte und jedem eine Freude machen wollte. Am Ende lachte der ganze See. » Kim schüttelt den Kopf: « Solche Geschichten passieren nur dir. »", questions = listOf(Exercise(id = "de-listen-sommerepisode-q1", kind = "choice", prompt = "Wo arbeitete Tim letzten Sommer ?", options = listOf("In einem Café am See", "In einem Park", "In einer Bäckerei", "Auf einem Boot"), answers = listOf("In einem Café am See"), explain = "« Letzten Sommer arbeitete ich in einem Café am See »."), Exercise(id = "de-listen-sommerepisode-q2", kind = "written", prompt = "Was bestellte der Gast ?", options = listOf(), answers = listOf("elfmal cappuccino", "elf cappuccinos", "elfmal cappuccino"), explain = "Einmal bestellte ein Gast elfmal Cappuccino."), Exercise(id = "de-listen-sommerepisode-q3", kind = "choice", prompt = "Wer stand plötzlich auf ?", options = listOf("Seine ganze Familie", "Die Passanten", "Kim und Tim", "Der Chef des Cafés"), answers = listOf("Seine ganze Familie"), explain = "« Plötzlich stand seine ganze Familie auf »."), Exercise(id = "de-listen-sommerepisode-q4", kind = "written", prompt = "Warum machte der Gast das ?", options = listOf(), answers = listOf("geburtstag", "er feierte seinen siebzigsten geburtstag", "siebzigster geburtstag"), explain = "Er feierte seinen siebzigsten Geburtstag und wollte jedem eine Freude machen."), Exercise(id = "de-listen-sommerepisode-q5", kind = "choice", prompt = "Wie endete die Geschichte ?", options = listOf("Alle lachten", "Die Familie ging wütend", "Tim verlor den Job", "Es begann zu regnen"), answers = listOf("Alle lachten"), explain = "« Am Ende lachte der ganze See »."), Exercise(id = "de-listen-sommerepisode-q6", kind = "choice", prompt = "Was meint Kim mit ihrem Schluss ?", options = listOf("Tim erlebt solche Dinge oft", "Tim soll aufhören zu arbeiten", "Tim lügt", "Tim mag keinen Kaffee"), answers = listOf("Tim erlebt solche Dinge oft"), explain = "« Solche Geschichten passieren nur dir » — scherzhaft: nur Tim erlebt so etwas.")), skills = listOf("listening:inference", "listening:detail", "grammar:past-simple-irregular", "grammar:connectors")) }

object ListenData025 { val text = ListeningText(id = "de-listen-debatte-takt", languageID = "de", title = "Debatte mit Takt", level = "C1", topic = "debatte", unitID = "de-foundations-u9", text = "In der Sendung « Punkt kontra Punkt » streiten Hana Berger und Robert Falk über autofreie Innenstädte. Falk beginnt: « Der Handel wird leiden, das ist doch klar. » Berger bleibt ruhig: « Ich verstehe die Sorge, aber die Zahlen aus anderen Städten widersprechen ihr. » Falk schärft nach: « Das mag stimmen, allerdings handelt es sich um Großstädte. » — « Da bin ich ganz bei Ihnen », sagt Berger, « dennoch war auch Freiburg vor zwanzig Jahren skeptisch. » Der Moderator greift ein: « Sie widersprechen sich höflich — wie geht das ? » Berger lacht: « Erst würdigen, dann kontern. Und nie den Menschen, immer die Position angreifen. » Falk nickt: « Daran könnte ich mich gewöhnen. »", questions = listOf(Exercise(id = "de-listen-debatte-takt-q1", kind = "choice", prompt = "Welche Sorge äußert Falk zuerst ?", options = listOf("Der Handel wird leiden", "Die Luft wird schlechter", "Die Stadt wird lauter", "Die Mieten steigen"), answers = listOf("Der Handel wird leiden"), explain = "« Der Handel wird leiden, das ist doch klar »."), Exercise(id = "de-listen-debatte-takt-q2", kind = "written", prompt = "Wie beginnt Berger ihren Widerspruch ?", options = listOf(), answers = listOf("ich verstehe die sorge", "ich verstehe ihre sorge"), explain = "« Ich verstehe die Sorge, aber… » — erst Verständnis, dann Kontra."), Exercise(id = "de-listen-debatte-takt-q3", kind = "choice", prompt = "Was räumt Falk ein und begrenzt er zugleich ?", options = listOf("Dass die Zahlen stimmen, aber nur für Großstädte", "Dass Freiburg skeptisch war", "Dass der Handel leidet", "Dass Berger recht hat"), answers = listOf("Dass die Zahlen stimmen, aber nur für Großstädte"), explain = "« Das mag stimmen, allerdings handelt es sich um Großstädte »."), Exercise(id = "de-listen-debatte-takt-q4", kind = "written", prompt = "Welches Beispiel nennt Berger ?", options = listOf(), answers = listOf("freiburg"), explain = "« Dennoch war auch Freiburg vor zwanzig Jahren skeptisch »."), Exercise(id = "de-listen-debatte-takt-q5", kind = "choice", prompt = "Was empfiehlt Berger für den höflichen Widerspruch ?", options = listOf("Erst würdigen, dann die Position angreifen", "Immer den Menschen angreifen", "Nie widersprechen", "Lauter werden"), answers = listOf("Erst würdigen, dann die Position angreifen"), explain = "« Erst würdigen, dann kontern. Und nie den Menschen, immer die Position angreifen »."), Exercise(id = "de-listen-debatte-takt-q6", kind = "written", prompt = "Wie reagiert Falk am Ende ?", options = listOf(), answers = listOf("daran könnte ich mich gewöhnen", "daran konnte ich mich gewohnen"), explain = "« Daran könnte ich mich gewöhnen » — er erkennt Bergers Takt halb im Scherz an.")), skills = listOf("listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion")) }

object ListenData026 { val text = ListeningText(id = "de-listen-feier-freitag", languageID = "de", title = "Ein Abend bei Lea", level = "A1", topic = "besuch", unitID = "de-foundations-u19", text = "Es ist Freitagabend. Jakob steht vor Leas Tür und klingelt. « Darf ich reinkommen ? » — « Natürlich, komm rein ! Du darfst die Schuhe ausziehen. » Jakob bringt einen Kuchen mit: « Der ist für euch. » Am Tisch fragt Lea: « Möchtest du Tee oder Saft ? » — « Tee, bitte. » Sie essen Kuchen und reden lange. Am Ende sagt Jakob: « Vielen Dank für die Einladung ! » — « Bis zum nächsten Mal ! »", questions = listOf(Exercise(id = "de-listen-feier-freitag-q1", kind = "choice", prompt = "Wann kommt Jakob zu Lea ?", options = listOf("Am Freitagabend", "Am Samstagmorgen", "Am Montag", "Am Sonntag"), answers = listOf("Am Freitagabend"), explain = "Es ist Freitagabend."), Exercise(id = "de-listen-feier-freitag-q2", kind = "written", prompt = "Was fragt Jakob an der Tür ?", options = listOf(), answers = listOf("darf ich reinkommen", "darf ich reinkommen ?", "darf ich hereinkommen"), explain = "« Darf ich reinkommen ? », fragt Jakob."), Exercise(id = "de-listen-feier-freitag-q3", kind = "choice", prompt = "Was darf Jakob machen ?", options = listOf("Die Schuhe ausziehen", "Rauchen", "Kochen", "Fernsehen"), answers = listOf("Die Schuhe ausziehen"), explain = "« Du darfst die Schuhe ausziehen. »"), Exercise(id = "de-listen-feier-freitag-q4", kind = "written", prompt = "Was bringt Jakob mit ?", options = listOf(), answers = listOf("einen kuchen", "kuchen", "einen kuchen mit"), explain = "Jakob bringt einen Kuchen mit."), Exercise(id = "de-listen-feier-freitag-q5", kind = "choice", prompt = "Was nimmt Jakob zu trinken ?", options = listOf("Tee", "Saft", "Wasser", "Kaffee"), answers = listOf("Tee"), explain = "« Tee, bitte. »"), Exercise(id = "de-listen-feier-freitag-q6", kind = "written", prompt = "Was sagt Jakob am Ende ?", options = listOf(), answers = listOf("vielen dank für die einladung", "vielen dank fur die einladung", "danke für die einladung"), explain = "« Vielen Dank für die Einladung ! »")), skills = listOf("listening:gist", "listening:detail", "vocab:social-expressions", "grammar:can")) }

object ListenData027 { val text = ListeningText(id = "de-listen-reklamation-rechnung", languageID = "de", title = "Anruf im Laden", level = "A2", topic = "reklamation", unitID = "de-foundations-u20", text = "Anna ruft im Laden ElektroPlus an. « Guten Tag, es tut mir leid, aber mein Wasserkocher funktioniert nicht mehr. » — « Das tut mir leid. Wann haben Sie ihn gekauft ? » — « Letzte Woche, am Montag. Ich habe die Rechnung hier. » — « Gut, dann können wir ihn umtauschen. Haben Sie ihn schon mit einer anderen Steckdose ausprobiert ? » — « Ja, zweimal. Er geht einfach nicht an. » — « Verstanden. Bringen Sie ihn und die Rechnung einfach vorbei, dann bekommen Sie ein neues Gerät. » — « Super, vielen Dank ! Bis morgen. »", questions = listOf(Exercise(id = "de-listen-reklamation-rechnung-q1", kind = "choice", prompt = "Was funktioniert nicht ?", options = listOf("Der Wasserkocher", "Die Kaffeemaschine", "Der Fernseher", "Der Drucker"), answers = listOf("Der Wasserkocher"), explain = "« Mein Wasserkocher funktioniert nicht mehr. »"), Exercise(id = "de-listen-reklamation-rechnung-q2", kind = "choice", prompt = "Wann hat Anna ihn gekauft ?", options = listOf("Letzte Woche, am Montag", "Gestern", "Im Mai", "Vor einem Monat"), answers = listOf("Letzte Woche, am Montag"), explain = "« Letzte Woche, am Montag. »"), Exercise(id = "de-listen-reklamation-rechnung-q3", kind = "written", prompt = "Welchen Beleg hat Anna ?", options = listOf(), answers = listOf("die rechnung", "eine rechnung"), explain = "« Ich habe die Rechnung hier. »"), Exercise(id = "de-listen-reklamation-rechnung-q4", kind = "written", prompt = "Was hat Anna schon ausprobiert ?", options = listOf(), answers = listOf("eine andere steckdose", "eine andere steckdose, zweimal", "eine andere steckdose zweimal"), explain = "« Haben Sie ihn schon mit einer anderen Steckdose ausprobiert ? » — « Ja, zweimal. »"), Exercise(id = "de-listen-reklamation-rechnung-q5", kind = "choice", prompt = "Was bekommt Anna am Ende ?", options = listOf("Ein neues Gerät", "Ihr Geld zurück", "Nur eine Reparatur", "Gar nichts"), answers = listOf("Ein neues Gerät"), explain = "« …dann bekommen Sie ein neues Gerät. »")), skills = listOf("listening:gist", "listening:detail", "function:solve-problems", "grammar:past-simple-regular")) }

object ListenData028 { val text = ListeningText(id = "de-listen-probevorstellung", languageID = "de", title = "Das Gespräch bei Frau Berger", level = "B1", topic = "arbeit", unitID = "de-foundations-u21", text = "Frau Berger führt das Gespräch. « Herr Moos, erzählen Sie kurz von Ihrer Erfahrung. » — « Ich habe drei Jahre in einer Marketingagentur gearbeitet, außerdem habe ich dort ein kleines Team geleitet. » — « Und was ist Ihre größte Stärke ? » — « Ich bleibe ruhig, wenn viel los ist. Letztes Jahr liefen zehn Projekte gleichzeitig — das hat gut funktioniert. » — « Warum haben Sie sich bei uns beworben ? » — « Weil Ihre Firma nachhaltig arbeitet. Das überzeugt mich. » Frau Berger nickt. « Wo sehen Sie sich in fünf Jahren ? » — « In einer Führungsrolle, aber zuerst will ich hier viel lernen. » — « Danke, wir melden uns bis Freitag. »", questions = listOf(Exercise(id = "de-listen-probevorstellung-q1", kind = "choice", prompt = "Warum hat sich Herr Moos beworben ?", options = listOf("Weil die Firma nachhaltig arbeitet", "Weil sie viel Geld zahlt", "Weil sie nah an seiner Wohnung liegt", "Weil sein Freund dort arbeitet"), answers = listOf("Weil die Firma nachhaltig arbeitet"), explain = "« Weil Ihre Firma nachhaltig arbeitet. Das überzeugt mich. »"), Exercise(id = "de-listen-probevorstellung-q2", kind = "written", prompt = "Was hat er in der Agentur geleitet ?", options = listOf(), answers = listOf("ein kleines team"), explain = "« Außerdem habe ich dort ein kleines Team geleitet. »"), Exercise(id = "de-listen-probevorstellung-q3", kind = "choice", prompt = "Wie reagiert er, wenn viel los ist ?", options = listOf("Er bleibt ruhig", "Er wird laut", "Er braucht Hilfe", "Er geht früher"), answers = listOf("Er bleibt ruhig"), explain = "« Ich bleibe ruhig, wenn viel los ist. »"), Exercise(id = "de-listen-probevorstellung-q4", kind = "written", prompt = "Wo sieht er sich in fünf Jahren ?", options = listOf(), answers = listOf("in einer führungsrolle", "in einer fuehrungsrolle", "in einer führenden rolle"), explain = "« In einer Führungsrolle … »"), Exercise(id = "de-listen-probevorstellung-q5", kind = "choice", prompt = "Was will er zuerst tun ?", options = listOf("In der Firma viel lernen", "Sofort Chef werden", "Die Firma wieder verlassen", "Ein eigenes Geschäft aufmachen"), answers = listOf("In der Firma viel lernen"), explain = "« …aber zuerst will ich hier viel lernen. »")), skills = listOf("listening:inference", "listening:detail", "vocab:work", "function:talk-about-work")) }

object ListenData029 { val text = ListeningText(id = "de-listen-ton-podcast", languageID = "de", title = "Podcast: Das passende Verb", level = "C1", topic = "sprache", unitID = "de-foundations-u9", text = "Im Podcast « Feines Deutsch » fragt Hörerin Katrin: « Warum klingt « eine Entscheidung machen » falsch ? » Wiebke erklärt: Kollokationen sind Gewohnheiten, keine Regeln — « treffen » gehört zur Entscheidung wie « üben » zur Kritik. Tarek ergänzt: « Wer das falsche Verb nimmt, macht keinen Fehler, der sofort auffällt — aber der Ton stimmt nicht ». Die beiden diskutieren, ob man solche Wendungen auswendig lernen soll. Wiebke hält Lesen für wirksamer: « Im Kontext bleibt die Verbindung hängen ». Am Ende geben sie der Hörerin einen Auftrag: eine Woche lang jede E-Mail auf ein einziges Verb prüfen — das, das man ersetzen könnte. « Genau genommen », lacht Tarek, « ist das die beste Übung für den genauen Ton ».", questions = listOf(Exercise(id = "de-listen-ton-podcast-q1", kind = "choice", prompt = "Was sind Kollokationen laut Wiebke ?", options = listOf("Gewohnheiten, keine Regeln", "Feste Grammatikregeln", "Fremdwörter aus dem Englischen", "Fehler, die auffallen"), answers = listOf("Gewohnheiten, keine Regeln"), explain = "« Kollokationen sind Gewohnheiten, keine Regeln. »"), Exercise(id = "de-listen-ton-podcast-q2", kind = "written", prompt = "Welches Verb gehört zur Kritik ?", options = listOf(), answers = listOf("üben", "ueben"), explain = "« …wie « üben » zur Kritik. »"), Exercise(id = "de-listen-ton-podcast-q3", kind = "choice", prompt = "Was meint Tarek mit « der Ton stimmt nicht » ?", options = listOf("Es klingt nicht muttersprachlich", "Die Grammatik ist falsch", "Die Mail ist zu lang", "Die Musik ist zu laut"), answers = listOf("Es klingt nicht muttersprachlich"), explain = "« …macht keinen Fehler, der sofort auffällt — aber der Ton stimmt nicht. »"), Exercise(id = "de-listen-ton-podcast-q4", kind = "choice", prompt = "Was hält Wiebke für wirksamer als Auswendiglernen ?", options = listOf("Lesen im Kontext", "Wortlisten schreiben", "Vokabel-Apps", "Alles übersetzen"), answers = listOf("Lesen im Kontext"), explain = "« Im Kontext bleibt die Verbindung hängen. »"), Exercise(id = "de-listen-ton-podcast-q5", kind = "written", prompt = "Welchen Auftrag bekommen die Hörer ?", options = listOf(), answers = listOf("jede e-mail auf ein verb prüfen", "jede email auf ein verb pruefen", "eine woche lang jede e-mail auf ein verb prüfen"), explain = "« …eine Woche lang jede E-Mail auf ein einziges Verb prüfen. »")), skills = listOf("listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion")) }

object ListenData030 { val text = ListeningText(id = "en-listen-language-cafe", languageID = "en", title = "The language café", level = "A1", topic = "introductions", unitID = "en-foundations-u1", text = "Every Wednesday evening, a small café in the city centre is a language café. Students from many countries sit together at big tables. Lucas is twenty-five years old, and he is from Brazil. His Portuguese and Spanish are excellent, and his English is quite good now. At his table there is a woman from Japan and two men from Italy. They ask simple questions: Where are you from? What do you do? Lucas is a nurse, and he is happy to answer. At ten o'clock the café closes, but the new friends are not tired. They are only happy to talk.", questions = listOf(Exercise(id = "en-listen-language-cafe-q1", kind = "choice", prompt = "Where is the language café?", options = listOf("In a small café in the city centre", "In a school", "In a park", "In a hotel"), answers = listOf("In a small café in the city centre"), explain = "Every Wednesday evening, a small café in the city centre is a language café."), Exercise(id = "en-listen-language-cafe-q2", kind = "choice", prompt = "Where is Lucas from?", options = listOf("Brazil", "Japan", "Italy", "Portugal"), answers = listOf("Brazil"), explain = "Lucas is from Brazil."), Exercise(id = "en-listen-language-cafe-q3", kind = "written", prompt = "How old is Lucas?", options = listOf(), answers = listOf("twenty-five", "25", "he is twenty-five"), explain = "Lucas is twenty-five years old."), Exercise(id = "en-listen-language-cafe-q4", kind = "choice", prompt = "What is his job?", options = listOf("He is a nurse", "He is a teacher", "He is a waiter", "He is a student"), answers = listOf("He is a nurse"), explain = "Lucas is a nurse, and he is happy to answer."), Exercise(id = "en-listen-language-cafe-q5", kind = "choice", prompt = "Who sits at his table?", options = listOf("A woman from Japan and two men from Italy", "Two women from Brazil", "A man from Japan", "Four students from Spain"), answers = listOf("A woman from Japan and two men from Italy"), explain = "At his table there is a woman from Japan and two men from Italy."), Exercise(id = "en-listen-language-cafe-q6", kind = "written", prompt = "What time does the café close?", options = listOf(), answers = listOf("at ten o'clock", "ten o'clock", "ten"), explain = "At ten o'clock the café closes.")), skills = listOf("listening:gist", "listening:detail", "vocab:introductions", "function:introduce-yourself")) }

object ListenData031 { val text = ListeningText(id = "en-listen-new-neighbour", languageID = "en", title = "The new neighbour", level = "A1", topic = "people", unitID = "en-foundations-u1", text = "There is a new neighbour in the building. Her name is Amélie, and she is from France. She is not a student; she is a photographer. She doesn't work in an office — she works at home, and she travels a lot. The people in the building are curious, but they are also shy, so they don't talk to her. Then one morning, Ben meets her at the door. \"Are you the new neighbour?\" he asks. \"Yes, I am,\" she says, \"and I am happy to be here.\" Now they are friends, and she isn't alone in the building.", questions = listOf(Exercise(id = "en-listen-new-neighbour-q1", kind = "choice", prompt = "Where is Amélie from?", options = listOf("France", "Italy", "Japan", "Brazil"), answers = listOf("France"), explain = "Amélie is from France."), Exercise(id = "en-listen-new-neighbour-q2", kind = "choice", prompt = "What is her job?", options = listOf("She is a photographer", "She is a student", "She works in an office", "She is a teacher"), answers = listOf("She is a photographer"), explain = "She is not a student; she is a photographer."), Exercise(id = "en-listen-new-neighbour-q3", kind = "choice", prompt = "Does she work in an office?", options = listOf("No, she works at home", "Yes, every day", "Only in summer", "She doesn't say"), answers = listOf("No, she works at home"), explain = "She doesn't work in an office — she works at home."), Exercise(id = "en-listen-new-neighbour-q4", kind = "written", prompt = "Why don't the people talk to her?", options = listOf(), answers = listOf("they are shy", "because they are shy", "shy"), explain = "They are curious, but they are also shy."), Exercise(id = "en-listen-new-neighbour-q5", kind = "choice", prompt = "Where does Ben meet her?", options = listOf("At the door", "In the lift", "In the street", "At the café"), answers = listOf("At the door"), explain = "One morning, Ben meets her at the door."), Exercise(id = "en-listen-new-neighbour-q6", kind = "written", prompt = "How does Amélie feel at the end?", options = listOf(), answers = listOf("happy", "she is happy", "happy to be here"), explain = "She says she is happy to be here.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")) }

object ListenData032 { val text = ListeningText(id = "en-listen-lost-umbrella", languageID = "en", title = "The blue umbrella", level = "A1", topic = "things", unitID = "en-foundations-u2", text = "It is a rainy Monday, and the classroom is full of umbrellas. \"Whose umbrella is this?\" the teacher asks. It is a big blue umbrella, and it is next to my chair. \"It isn't mine,\" says Marta. \"My umbrella is green.\" \"Is it yours, Pedro?\" \"No, it isn't. My things are in my bag.\" Then Daniel comes in, wet and tired. He looks at the blue umbrella and laughs. \"That's my umbrella! It's my father's umbrella, and he needs it today.\" The class laughs too. Daniel takes his umbrella, and the teacher writes on the board: your, my, his, her.", questions = listOf(Exercise(id = "en-listen-lost-umbrella-q1", kind = "choice", prompt = "What is the weather like?", options = listOf("Rainy", "Sunny", "Snowy", "Windy and dry"), answers = listOf("Rainy"), explain = "It is a rainy Monday."), Exercise(id = "en-listen-lost-umbrella-q2", kind = "choice", prompt = "What colour is the umbrella next to the chair?", options = listOf("Blue", "Green", "Black", "Red"), answers = listOf("Blue"), explain = "It is a big blue umbrella."), Exercise(id = "en-listen-lost-umbrella-q3", kind = "written", prompt = "What colour is Marta's umbrella?", options = listOf(), answers = listOf("green", "it is green", "her umbrella is green"), explain = "Marta's umbrella is green."), Exercise(id = "en-listen-lost-umbrella-q4", kind = "choice", prompt = "Whose umbrella is the blue one?", options = listOf("Daniel's", "Marta's", "Pedro's", "The teacher's"), answers = listOf("Daniel's"), explain = "Daniel says it is his umbrella — his father's umbrella."), Exercise(id = "en-listen-lost-umbrella-q5", kind = "choice", prompt = "Where are Pedro's things?", options = listOf("In his bag", "At home", "In his car", "Under the chair"), answers = listOf("In his bag"), explain = "Pedro says his things are in his bag."), Exercise(id = "en-listen-lost-umbrella-q6", kind = "choice", prompt = "Why does Daniel need the umbrella today?", options = listOf("His father needs it", "It is a gift for Marta", "It is for the teacher", "He wants to sell it"), answers = listOf("His father needs it"), explain = "It is his father's umbrella, and his father needs it today.")), skills = listOf("listening:detail", "grammar:demonstratives", "vocab:social-expressions")) }

object ListenData033 { val text = ListeningText(id = "en-listen-new-flatmate", languageID = "en", title = "A new flatmate", level = "A1", topic = "home", unitID = "en-foundations-u2", text = "Tom has got a new flatmate. His name is Leo and he is twenty-three years old. Leo comes from a small town in the north, but he works in the city now. He has got two boxes, a guitar and a bicycle. The flat has got two bedrooms and a sunny kitchen. Tom hopes Leo likes cooking, because Tom hates it.", questions = listOf(Exercise(id = "en-listen-new-flatmate-q1", kind = "choice", prompt = "How old is Leo?", options = listOf("Twenty-three", "Thirty-two", "Twenty", "Thirty"), answers = listOf("Twenty-three"), explain = "Leo is twenty-three years old."), Exercise(id = "en-listen-new-flatmate-q2", kind = "choice", prompt = "What has Leo NOT got?", options = listOf("A television", "Two boxes", "A guitar", "A bicycle"), answers = listOf("A television"), explain = "He has two boxes, a guitar and a bicycle — no television."), Exercise(id = "en-listen-new-flatmate-q3", kind = "written", prompt = "What does Tom hate doing?", options = listOf(), answers = listOf("cooking", "he hates cooking", "tom hates cooking"), explain = "Tom hates cooking."), Exercise(id = "en-listen-new-flatmate-q4", kind = "choice", prompt = "What does the flat have?", options = listOf("Two bedrooms and a sunny kitchen", "One bedroom and a balcony", "A garden", "Two bathrooms"), answers = listOf("Two bedrooms and a sunny kitchen"), explain = "The flat has got two bedrooms and a sunny kitchen."), Exercise(id = "en-listen-new-flatmate-q5", kind = "choice", prompt = "Where does Leo work now?", options = listOf("In the city", "In a small town", "In the north", "He doesn't work"), answers = listOf("In the city"), explain = "He comes from a small town, but he works in the city now."), Exercise(id = "en-listen-new-flatmate-q6", kind = "written", prompt = "Which instrument has Leo got?", options = listOf(), answers = listOf("a guitar", "guitar", "he has got a guitar"), explain = "Leo has got a guitar.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")) }

object ListenData034 { val text = ListeningText(id = "en-listen-coffee-morning", languageID = "en", title = "A coffee before work", level = "A1", topic = "routine", unitID = "en-foundations-u3", text = "Every morning, Marta walks to a small café near her flat. The waiter knows her name, so she never has to order. Today she sits by the window with a coffee and a croissant. Her bus leaves at half past eight, but she is not worried. The café is very quiet at this hour. She drinks her coffee slowly and watches the city wake up.", questions = listOf(Exercise(id = "en-listen-coffee-morning-q1", kind = "choice", prompt = "Where does Marta go every morning?", options = listOf("To a small café", "To her office", "To the bus station", "To a park"), answers = listOf("To a small café"), explain = "She walks to a small café near her flat."), Exercise(id = "en-listen-coffee-morning-q2", kind = "choice", prompt = "What does she have for breakfast today?", options = listOf("Tea and toast", "A coffee and a croissant", "Orange juice", "Nothing"), answers = listOf("A coffee and a croissant"), explain = "She sits by the window with a coffee and a croissant."), Exercise(id = "en-listen-coffee-morning-q3", kind = "written", prompt = "What time does her bus leave?", options = listOf(), answers = listOf("at half past eight", "half past eight", "8:30"), explain = "Her bus leaves at half past eight."), Exercise(id = "en-listen-coffee-morning-q4", kind = "choice", prompt = "How does she feel about the time?", options = listOf("She is not worried", "She is very late", "She is angry", "She is sleepy"), answers = listOf("She is not worried"), explain = "The text says she is not worried."), Exercise(id = "en-listen-coffee-morning-q5", kind = "choice", prompt = "Who knows Marta's name?", options = listOf("The waiter", "The bus driver", "Her boss", "A neighbour"), answers = listOf("The waiter"), explain = "The waiter knows her name, so she never has to order."), Exercise(id = "en-listen-coffee-morning-q6", kind = "written", prompt = "Where does she sit today?", options = listOf(), answers = listOf("by the window", "next to the window", "at the window"), explain = "Today she sits by the window.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")) }

object ListenData035 { val text = ListeningText(id = "en-listen-night-shift", languageID = "en", title = "The night shift", level = "A1", topic = "work", unitID = "en-foundations-u3", text = "Paolo is a baker, and he works at night. His shift starts at eleven o'clock in the evening, and it finishes at seven in the morning. First, he makes the bread; then he makes the cakes. He never works alone — his cousin works with him, and they talk while they work. Paolo usually sleeps from nine in the morning to three in the afternoon. On Sundays he doesn't work, and he has lunch with his family. His neighbours sometimes ask him: \"Do you like your job?\" \"Yes,\" he says, \"the city is quiet, the bread smells wonderful, and my mornings are free.\"", questions = listOf(Exercise(id = "en-listen-night-shift-q1", kind = "choice", prompt = "When does Paolo's shift start?", options = listOf("At eleven in the evening", "At seven in the morning", "At nine in the morning", "At three in the afternoon"), answers = listOf("At eleven in the evening"), explain = "His shift starts at eleven o'clock in the evening."), Exercise(id = "en-listen-night-shift-q2", kind = "written", prompt = "What does he make first?", options = listOf(), answers = listOf("bread", "the bread", "he makes the bread"), explain = "First, he makes the bread; then the cakes."), Exercise(id = "en-listen-night-shift-q3", kind = "choice", prompt = "Who works with him?", options = listOf("His cousin", "His brother", "His wife", "A friend from school"), answers = listOf("His cousin"), explain = "He never works alone — his cousin works with him."), Exercise(id = "en-listen-night-shift-q4", kind = "written", prompt = "When does Paolo usually sleep?", options = listOf(), answers = listOf("from nine to three", "from nine in the morning to three in the afternoon", "nine to three"), explain = "He usually sleeps from nine in the morning to three in the afternoon."), Exercise(id = "en-listen-night-shift-q5", kind = "choice", prompt = "What does he do on Sundays?", options = listOf("He has lunch with his family", "He sleeps all day", "He works alone", "He bakes cakes at home"), answers = listOf("He has lunch with his family"), explain = "On Sundays he doesn't work, and he has lunch with his family."), Exercise(id = "en-listen-night-shift-q6", kind = "choice", prompt = "Why does Paolo like his job?", options = listOf("The city is quiet and the bread smells wonderful", "It is very well paid", "He meets a lot of people", "The nights are long"), answers = listOf("The city is quiet and the bread smells wonderful"), explain = "He says the city is quiet, the bread smells wonderful and his mornings are free.")), skills = listOf("listening:number-time", "listening:detail", "grammar:third-person-s", "grammar:frequency-adverbs", "vocab:work")) }

object ListenData036 { val text = ListeningText(id = "en-listen-city-walk", languageID = "en", title = "A walk in the new city", level = "A1", topic = "directions", unitID = "en-foundations-u4", text = "Nadia is new in town, and today she explores on foot. In her street there is a small supermarket, a bakery and a bookshop — everything is very close, so she doesn't need the bus. She walks to the river and turns left. There, she can see the old bridge and a big park. In the park there are children, dogs and a lot of green space. She can't visit the museum because it is closed on Mondays, but she can sit in the sun. A man with a dog gives her directions to the market: \"Go straight, cross the bridge, and the market is on your right.\" She thanks him and walks on.", questions = listOf(Exercise(id = "en-listen-city-walk-q1", kind = "choice", prompt = "How does Nadia explore the city?", options = listOf("On foot", "By bus", "By bike", "By tram"), answers = listOf("On foot"), explain = "Today she explores on foot."), Exercise(id = "en-listen-city-walk-q2", kind = "choice", prompt = "What is in her street?", options = listOf("A supermarket, a bakery and a bookshop", "A cinema and a café", "A school", "A hospital"), answers = listOf("A supermarket, a bakery and a bookshop"), explain = "In her street there is a small supermarket, a bakery and a bookshop."), Exercise(id = "en-listen-city-walk-q3", kind = "choice", prompt = "What can she see from the river?", options = listOf("The old bridge and a big park", "A castle", "The museum", "A shopping centre"), answers = listOf("The old bridge and a big park"), explain = "From the river she can see the old bridge and a big park."), Exercise(id = "en-listen-city-walk-q4", kind = "choice", prompt = "Why can't she visit the museum?", options = listOf("It is closed on Mondays", "She doesn't have time", "It is too expensive", "She can't find it"), answers = listOf("It is closed on Mondays"), explain = "The museum is closed on Mondays."), Exercise(id = "en-listen-city-walk-q5", kind = "written", prompt = "Where is the market?", options = listOf(), answers = listOf("on your right", "on the right", "on her right"), explain = "Cross the bridge, and the market is on your right."), Exercise(id = "en-listen-city-walk-q6", kind = "written", prompt = "Who gives her directions?", options = listOf(), answers = listOf("a man with a dog", "a man", "the man with the dog"), explain = "A man with a dog gives her directions.")), skills = listOf("listening:detail", "function:ask-for-directions", "vocab:directions", "grammar:imperatives")) }

object ListenData037 { val text = ListeningText(id = "en-listen-bus-stop-chat", languageID = "en", title = "The bus stop chat", level = "A1", topic = "people", unitID = "en-foundations-out", text = "It's cold at the bus stop, and Ben doesn't like silence. 'Cold today, isn't it?' he says to the woman next to him. 'Freezing,' she says. 'Any plans for the weekend?' Ben asks. 'Nothing much — you?' 'My sister is visiting, so we'll walk by the river if it doesn't rain.' The woman smiles. 'Sounds nice. My plans are tea and a book!' The bus arrives — late, of course. 'Have a good one!' Ben says as she gets on. 'You too!' And that's it: a complete conversation with a stranger, sixty seconds long.", questions = listOf(Exercise(id = "en-listen-bus-stop-chat-q1", kind = "choice", prompt = "How does Ben open the conversation?", options = listOf("About the cold", "About the bus", "About the river", "About tea"), answers = listOf("About the cold"), explain = "'Cold today, isn't it?' — the weather opener."), Exercise(id = "en-listen-bus-stop-chat-q2", kind = "written", prompt = "What are the woman's plans for the weekend?", options = listOf(), answers = listOf("tea and a book", "tea", "a book"), explain = "Her plans are tea and a book."), Exercise(id = "en-listen-bus-stop-chat-q3", kind = "choice", prompt = "Who is visiting Ben?", options = listOf("His sister", "His mother", "A neighbour", "Nobody"), answers = listOf("His sister"), explain = "His sister is visiting, so they'll walk by the river."), Exercise(id = "en-listen-bus-stop-chat-q4", kind = "written", prompt = "Where will they walk if it doesn't rain?", options = listOf(), answers = listOf("by the river", "the river"), explain = "By the river."), Exercise(id = "en-listen-bus-stop-chat-q5", kind = "choice", prompt = "How does the bus arrive?", options = listOf("Late, of course", "Early", "Full", "It never arrives"), answers = listOf("Late, of course"), explain = "The bus arrives — late, of course."), Exercise(id = "en-listen-bus-stop-chat-q6", kind = "written", prompt = "How does Ben say goodbye?", options = listOf(), answers = listOf("have a good one", "have a good one!"), explain = "'Have a good one!' as she gets on.")), skills = listOf("vocab:social-expressions", "grammar:present-continuous", "function:talk-about-weather")) }

object ListenData038 { val text = ListeningText(id = "en-listen-saturday-list", languageID = "en", title = "The Saturday list", level = "A1", topic = "shopping", unitID = "en-foundations-out", text = "Saturday morning, and Marta is at the supermarket with a long list. She needs bread, milk, eggs and tomatoes, but she can't find the tomatoes. A shop assistant is stacking apples nearby. 'Excuse me, where are the tomatoes?' Marta asks. 'Aisle three, next to the juice,' the assistant says. Marta finds them, checks the price — two euros fifty — and goes to the checkout. 'Anything else?' the cashier asks. 'No, that's all, thanks!' At home, she unpacks the bag and finds one thing missing: the bread. It's still on the kitchen table, next to her keys.", questions = listOf(Exercise(id = "en-listen-saturday-list-q1", kind = "choice", prompt = "What is NOT on Marta's list?", options = listOf("Tomatoes", "Bread", "Milk", "Apples"), answers = listOf("Apples"), explain = "The apples belong to the shop assistant, not the list."), Exercise(id = "en-listen-saturday-list-q2", kind = "written", prompt = "Where are the tomatoes?", options = listOf(), answers = listOf("aisle three", "in aisle three", "aisle 3"), explain = "Aisle three, next to the juice."), Exercise(id = "en-listen-saturday-list-q3", kind = "choice", prompt = "How much are the tomatoes?", options = listOf("Two euros fifty", "Three euros", "Two euros", "Fifty cents"), answers = listOf("Two euros fifty"), explain = "She checks the price: two euros fifty."), Exercise(id = "en-listen-saturday-list-q4", kind = "written", prompt = "What does the cashier ask?", options = listOf(), answers = listOf("anything else", "anything else?"), explain = "'Anything else?' — the cashier's question."), Exercise(id = "en-listen-saturday-list-q5", kind = "choice", prompt = "What is missing at home?", options = listOf("The bread", "The milk", "The eggs", "The tomatoes"), answers = listOf("The bread"), explain = "The bread is still on the kitchen table."), Exercise(id = "en-listen-saturday-list-q6", kind = "written", prompt = "What else is on the kitchen table?", options = listOf(), answers = listOf("her keys", "the keys", "keys"), explain = "Her keys are next to the bread.")), skills = listOf("vocab:food", "grammar:there-is-are", "grammar:present-simple", "function:go-shopping")) }

object ListenData039 { val text = ListeningText(id = "en-listen-sunday-market", languageID = "en", title = "The Sunday market", level = "A1", topic = "shopping", unitID = "en-foundations-u4", text = "On Sundays there is a market in the town square. Anna and her father go there at nine o'clock, before it gets busy. They buy fruit, bread and flowers. Anna wants some strawberries, but her father says they are too expensive this week. In the end they take home a big bag of oranges and some white roses for the kitchen table.", questions = listOf(Exercise(id = "en-listen-sunday-market-q1", kind = "choice", prompt = "When do Anna and her father go to the market?", options = listOf("At nine o'clock", "At noon", "In the afternoon", "At half past six"), answers = listOf("At nine o'clock"), explain = "They go at nine o'clock, before it gets busy."), Exercise(id = "en-listen-sunday-market-q2", kind = "written", prompt = "Why doesn't Anna get the strawberries?", options = listOf(), answers = listOf("they are too expensive", "too expensive", "because they are too expensive"), explain = "Her father says they are too expensive this week."), Exercise(id = "en-listen-sunday-market-q3", kind = "choice", prompt = "What do they take home?", options = listOf("Oranges and roses", "Strawberries and bread", "Apples and tulips", "Bread and cheese"), answers = listOf("Oranges and roses"), explain = "They take home oranges and white roses."), Exercise(id = "en-listen-sunday-market-q4", kind = "choice", prompt = "Where is the market?", options = listOf("In the town square", "Near the river", "At the station", "In a supermarket"), answers = listOf("In the town square"), explain = "There is a market in the town square on Sundays."), Exercise(id = "en-listen-sunday-market-q5", kind = "choice", prompt = "What do they buy?", options = listOf("Fruit, bread and flowers", "Fish and vegetables", "Cheese and meat", "Only flowers"), answers = listOf("Fruit, bread and flowers"), explain = "They buy fruit, bread and flowers."), Exercise(id = "en-listen-sunday-market-q6", kind = "written", prompt = "What does Anna want?", options = listOf(), answers = listOf("strawberries", "some strawberries", "she wants strawberries"), explain = "Anna wants some strawberries.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")) }

object ListenData040 { val text = ListeningText(id = "en-listen-new-neighbourhood", languageID = "en", title = "The new neighbourhood", level = "A1", topic = "town", unitID = "en-foundations-town", text = "Sofia just moved to Maple Street, and her new neighbour Tom is telling her everything. 'There's a bakery on the corner — the bread is fantastic. There are two schools, a park and a small library. There isn't a cinema, I'm afraid; the nearest one is two bus stops away.' Sofia asks about the park: 'Is there a chemist's near the park?' 'Yes, right next to it,' Tom says. 'And the people?' Sofia wants to know. 'They're friendly and very quiet,' Tom laughs, 'except on Saturdays, when the football starts.'", questions = listOf(Exercise(id = "en-listen-new-neighbourhood-q1", kind = "choice", prompt = "What is on the corner?", options = listOf("A bakery", "A park", "A library", "A cinema"), answers = listOf("A bakery"), explain = "There's a bakery on the corner — fantastic bread."), Exercise(id = "en-listen-new-neighbourhood-q2", kind = "written", prompt = "What is there two of?", options = listOf(), answers = listOf("schools", "two schools"), explain = "There are two schools."), Exercise(id = "en-listen-new-neighbourhood-q3", kind = "choice", prompt = "What is missing in the neighbourhood?", options = listOf("A cinema", "A library", "A bakery", "A park"), answers = listOf("A cinema"), explain = "There isn't a cinema — the nearest is two bus stops away."), Exercise(id = "en-listen-new-neighbourhood-q4", kind = "written", prompt = "Where is the chemist's?", options = listOf(), answers = listOf("next to the park", "near the park", "right next to the park"), explain = "Right next to the park."), Exercise(id = "en-listen-new-neighbourhood-q5", kind = "choice", prompt = "What are the people like?", options = listOf("Friendly and quiet", "Loud", "Unfriendly", "Always at football"), answers = listOf("Friendly and quiet"), explain = "Friendly and very quiet — except on Saturdays."), Exercise(id = "en-listen-new-neighbourhood-q6", kind = "written", prompt = "What starts on Saturdays?", options = listOf(), answers = listOf("the football", "football"), explain = "The football starts on Saturdays.")), skills = listOf("vocab:town", "grammar:there-is-are", "function:ask-simple-questions")) }

object ListenData041 { val text = ListeningText(id = "en-listen-rainy-day", languageID = "en", title = "A rainy Saturday", level = "A1", topic = "weather", unitID = "en-foundations-now", text = "It is raining in Maple Street, and Anna is looking out of the window. Her brother Ben is playing a video game in the living room, and their mother is reading on the sofa. Outside, the neighbours are running to their cars with umbrellas. The cat is sleeping in its favourite chair, and the dog is watching the rain too. Anna is not bored — she is drawing the grey sky in her notebook. Her mother is making tea, and the kitchen smells wonderful. 'What are you doing?' Ben asks. 'I'm drawing the weather,' Anna says, 'because today the weather is interesting!'", questions = listOf(Exercise(id = "en-listen-rainy-day-q1", kind = "choice", prompt = "What is the weather doing?", options = listOf("It's raining", "It's snowing", "It's sunny", "It's windy"), answers = listOf("It's raining"), explain = "It is raining in Maple Street."), Exercise(id = "en-listen-rainy-day-q2", kind = "choice", prompt = "What is Ben doing?", options = listOf("He's playing a video game", "He's drawing", "He's making tea", "He's sleeping"), answers = listOf("He's playing a video game"), explain = "Her brother Ben is playing a video game."), Exercise(id = "en-listen-rainy-day-q3", kind = "written", prompt = "What is Anna drawing?", options = listOf(), answers = listOf("the grey sky", "the sky", "the weather"), explain = "She is drawing the grey sky in her notebook."), Exercise(id = "en-listen-rainy-day-q4", kind = "choice", prompt = "Where is the cat?", options = listOf("In its favourite chair", "Under the table", "Outside in the rain", "On Anna's bed"), answers = listOf("In its favourite chair"), explain = "The cat is sleeping in its favourite chair."), Exercise(id = "en-listen-rainy-day-q5", kind = "written", prompt = "What is the mother making?", options = listOf(), answers = listOf("tea", "making tea", "she is making tea"), explain = "Her mother is making tea."), Exercise(id = "en-listen-rainy-day-q6", kind = "choice", prompt = "How does Anna feel about the day?", options = listOf("She is not bored", "She is sad", "She is angry", "She is tired"), answers = listOf("She is not bored"), explain = "Anna is not bored — for her the weather is interesting.")), skills = listOf("listening:detail", "grammar:present-continuous", "vocab:weather")) }

object ListenData042 { val text = ListeningText(id = "en-listen-busy-kitchen", languageID = "en", title = "Sunday in the kitchen", level = "A1", topic = "family", unitID = "en-foundations-now", text = "It is Sunday morning, and the whole family is in the kitchen. Grandma is cutting bread, and Grandpa is making coffee — his coffee is always too strong. Anna's father is singing while he is cooking eggs, and her mother is setting the table. The twins are helping, but they are eating more strawberries than they are putting in the bowl. Even the dog is working: he is waiting under the table for pieces of cheese. 'Is anyone NOT eating in this kitchen?' Grandpa laughs. Everyone is smiling. Sunday breakfast is the family's favourite moment of the week.", questions = listOf(Exercise(id = "en-listen-busy-kitchen-q1", kind = "choice", prompt = "Where is the whole family?", options = listOf("In the kitchen", "In the garden", "In the car", "At a café"), answers = listOf("In the kitchen"), explain = "The whole family is in the kitchen on Sunday morning."), Exercise(id = "en-listen-busy-kitchen-q2", kind = "written", prompt = "What is Grandma doing?", options = listOf(), answers = listOf("cutting bread", "she is cutting bread", "she's cutting bread"), explain = "Grandma is cutting bread."), Exercise(id = "en-listen-busy-kitchen-q3", kind = "choice", prompt = "What is Grandpa's coffee like?", options = listOf("Always too strong", "Cold", "Perfect", "Without sugar"), answers = listOf("Always too strong"), explain = "His coffee is always too strong."), Exercise(id = "en-listen-busy-kitchen-q4", kind = "written", prompt = "What is the father doing while he cooks?", options = listOf(), answers = listOf("singing", "he is singing", "he's singing"), explain = "He is singing while he is cooking eggs."), Exercise(id = "en-listen-busy-kitchen-q5", kind = "choice", prompt = "What are the twins really doing with the strawberries?", options = listOf("Eating them", "Washing them", "Selling them", "Cutting them"), answers = listOf("Eating them"), explain = "They are eating more strawberries than they are putting in the bowl."), Exercise(id = "en-listen-busy-kitchen-q6", kind = "written", prompt = "What is the dog waiting for?", options = listOf(), answers = listOf("pieces of cheese", "cheese", "some cheese"), explain = "He is waiting under the table for pieces of cheese.")), skills = listOf("listening:gist", "grammar:present-continuous", "vocab:family")) }

object ListenData043 { val text = ListeningText(id = "en-listen-birthday-week", languageID = "en", title = "The birthday week", level = "A1", topic = "dates", unitID = "en-foundations-days", text = "This is a special week for Leo. His birthday is on Friday, 12 September, and his family is planning three small parties. On Monday, his colleagues are taking him to a café after work. On Wednesday, his friends are coming to his flat for a film night — his sister is making her famous chocolate cake on Thursday, so the flat smells of chocolate for two days. The family party is on Saturday at three o'clock, at his grandparents' house. Leo's favourite day? 'Sunday,' he laughs, 'because then I can finally rest — my birthday week is wonderful but very busy!'", questions = listOf(Exercise(id = "en-listen-birthday-week-q1", kind = "written", prompt = "When is Leo's birthday?", options = listOf(), answers = listOf("on friday 12 september", "friday 12 september", "12 september", "friday 12th september"), explain = "His birthday is on Friday, 12 September."), Exercise(id = "en-listen-birthday-week-q2", kind = "choice", prompt = "What are his colleagues doing on Monday?", options = listOf("Taking him to a café", "Cooking a cake", "Coming to his flat", "Resting"), answers = listOf("Taking him to a café"), explain = "On Monday, his colleagues are taking him to a café after work."), Exercise(id = "en-listen-birthday-week-q3", kind = "choice", prompt = "When is the family party?", options = listOf("On Saturday at three o'clock", "On Wednesday evening", "On Friday at work", "On Monday morning"), answers = listOf("On Saturday at three o'clock"), explain = "The family party is on Saturday at three o'clock."), Exercise(id = "en-listen-birthday-week-q4", kind = "written", prompt = "What is his sister making, and when?", options = listOf(), answers = listOf("chocolate cake on thursday", "a chocolate cake on thursday", "chocolate cake, on thursday"), explain = "She is making her famous chocolate cake on Thursday."), Exercise(id = "en-listen-birthday-week-q5", kind = "choice", prompt = "Where is the family party?", options = listOf("At his grandparents' house", "At a café", "At his flat", "At work"), answers = listOf("At his grandparents' house"), explain = "It is at his grandparents' house."), Exercise(id = "en-listen-birthday-week-q6", kind = "written", prompt = "What is Leo's favourite day of the week? Why? (one word for the day)", options = listOf(), answers = listOf("sunday", "on sunday", "sunday because he can rest"), explain = "Sunday — because then he can finally rest.")), skills = listOf("listening:number-time", "grammar:time-expressions", "function:tell-time"), exposureSkills = listOf("grammar:present-continuous")) }

object ListenData044 { val text = ListeningText(id = "en-listen-not-feeling-well", languageID = "en", title = "Not feeling well", level = "A1", topic = "health", unitID = "en-foundations-days", text = "Daniel doesn't feel well this morning. He has got a headache and a sore throat, and his whole body is tired. At work, his colleague Sofia notices immediately. 'What's wrong?' she asks. 'I've got a cold, I think,' Daniel says. 'My throat hurts, and I can't stop sneezing.' Sofia is worried. 'Go home and rest! Drink hot tea with honey — my grandmother's recipe.' Daniel takes her advice. In the afternoon, he is in bed with a big cup of tea. His cat is sleeping next to him. On Friday he is back at work, and his colleagues say he looks great.", questions = listOf(Exercise(id = "en-listen-not-feeling-well-q1", kind = "choice", prompt = "How does Daniel feel this morning?", options = listOf("He doesn't feel well", "He feels great", "He is angry", "He is hungry"), answers = listOf("He doesn't feel well"), explain = "Daniel doesn't feel well this morning."), Exercise(id = "en-listen-not-feeling-well-q2", kind = "written", prompt = "What has Daniel got?", options = listOf(), answers = listOf("a cold", "he has got a cold", "he's got a cold", "a headache and a cold"), explain = "He thinks he has got a cold."), Exercise(id = "en-listen-not-feeling-well-q3", kind = "choice", prompt = "Who notices first?", options = listOf("His colleague Sofia", "His mother", "His cat", "His boss"), answers = listOf("His colleague Sofia"), explain = "His colleague Sofia notices immediately."), Exercise(id = "en-listen-not-feeling-well-q4", kind = "written", prompt = "What does Sofia recommend?", options = listOf(), answers = listOf("hot tea with honey", "tea with honey", "go home and rest"), explain = "Hot tea with honey — her grandmother's recipe."), Exercise(id = "en-listen-not-feeling-well-q5", kind = "choice", prompt = "Where is Daniel in the afternoon?", options = listOf("In bed with a cup of tea", "At the pharmacy", "At work", "At Sofia's house"), answers = listOf("In bed with a cup of tea"), explain = "He is in bed with a big cup of tea."), Exercise(id = "en-listen-not-feeling-well-q6", kind = "choice", prompt = "When is he back at work?", options = listOf("On Friday", "On Monday", "The same afternoon", "On Wednesday"), answers = listOf("On Friday"), explain = "On Friday he is back at work and looks great.")), skills = listOf("listening:detail", "vocab:health", "grammar:have-got", "grammar:can")) }

object ListenData045 { val text = ListeningText(id = "en-listen-language-exchange", languageID = "en", title = "The language-exchange evening", level = "A2", topic = "languages", unitID = "en-foundations-u5", text = "Last Thursday, Ines went to a language exchange at a bar in the old town. She wanted to practise her English, so she sat with a group from Manchester. At first she could only smile and nod. But after half an hour the words started to come. They talked about films, football and the differences between Spanish and English breakfasts. She didn't leave until eleven, and she wrote down fifteen new expressions on the tram home.", questions = listOf(Exercise(id = "en-listen-language-exchange-q1", kind = "choice", prompt = "Why did Ines go to the exchange?", options = listOf("To practise her English", "To watch football", "To eat breakfast", "To teach maths"), answers = listOf("To practise her English"), explain = "She wanted to practise her English."), Exercise(id = "en-listen-language-exchange-q2", kind = "written", prompt = "What could she do at first?", options = listOf(), answers = listOf("she could only smile and nod", "smile and nod", "only smile and nod"), explain = "At first she could only smile and nod."), Exercise(id = "en-listen-language-exchange-q3", kind = "choice", prompt = "What did they NOT talk about?", options = listOf("Their jobs", "Films", "Football", "Breakfasts"), answers = listOf("Their jobs"), explain = "They talked about films, football and breakfasts — not jobs."), Exercise(id = "en-listen-language-exchange-q4", kind = "written", prompt = "What did she do on the tram home?", options = listOf(), answers = listOf("she wrote down fifteen new expressions", "she wrote down new expressions", "wrote down fifteen expressions"), explain = "She wrote down fifteen new expressions."), Exercise(id = "en-listen-language-exchange-q5", kind = "choice", prompt = "Where did the exchange take place?", options = listOf("In a bar in the old town", "In a school", "In a library", "In a park"), answers = listOf("In a bar in the old town"), explain = "It was at a bar in the old town."), Exercise(id = "en-listen-language-exchange-q6", kind = "written", prompt = "What time did she leave?", options = listOf(), answers = listOf("at eleven", "eleven", "at 11"), explain = "She didn't leave until eleven.")), skills = listOf("listening:gist", "listening:inference", "vocab:social-expressions"), exposureSkills = listOf("grammar:past-simple-regular")) }

object ListenData046 { val text = ListeningText(id = "en-listen-rainy-picnic", languageID = "en", title = "The rainy picnic", level = "A2", topic = "weather", unitID = "en-foundations-u5", text = "We were so excited about the picnic on Saturday. The weather was warm on Friday, so we didn't check the forecast. On Saturday morning it started to rain and it didn't stop all day. We moved everything into the kitchen and ate on the floor. Honestly, it was one of the best afternoons of the summer. Sometimes the plans that go wrong are the ones you remember.", questions = listOf(Exercise(id = "en-listen-rainy-picnic-q1", kind = "choice", prompt = "Why didn't they check the forecast?", options = listOf("The weather was warm on Friday", "They don't have a phone", "They were in a hurry", "They forgot"), answers = listOf("The weather was warm on Friday"), explain = "The weather was warm on Friday, so they didn't check."), Exercise(id = "en-listen-rainy-picnic-q2", kind = "written", prompt = "Where did they eat?", options = listOf(), answers = listOf("in the kitchen", "on the kitchen floor", "on the floor in the kitchen"), explain = "They moved everything into the kitchen and ate on the floor."), Exercise(id = "en-listen-rainy-picnic-q3", kind = "choice", prompt = "How did they feel about the day in the end?", options = listOf("It was one of the best afternoons", "It was a disaster", "They were bored", "They were angry"), answers = listOf("It was one of the best afternoons"), explain = "It was one of the best afternoons of the summer."), Exercise(id = "en-listen-rainy-picnic-q4", kind = "choice", prompt = "What was the weather like on Saturday?", options = listOf("It rained all day", "Sunny", "Cloudy but dry", "Snowy"), answers = listOf("It rained all day"), explain = "It started to rain and didn't stop all day."), Exercise(id = "en-listen-rainy-picnic-q5", kind = "choice", prompt = "Which day was the picnic planned for?", options = listOf("Saturday", "Friday", "Sunday", "Monday"), answers = listOf("Saturday"), explain = "They were excited about the picnic on Saturday."), Exercise(id = "en-listen-rainy-picnic-q6", kind = "written", prompt = "What was the weather like on Friday?", options = listOf(), answers = listOf("warm", "it was warm", "the weather was warm"), explain = "The weather was warm on Friday.")), skills = listOf("listening:inference", "listening:detail", "vocab:weather"), exposureSkills = listOf("grammar:past-was-were", "grammar:past-simple-regular")) }

object ListenData047 { val text = ListeningText(id = "en-listen-first-day", languageID = "en", title = "Sofia's first day", level = "A2", topic = "jobs", unitID = "en-foundations-u6", text = "Yesterday was Sofia's first day at her new job. She woke up at six, took the tram and arrived early. The office was smaller than she expected, but everyone was friendly. Her manager gave her a laptop and a long list of things to read. At lunchtime she ate with two colleagues in the park next to the office. On the way home she felt tired but happy, and she called her mother to tell her everything.", questions = listOf(Exercise(id = "en-listen-first-day-q1", kind = "choice", prompt = "When did Sofia arrive at the office?", options = listOf("Early", "Late", "At noon", "She doesn't say"), answers = listOf("Early"), explain = "She woke up at six and arrived early."), Exercise(id = "en-listen-first-day-q2", kind = "written", prompt = "What did her manager give her?", options = listOf(), answers = listOf("a laptop and a long list", "a laptop and a list of things to read", "a laptop"), explain = "He gave her a laptop and a long list of things to read."), Exercise(id = "en-listen-first-day-q3", kind = "choice", prompt = "Where did she eat lunch?", options = listOf("In the park", "At her desk", "In a café", "At home"), answers = listOf("In the park"), explain = "She ate with two colleagues in the park next to the office."), Exercise(id = "en-listen-first-day-q4", kind = "choice", prompt = "How did she feel on the way home?", options = listOf("Tired but happy", "Angry", "Sad and lonely", "Nervous"), answers = listOf("Tired but happy"), explain = "She felt tired but happy."), Exercise(id = "en-listen-first-day-q5", kind = "choice", prompt = "How did she go to work?", options = listOf("By tram", "By bus", "On foot", "By car"), answers = listOf("By tram"), explain = "She took the tram."), Exercise(id = "en-listen-first-day-q6", kind = "written", prompt = "Who did she call on the way home?", options = listOf(), answers = listOf("her mother", "she called her mother", "mother"), explain = "She called her mother to tell her everything.")), skills = listOf("listening:detail", "grammar:past-simple-regular", "vocab:work")) }

object ListenData048 { val text = ListeningText(id = "en-listen-small-accident", languageID = "en", title = "A small accident", level = "A2", topic = "pets", unitID = "en-foundations-u6", text = "While Carlos was cooking dinner on Sunday, he heard a crash from the living room. His cat, Luna, had jumped onto the bookshelf and knocked down his favourite cup. The cup was in pieces on the floor. Luna sat next to the broken pieces, completely calm, as if nothing had happened. Carlos cleaned everything up carefully. The cup was from a trip to Lisbon five years ago, but he didn't shout. It was, after all, only a cup.", questions = listOf(Exercise(id = "en-listen-small-accident-q1", kind = "choice", prompt = "What was Carlos doing when he heard the crash?", options = listOf("Cooking dinner", "Cleaning the floor", "Reading", "Sleeping"), answers = listOf("Cooking dinner"), explain = "He was cooking dinner on Sunday."), Exercise(id = "en-listen-small-accident-q2", kind = "written", prompt = "Who broke the cup?", options = listOf(), answers = listOf("his cat luna", "luna", "the cat", "his cat"), explain = "Luna the cat jumped onto the bookshelf and knocked it down."), Exercise(id = "en-listen-small-accident-q3", kind = "choice", prompt = "Where was the cup from?", options = listOf("A trip to Lisbon", "A birthday", "His grandmother", "A market"), answers = listOf("A trip to Lisbon"), explain = "The cup was from a trip to Lisbon five years ago."), Exercise(id = "en-listen-small-accident-q4", kind = "choice", prompt = "How did Carlos react?", options = listOf("He didn't shout", "He shouted at Luna", "He cried", "He called his friend"), answers = listOf("He didn't shout"), explain = "He cleaned up carefully and didn't shout."), Exercise(id = "en-listen-small-accident-q5", kind = "choice", prompt = "Where was the bookshelf?", options = listOf("In the living room", "In the kitchen", "In the bedroom", "In the hall"), answers = listOf("In the living room"), explain = "He heard the crash from the living room, where the bookshelf was."), Exercise(id = "en-listen-small-accident-q6", kind = "written", prompt = "How old is the cup?", options = listOf(), answers = listOf("five years old", "five years", "five"), explain = "The cup was from a trip to Lisbon five years ago.")), skills = listOf("listening:detail", "grammar:past-simple-regular"), exposureSkills = listOf("grammar:past-continuous")) }

object ListenData049 { val text = ListeningText(id = "en-listen-two-cities", languageID = "en", title = "Two cities, one decision", level = "A2", topic = "travel", unitID = "en-foundations-compare", text = "'So, Lisbon or Porto?' Marta asks. Her sister Lena is moving next month, and the decision is harder than she expected. 'Porto is smaller and cheaper,' Lena says, 'but Lisbon has more job opportunities.' Marta nods. 'And the weather? Lisbon is warmer in winter.' 'True, but Porto is greener — I love the rain on the river.' They compare the flats they found online: the Lisbon flat is more modern but noisier; the Porto flat is older but much bigger, and the rent is lower than in Lisbon. 'Which one do you prefer?' Marta asks. Lena smiles. 'Honestly, the people make the city. My best friend is in Porto — that's the most important thing.'", questions = listOf(Exercise(id = "en-listen-two-cities-q1", kind = "choice", prompt = "What is Lena's decision about?", options = listOf("Moving to Lisbon or Porto", "Two jobs", "Two flats in the same city", "A holiday"), answers = listOf("Moving to Lisbon or Porto"), explain = "She is moving next month and must choose between the two cities."), Exercise(id = "en-listen-two-cities-q2", kind = "written", prompt = "According to Lena, what does Lisbon have more of?", options = listOf(), answers = listOf("job opportunities", "more job opportunities", "jobs"), explain = "Lisbon has more job opportunities."), Exercise(id = "en-listen-two-cities-q3", kind = "choice", prompt = "How does Lena describe the Porto flat?", options = listOf("Older but much bigger", "More modern but noisier", "Cheaper but smaller", "Newer and greener"), answers = listOf("Older but much bigger"), explain = "The Porto flat is older but much bigger, and the rent is lower."), Exercise(id = "en-listen-two-cities-q4", kind = "written", prompt = "Which city is warmer in winter?", options = listOf(), answers = listOf("lisbon", "lisboa"), explain = "Marta says Lisbon is warmer in winter."), Exercise(id = "en-listen-two-cities-q5", kind = "choice", prompt = "What does Lena say is the most important thing?", options = listOf("Her best friend is in Porto", "The weather", "The rent", "The modern flat"), answers = listOf("Her best friend is in Porto"), explain = "For her, the people make the city."), Exercise(id = "en-listen-two-cities-q6", kind = "choice", prompt = "How hard was the decision?", options = listOf("Harder than she expected", "Easy", "Impossible", "She doesn't say"), answers = listOf("Harder than she expected"), explain = "The decision is harder than she expected.")), skills = listOf("listening:inference", "grammar:comparatives", "grammar:superlatives", "vocab:travel")) }

object ListenData050 { val text = ListeningText(id = "en-listen-quiet-hotel", languageID = "en", title = "The quiet hotel problem", level = "A2", topic = "travel", unitID = "en-foundations-compare", text = "Tom booked a quiet hotel for his holiday, but on the first night a group arrived for a wedding. The music played until three in the morning, and Tom couldn't sleep. In the morning he went to reception. 'I booked a quiet room,' he said calmly. 'Last night I heard every song of the party.' The manager apologised. 'You're right — we shouldn't have given you room twelve. We're moving you to the garden side, and breakfast is on us today.' Tom thanked her. 'That's fair.' The new room was quieter than a library, and by the pool Tom finally started to enjoy his holiday.", questions = listOf(Exercise(id = "en-listen-quiet-hotel-q1", kind = "choice", prompt = "Why couldn't Tom sleep?", options = listOf("There was a wedding party", "The bed was uncomfortable", "It was too cold", "The street was noisy"), answers = listOf("There was a wedding party"), explain = "A wedding group arrived and the music played until three."), Exercise(id = "en-listen-quiet-hotel-q2", kind = "written", prompt = "What had Tom booked?", options = listOf(), answers = listOf("a quiet hotel", "a quiet room", "a quiet hotel room"), explain = "He booked a quiet hotel for his holiday."), Exercise(id = "en-listen-quiet-hotel-q3", kind = "choice", prompt = "How did Tom complain?", options = listOf("Calmly at reception", "He shouted at the manager", "He wrote a bad review", "He called the police"), answers = listOf("Calmly at reception"), explain = "He went to reception and spoke calmly."), Exercise(id = "en-listen-quiet-hotel-q4", kind = "written", prompt = "What did the manager offer?", options = listOf(), answers = listOf("a room on the garden side", "a quieter room", "a room on the garden side and free breakfast", "a new room and free breakfast"), explain = "A room on the garden side, and breakfast on the house."), Exercise(id = "en-listen-quiet-hotel-q5", kind = "choice", prompt = "How was the new room?", options = listOf("Quieter than a library", "Still noisy", "Bigger but expensive", "Next to the pool"), answers = listOf("Quieter than a library"), explain = "The new room was quieter than a library."), Exercise(id = "en-listen-quiet-hotel-q6", kind = "written", prompt = "What was Tom's reaction to the solution?", options = listOf(), answers = listOf("that's fair", "he thanked her", "he said that's fair"), explain = "He thanked her and said that was fair.")), skills = listOf("listening:detail", "function:solve-problems", "grammar:comparatives", "vocab:travel"), exposureSkills = listOf("grammar:past-continuous")) }

object ListenData051 { val text = ListeningText(id = "en-listen-weekend-plans", languageID = "en", title = "The weekend plan", level = "A2", topic = "free time", unitID = "en-foundations-plans", text = "'What are you going to do this weekend?' Sara asks her flatmate Diego. 'Nothing special,' he says, 'I'm going to clean the flat and maybe watch a film.' Sara has a better idea. 'The weather is going to be sunny on Saturday — some friends are going to cycle to the lake. Are you going to come?' Diego thinks. 'I haven't got a bike.' 'You can rent one — it's only eight euros for the whole day. We're going to leave at nine, have lunch by the water and come back before six.' 'And if it rains?' 'We're going to take the train back — problem solved!' Diego laughs. 'OK, I'm in. But I'm not going to cycle uphill!'", questions = listOf(Exercise(id = "en-listen-weekend-plans-q1", kind = "choice", prompt = "What was Diego going to do this weekend?", options = listOf("Clean the flat and watch a film", "Cycle to the lake", "Visit Sara's friends", "Work"), answers = listOf("Clean the flat and watch a film"), explain = "He was going to clean the flat and maybe watch a film."), Exercise(id = "en-listen-weekend-plans-q2", kind = "written", prompt = "What is the weather going to be like on Saturday?", options = listOf(), answers = listOf("sunny", "it's going to be sunny", "sunny on saturday"), explain = "The weather is going to be sunny."), Exercise(id = "en-listen-weekend-plans-q3", kind = "choice", prompt = "What are Sara and her friends going to do?", options = listOf("Cycle to the lake", "Go to the cinema", "Visit a museum", "Have a picnic in the park"), answers = listOf("Cycle to the lake"), explain = "Some friends are going to cycle to the lake."), Exercise(id = "en-listen-weekend-plans-q4", kind = "written", prompt = "How much does renting a bike cost?", options = listOf(), answers = listOf("eight euros", "8 euros", "8€"), explain = "It's only eight euros for the whole day."), Exercise(id = "en-listen-weekend-plans-q5", kind = "choice", prompt = "What time are they going to leave?", options = listOf("At nine", "At six", "At noon", "At eight"), answers = listOf("At nine"), explain = "They're going to leave at nine and come back before six."), Exercise(id = "en-listen-weekend-plans-q6", kind = "written", prompt = "What is Diego NOT going to do?", options = listOf(), answers = listOf("cycle uphill", "go uphill", "cycle up hill"), explain = "He's in — but he's not going to cycle uphill!")), skills = listOf("listening:gist", "grammar:going-to", "function:make-future-plans", "vocab:hobbies")) }

object ListenData052 { val text = ListeningText(id = "en-listen-office-rules", languageID = "en", title = "The office rules", level = "A2", topic = "work", unitID = "en-foundations-plans", text = "It's Nerea's first day, and Pablo is showing her around. 'A few rules,' he smiles. 'Everyone has to wear the badge — security is strict about that. You don't have to arrive at eight exactly, but meetings start at nine sharp, so don't be late for those.' 'Should I bring my own laptop?' Nerea asks. 'No — the company gives you one, and you mustn't install outside software on it. Lunch is at one; you can eat in the canteen or go out. On Fridays we don't have to wear formal clothes.' 'And coffee?' 'The machine is free — but you should try the bar next door. Their coffee is much better!'", questions = listOf(Exercise(id = "en-listen-office-rules-q1", kind = "choice", prompt = "What does everyone have to wear?", options = listOf("A badge", "A uniform", "Formal clothes", "A helmet"), answers = listOf("A badge"), explain = "Everyone has to wear the badge — security is strict."), Exercise(id = "en-listen-office-rules-q2", kind = "written", prompt = "What time do meetings start?", options = listOf(), answers = listOf("at nine", "nine", "9"), explain = "Meetings start at nine sharp."), Exercise(id = "en-listen-office-rules-q3", kind = "choice", prompt = "What mustn't Nerea do with the work laptop?", options = listOf("Install outside software", "Take it home", "Use it for email", "Charge it at night"), answers = listOf("Install outside software"), explain = "You mustn't install outside software on it."), Exercise(id = "en-listen-office-rules-q4", kind = "written", prompt = "What is different on Fridays?", options = listOf(), answers = listOf("no formal clothes", "you don't have to wear formal clothes", "informal clothes", "casual clothes"), explain = "On Fridays they don't have to wear formal clothes."), Exercise(id = "en-listen-office-rules-q5", kind = "choice", prompt = "What does Pablo recommend for coffee?", options = listOf("The bar next door", "The office machine", "Making it at home", "The canteen"), answers = listOf("The bar next door"), explain = "You should try the bar next door — much better coffee."), Exercise(id = "en-listen-office-rules-q6", kind = "choice", prompt = "Where can Nerea eat lunch?", options = listOf("In the canteen or out", "Only at her desk", "Only in the canteen", "At the bar next door"), answers = listOf("In the canteen or out"), explain = "Lunch is at one — canteen or out.")), skills = listOf("listening:detail", "grammar:modal-must-have-to", "grammar:modal-should", "vocab:work"), exposureSkills = listOf("grammar:going-to")) }

object ListenData053 { val text = ListeningText(id = "en-listen-never-been", languageID = "en", title = "Things I've never done", level = "B1", topic = "travel", unitID = "en-foundations-experiences", text = "At a hostel kitchen table, three travellers compare lives. Jonas has visited twenty countries, but he's never learned to swim — 'I know, it's ridiculous.' Amara has swum with dolphins twice, yet she's never left Africa until this trip. And Coco, who has been on the road for six years, has never flown: she crosses oceans on ships and borders on buses. 'Never?' Jonas asks. 'Never. The fear is older than I am.' They laugh about the things they haven't done, and Coco says something that stays with them: 'You don't need to have done everything. You just need to still want to.'", questions = listOf(Exercise(id = "en-listen-never-been-q1", kind = "choice", prompt = "What has Jonas never done?", options = listOf("Learned to swim", "Visited twenty countries", "Flown on a plane", "Crossed a border"), answers = listOf("Learned to swim"), explain = "He has visited twenty countries but has never learned to swim."), Exercise(id = "en-listen-never-been-q2", kind = "written", prompt = "How many times has Amara swum with dolphins?", options = listOf(), answers = listOf("twice", "2 times", "two times"), explain = "She has swum with dolphins twice."), Exercise(id = "en-listen-never-been-q3", kind = "choice", prompt = "How does Coco travel across oceans?", options = listOf("On ships", "On buses", "By plane", "She doesn't cross them"), answers = listOf("On ships"), explain = "She crosses oceans on ships and borders on buses."), Exercise(id = "en-listen-never-been-q4", kind = "written", prompt = "How long has Coco been travelling?", options = listOf(), answers = listOf("six years", "6 years"), explain = "She has been on the road for six years."), Exercise(id = "en-listen-never-been-q5", kind = "choice", prompt = "Why has Coco never flown?", options = listOf("Her fear is older than she is", "She can't afford it", "She prefers trains", "She has never wanted to"), answers = listOf("Her fear is older than she is"), explain = "She says the fear is older than she is."), Exercise(id = "en-listen-never-been-q6", kind = "choice", prompt = "What does Coco say at the end?", options = listOf("You just need to still want to", "Everyone should fly once", "Travel is overrated", "Ships are better"), answers = listOf("You just need to still want to"), explain = "You don't need to have done everything — just to still want to.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")) }

object ListenData054 { val text = ListeningText(id = "en-listen-traffic-tale", languageID = "en", title = "The day of the parade", level = "B1", topic = "stories", unitID = "en-foundations-experiences", text = "It was a quiet Sunday morning and Elena was cycling to work, as she always did. The streets were almost empty; a few runners were crossing the bridge, and a baker was setting out trays of bread. She was crossing the main square when she heard drums. Suddenly, the road ahead filled with people — a parade she had completely forgotten about. Dancers were spinning, children were waving flags, and a brass band was playing behind them. Elena stopped, one foot on the ground, and just watched. She was twenty minutes late for work, but her boss, who had also been stuck in the crowd, only laughed. 'Some mornings,' he said, 'you're exactly where you should be.'", questions = listOf(Exercise(id = "en-listen-traffic-tale-q1", kind = "choice", prompt = "What was Elena doing when she heard the drums?", options = listOf("She was crossing the main square", "She was working", "She was setting out bread", "She was at home"), answers = listOf("She was crossing the main square"), explain = "She was crossing the main square when she heard drums."), Exercise(id = "en-listen-traffic-tale-q2", kind = "written", prompt = "What were the runners doing on the bridge?", options = listOf(), answers = listOf("crossing it", "crossing the bridge", "running"), explain = "A few runners were crossing the bridge."), Exercise(id = "en-listen-traffic-tale-q3", kind = "choice", prompt = "What filled the road?", options = listOf("A parade", "Traffic", "Rain", "Runners"), answers = listOf("A parade"), explain = "Suddenly, the road filled with people — a forgotten parade."), Exercise(id = "en-listen-traffic-tale-q4", kind = "written", prompt = "What was the brass band doing?", options = listOf(), answers = listOf("playing", "playing behind the dancers", "playing music"), explain = "A brass band was playing behind the dancers."), Exercise(id = "en-listen-traffic-tale-q5", kind = "choice", prompt = "How late was Elena for work?", options = listOf("Twenty minutes", "Ten minutes", "An hour", "She never arrived"), answers = listOf("Twenty minutes"), explain = "She was twenty minutes late."), Exercise(id = "en-listen-traffic-tale-q6", kind = "choice", prompt = "Why did her boss only laugh?", options = listOf("He had also been stuck in the crowd", "It was a holiday", "She never told him", "He loves parades"), answers = listOf("He had also been stuck in the crowd"), explain = "Her boss had also been stuck — some mornings you're exactly where you should be.")), skills = listOf("listening:detail", "grammar:past-continuous", "grammar:past-simple-irregular", "function:tell-a-story"), exposureSkills = listOf("grammar:past-continuous")) }

object ListenData055 { val text = ListeningText(id = "en-listen-if-it-rains", languageID = "en", title = "If it rains", level = "B1", topic = "plans", unitID = "en-foundations-connections", text = "'So what's the plan if it rains?' Sam asks, looking at the grey sky. Priya has thought about everything. 'If it rains before ten, we'll move the picnic into the greenhouse — my aunt said we can use it. If it starts while we're out, we'll walk fifteen minutes to the station and take the train back.' 'And if the trains stop?' 'They won't — but if they do, we'll call my brother; he loves an excuse to drive at night.' Sam laughs. 'And if the sun shines all day?' 'Then we'll have the best picnic of the year, and you'll owe me an apology for doubting my planning.'", questions = listOf(Exercise(id = "en-listen-if-it-rains-q1", kind = "choice", prompt = "Where will they go if it rains before ten?", options = listOf("To the greenhouse", "Home", "To the station", "To Sam's flat"), answers = listOf("To the greenhouse"), explain = "They'll move the picnic into the greenhouse."), Exercise(id = "en-listen-if-it-rains-q2", kind = "written", prompt = "What will they do if rain starts while they're out?", options = listOf(), answers = listOf("take the train back", "walk to the station and take the train", "walk to the station"), explain = "Walk to the station and take the train back."), Exercise(id = "en-listen-if-it-rains-q3", kind = "choice", prompt = "Who will pick them up if the trains stop?", options = listOf("Priya's brother", "Sam's sister", "Priya's aunt", "Nobody"), answers = listOf("Priya's brother"), explain = "Her brother loves an excuse to drive at night."), Exercise(id = "en-listen-if-it-rains-q4", kind = "written", prompt = "What does Priya say will happen if the sun shines all day?", options = listOf(), answers = listOf("the best picnic of the year", "they'll have the best picnic of the year", "it will be the best picnic of the year"), explain = "Then they'll have the best picnic of the year."), Exercise(id = "en-listen-if-it-rains-q5", kind = "choice", prompt = "Why does Sam owe an apology?", options = listOf("For doubting Priya's planning", "For being late", "For eating the food", "For losing the map"), answers = listOf("For doubting Priya's planning"), explain = "Priya says he'll owe an apology for doubting her planning."), Exercise(id = "en-listen-if-it-rains-q6", kind = "choice", prompt = "How does Priya seem about her plan?", options = listOf("She has thought about everything", "She is nervous", "She hasn't prepared", "She wants to cancel"), answers = listOf("She has thought about everything"), explain = "Priya has an answer for every condition.")), skills = listOf("listening:detail", "grammar:first-conditional", "function:make-future-plans")) }

object ListenData056 { val text = ListeningText(id = "en-listen-job-change", languageID = "en", title = "Before the change", level = "B1", topic = "work", unitID = "en-foundations-connections", text = "Rosa remembers her office life the way you remember an old coat: familiar, slightly tight. She used to commute ninety minutes each way. She used to eat lunch at her desk and answer emails at midnight. 'I used to think that was normal,' she says. 'Everyone around me did the same.' Two years ago she moved to a small town and opened a bookshop. At first, the silence was unbearable — she didn't use to have quiet, and it felt like something was wrong. Now she closes at six and reads in the evenings. 'People ask if I miss the city. Although I loved parts of it, I don't miss the person I was becoming there.'", questions = listOf(Exercise(id = "en-listen-job-change-q1", kind = "written", prompt = "How long did Rosa use to commute each way?", options = listOf(), answers = listOf("ninety minutes", "90 minutes", "an hour and a half"), explain = "She used to commute ninety minutes each way."), Exercise(id = "en-listen-job-change-q2", kind = "choice", prompt = "What did she use to do at midnight?", options = listOf("Answer emails", "Sleep", "Read", "Cook"), answers = listOf("Answer emails"), explain = "She used to answer emails at midnight."), Exercise(id = "en-listen-job-change-q3", kind = "written", prompt = "What did she open in the small town?", options = listOf(), answers = listOf("a bookshop", "a book shop", "a bookstore"), explain = "She opened a bookshop."), Exercise(id = "en-listen-job-change-q4", kind = "choice", prompt = "How did the silence feel at first?", options = listOf("Unbearable", "Wonderful", "Normal", "Exciting"), answers = listOf("Unbearable"), explain = "She didn't use to have quiet, and it felt like something was wrong."), Exercise(id = "en-listen-job-change-q5", kind = "written", prompt = "What does she do in the evenings now?", options = listOf(), answers = listOf("she reads", "reads"), explain = "Now she closes at six and reads in the evenings."), Exercise(id = "en-listen-job-change-q6", kind = "choice", prompt = "What doesn't she miss about the city?", options = listOf("The person she was becoming", "Her colleagues", "The food", "The salary"), answers = listOf("The person she was becoming"), explain = "Although she loved parts of it, she doesn't miss who she was becoming.")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:work")) }

object ListenData057 { val text = ListeningText(id = "en-listen-monday-predictions", languageID = "en", title = "The Monday pool", level = "B1", topic = "work", unitID = "en-foundations-change", text = "Every Monday, the design team runs a small prediction pool. 'Ten euros says the client changes the brief by Wednesday,' says Jonas. Petra shakes her head. 'The brief will survive — but the printer will break. It always does.' Newcomer Ana smiles nervously. 'I'll just predict something safe: we'll all complain about the coffee.' Everyone writes their bets on the whiteboard, and the week starts. By Wednesday, the client has indeed changed the brief, twice. Jonas collects his ten euros without a word. The printer, loyal to tradition, jams on Thursday morning — Petra's turn to smile. And on Friday, Ana looks at her line on the board, at the empty coffee machine, and says what everyone is thinking: 'Will anyone else complain, or is it just me?'", questions = listOf(Exercise(id = "en-listen-monday-predictions-q1", kind = "choice", prompt = "What does Jonas predict on Monday?", options = listOf("The client will change the brief", "The printer will break", "The coffee will run out", "Ana will win"), answers = listOf("The client will change the brief"), explain = "'Ten euros says the client changes the brief by Wednesday.'"), Exercise(id = "en-listen-monday-predictions-q2", kind = "written", prompt = "What is Petra's prediction?", options = listOf(), answers = listOf("the printer will break", "the printer breaks", "printer will break"), explain = "The brief will survive, but the printer will break."), Exercise(id = "en-listen-monday-predictions-q3", kind = "written", prompt = "What does newcomer Ana predict?", options = listOf(), answers = listOf("they will all complain about the coffee", "everyone will complain about the coffee", "they'll complain about the coffee"), explain = "A safe prediction: everyone complains about the coffee."), Exercise(id = "en-listen-monday-predictions-q4", kind = "choice", prompt = "What happened by Wednesday?", options = listOf("The client changed the brief twice", "The printer broke", "The coffee machine died", "Nothing"), answers = listOf("The client changed the brief twice"), explain = "The client changed the brief, twice — Jonas wins his bet."), Exercise(id = "en-listen-monday-predictions-q5", kind = "choice", prompt = "When did the printer jam?", options = listOf("Thursday morning", "Wednesday", "Monday", "It didn't"), answers = listOf("Thursday morning"), explain = "Loyal to tradition, it jammed on Thursday morning."), Exercise(id = "en-listen-monday-predictions-q6", kind = "choice", prompt = "How did Jonas collect his winnings?", options = listOf("Without a word", "With a speech", "He never did", "He bought coffee"), answers = listOf("Without a word"), explain = "He collected his ten euros without a word — the quiet winner.")), skills = listOf("listening:inference", "grammar:future-forms", "function:make-future-plans")) }

object ListenData058 { val text = ListeningText(id = "en-listen-office-rumours", languageID = "en", title = "The rumour mill", level = "B1", topic = "work", unitID = "en-foundations-change", text = "Carmen came back from one day off and the office had invented three futures. 'Marco said the company was moving to Lisbon,' whispered Diego. 'Lena told me they were hiring twenty people,' said Carmen. 'And Priya swears she heard we were all getting new laptops.' Carmen put down her bag and applied the office rule: trace every rumour to its source. The Lisbon story started with a photo Marco took of a moving van — which was moving his neighbour's piano. The twenty hires were real, but Lena had read 'over the next five years' and skipped that part. And the laptops were true: an email had gone out at seven that morning. One truth, one exaggeration, one piano.", questions = listOf(Exercise(id = "en-listen-office-rumours-q1", kind = "choice", prompt = "How many futures had the office invented?", options = listOf("Three", "Two", "Five", "One"), answers = listOf("Three"), explain = "The office had invented three futures in one day."), Exercise(id = "en-listen-office-rumours-q2", kind = "written", prompt = "What did Marco say, according to Diego?", options = listOf(), answers = listOf("the company was moving to lisbon", "they were moving to lisbon", "the company was moving"), explain = "Marco said the company was moving to Lisbon."), Exercise(id = "en-listen-office-rumours-q3", kind = "choice", prompt = "What was the moving van actually moving?", options = listOf("A piano", "Office furniture", "Twenty laptops", "Files"), answers = listOf("A piano"), explain = "Marco's photo showed his neighbour's piano being moved."), Exercise(id = "en-listen-office-rumours-q4", kind = "written", prompt = "What was true about the twenty hires?", options = listOf(), answers = listOf("over the next five years", "they were real but over five years", "over five years"), explain = "Real — but 'over the next five years', which Lena skipped."), Exercise(id = "en-listen-office-rumours-q5", kind = "choice", prompt = "Which rumour was completely true?", options = listOf("The new laptops", "Lisbon", "Twenty hires immediately", "None"), answers = listOf("The new laptops"), explain = "An email had gone out at seven that morning."), Exercise(id = "en-listen-office-rumours-q6", kind = "choice", prompt = "What is the office rule Carmen applies?", options = listOf("Trace every rumour to its source", "Never believe Lena", "Ignore all emails", "Trust Diego"), answers = listOf("Trace every rumour to its source"), explain = "Her rule: trace every rumour to its source.")), skills = listOf("listening:inference", "grammar:reported-speech-basic", "grammar:future-forms", "vocab:work")) }

object ListenData059 { val text = ListeningText(id = "en-listen-news-swap", languageID = "en", title = "The news swap", level = "B1", topic = "people", unitID = "en-foundations-telling", text = "Café table, two old friends, forty-eight hours of accumulated news. 'You first,' says Ines. 'OK — I got the promotion!' 'No way! Congratulations! When do you start?' 'Monday. And the office is ten minutes from my flat.' 'That IS great news.' Then Ines takes a breath. 'Mine isn't all good. I crashed my bike — I'm fine, but the bike is gone.' 'Oh no, I'm so sorry. Are you OK though? Really?' 'Honestly, yes. Just angry about the bike.' Ines nods, then smiles. 'But there's more: I'm going to Italy in June.' 'Stop it! You're kidding!' 'I'm not. Two weeks, Tuscany, and you're coming with me.'", questions = listOf(Exercise(id = "en-listen-news-swap-q1", kind = "choice", prompt = "What is Ines's good news at the end?", options = listOf("A trip to Italy", "A new bike", "A promotion", "A new job"), answers = listOf("A trip to Italy"), explain = "Two weeks in Tuscany in June."), Exercise(id = "en-listen-news-swap-q2", kind = "written", prompt = "What is the friend's good news?", options = listOf(), answers = listOf("a promotion", "she got the promotion", "the promotion"), explain = "She got the promotion — starting Monday."), Exercise(id = "en-listen-news-swap-q3", kind = "choice", prompt = "What happened to the bike?", options = listOf("It's gone after a crash", "It was stolen", "It needs repair", "She sold it"), answers = listOf("It's gone after a crash"), explain = "Ines crashed her bike; she's fine, but the bike is gone."), Exercise(id = "en-listen-news-swap-q4", kind = "written", prompt = "What is the friend's reaction to the crash?", options = listOf(), answers = listOf("im so sorry", "oh no im so sorry"), explain = "'Oh no, I'm so sorry' — then the care question."), Exercise(id = "en-listen-news-swap-q5", kind = "choice", prompt = "How does the friend react to the promotion?", options = listOf("'No way! Congratulations!'", "'That's awful.'", "'Really? Are you OK?'", "'Good luck.'"), answers = listOf("'No way! Congratulations!'"), explain = "React + congratulate."), Exercise(id = "en-listen-news-swap-q6", kind = "choice", prompt = "What does Ines invite her friend to do?", options = listOf("Come to Tuscany", "Buy a new bike", "Visit the new office", "Start in June"), answers = listOf("Come to Tuscany"), explain = "'You're coming with me.'")), skills = listOf("vocab:social-expressions", "function:express-opinion", "grammar:future-forms")) }

object ListenData060 { val text = ListeningText(id = "en-listen-grandpas-garden", languageID = "en", title = "Grandpa's garden", level = "A2", topic = "family", text = "When Pablo was a child, he spent every summer at his grandpa's house. The garden was enormous, full of tomato plants and lemon trees. Every morning they watered the plants together and every afternoon they played cards under the big tree. His grandpa didn't talk much, but he laughed easily. Pablo didn't like vegetables then. Now he grows his own tomatoes and understands why his grandpa smiled at them.", questions = listOf(Exercise(id = "en-listen-grandpas-garden-q1", kind = "choice", prompt = "What was in grandpa's garden?", options = listOf("Tomato plants and lemon trees", "Only flowers", "Vegetable soup", "Apple trees"), answers = listOf("Tomato plants and lemon trees"), explain = "It was full of tomato plants and lemon trees."), Exercise(id = "en-listen-grandpas-garden-q2", kind = "written", prompt = "What did they do every afternoon?", options = listOf(), answers = listOf("they played cards", "played cards under the big tree", "they played cards under the big tree"), explain = "They played cards under the big tree."), Exercise(id = "en-listen-grandpas-garden-q3", kind = "choice", prompt = "What was grandpa like?", options = listOf("Quiet but quick to laugh", "Loud and serious", "He never smiled", "He talked all day"), answers = listOf("Quiet but quick to laugh"), explain = "He didn't talk much, but he laughed easily."), Exercise(id = "en-listen-grandpas-garden-q4", kind = "written", prompt = "What does Pablo grow now?", options = listOf(), answers = listOf("tomatoes", "his own tomatoes", "he grows tomatoes"), explain = "Now he grows his own tomatoes."), Exercise(id = "en-listen-grandpas-garden-q5", kind = "choice", prompt = "What did they do every morning?", options = listOf("They watered the plants", "They played cards", "They cooked lunch", "They went shopping"), answers = listOf("They watered the plants"), explain = "Every morning they watered the plants together."), Exercise(id = "en-listen-grandpas-garden-q6", kind = "written", prompt = "What didn't Pablo like as a child?", options = listOf(), answers = listOf("vegetables", "he didn't like vegetables"), explain = "Pablo didn't like vegetables then.")), skills = listOf("listening:inference", "grammar:past-simple-irregular", "vocab:family")) }

object ListenData061 { val text = ListeningText(id = "en-listen-lost-jacket", languageID = "en", title = "The lost jacket", level = "A2", topic = "clothes", text = "Last week Daniel lost his favourite jacket. He left it on the number twelve bus on Friday evening. He called the lost property office on Monday, but nobody had seen it. Two days later a neighbour knocked on his door and gave him the jacket. She found it on the bus seat with his name and address inside the pocket. Daniel was amazed and invited her in for a cup of tea.", questions = listOf(Exercise(id = "en-listen-lost-jacket-q1", kind = "written", prompt = "Where did Daniel leave his jacket?", options = listOf(), answers = listOf("on the number twelve bus", "on the bus", "on the 12 bus"), explain = "He left it on the number twelve bus."), Exercise(id = "en-listen-lost-jacket-q2", kind = "choice", prompt = "When did he call the lost property office?", options = listOf("On Monday", "On Friday", "Two days later", "The same evening"), answers = listOf("On Monday"), explain = "He called on Monday, but nobody had seen it."), Exercise(id = "en-listen-lost-jacket-q3", kind = "choice", prompt = "Who found the jacket?", options = listOf("A neighbour", "A bus driver", "His mother", "A colleague"), answers = listOf("A neighbour"), explain = "A neighbour knocked on his door and gave him the jacket."), Exercise(id = "en-listen-lost-jacket-q4", kind = "written", prompt = "How did the neighbour know it was Daniel's jacket?", options = listOf(), answers = listOf("his name and address were inside the pocket", "there was a name and address in the pocket", "his name and address in the pocket"), explain = "His name and address were inside the pocket."), Exercise(id = "en-listen-lost-jacket-q5", kind = "choice", prompt = "How did Daniel feel when he got the jacket back?", options = listOf("Amazed", "Angry", "Sad", "Sleepy"), answers = listOf("Amazed"), explain = "Daniel was amazed."), Exercise(id = "en-listen-lost-jacket-q6", kind = "written", prompt = "What did he invite the neighbour for?", options = listOf(), answers = listOf("a cup of tea", "cup of tea", "tea"), explain = "He invited her in for a cup of tea.")), skills = listOf("listening:detail", "grammar:past-simple-regular", "vocab:transport")) }

object ListenData062 { val text = ListeningText(id = "en-listen-night-train", languageID = "en", title = "The night train", level = "A2", topic = "travel", text = "Ella took the night train to the coast because the morning tickets were too expensive. She shared a small compartment with a woman who worked as a nurse and a student who talked for hours about football. Ella couldn't sleep, but she didn't mind. The train arrived at five in the morning, before the sun came up. She walked out of the station, smelled the sea and knew the trip was worth it.", questions = listOf(Exercise(id = "en-listen-night-train-q1", kind = "written", prompt = "Why did Ella take the night train?", options = listOf(), answers = listOf("the morning tickets were too expensive", "because the morning tickets were too expensive", "morning tickets were too expensive"), explain = "The morning tickets were too expensive."), Exercise(id = "en-listen-night-train-q2", kind = "choice", prompt = "What did the student talk about?", options = listOf("Football", "Nursing", "The coast", "Music"), answers = listOf("Football"), explain = "The student talked for hours about football."), Exercise(id = "en-listen-night-train-q3", kind = "choice", prompt = "When did the train arrive?", options = listOf("At five in the morning", "At five in the evening", "At sunrise", "At midnight"), answers = listOf("At five in the morning"), explain = "It arrived at five, before the sun came up."), Exercise(id = "en-listen-night-train-q4", kind = "written", prompt = "How did Ella know the trip was worth it when she arrived?", options = listOf(), answers = listOf("she smelled the sea", "she smelled the sea and knew the trip was worth it", "because she smelled the sea"), explain = "She walked out and smelled the sea."), Exercise(id = "en-listen-night-train-q5", kind = "choice", prompt = "What was the woman in the compartment?", options = listOf("A nurse", "A teacher", "A doctor", "A driver"), answers = listOf("A nurse"), explain = "She worked as a nurse."), Exercise(id = "en-listen-night-train-q6", kind = "choice", prompt = "Did Ella sleep on the train?", options = listOf("No, but she didn't mind", "Yes, all night", "Yes, for two hours", "She doesn't say"), answers = listOf("No, but she didn't mind"), explain = "She couldn't sleep, but she didn't mind.")), skills = listOf("listening:inference", "grammar:past-simple-irregular", "vocab:travel")) }

object ListenData063 { val text = ListeningText(id = "en-listen-doctor-call", languageID = "en", title = "The doctor's phone call", level = "A2", topic = "health", unitID = "en-foundations-health", text = "The receptionist answers on the second ring. 'Good morning, Riverside Clinic.' 'Hello, I'd like to make an appointment. It's not an emergency, but I've had back pain for two weeks and it's getting worse.' The receptionist types. 'Dr Lee has a slot today at 16:40. Is that OK?' 'Perfect.' 'Just so I know you've got it: today, 16:40, Dr Lee. Bring your ID and your medication list. And drink water — it helps everything.' The caller laughs. 'Thank you very much.' 'See you this afternoon. Take care!'", questions = listOf(Exercise(id = "en-listen-doctor-call-q1", kind = "choice", prompt = "What does the caller want?", options = listOf("To make an appointment", "A prescription now", "To cancel", "To speak to Dr Lee"), answers = listOf("To make an appointment"), explain = "I'd like to make an appointment."), Exercise(id = "en-listen-doctor-call-q2", kind = "written", prompt = "How long has the back pain lasted?", options = listOf(), answers = listOf("two weeks", "for two weeks"), explain = "For two weeks — and getting worse."), Exercise(id = "en-listen-doctor-call-q3", kind = "choice", prompt = "When is the appointment?", options = listOf("Today at 16:40", "Tomorrow morning", "This evening", "Next week"), answers = listOf("Today at 16:40"), explain = "Dr Lee has a slot today at 16:40."), Exercise(id = "en-listen-doctor-call-q4", kind = "written", prompt = "What should the caller bring?", options = listOf(), answers = listOf("id and medication list", "her id and medication list", "id and a medication list"), explain = "ID and the medication list."), Exercise(id = "en-listen-doctor-call-q5", kind = "choice", prompt = "What does the receptionist recommend for everything?", options = listOf("Drinking water", "Resting", "Painkillers", "Walking"), answers = listOf("Drinking water"), explain = "Drink water — it helps everything (she's joking, half)."), Exercise(id = "en-listen-doctor-call-q6", kind = "written", prompt = "How does the receptionist close the call?", options = listOf(), answers = listOf("see you this afternoon take care", "take care"), explain = "'See you this afternoon. Take care!'")), skills = listOf("function:talk-about-health", "grammar:present-perfect", "vocab:health")) }

object ListenData064 { val text = ListeningText(id = "en-listen-four-day-week", languageID = "en", title = "The four-day week", level = "B2", topic = "work", unitID = "en-foundations-viewpoints", text = "At the town-hall debate, both speakers agreed on the problem — burnout — and disagreed on nearly everything else. The union representative argued that a four-day week was the obvious fix: trials in Iceland, she said, had been judged a success by almost every measure, and productivity had been maintained with happier staff. The chamber-of-commerce speaker pushed back. Those trials, he replied, were small and self-selected; forcing the change on small businesses could raise costs and reduce service hours. An audience member proposed the middle path nobody had mentioned: keep five contract days but cut meetings by half. Both speakers, perhaps unexpectedly, said they could live with that — which is usually the sign of a good compromise.", questions = listOf(Exercise(id = "en-listen-four-day-week-q1", kind = "choice", prompt = "What did both speakers agree on?", options = listOf("The problem: burnout", "The solution", "The costs", "Nothing"), answers = listOf("The problem: burnout"), explain = "They agreed on the problem and disagreed on nearly everything else."), Exercise(id = "en-listen-four-day-week-q2", kind = "written", prompt = "Which country's trials did the union representative mention?", options = listOf(), answers = listOf("iceland", "trials in iceland"), explain = "Trials in Iceland had been judged a success."), Exercise(id = "en-listen-four-day-week-q3", kind = "choice", prompt = "What was the counter-argument?", options = listOf("The trials were small and self-selected", "Workers don't want it", "It is illegal", "Productivity would double"), answers = listOf("The trials were small and self-selected"), explain = "He replied the trials were small and self-selected."), Exercise(id = "en-listen-four-day-week-q4", kind = "written", prompt = "What middle path did an audience member propose?", options = listOf(), answers = listOf("keep five days but cut meetings by half", "cut meetings by half", "five days with half the meetings"), explain = "Keep five contract days but cut meetings by half."), Exercise(id = "en-listen-four-day-week-q5", kind = "choice", prompt = "How did the speakers react to the compromise?", options = listOf("They said they could live with it", "They rejected it", "They laughed", "They left"), answers = listOf("They said they could live with it"), explain = "Both said they could live with it — a good compromise."), Exercise(id = "en-listen-four-day-week-q6", kind = "choice", prompt = "What does the passive voice of the report emphasise?", options = listOf("The trials and their judgement, not who judged them", "The speaker's anger", "The costs", "The audience"), answers = listOf("The trials and their judgement, not who judged them"), explain = "Had been judged a success — the doer doesn't matter.")), skills = listOf("listening:inference", "grammar:connectors", "function:express-opinion", "grammar:passive-intro")) }

object ListenData065 { val text = ListeningText(id = "en-listen-negotiation-standoff", languageID = "en", title = "The salary standoff", level = "B2", topic = "work", unitID = "en-foundations-viewpoints", text = "'Let's start with the number you want, and I'll tell you honestly if it's possible,' said the manager. Nadia appreciated the directness. 'Forty-eight thousand — that's the market rate for this role, and I can show you three listings that prove it.' The manager didn't flinch. 'I believe you. If I approved that today, I'd have to rewrite three other salaries, and I don't have the budget for that this quarter.' 'What if we phased it?' Nadia offered. 'Forty-four now, a review in March with clear targets, and forty-eight if I hit them.' The manager was quiet for a moment. 'If you put those targets in writing and hit them, I'll defend that raise upstairs. Shall we say we have a deal?' Nadia smiled. 'We have a deal — in writing.'", questions = listOf(Exercise(id = "en-listen-negotiation-standoff-q1", kind = "written", prompt = "What salary did Nadia ask for?", options = listOf(), answers = listOf("forty-eight thousand", "48.000", "48000", "forty-eight thousand euros"), explain = "Forty-eight thousand — the market rate, she said."), Exercise(id = "en-listen-negotiation-standoff-q2", kind = "choice", prompt = "Why couldn't the manager approve it today?", options = listOf("He'd have to rewrite three other salaries", "She didn't deserve it", "It's illegal", "The company is closing"), answers = listOf("He'd have to rewrite three other salaries"), explain = "Approving it would force three rewrites — and there's no budget this quarter."), Exercise(id = "en-listen-negotiation-standoff-q3", kind = "written", prompt = "What was Nadia's phased proposal?", options = listOf(), answers = listOf("44 now and 48 in march with targets", "forty-four now a review in march and forty-eight if she hit targets", "44 now 48 later"), explain = "Forty-four now, review in March, forty-eight if she hits the targets."), Exercise(id = "en-listen-negotiation-standoff-q4", kind = "choice", prompt = "What condition did the manager add?", options = listOf("The targets in writing", "A six-month wait", "No review at all", "A different role"), answers = listOf("The targets in writing"), explain = "If the targets are in writing and hit, he'll defend the raise."), Exercise(id = "en-listen-negotiation-standoff-q5", kind = "choice", prompt = "Which negotiation move is 'What if we phased it?'", options = listOf("Offering a middle path", "Rejecting the deal", "Buying time", "Closing"), answers = listOf("Offering a middle path"), explain = "What if… proposes the middle path between the two positions."), Exercise(id = "en-listen-negotiation-standoff-q6", kind = "choice", prompt = "How did Nadia make sure the deal would hold?", options = listOf("She asked for it in writing", "She shook hands", "She lowered her ask", "She threatened to leave"), answers = listOf("She asked for it in writing"), explain = "'We have a deal — in writing.'")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:first-conditional")) }

object ListenData066 { val text = ListeningText(id = "en-listen-news-desk", languageID = "en", title = "At the news desk", level = "B2", topic = "work", unitID = "en-foundations-media", text = "The 18:00 bulletin is being assembled at the news desk. The editor reads the running order aloud: 'Lead story: the city council has announced a new flood-prevention plan — measures are expected to cost four million euros, according to documents seen by our reporters. Second: the bridge is believed to be safe after emergency inspections; it is thought that traffic will return to normal by Monday. And the sports close: the match was postponed because the pitch was flooded — the third postponement this season.' A young reporter raises her hand. 'Should we say who saw the documents?' The editor shakes his head. 'We protect sources. The documents exist; the audience can decide what they mean.'", questions = listOf(Exercise(id = "en-listen-news-desk-q1", kind = "written", prompt = "What has the city council announced?", options = listOf(), answers = listOf("a new flood-prevention plan", "a flood-prevention plan"), explain = "A new flood-prevention plan."), Exercise(id = "en-listen-news-desk-q2", kind = "choice", prompt = "How is the cost being reported?", options = listOf("According to documents seen by reporters", "The council said it", "It is a rumour", "It is not mentioned"), answers = listOf("According to documents seen by reporters"), explain = "According to documents seen by our reporters."), Exercise(id = "en-listen-news-desk-q3", kind = "written", prompt = "What is believed about the bridge?", options = listOf(), answers = listOf("that it is safe", "it is believed to be safe", "it is safe"), explain = "It is believed to be safe after inspections."), Exercise(id = "en-listen-news-desk-q4", kind = "choice", prompt = "Why was the match postponed?", options = listOf("The pitch was flooded", "The teams were tired", "The bridge closed", "It wasn't"), answers = listOf("The pitch was flooded"), explain = "Postponed because the pitch was flooded."), Exercise(id = "en-listen-news-desk-q5", kind = "choice", prompt = "Why does the editor protect the source?", options = listOf("The audience can decide what the documents mean", "The documents are fake", "It is illegal", "He doesn't know the source"), answers = listOf("The audience can decide what the documents mean"), explain = "The documents exist; the audience decides."), Exercise(id = "en-listen-news-desk-q6", kind = "written", prompt = "How many postponements has the season had?", options = listOf(), answers = listOf("three", "3"), explain = "The third postponement this season.")), skills = listOf("grammar:passive-intro", "grammar:present-perfect", "function:talk-about-work")) }

object ListenData067 { val text = ListeningText(id = "en-listen-bridge-news", languageID = "en", title = "The morning news: bridge reopened", level = "B2", topic = "town", unitID = "en-foundations-viewpoints", text = "Good morning. The Millbrook bridge, which was closed in March after cracks were discovered in two support beams, was reopened to traffic shortly after six this morning — three weeks ahead of schedule. Repair work, which was carried out by a local firm, was funded jointly by the council and the regional government, though the exact split has not been disclosed. Drivers are being asked to observe the fifty-kilometre limit for the first fortnight while the surface settles. Bus route nine, which was diverted via the ring road, returns to its original route today. And in a surprise twist, the ferry that was launched as a temporary replacement — will keep running until September, after commuters, apparently, fell in love with it.", questions = listOf(Exercise(id = "en-listen-bridge-news-q1", kind = "written", prompt = "When was the bridge reopened?", options = listOf(), answers = listOf("shortly after six this morning", "after six this morning", "this morning at six"), explain = "Reopened shortly after six this morning."), Exercise(id = "en-listen-bridge-news-q2", kind = "choice", prompt = "Why had it been closed?", options = listOf("Cracks were found in support beams", "A flood", "It was repainted", "An accident"), answers = listOf("Cracks were found in support beams"), explain = "Closed in March after cracks were discovered in two beams."), Exercise(id = "en-listen-bridge-news-q3", kind = "choice", prompt = "Who carried out the repairs?", options = listOf("A local firm", "The council itself", "The regional government", "It doesn't say"), answers = listOf("A local firm"), explain = "Carried out by a local firm — the passive keeps focus on the work."), Exercise(id = "en-listen-bridge-news-q4", kind = "written", prompt = "What are drivers asked to do for the first fortnight?", options = listOf(), answers = listOf("observe the fifty kilometre limit", "observe the 50 km limit", "drive at fifty"), explain = "Observe the 50 km/h limit while the surface settles."), Exercise(id = "en-listen-bridge-news-q5", kind = "choice", prompt = "What happens to the temporary ferry?", options = listOf("It keeps running until September", "It stops today", "It was cancelled", "It becomes permanent"), answers = listOf("It keeps running until September"), explain = "Commuters apparently fell in love with it."), Exercise(id = "en-listen-bridge-news-q6", kind = "choice", prompt = "Why does this report rely so heavily on the passive?", options = listOf("The doers matter less than the facts", "The doers are famous", "It is an error", "To hide the costs"), answers = listOf("The doers matter less than the facts"), explain = "News reports the event: was closed, was reopened, was carried out.")), skills = listOf("listening:connected-speech", "listening:detail", "grammar:passive-intro", "grammar:relative-clauses")) }

object ListenData068 { val text = ListeningText(id = "en-listen-podcast-habits", languageID = "en", title = "Podcast: the habits episode", level = "B2", topic = "free time", unitID = "en-foundations-viewpoints", text = "HOST: Welcome back. Today, habits — the ones that stick and the ones that don't. With me, Dr Amaia Ruiz, who has spent a decade researching behaviour. Amaia, quick version: why do most New Year's resolutions fail? DR RUIZ: Because they're ambitions, not systems. People say 'I'll get fit' — that's a wish. A system is 'I run on Tuesdays with Sam.' HOST: So the friend is part of the system? DR RUIZ: The friend is the system. Accountability beats motivation roughly nine times out of ten in our data. HOST: Nine out of ten! And the two-minute rule everyone quotes? DR RUIZ: Useful, slightly overrated. Starting small matters less than starting at the same time. The clock does the remembering for you. HOST: One habit you'd recommend to everyone? DR RUIZ: A ten-minute walk after lunch. Boring, free, and — according to everything we know — the closest thing to a miracle we've measured.", questions = listOf(Exercise(id = "en-listen-podcast-habits-q1", kind = "choice", prompt = "Why do most resolutions fail, according to Dr Ruiz?", options = listOf("They're ambitions, not systems", "January is too cold", "People are lazy", "Gyms are expensive"), answers = listOf("They're ambitions, not systems"), explain = "'I'll get fit' is a wish; a system is 'I run on Tuesdays with Sam.'"), Exercise(id = "en-listen-podcast-habits-q2", kind = "written", prompt = "What beats motivation in her data?", options = listOf(), answers = listOf("accountability", "the friend", "accountability beats motivation"), explain = "Accountability beats motivation nine times out of ten."), Exercise(id = "en-listen-podcast-habits-q3", kind = "choice", prompt = "What does she think of the two-minute rule?", options = listOf("Useful, slightly overrated", "Completely wrong", "The best idea", "Dangerous"), answers = listOf("Useful, slightly overrated"), explain = "Starting small matters less than starting at the same time."), Exercise(id = "en-listen-podcast-habits-q4", kind = "written", prompt = "What does the clock do, according to Dr Ruiz?", options = listOf(), answers = listOf("the remembering for you", "does the remembering", "remembers for you"), explain = "The clock does the remembering for you."), Exercise(id = "en-listen-podcast-habits-q5", kind = "choice", prompt = "What habit does she recommend to everyone?", options = listOf("A ten-minute walk after lunch", "Running on Tuesdays", "Going to the gym", "Journaling"), answers = listOf("A ten-minute walk after lunch"), explain = "Boring, free, and the closest thing to a miracle they've measured."), Exercise(id = "en-listen-podcast-habits-q6", kind = "choice", prompt = "What makes this sound like a podcast rather than an essay?", options = listOf("The host's interruptions and quick exchanges", "The long sentences", "The passive voice", "The statistics only"), answers = listOf("The host's interruptions and quick exchanges"), explain = "Turn-taking, reactions and short questions are the podcast register.")), skills = listOf("listening:connected-speech", "listening:inference", "grammar:first-conditional", "function:talk-about-routines")) }

object ListenData069 { val text = ListeningText(id = "en-listen-keynote", languageID = "en", title = "The keynote", level = "C1", topic = "work", unitID = "en-foundations-nuance", text = "Good afternoon. I'd like to begin with a confession: everything I believed about attention five years ago has aged badly. The research I'll present today — conducted across four countries, with the caveats that such breadth demands — suggests something uncomfortable: our capacity for sustained focus hasn't declined so much as our tolerance for discomfort has collapsed. Now, I appreciate that's a strong claim. The evidence runs like this. In conditions where devices were removed — not silenced, removed — reading comprehension recovered to pre-smartphone baselines within nine days. What participants reported, however, was not relief but a kind of withdrawal, which raises the question I'd like to leave you with: if a tool has rewritten our baseline for what feels bearable, is it a tool any more? I'll let you sit with that. Thank you.", questions = listOf(Exercise(id = "en-listen-keynote-q1", kind = "choice", prompt = "How does the speaker open the keynote?", options = listOf("With a confession", "With a joke", "With data", "With thanks"), answers = listOf("With a confession"), explain = "Everything I believed five years ago has aged badly — a confession opener."), Exercise(id = "en-listen-keynote-q2", kind = "written", prompt = "What has collapsed, according to the research?", options = listOf(), answers = listOf("Our tolerance for discomfort"), explain = "Not our focus — our tolerance for discomfort has collapsed."), Exercise(id = "en-listen-keynote-q3", kind = "choice", prompt = "How does she flag the strength of her claim?", options = listOf("Now, I appreciate that's a strong claim", "Obviously", "Everyone knows", "She doesn't"), answers = listOf("Now, I appreciate that's a strong claim"), explain = "Naming the claim's strength is the C1 move: hedge before you hit."), Exercise(id = "en-listen-keynote-q4", kind = "written", prompt = "What recovered within nine days when devices were removed?", options = listOf(), answers = listOf("reading comprehension", "comprehension recovered to pre-smartphone baselines", "reading"), explain = "Reading comprehension recovered to pre-smartphone baselines."), Exercise(id = "en-listen-keynote-q5", kind = "choice", prompt = "What did participants report feeling?", options = listOf("A kind of withdrawal", "Relief", "Nothing", "Happiness"), answers = listOf("A kind of withdrawal"), explain = "Not relief — a kind of withdrawal."), Exercise(id = "en-listen-keynote-q6", kind = "choice", prompt = "What is the closing question really about?", options = listOf("Whether a tool that rewrites our baseline is still a tool", "Device batteries", "Reading speed", "Four countries"), answers = listOf("Whether a tool that rewrites our baseline is still a tool"), explain = "She leaves the redefinition question with the audience.")), skills = listOf("listening:connected-speech", "listening:inference", "function:express-opinion", "grammar:connectors")) }

object ListenData070 { val text = ListeningText(id = "en-listen-radio-debate", languageID = "en", title = "The radio debate", level = "C1", topic = "work", unitID = "en-foundations-nuance", text = "Radio phone-in, two guests, one question: should cities ban cars from their centres? The urbanist goes first: 'The evidence tends to support it. Air quality improves, shops report more foot traffic. I wouldn't say it solves everything — admittedly, delivery logistics need rethinking — but the direction is clear.' The taxi representative is unimpressed: 'That's a very comfortable position for someone with a parking space. It is often claimed that everyone supports these bans. My members do not.' The host steps in: 'Let me bring you both together. If — and at this stage it's an if — the city invested in night deliveries, would that change your position?' A long pause. 'It would certainly change mine,' the taxi man admits. The urbanist laughs: 'Then we have something to build on.'", questions = listOf(Exercise(id = "en-listen-radio-debate-q1", kind = "choice", prompt = "What is the urbanist's position?", options = listOf("The evidence tends to support the ban", "The ban solves everything", "The ban is tyranny", "She has no position"), answers = listOf("The evidence tends to support the ban"), explain = "Hedged: tends to support, not solves everything."), Exercise(id = "en-listen-radio-debate-q2", kind = "written", prompt = "What does the urbanist concede?", options = listOf(), answers = listOf("delivery logistics need rethinking", "deliveries are a problem"), explain = "Admittedly, delivery logistics need rethinking."), Exercise(id = "en-listen-radio-debate-q3", kind = "choice", prompt = "What does 'It is often claimed that everyone supports these bans' imply?", options = listOf("The claim is exaggerated", "Everyone supports them", "It is a fact", "Nobody supports them"), answers = listOf("The claim is exaggerated"), explain = "The passive + often claims distance the speaker from the claim."), Exercise(id = "en-listen-radio-debate-q4", kind = "written", prompt = "What is the host's conditional question?", options = listOf(), answers = listOf("if the city invested in night deliveries", "whether the city invested in night deliveries"), explain = "If the city invested in night deliveries, would positions change?"), Exercise(id = "en-listen-radio-debate-q5", kind = "choice", prompt = "How does the taxi man respond at the end?", options = listOf("It would certainly change mine", "Never", "He leaves", "He agrees fully"), answers = listOf("It would certainly change mine"), explain = "A conditional concession — something to build on."), Exercise(id = "en-listen-radio-debate-q6", kind = "choice", prompt = "What does the urbanist's laugh suggest?", options = listOf("A starting point for agreement", "She is mocking him", "She disagrees", "She is nervous"), answers = listOf("A starting point for agreement"), explain = "'Then we have something to build on.'")), skills = listOf("grammar:second-conditional", "function:negotiate", "grammar:connectors", "function:express-opinion"), exposureSkills = listOf("grammar:first-conditional")) }

object ListenData071 { val text = ListeningText(id = "en-listen-viewpoint-interview", languageID = "en", title = "The viewpoint interview", level = "B2", topic = "work", unitID = "en-foundations-viewpoints", text = "Interviewer: 'You've argued that the five-day office week is obsolete. But many CEOs disagree.' Marta: 'They do, and I understand why. Commercial leases are expensive. Middle managers built careers on supervision. But the data — and I'd point to the Stanford study of sixteen thousand workers — shows remote workers are 13% more productive.' Interviewer: 'What about young employees who need mentorship?' Marta: 'Fair point. My answer is structured onboarding, not forced presence. You can mentor on Tuesday and Thursday without watching someone's desk on Monday.' Interviewer: 'If you were CEO of a Fortune 500, what would you do first?' Marta: 'I'd scrap the office policy entirely and rebuild it around outcomes, not hours.'", questions = listOf(Exercise(id = "en-listen-viewpoint-interview-q1", kind = "choice", prompt = "What does Marta argue?", options = listOf("The five-day office week is obsolete", "CEOs are always right", "Remote work is perfect", "Ban all offices"), answers = listOf("The five-day office week is obsolete"), explain = "She argues the five-day office week is obsolete."), Exercise(id = "en-listen-viewpoint-interview-q2", kind = "written", prompt = "What study does Marta cite?", options = listOf(), answers = listOf("the stanford study", "stanford"), explain = "The Stanford study of 16,000 workers."), Exercise(id = "en-listen-viewpoint-interview-q3", kind = "choice", prompt = "What does Marta propose instead of forced presence?", options = listOf("Structured onboarding", "More offices", "Higher salaries", "Fewer meetings"), answers = listOf("Structured onboarding"), explain = "Her answer is structured onboarding, not forced presence."), Exercise(id = "en-listen-viewpoint-interview-q4", kind = "written", prompt = "What would Marta do first as CEO?", options = listOf(), answers = listOf("scrap the office policy"), explain = "Scrap the office policy and rebuild around outcomes."), Exercise(id = "en-listen-viewpoint-interview-q5", kind = "choice", prompt = "What does Marta concede about young employees?", options = listOf("They need mentorship", "They are less productive", "They prefer offices", "They need more money"), answers = listOf("They need mentorship"), explain = "Fair point: young employees need mentorship."), Exercise(id = "en-listen-viewpoint-interview-q6", kind = "choice", prompt = "How does Marta handle the CEO hypothetical?", options = listOf("She gives a direct answer", "She refuses", "She laughs", "She changes topic"), answers = listOf("She gives a direct answer"), explain = "If I were CEO, I'd scrap the office policy — direct and structured.")), skills = listOf("grammar:second-conditional", "function:express-opinion", "grammar:connectors", "vocab:work"), exposureSkills = listOf("grammar:passive-intro")) }

object ListenData072 { val text = ListeningText(id = "en-listen-hospital-stories", languageID = "en", title = "Stories from the ward", level = "B2", topic = "health", unitID = "en-foundations-viewpoints", text = "Nurse Rosa has worked the night shift for twelve years, and she's collected stories the way other people collect stamps. There was the man who sang opera to his IV drip — he said it was Puccini or nothing. And the woman who refused to sleep until she'd taught every nurse on the ward to make paella. 'It took three nights,' Rosa remembers. 'But the paella was excellent.' The hardest stories, she says, are the quiet ones — the patients who ask the same question over and over because they're more afraid of the answer than the illness. 'You answer it every time. That's the job. You answer, and you stay.'", questions = listOf(Exercise(id = "en-listen-hospital-stories-q1", kind = "choice", prompt = "How long has Rosa worked nights?", options = listOf("Twelve years", "Two years", "Twenty years", "Ten years"), answers = listOf("Twelve years"), explain = "Twelve years on the night shift."), Exercise(id = "en-listen-hospital-stories-q2", kind = "written", prompt = "What did the opera man sing to his IV drip?", options = listOf(), answers = listOf("puccini", "opera"), explain = "Puccini — or nothing."), Exercise(id = "en-listen-hospital-stories-q3", kind = "choice", prompt = "How many nights did the paella lesson take?", options = listOf("Three", "One", "Two", "Five"), answers = listOf("Three"), explain = "Three nights — but the paella was excellent."), Exercise(id = "en-listen-hospital-stories-q4", kind = "choice", prompt = "What are the hardest stories?", options = listOf("The quiet ones — patients afraid of the answer", "The loud ones", "The opera singers", "The long shifts"), answers = listOf("The quiet ones — patients afraid of the answer"), explain = "Patients afraid of the answer than the illness."), Exercise(id = "en-listen-hospital-stories-q5", kind = "written", prompt = "What is the job, according to Rosa?", options = listOf(), answers = listOf("answer and stay"), explain = "You answer, and you stay."), Exercise(id = "en-listen-hospital-stories-q6", kind = "choice", prompt = "What does Rosa collect?", options = listOf("Stories", "Stamps", "IV drips", "Recipes"), answers = listOf("Stories"), explain = "Stories, like others collect stamps.")), skills = listOf("listening:inference", "grammar:past-continuous", "function:talk-about-health", "vocab:health"), exposureSkills = listOf("grammar:used-to")) }

object ListenData073 { val text = ListeningText(id = "en-listen-podcast-nuance", languageID = "en", title = "The nuance episode", level = "C1", topic = "work", unitID = "en-foundations-nuance", text = "HOST: You've written that 'nuance is the first casualty of urgency.' That's a great line — but what does it mean? AUTHOR: It means that when we're in a hurry, we flatten complex positions into for-and-against. And most interesting problems are neither. HOST: Give me an example. AUTHOR: Take remote work. The productive question isn't 'is it good or bad?' — it's 'which parts of which jobs benefit from which conditions?' That's a harder question, and the answer is boring: it depends. HOST: So nuance is just… saying it depends? AUTHOR: [laughs] No — it depends is where nuance starts, not where it ends. The next step is specifying: depends on what, for whom, under what conditions. HOST: And that's the book? AUTHOR: That's the book.", questions = listOf(Exercise(id = "en-listen-podcast-nuance-q1", kind = "choice", prompt = "What is the first casualty of urgency?", options = listOf("Nuance", "Data", "Humour", "Time"), answers = listOf("Nuance"), explain = "Nuance is the first casualty of urgency."), Exercise(id = "en-listen-podcast-nuance-q2", kind = "written", prompt = "What does urgency do to complex positions?", options = listOf(), answers = listOf("flattens them into for-and-against"), explain = "It flattens complex positions into for-and-against."), Exercise(id = "en-listen-podcast-nuance-q3", kind = "choice", prompt = "What's the productive question about remote work?", options = listOf("Which parts benefit from which conditions", "Is it good or bad", "Should everyone be remote", "Why do people hate it"), answers = listOf("Which parts benefit from which conditions"), explain = "Not good-or-bad, but which parts of which jobs benefit from which conditions."), Exercise(id = "en-listen-podcast-nuance-q4", kind = "written", prompt = "What's the boring answer?", options = listOf(), answers = listOf("it depends"), explain = "The answer is boring: it depends."), Exercise(id = "en-listen-podcast-nuance-q5", kind = "choice", prompt = "Where does nuance start and end?", options = listOf("Starts at it depends, ends with specification", "Starts with data", "Starts and ends with it depends", "Never starts"), answers = listOf("Starts at it depends, ends with specification"), explain = "It depends is where nuance starts; specifying conditions is where it goes."), Exercise(id = "en-listen-podcast-nuance-q6", kind = "choice", prompt = "What's the book about?", options = listOf("Specifying what nuance depends on", "Remote work", "Urgency", "Podcasts"), answers = listOf("Specifying what nuance depends on"), explain = "Depends on what, for whom, under what conditions.")), skills = listOf("listening:inference", "grammar:connectors", "function:express-opinion", "vocab:collocations")) }

object ListenData074 { val text = ListeningText(id = "es-listen-cafe-morning", languageID = "es", title = "Un café antes del trabajo", level = "A1", topic = "rutina", unitID = "es-foundations-u1", text = "Cada mañana, Marta camina hasta una cafetería pequeña cerca de su piso. El camarero sabe su nombre, así que nunca tiene que pedir. Hoy se sienta junto a la ventana con un café y un croissant. Su autobús sale a las ocho y media, pero no está preocupada. La cafetería es muy tranquila a esta hora. Bebe su café despacio y mira cómo la ciudad despierta.", questions = listOf(Exercise(id = "es-listen-cafe-morning-q1", kind = "choice", prompt = "¿Adónde va Marta cada mañana?", options = listOf("A una cafetería pequeña", "A su oficina", "A la estación de autobuses", "A un parque"), answers = listOf("A una cafetería pequeña"), explain = "Camina hasta una cafetería pequeña cerca de su piso."), Exercise(id = "es-listen-cafe-morning-q2", kind = "choice", prompt = "¿Qué desayuna hoy?", options = listOf("Un café y un croissant", "Té y tostadas", "Zumo de naranja", "Nada"), answers = listOf("Un café y un croissant"), explain = "Se sienta junto a la ventana con un café y un croissant."), Exercise(id = "es-listen-cafe-morning-q3", kind = "written", prompt = "¿A qué hora sale su autobús?", options = listOf(), answers = listOf("a las ocho y media", "las ocho y media", "ocho y media"), explain = "Su autobús sale a las ocho y media."), Exercise(id = "es-listen-cafe-morning-q4", kind = "choice", prompt = "¿Cómo se siente con el tiempo?", options = listOf("No está preocupada", "Está muy tarde", "Está enfadada", "Tiene sueño"), answers = listOf("No está preocupada"), explain = "El texto dice que no está preocupada."), Exercise(id = "es-listen-cafe-morning-q5", kind = "choice", prompt = "¿Quién sabe su nombre?", options = listOf("El camarero", "El conductor del autobús", "Su jefe", "Un vecino"), answers = listOf("El camarero"), explain = "El camarero sabe su nombre, así que nunca tiene que pedir."), Exercise(id = "es-listen-cafe-morning-q6", kind = "written", prompt = "¿Dónde se sienta hoy?", options = listOf(), answers = listOf("junto a la ventana", "al lado de la ventana", "en la ventana"), explain = "Hoy se sienta junto a la ventana.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")) }

object ListenData075 { val text = ListeningText(id = "es-listen-language-class", languageID = "es", title = "La clase de idiomas", level = "A1", topic = "presentaciones", unitID = "es-foundations-u1", text = "Marta asiste a su primera clase de portugués en un instituto pequeño. En la clase hay seis personas y todas quieren hablar. La profesora pide presentaciones. «Me llamo Marta y soy de Bolivia», dice una señora. «Yo soy Andrés, soy de Perú y trabajo en un restaurante», dice un chico joven. Marta también se presenta: «Soy Marta, soy de Argentina y soy enfermera». La profesora es de Madrid y enseña con mucho humor. Al final de la clase, los estudiantes intercambian números de teléfono. No son amigos todavía, pero la próxima semana van a tomar un café juntos y practicar.", questions = listOf(Exercise(id = "es-listen-language-class-q1", kind = "choice", prompt = "¿Cuántas personas hay en la clase?", options = listOf("Seis", "Tres", "Diez", "Catorce"), answers = listOf("Seis"), explain = "En la clase hay seis personas."), Exercise(id = "es-listen-language-class-q2", kind = "choice", prompt = "¿De dónde es Andrés?", options = listOf("De Perú", "De Bolivia", "De Argentina", "De México"), answers = listOf("De Perú"), explain = "Andrés es de Perú y trabaja en un restaurante."), Exercise(id = "es-listen-language-class-q3", kind = "choice", prompt = "¿Cuál es el trabajo de Marta?", options = listOf("Enfermera", "Profesora", "Camarera", "Estudiante"), answers = listOf("Enfermera"), explain = "Marta es de Argentina y es enfermera."), Exercise(id = "es-listen-language-class-q4", kind = "written", prompt = "¿De dónde es la profesora?", options = listOf(), answers = listOf("madrid", "de madrid", "es de madrid"), explain = "La profesora es de Madrid."), Exercise(id = "es-listen-language-class-q5", kind = "choice", prompt = "¿Qué hacen al final de la clase?", options = listOf("Intercambian números de teléfono", "Vuelven a casa solos", "Hacen un examen", "Cenan en un restaurante"), answers = listOf("Intercambian números de teléfono"), explain = "Los estudiantes intercambian números de teléfono."), Exercise(id = "es-listen-language-class-q6", kind = "written", prompt = "¿Qué van a hacer la próxima semana?", options = listOf(), answers = listOf("tomar un café", "van a tomar un café", "tomar un café juntos"), explain = "La próxima semana van a tomar un café juntos y practicar.")), skills = listOf("listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself")) }

object ListenData076 { val text = ListeningText(id = "es-listen-little-sister", languageID = "es", title = "Mi hermana pequeña", level = "A1", topic = "familia", unitID = "es-foundations-u1", text = "Mi hermana pequeña se llama Carla y tiene nueve años. Es muy simpática y muy habladora. Carla no es callada: habla con todo el mundo, con los vecinos, con los profesores y con los perros del parque. Es rubia, como nuestra madre, y tiene los ojos marrones como mi padre. No es alta para su edad, pero es muy rápida y le encanta el fútbol. Su equipo no es muy bueno, pero a ella no le importa. «Yo no soy profesional», dice ella, «yo solo soy feliz con la pelota». Mi hermana es pequeña, pero su alegría es enorme.", questions = listOf(Exercise(id = "es-listen-little-sister-q1", kind = "choice", prompt = "¿Cuántos años tiene Carla?", options = listOf("Nueve", "Diecinueve", "Siete", "Diez"), answers = listOf("Nueve"), explain = "Carla tiene nueve años."), Exercise(id = "es-listen-little-sister-q2", kind = "choice", prompt = "¿Cómo es Carla?", options = listOf("Simpática y habladora", "Tímida y callada", "Seria", "Triste"), answers = listOf("Simpática y habladora"), explain = "Es muy simpática y muy habladora."), Exercise(id = "es-listen-little-sister-q3", kind = "written", prompt = "¿De qué color son sus ojos?", options = listOf(), answers = listOf("marrones", "marrón", "los ojos marrones"), explain = "Tiene los ojos marrones como su padre."), Exercise(id = "es-listen-little-sister-q4", kind = "choice", prompt = "¿Cómo es su pelo?", options = listOf("Rubio, como su madre", "Moreno, como su padre", "Pelirrojo", "Corto y negro"), answers = listOf("Rubio, como su madre"), explain = "Es rubia, como nuestra madre."), Exercise(id = "es-listen-little-sister-q5", kind = "choice", prompt = "¿Qué le encanta?", options = listOf("El fútbol", "La natación", "La música", "Los videojuegos"), answers = listOf("El fútbol"), explain = "Es muy rápida y le encanta el fútbol."), Exercise(id = "es-listen-little-sister-q6", kind = "written", prompt = "¿Cómo es su alegría?", options = listOf(), answers = listOf("enorme", "muy grande", "grande"), explain = "Su alegría es enorme.")), skills = listOf("listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family")) }

object ListenData077 { val text = ListeningText(id = "es-listen-new-flatmate", languageID = "es", title = "Un nuevo compañero de piso", level = "A1", topic = "casa", unitID = "es-foundations-u1", text = "Tom tiene un compañero de piso nuevo. Se llama Leo y tiene veintitrés años. Leo viene de un pueblo pequeño del norte, pero ahora trabaja en la ciudad. Tiene dos cajas, una guitarra y una bicicleta. El piso tiene dos habitaciones y una cocina luminosa. Tom espera que a Leo le guste cocinar, porque a Tom no le gusta nada.", questions = listOf(Exercise(id = "es-listen-new-flatmate-q1", kind = "choice", prompt = "¿Cuántos años tiene Leo?", options = listOf("Veintitrés", "Treinta y dos", "Veinte", "Treinta"), answers = listOf("Veintitrés"), explain = "Leo tiene veintitrés años."), Exercise(id = "es-listen-new-flatmate-q2", kind = "choice", prompt = "¿Qué NO tiene Leo?", options = listOf("Un televisor", "Dos cajas", "Una guitarra", "Una bicicleta"), answers = listOf("Un televisor"), explain = "Tiene dos cajas, una guitarra y una bicicleta — sin televisor."), Exercise(id = "es-listen-new-flatmate-q3", kind = "written", prompt = "¿Qué odia hacer Tom?", options = listOf(), answers = listOf("cocinar", "odia cocinar", "tom odia cocinar"), explain = "A Tom no le gusta nada cocinar."), Exercise(id = "es-listen-new-flatmate-q4", kind = "choice", prompt = "¿Cómo es el piso?", options = listOf("Dos habitaciones y una cocina luminosa", "Un dormitorio y un balcón", "Un jardín", "Dos baños"), answers = listOf("Dos habitaciones y una cocina luminosa"), explain = "El piso tiene dos habitaciones y una cocina luminosa."), Exercise(id = "es-listen-new-flatmate-q5", kind = "choice", prompt = "¿Dónde trabaja Leo ahora?", options = listOf("En la ciudad", "En un pueblo", "En el norte", "No trabaja"), answers = listOf("En la ciudad"), explain = "Viene de un pueblo pequeño, pero ahora trabaja en la ciudad."), Exercise(id = "es-listen-new-flatmate-q6", kind = "written", prompt = "¿Qué instrumento tiene Leo?", options = listOf(), answers = listOf("una guitarra", "la guitarra", "guitarra"), explain = "Leo tiene una guitarra.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")) }

object ListenData078 { val text = ListeningText(id = "es-listen-new-neighbour", languageID = "es", title = "La vecina nueva", level = "A1", topic = "gente", unitID = "es-foundations-u1", text = "En el edificio hay una vecina nueva. Se llama Amélie y es de Francia. No es estudiante; es fotógrafa. No trabaja en una oficina: trabaja en casa y viaja mucho. Los vecinos son curiosos, pero también son tímidos, así que no le hablan. Entonces, una mañana, Ben la encuentra en la puerta. «¿Eres tú la vecina nueva?», pregunta él. «Sí, soy yo», contesta ella, «y estoy contenta de estar aquí». Ahora son amigos, y ella ya no está sola en el edificio.", questions = listOf(Exercise(id = "es-listen-new-neighbour-q1", kind = "choice", prompt = "¿De dónde es Amélie?", options = listOf("De Francia", "De Italia", "De Japón", "De Brasil"), answers = listOf("De Francia"), explain = "Amélie es de Francia."), Exercise(id = "es-listen-new-neighbour-q2", kind = "choice", prompt = "¿Cuál es su trabajo?", options = listOf("Es fotógrafa", "Es estudiante", "Trabaja en una oficina", "Es profesora"), answers = listOf("Es fotógrafa"), explain = "No es estudiante; es fotógrafa."), Exercise(id = "es-listen-new-neighbour-q3", kind = "choice", prompt = "¿Trabaja en una oficina?", options = listOf("No, trabaja en casa", "Sí, todos los días", "Solo en verano", "No lo dice"), answers = listOf("No, trabaja en casa"), explain = "No trabaja en una oficina: trabaja en casa."), Exercise(id = "es-listen-new-neighbour-q4", kind = "written", prompt = "¿Por qué no le hablan los vecinos?", options = listOf(), answers = listOf("son tímidos", "porque son tímidos", "tímidos"), explain = "Son curiosos, pero también son tímidos."), Exercise(id = "es-listen-new-neighbour-q5", kind = "choice", prompt = "¿Dónde la encuentra Ben?", options = listOf("En la puerta", "En el ascensor", "En la calle", "En la cafetería"), answers = listOf("En la puerta"), explain = "Una mañana, Ben la encuentra en la puerta."), Exercise(id = "es-listen-new-neighbour-q6", kind = "written", prompt = "¿Cómo se siente Amélie al final?", options = listOf(), answers = listOf("contenta", "feliz", "está contenta"), explain = "Dice que está contenta de estar aquí.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")) }

object ListenData079 { val text = ListeningText(id = "es-listen-sunday-market", languageID = "es", title = "El mercado del domingo", level = "A1", topic = "compras", unitID = "es-foundations-u1", text = "Los domingos hay un mercado en la plaza del pueblo. Ana y su padre van allí a las nueve, antes de que se llene. Compran fruta, pan y flores. Ana quiere unas fresas, pero su padre dice que esta semana son muy caras. Al final se llevan una bolsa grande de naranjas y unas rosas blancas para la mesa de la cocina.", questions = listOf(Exercise(id = "es-listen-sunday-market-q1", kind = "choice", prompt = "¿Cuándo van Ana y su padre al mercado?", options = listOf("A las nueve", "Al mediodía", "Por la tarde", "A las seis y media"), answers = listOf("A las nueve"), explain = "Van a las nueve, antes de que se llene."), Exercise(id = "es-listen-sunday-market-q2", kind = "written", prompt = "¿Por qué no compra Ana las fresas?", options = listOf(), answers = listOf("son muy caras", "muy caras", "porque son muy caras"), explain = "Su padre dice que son muy caras esta semana."), Exercise(id = "es-listen-sunday-market-q3", kind = "choice", prompt = "¿Qué se llevan a casa?", options = listOf("Naranjas y rosas", "Fresas y pan", "Manzanas y tulipanes", "Pan y queso"), answers = listOf("Naranjas y rosas"), explain = "Se llevan naranjas y rosas blancas."), Exercise(id = "es-listen-sunday-market-q4", kind = "choice", prompt = "¿Dónde está el mercado?", options = listOf("En la plaza del pueblo", "Junto al río", "En la estación", "En un supermercado"), answers = listOf("En la plaza del pueblo"), explain = "Hay un mercado en la plaza del pueblo los domingos."), Exercise(id = "es-listen-sunday-market-q5", kind = "choice", prompt = "¿Qué compran?", options = listOf("Fruta, pan y flores", "Pescado y verduras", "Queso y carne", "Solo flores"), answers = listOf("Fruta, pan y flores"), explain = "Compran fruta, pan y flores."), Exercise(id = "es-listen-sunday-market-q6", kind = "written", prompt = "¿Qué quiere Ana?", options = listOf(), answers = listOf("fresas", "unas fresas", "quiere fresas"), explain = "Ana quiere unas fresas.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")) }

object ListenData080 { val text = ListeningText(id = "es-listen-piso-elegido", languageID = "es", title = "El piso elegido", level = "A2", topic = "pisos", unitID = "es-foundations-u7", text = "Lucía y Pablo buscan piso en la app. El primero es más barato, pero está peor situado: a cuarenta minutos del centro. El segundo cuesta cien euros más al mes, pero es más luminoso y tiene balcón. Lucía opina que la luz es lo más importante, porque trabaja desde casa. Al final deciden pedir visita al segundo: es más caro, pero es el mejor de los dos para ellos.", questions = listOf(Exercise(id = "es-listen-piso-elegido-q1", kind = "choice", prompt = "¿Cuántos pisos comparan?", options = listOf("Dos", "Tres", "Cuatro"), answers = listOf("Dos"), explain = "Comparan dos pisos en la app."), Exercise(id = "es-listen-piso-elegido-q2", kind = "choice", prompt = "¿Qué problema tiene el más barato?", options = listOf("Está lejos del centro", "No tiene balcón", "Es muy caro", "Es pequeño"), answers = listOf("Está lejos del centro"), explain = "A cuarenta minutos del centro."), Exercise(id = "es-listen-piso-elegido-q3", kind = "written", prompt = "¿Cuánto cuesta más el segundo al mes?", options = listOf(), answers = listOf("cien euros", "100 euros"), explain = "Cuesta cien euros más al mes."), Exercise(id = "es-listen-piso-elegido-q4", kind = "choice", prompt = "¿Qué es lo más importante para Lucía?", options = listOf("La luz", "El precio", "El balcón", "La cocina"), answers = listOf("La luz"), explain = "Trabaja desde casa y la luz es lo más importante."), Exercise(id = "es-listen-piso-elegido-q5", kind = "choice", prompt = "¿Qué deciden al final?", options = listOf("Pedir visita al segundo", "Quedarse con el primero", "Seguir buscando", "Pedir descuento"), answers = listOf("Pedir visita al segundo"), explain = "Deciden pedir visita al segundo."), Exercise(id = "es-listen-piso-elegido-q6", kind = "written", prompt = "¿Para quién es el mejor?", options = listOf(), answers = listOf("para ellos"), explain = "Es el mejor de los dos para ellos.")), skills = listOf("listening:gist", "listening:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")) }

object ListenData081 { val text = ListeningText(id = "es-listen-plan-sabado", languageID = "es", title = "El sábado, organizado", level = "A2", topic = "planes", unitID = "es-foundations-u7", text = "Elena llama a su hermano para organizar el sábado. Él propone ir a la montaña, pero va a llover, así que Elena sugiere el museo nuevo. Van a quedar a las diez en la entrada principal y van a comer en el mercado de al lado, que es más barato que los restaurantes del centro. Por la noche no tienen plan: van a decidir sobre la marcha, cuando sepan qué tiempo hace.", questions = listOf(Exercise(id = "es-listen-plan-sabado-q1", kind = "choice", prompt = "¿Quién propone la montaña?", options = listOf("El hermano", "Elena", "Su madre", "Un amigo"), answers = listOf("El hermano"), explain = "Su hermano propone ir a la montaña."), Exercise(id = "es-listen-plan-sabado-q2", kind = "choice", prompt = "¿Por qué no van a la montaña?", options = listOf("Va a llover", "Están cansados", "El museo es gratis", "La montaña está lejos"), answers = listOf("Va a llover"), explain = "Va a llover, así que van al museo."), Exercise(id = "es-listen-plan-sabado-q3", kind = "written", prompt = "¿A qué hora van a quedar?", options = listOf(), answers = listOf("a las diez", "las diez"), explain = "Van a quedar a las diez."), Exercise(id = "es-listen-plan-sabado-q4", kind = "choice", prompt = "¿Dónde van a comer?", options = listOf("En el mercado de al lado", "En un restaurante del centro", "En casa", "En el museo"), answers = listOf("En el mercado de al lado"), explain = "Es más barato que los restaurantes del centro."), Exercise(id = "es-listen-plan-sabado-q5", kind = "choice", prompt = "¿Qué van a hacer por la noche?", options = listOf("Decidir sobre la marcha", "Ir al cine", "Volver temprano", "Quedar con amigos"), answers = listOf("Decidir sobre la marcha"), explain = "Van a decidir cuando sepan el tiempo.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("grammar:future-forms")) }

object ListenData082 { val text = ListeningText(id = "es-listen-primera-vez", languageID = "es", title = "Cosas que no he hecho", level = "B1", topic = "viajes", unitID = "es-foundations-u5", text = "En la cocina de un hostal, tres viajeros comparan vidas. Diego ha visitado veinte países, pero nunca ha aprendido a nadar: «Lo sé, es ridículo». Valeria ha buceado dos veces con tortugas, pero no ha salido de América Latina hasta este viaje. Y Marta, que lleva seis años en la carretera, nunca ha volado: cruza los océanos en barco y las fronteras en autobús. «¿Nunca?», pregunta Diego. «Nunca. El miedo es más viejo que yo.» Se ríen de lo que no han hecho, y Marta dice algo que se quedan todos: «No hace falta haberlo hecho todo. Basta con seguir queriendo».", questions = listOf(Exercise(id = "es-listen-primera-vez-q1", kind = "choice", prompt = "¿Qué no ha hecho nunca Diego?", options = listOf("Aprender a nadar", "Visitar veinte países", "Cruzar en barco", "Salir de América"), answers = listOf("Aprender a nadar"), explain = "Ha visitado veinte países, pero nunca ha aprendido a nadar."), Exercise(id = "es-listen-primera-vez-q2", kind = "written", prompt = "¿Cuántas veces ha buceado Valeria?", options = listOf(), answers = listOf("dos veces", "2 veces", "dos"), explain = "Valeria ha buceado dos veces con tortugas."), Exercise(id = "es-listen-primera-vez-q3", kind = "choice", prompt = "¿Cómo cruza Marta los océanos?", options = listOf("En barco", "En avión", "En autobús", "A pie"), answers = listOf("En barco"), explain = "Cruza los océanos en barco y las fronteras en autobús."), Exercise(id = "es-listen-primera-vez-q4", kind = "choice", prompt = "¿Qué dice Marta sobre el miedo?", options = listOf("Es más viejo que ella", "Es más joven que ella", "Es ridículo", "Se ha ido"), answers = listOf("Es más viejo que ella"), explain = "El miedo es más viejo que yo."), Exercise(id = "es-listen-primera-vez-q5", kind = "written", prompt = "¿Qué basta, según Marta?", options = listOf(), answers = listOf("seguir queriendo", "con seguir queriendo"), explain = "Basta con seguir queriendo."), Exercise(id = "es-listen-primera-vez-q6", kind = "choice", prompt = "¿Cómo reaccionan los tres?", options = listOf("Se ríen", "Se enfadan", "Se van", "Lloran"), answers = listOf("Se ríen"), explain = "Se ríen de lo que no han hecho.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")) }

object ListenData083 { val text = ListeningText(id = "es-listen-cambio-pueblo", languageID = "es", title = "De la ciudad al pueblo", level = "B1", topic = "cambios", unitID = "es-foundations-u5", text = "Nacho explica por qué dejó Madrid. Antes vivía en un piso pequeño y trabajaba once horas al día: «Ganaba bien, pero no tenía vida». Un invierno se puso enfermo, y entonces entendió que algo tenía que cambiar. Ahora vive en un pueblo de mil habitantes, trabaja desde casa por las mañanas y cultiva un huerto por las tardes. «Gano menos, pero me sobra tiempo.» Al principio sus padres no lo entendían; ahora vienen cada mes. «¿Te arrepientes de algo?», le pregunta su amiga. «De no haberlo hecho antes».", questions = listOf(Exercise(id = "es-listen-cambio-pueblo-q1", kind = "choice", prompt = "¿Dónde vivía Nacho antes?", options = listOf("En Madrid", "En un pueblo", "En Barcelona", "En un hostal"), answers = listOf("En Madrid"), explain = "Nacho explica por qué dejó Madrid."), Exercise(id = "es-listen-cambio-pueblo-q2", kind = "written", prompt = "¿Cuántas horas trabajaba al día?", options = listOf(), answers = listOf("once horas", "11 horas", "once"), explain = "Trabajaba once horas al día."), Exercise(id = "es-listen-cambio-pueblo-q3", kind = "choice", prompt = "¿Qué le hizo cambiar?", options = listOf("Se puso enfermo", "Perdió el trabajo", "Ganó la lotería", "Conoció a alguien"), answers = listOf("Se puso enfermo"), explain = "Un invierno se puso enfermo, y entonces entendió que tenía que cambiar."), Exercise(id = "es-listen-cambio-pueblo-q4", kind = "choice", prompt = "¿Qué hace por las tardes ahora?", options = listOf("Cultiva un huerto", "Trabaja más horas", "Viaja cada mes", "Estudia"), answers = listOf("Cultiva un huerto"), explain = "Trabaja desde casa por las mañanas y cultiva un huerto por las tardes."), Exercise(id = "es-listen-cambio-pueblo-q5", kind = "written", prompt = "¿Qué se arrepiente Nacho?", options = listOf(), answers = listOf("de no haberlo hecho antes", "no haberlo hecho antes"), explain = "«De no haberlo hecho antes».")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions")) }

object ListenData084 { val text = ListeningText(id = "es-listen-regateo-mesa", languageID = "es", title = "El regateo de la mesa", level = "B2", topic = "negocios", unitID = "es-foundations-u8", text = "En una app de segunda mano, Clara quiere una mesa de madera que cuesta 80 euros. « ¿Y si nos viéramos en 60 ? », propone ella. El vendedor no acepta: « Solo si te la llevas hoy ». Clara lo piensa: « Te daría 65 si incluyes la silla ». « Imposible », ríe él, « pero te dejaría la mesa en 70 y te la subiría al piso ». Clara no lo duda: « ¿La subirías tú sola ? ». « Tengo un carro », responde. « Trato hecho », dice ella, y añade: « Si me gusta tanto como en la foto, te dejo una reseña de cinco estrellas ».", questions = listOf(Exercise(id = "es-listen-regateo-mesa-q1", kind = "choice", prompt = "¿Cuánto pide el vendedor por la mesa ?", options = listOf("80 euros", "60 euros", "70 euros", "65 euros"), answers = listOf("80 euros"), explain = "La mesa cuesta 80 euros."), Exercise(id = "es-listen-regateo-mesa-q2", kind = "written", prompt = "¿Qué propone Clara primero ?", options = listOf(), answers = listOf("60 euros", "sesenta euros", "nos vieramos en 60", "nos viéramos en 60"), explain = "« ¿Y si nos viéramos en 60 ? »."), Exercise(id = "es-listen-regateo-mesa-q3", kind = "choice", prompt = "¿Qué condición pone el vendedor ?", options = listOf("Llevarla hoy", "Pagar en efectivo", "Añadir una reseña", "Volver mañana"), answers = listOf("Llevarla hoy"), explain = "« Solo si te la llevas hoy »."), Exercise(id = "es-listen-regateo-mesa-q4", kind = "choice", prompt = "¿Qué ofrece el vendedor por 70 ?", options = listOf("Subirle la mesa al piso", "Añadir la silla", "Bajar a 60", "Darle un carro"), answers = listOf("Subirle la mesa al piso"), explain = "« Te la subiría al piso »."), Exercise(id = "es-listen-regateo-mesa-q5", kind = "written", prompt = "¿Qué promete Clara si le gusta ?", options = listOf(), answers = listOf("una resena de cinco estrellas", "una reseña de cinco estrellas", "resena cinco estrellas"), explain = "Una reseña de cinco estrellas.")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors")) }

object ListenData085 { val text = ListeningText(id = "es-listen-noticia-barrio", languageID = "es", title = "La noticia del barrio", level = "B2", topic = "noticias", unitID = "es-foundations-u9", text = "En el mercado, Ana y Luis comentan lo que se dice. « Se dice que van a peatonalizar la calle Mayor », cuenta Ana. « ¿Otra vez ? », se ríe Luis. « La noticia que leí dice que empiezan en primavera ». Según el ayuntamiento, serían solo los sábados, pero los comerciantes, cuyo negocio dependería del turismo, ya se han manifestado. « Es cierto que bajaría el ruido », reconoce Luis, « pero, ¿y el aparcamiento ? ». Ana defiende la medida: « Por un lado, más gente caminaría; por otro, los autobuses llegarían a la puerta ». Se quedan sin resolverlo, pero prometen volver a hablarlo cuando se publique el plan.", questions = listOf(Exercise(id = "es-listen-noticia-barrio-q1", kind = "choice", prompt = "¿Qué se dice de la calle Mayor ?", options = listOf("Que la peatonalizarán", "Que la ampliarán", "Que la cerrarán", "Que cambiará de nombre"), answers = listOf("Que la peatonalizarán"), explain = "« Se dice que van a peatonalizar la calle Mayor »."), Exercise(id = "es-listen-noticia-barrio-q2", kind = "written", prompt = "¿Cuándo empezarían ?", options = listOf(), answers = listOf("en primavera", "primavera"), explain = "« La noticia que leí dice que empiezan en primavera »."), Exercise(id = "es-listen-noticia-barrio-q3", kind = "choice", prompt = "¿Qué dice el ayuntamiento ?", options = listOf("Solo los sábados", "Todos los días", "Solo en verano", "Los festivos"), answers = listOf("Solo los sábados"), explain = "Según el ayuntamiento, serían solo los sábados."), Exercise(id = "es-listen-noticia-barrio-q4", kind = "choice", prompt = "¿Quién se ha manifestado ?", options = listOf("Los comerciantes", "Los vecinos", "Los taxistas", "El ayuntamiento"), answers = listOf("Los comerciantes"), explain = "Los comerciantes ya se han manifestado."), Exercise(id = "es-listen-noticia-barrio-q5", kind = "written", prompt = "¿Qué prometen Ana y Luis ?", options = listOf(), answers = listOf("volver a hablarlo", "hablarlo otra vez", "volverlo a hablar"), explain = "Prometen volver a hablarlo cuando se publique el plan.")), skills = listOf("listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors")) }

object ListenData086 { val text = ListeningText(id = "es-listen-debate-radio", languageID = "es", title = "Tertulia: el teletrabajo", level = "C1", topic = "debate", unitID = "es-foundations-u10", text = "En « Punto de vista », la tertulia de la emisora, la presentadora abre el debate sobre el teletrabajo. « Para empezar, un dato: la productividad sube, según el ministerio », dice. Un contertulio relativiza la cifra: « En cierto modo, sí; pero, desde mi punto de vista, ese dato mide otra cosa ». Una editorial, en cambio, defiende volver a la oficina: « A esto se añade que el equipo necesita verse ». « No obstante », apostilla la presentadora, « hay quien trabaja a cien kilómetros de la sede ». La tertulia se encrespa: por otra parte, nadie menciona los costes del transporte. « En resumen », cierra la presentadora, « el debate sigue abierto: por así decirlo, ni blanco ni negro ».", questions = listOf(Exercise(id = "es-listen-debate-radio-q1", kind = "choice", prompt = "¿Qué tema abre la tertulia ?", options = listOf("El teletrabajo", "El precio del transporte", "Los indicadores del ministerio", "Una editorial del día"), answers = listOf("El teletrabajo"), explain = "La presentadora abre el debate sobre el teletrabajo."), Exercise(id = "es-listen-debate-radio-q2", kind = "written", prompt = "¿Qué dato da la presentadora para empezar ?", options = listOf(), answers = listOf("sube la productividad", "la productividad sube", "que sube la productividad"), explain = "« Un dato: la productividad sube »."), Exercise(id = "es-listen-debate-radio-q3", kind = "choice", prompt = "¿Qué opina el contertulio de ese dato ?", options = listOf("Que mide otra cosa", "Que es falso", "Que lo firma el ministerio", "Que es definitivo"), answers = listOf("Que mide otra cosa"), explain = "« En cierto modo, sí; pero… ese dato mide otra cosa »."), Exercise(id = "es-listen-debate-radio-q4", kind = "choice", prompt = "¿Qué añade la editorial al debate ?", options = listOf("Que el equipo necesita verse", "Que la oficina es cara", "Que sube la productividad", "Que nadie usa el metro"), answers = listOf("Que el equipo necesita verse"), explain = "« A esto se añade que el equipo necesita verse »."), Exercise(id = "es-listen-debate-radio-q5", kind = "written", prompt = "¿Cómo cierra la presentadora el programa ?", options = listOf(), answers = listOf("el debate sigue abierto", "sigue abierto", "ni blanco ni negro"), explain = "« En resumen… el debate sigue abierto ».")), skills = listOf("listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion")) }

object ListenData087 { val text = ListeningText(id = "es-listen-charla-claves", languageID = "es", title = "Tres claves para presentar", level = "C1", topic = "comunicación", unitID = "es-foundations-u10", text = "Gracias por venir. Hoy quiero compartir con ustedes tres claves para presentar ideas con claridad. La primera: abrir con un mapa. « Para empezar » y « en primer lugar » no son adornos: le dicen al oyente por dónde vamos. La segunda: encadenar, no saltar. Cada argumento debe venir tomado de la mano del anterior — por otra parte, a esto se añade que… —; si saltamos de piedra en piedra, el público se baja del tren. Y la tercera: cerrar con una sola idea. « En resumen » significa elegir: si su conclusión tiene tres frases, no es una conclusión, es un resumen mal entendido. Desde mi punto de vista, quien domina estos conectores no improvisa: simplemente se deja leer. Pasemos ahora a practicar con un caso real de consulta.", questions = listOf(Exercise(id = "es-listen-charla-claves-q1", kind = "choice", prompt = "¿Cuál es el propósito principal de la charla ?", options = listOf("Explicar cómo presentar ideas", "Vender un libro de estilo", "Critica las reuniones de trabajo", "Contar la carrera de la ponente"), answers = listOf("Explicar cómo presentar ideas"), explain = "Toda la charla gira alrededor de presentar ideas con claridad."), Exercise(id = "es-listen-charla-claves-q2", kind = "choice", prompt = "¿Cuántas claves presenta la ponente ?", options = listOf("Tres", "Dos", "Cuatro", "Cinco"), answers = listOf("Tres"), explain = "« Hoy quiero compartir con ustedes tres claves »."), Exercise(id = "es-listen-charla-claves-q3", kind = "written", prompt = "Según la charla, ¿qué significa cerrar con « en resumen » ?", options = listOf(), answers = listOf("elegir", "elegir una sola idea", "una sola idea"), explain = "« En resumen significa elegir »: una sola idea final."), Exercise(id = "es-listen-charla-claves-q4", kind = "choice", prompt = "¿Cómo deben encadenarse los argumentos ?", options = listOf("Tomados de la mano del anterior", "Cada uno por su lado", "Del más fuerte al más débil", "Por orden de llegada"), answers = listOf("Tomados de la mano del anterior"), explain = "Cada argumento viene tomado de la mano del anterior; si saltas, el público se baja del tren."), Exercise(id = "es-listen-charla-claves-q5", kind = "written", prompt = "¿Qué dice la ponente de quien domina los conectores ?", options = listOf(), answers = listOf("no improvisa", "que no improvisa", "se deja leer"), explain = "« No improvisa: simplemente se deja leer ».")), skills = listOf("listening:gist", "listening:detail", "grammar:connectors", "vocab:work")) }

object ListenData088 { val text = ListeningText(id = "es-listen-podcast-matices", languageID = "es", title = "En defensa del matiz", level = "C1", topic = "lenguaje", unitID = "es-foundations-u10", text = "En « Se dice así », Marta y Diego discuten sobre la manía de matizar. « Hoy en cierto modo todo el mundo matiza », observa Marta. « ¿Moda ? Yo diría que es pereza: decimos \"más o menos\" para no mojarnos », rebate Diego. « No obstante, matizar no es cobardía; por así decirlo, es dejar la puerta abierta », responde ella. « Desde tu punto de vista, claro: tú jamás das un sí rotundo », se burla él. « Tampoco hace falta: en una reunión, un matiz a tiempo te ahorra una discusión ». « Bueno, ahí te doy la razón: mejor un \"hasta cierto punto\" honesto que un \"sí\" que luego te pesa ». « Trato hecho: matices bien entendidos ».", questions = listOf(Exercise(id = "es-listen-podcast-matices-q1", kind = "choice", prompt = "¿Qué piensa Diego de la moda de matizar ?", options = listOf("Que a veces es pereza", "Que es obligatoria en las reuniones", "Que es muy reciente", "Que la defiende sin reservas"), answers = listOf("Que a veces es pereza"), explain = "« Yo diría que es pereza: decimos más o menos para no mojarnos »."), Exercise(id = "es-listen-podcast-matices-q2", kind = "written", prompt = "Según Marta, ¿qué consigue un matiz a tiempo ?", options = listOf(), answers = listOf("te ahorra una discusion", "te ahorra una discusión", "ahorra una discusión"), explain = "« Un matiz a tiempo te ahorra una discusión »."), Exercise(id = "es-listen-podcast-matices-q3", kind = "choice", prompt = "¿En qué punto cede Diego ?", options = listOf("Mejor un matiz honesto que un sí que pesa", "Que Marta nunca da un sí rotundo", "Que los matices son pereza", "Que hay que mojarse siempre"), answers = listOf("Mejor un matiz honesto que un sí que pesa"), explain = "« Mejor un 'hasta cierto punto' honesto que un 'sí' que luego te pesa »."), Exercise(id = "es-listen-podcast-matices-q4", kind = "written", prompt = "¿Cómo defiende Marta el hecho de matizar ?", options = listOf(), answers = listOf("dejar la puerta abierta", "no es cobardia", "no es cobardía"), explain = "« Matizar no es cobardía; es dejar la puerta abierta »."), Exercise(id = "es-listen-podcast-matices-q5", kind = "choice", prompt = "¿Qué tono tiene la conversación al final ?", options = listOf("Cordial", "Enfrentado", "Indiferente", "Fríamente profesional"), answers = listOf("Cordial"), explain = "Se dan la razón en parte y cierran en buen término.")), skills = listOf("listening:inference", "listening:connected-speech", "function:express-opinion", "vocab:social-expressions")) }

object ListenData089 { val text = ListeningText(id = "es-listen-piso-nuevo", languageID = "es", title = "Un piso nuevo", level = "A1", topic = "casa", unitID = "es-foundations-u11", text = "Leo tiene un piso nuevo en el centro. El piso tiene dos habitaciones y un salón grande. En el salón hay un sofá azul y una mesa junto a la ventana. La cocina es pequeña, pero hay una mesa para desayunar. Su compañero de piso se llama Martín. Su habitación está limpia y sus libros están encima de la mesa. No hay lavavajillas, así que lavan los platos a mano. A Leo le gusta el piso porque está cerca de un parque.", questions = listOf(Exercise(id = "es-listen-piso-nuevo-q1", kind = "choice", prompt = "¿Cuántas habitaciones tiene el piso?", options = listOf("Dos", "Tres", "Cuatro", "Una"), answers = listOf("Dos"), explain = "El piso tiene dos habitaciones y un salón grande."), Exercise(id = "es-listen-piso-nuevo-q2", kind = "choice", prompt = "¿Dónde está la mesa del salón?", options = listOf("Junto a la ventana", "En la cocina", "Debajo del sofá", "En el pasillo"), answers = listOf("Junto a la ventana"), explain = "Hay una mesa junto a la ventana."), Exercise(id = "es-listen-piso-nuevo-q3", kind = "written", prompt = "¿Cómo se llama su compañero de piso?", options = listOf(), answers = listOf("Martin", "Martín"), explain = "Su compañero de piso se llama Martín."), Exercise(id = "es-listen-piso-nuevo-q4", kind = "choice", prompt = "¿Dónde están los libros de Martín?", options = listOf("Encima de la mesa", "Debajo de la cama", "En el salón", "En una caja"), answers = listOf("Encima de la mesa"), explain = "Sus libros están encima de la mesa."), Exercise(id = "es-listen-piso-nuevo-q5", kind = "written", prompt = "¿Por qué le gusta el piso a Leo?", options = listOf(), answers = listOf("esta cerca de un parque", "está cerca de un parque", "porque está cerca de un parque"), explain = "Está cerca de un parque."), Exercise(id = "es-listen-piso-nuevo-q6", kind = "choice", prompt = "¿Cómo es la cocina?", options = listOf("Pequeña", "Grande", "Nueva", "Moderna"), answers = listOf("Pequeña"), explain = "La cocina es pequeña, pero hay una mesa para desayunar.")), skills = listOf("listening:gist", "listening:detail", "grammar:there-is-are", "grammar:prepositions-place", "vocab:home")) }

object ListenData090 { val text = ListeningText(id = "es-listen-paseo-barrio", languageID = "es", title = "Un paseo por el barrio", level = "A1", topic = "barrio", unitID = "es-foundations-u12", text = "Hoy soy nuevo en el barrio. Pregunto a una señora: «Perdone, ¿hay un supermercado por aquí?». «Sí, hay uno en la esquina», dice ella. «¿Y una farmacia?». «Siga recto y gire a la izquierda; está a tres minutos». Camino y veo el supermercado, pero no veo la farmacia. Una chica me ayuda: «Está detrás del supermercado, muy cerca». Al final compro agua y pan. El barrio es tranquilo y la gente es muy amable.", questions = listOf(Exercise(id = "es-listen-paseo-barrio-q1", kind = "choice", prompt = "¿Dónde está el supermercado?", options = listOf("En la esquina", "En la plaza", "Detrás de la farmacia", "Muy lejos"), answers = listOf("En la esquina"), explain = "La señora dice: hay uno en la esquina."), Exercise(id = "es-listen-paseo-barrio-q2", kind = "choice", prompt = "¿Qué hay que hacer para llegar a la farmacia?", options = listOf("Siga recto y gire a la izquierda", "Gire a la derecha", "Tome el autobús", "Vuelva a casa"), answers = listOf("Siga recto y gire a la izquierda"), explain = "Siga recto y gire a la izquierda."), Exercise(id = "es-listen-paseo-barrio-q3", kind = "written", prompt = "¿Dónde está la farmacia?", options = listOf(), answers = listOf("detras del supermercado", "detrás del supermercado", "muy cerca"), explain = "Está detrás del supermercado."), Exercise(id = "es-listen-paseo-barrio-q4", kind = "choice", prompt = "¿Qué compra al final?", options = listOf("Agua y pan", "Fruta", "Leche y café", "Nada"), answers = listOf("Agua y pan"), explain = "Al final compra agua y pan."), Exercise(id = "es-listen-paseo-barrio-q5", kind = "choice", prompt = "¿Cómo es el barrio?", options = listOf("Tranquilo", "Ruidoso", "Grande", "Feo"), answers = listOf("Tranquilo"), explain = "El barrio es tranquilo."), Exercise(id = "es-listen-paseo-barrio-q6", kind = "written", prompt = "¿Cómo es la gente del barrio?", options = listOf(), answers = listOf("muy amable", "es muy amable", "amable"), explain = "La gente es muy amable.")), skills = listOf("listening:gist", "listening:detail", "grammar:there-is-are", "vocab:town", "function:ask-for-directions")) }

object ListenData091 { val text = ListeningText(id = "es-listen-llamada-abuela", languageID = "es", title = "Una llamada a la abuela", level = "A1", topic = "familia", unitID = "es-foundations-u13", text = "Hablo con mi abuela por teléfono. «¡Hola, abuela! ¿Está el abuelo?». «No está ahora; está en el mercado. ¿Todo bien?». «Sí, abuela. Mi hermana siempre estudia por la noche y a veces cena con nosotros. Nunca tenemos tiempo los viernes». «¿Y tu madre?». «Trabaja mucho, pero llamamos los domingos». «Vale, cariño. Dile al abuelo que llamo más tarde». «Vale, abuela. Un beso».", questions = listOf(Exercise(id = "es-listen-llamada-abuela-q1", kind = "choice", prompt = "¿Con quién habla?", options = listOf("Con su abuela", "Con su tío", "Con su madre", "Con su hermana"), answers = listOf("Con su abuela"), explain = "Hablo con mi abuela por teléfono."), Exercise(id = "es-listen-llamada-abuela-q2", kind = "choice", prompt = "¿Dónde está el abuelo?", options = listOf("En el mercado", "En casa", "En el trabajo", "En la calle"), answers = listOf("En el mercado"), explain = "No está ahora; está en el mercado."), Exercise(id = "es-listen-llamada-abuela-q3", kind = "choice", prompt = "¿Qué hace siempre la hermana?", options = listOf("Estudia por la noche", "Cena fuera", "Llama a la abuela", "Trabaja mucho"), answers = listOf("Estudia por la noche"), explain = "Mi hermana siempre estudia por la noche."), Exercise(id = "es-listen-llamada-abuela-q4", kind = "written", prompt = "¿Qué hace a veces la hermana?", options = listOf(), answers = listOf("Cena con nosotros", "cena con nosotros", "a veces cena con nosotros"), explain = "A veces cena con nosotros."), Exercise(id = "es-listen-llamada-abuela-q5", kind = "choice", prompt = "¿Cuándo llaman a la madre?", options = listOf("Los domingos", "Los viernes", "Los sábados", "Los lunes"), answers = listOf("Los domingos"), explain = "Llamamos los domingos."), Exercise(id = "es-listen-llamada-abuela-q6", kind = "written", prompt = "¿Qué va a hacer la abuela con el abuelo?", options = listOf(), answers = listOf("Llamar más tarde", "llamar mas tarde", "llamar más tarde"), explain = "Dile al abuelo que llamo más tarde.")), skills = listOf("listening:gist", "listening:detail", "vocab:family", "vocab:daily-routine", "grammar:frequency-adverbs")) }

object ListenData092 { val text = ListeningText(id = "es-listen-finde-lluvioso", languageID = "es", title = "Un sábado de lluvia", level = "A1", topic = "clima", unitID = "es-foundations-u14", text = "Hoy es sábado y llueve mucho. Nunca salgo los días de lluvia. Por la mañana veo una serie y a veces leo un libro. Mi hermano siempre juega al fútbol, pero hoy no puede: hace frío y llueve. Por la tarde vamos al cine con nuestros amigos. En esta ciudad llueve mucho en otoño, pero en verano hace sol todos los días. Me gusta el otoño, pero no me gusta la lluvia.", questions = listOf(Exercise(id = "es-listen-finde-lluvioso-q1", kind = "choice", prompt = "¿Qué tiempo hace hoy?", options = listOf("Llueve", "Nieva", "Hace sol", "Hace viento"), answers = listOf("Llueve"), explain = "Hoy es sábado y llueve mucho."), Exercise(id = "es-listen-finde-lluvioso-q2", kind = "choice", prompt = "¿Qué hace el narrador por la mañana?", options = listOf("Ve una serie y a veces lee", "Juega al fútbol", "Va al cine", "Sale con amigos"), answers = listOf("Ve una serie y a veces lee"), explain = "Por la mañana veo una serie y a veces leo un libro."), Exercise(id = "es-listen-finde-lluvioso-q3", kind = "written", prompt = "¿Por qué no puede jugar al fútbol el hermano?", options = listOf(), answers = listOf("Porque llueve", "porque hace frío", "porque hace frio", "porque llueve y hace frío"), explain = "Hace frío y llueve."), Exercise(id = "es-listen-finde-lluvioso-q4", kind = "choice", prompt = "¿Adónde van por la tarde?", options = listOf("Al cine", "A la piscina", "Al mercado", "A la montaña"), answers = listOf("Al cine"), explain = "Por la tarde vamos al cine."), Exercise(id = "es-listen-finde-lluvioso-q5", kind = "choice", prompt = "¿Cómo es el verano en esta ciudad?", options = listOf("Hace sol todos los días", "Llueve todos los días", "Nieva mucho", "Hace frío"), answers = listOf("Hace sol todos los días"), explain = "En verano hace sol todos los días."), Exercise(id = "es-listen-finde-lluvioso-q6", kind = "written", prompt = "¿Qué estación le gusta?", options = listOf(), answers = listOf("El otoño", "el otoño", "el otono"), explain = "Me gusta el otoño.")), skills = listOf("listening:gist", "listening:detail", "vocab:weather", "function:talk-about-weather", "grammar:frequency-adverbs")) }

object ListenData093 { val text = ListeningText(id = "es-listen-metro-perdido", languageID = "es", title = "Perdido en el metro", level = "A1", topic = "transporte", unitID = "es-foundations-u15", text = "Estoy en el centro y quiero ir al museo. No conozco la ciudad y estoy perdido. Pregunto a una señora: «¿Dónde está la estación de metro, por favor?». La señora dice: «Está en la plaza, al lado del banco». Tomo la línea cuatro y bajo en la parada del museo. El metro pasa cada cinco minutos y el viaje dura diez. Llego al museo a las once y cuarto. Los billetes cuestan dos euros y cincuenta.", questions = listOf(Exercise(id = "es-listen-metro-perdido-q1", kind = "choice", prompt = "¿Adónde quiere ir el narrador?", options = listOf("Al museo", "A la estación", "Al banco", "A la plaza"), answers = listOf("Al museo"), explain = "Estoy en el centro y quiero ir al museo."), Exercise(id = "es-listen-metro-perdido-q2", kind = "choice", prompt = "¿Dónde está la estación de metro?", options = listOf("En la plaza, al lado del banco", "Dentro del museo", "En la parada del bus", "Al final de la calle"), answers = listOf("En la plaza, al lado del banco"), explain = "La señora dice: «Está en la plaza, al lado del banco»."), Exercise(id = "es-listen-metro-perdido-q3", kind = "written", prompt = "¿Qué línea toma el narrador?", options = listOf(), answers = listOf("La línea cuatro", "la linea cuatro", "la cuatro"), explain = "Tomo la línea cuatro."), Exercise(id = "es-listen-metro-perdido-q4", kind = "choice", prompt = "¿Cada cuánto pasa el metro?", options = listOf("Cada cinco minutos", "Cada diez minutos", "Cada quince minutos", "Cada media hora"), answers = listOf("Cada cinco minutos"), explain = "El metro pasa cada cinco minutos."), Exercise(id = "es-listen-metro-perdido-q5", kind = "written", prompt = "¿A qué hora llega al museo?", options = listOf(), answers = listOf("A las once y cuarto", "a las once y cuarto", "las once y cuarto"), explain = "Llego al museo a las once y cuarto."), Exercise(id = "es-listen-metro-perdido-q6", kind = "written", prompt = "¿Cuánto cuesta el billete?", options = listOf(), answers = listOf("Dos euros y cincuenta", "dos euros con cincuenta", "2,50 euros"), explain = "Los billetes cuestan dos euros y cincuenta.")), skills = listOf("listening:gist", "listening:detail", "vocab:transport", "function:tell-time")) }

object ListenData094 { val text = ListeningText(id = "es-listen-farmacia-sabado", languageID = "es", title = "Sábado en la farmacia", level = "A1", topic = "salud", unitID = "es-foundations-u16", text = "Es sábado y no me siento bien. Me duele la garganta y tengo tos, pero no tengo fiebre. Voy a la farmacia de mi barrio y pregunto por un jarabe para la tos. El farmacéutico pregunta: «¿Para quién es?». Es para mí. Compro también unas pastillas para la garganta: cuestan tres euros. La pastilla es una cada ocho horas y el jarabe, tres veces al día. Por la tarde descanso en casa y bebo mucha agua. Nunca tomo medicamentos sin preguntar primero.", questions = listOf(Exercise(id = "es-listen-farmacia-sabado-q1", kind = "choice", prompt = "¿Qué le duele?", options = listOf("La garganta", "La cabeza", "El estómago", "La espalda"), answers = listOf("La garganta"), explain = "Me duele la garganta."), Exercise(id = "es-listen-farmacia-sabado-q2", kind = "choice", prompt = "¿Qué tiene y qué no tiene?", options = listOf("Tos, pero no fiebre", "Fiebre, pero no tos", "Fiebre y tos", "Ni tos ni fiebre"), answers = listOf("Tos, pero no fiebre"), explain = "Tengo tos, pero no tengo fiebre."), Exercise(id = "es-listen-farmacia-sabado-q3", kind = "choice", prompt = "¿Qué compra para la garganta?", options = listOf("Pastillas", "Jarabe", "Agua", "Nada"), answers = listOf("Pastillas"), explain = "Compro también unas pastillas para la garganta."), Exercise(id = "es-listen-farmacia-sabado-q4", kind = "written", prompt = "¿Cuánto cuestan las pastillas?", options = listOf(), answers = listOf("Tres euros", "tres euros", "3 euros"), explain = "Las pastillas cuestan tres euros."), Exercise(id = "es-listen-farmacia-sabado-q5", kind = "written", prompt = "¿Cada cuántas horas toma la pastilla?", options = listOf(), answers = listOf("Cada ocho horas", "cada ocho horas", "cada 8 horas"), explain = "La pastilla es una cada ocho horas."), Exercise(id = "es-listen-farmacia-sabado-q6", kind = "choice", prompt = "¿Qué hace por la tarde?", options = listOf("Descansa en casa y bebe agua", "Trabaja en la farmacia", "Sale con amigos", "Juega al fútbol"), answers = listOf("Descansa en casa y bebe agua"), explain = "Por la tarde descanso en casa y bebo mucha agua.")), skills = listOf("listening:gist", "listening:detail", "vocab:health", "grammar:frequency-adverbs")) }

object ListenData095 { val text = ListeningText(id = "es-listen-cena-sorpresa", languageID = "es", title = "Una cena de sorpresa", level = "A1", topic = "restaurantes", unitID = "es-foundations-u17", text = "Es el cumpleaños de Marta. Sus amigos organizan una cena de sorpresa en un restaurante del centro. La carta tiene paella, gazpacho y tortilla. Los amigos piden tres menús y dos jarras de agua. Marta no sabe nada: cree que es una cena normal con su amiga Laura. A las nueve, Marta entra en el restaurante y todos cantan: «¡Sorpresa!». El camarero trae un pastel con velas y dice: «El pastel es de la casa». Marta llora de alegría.", questions = listOf(Exercise(id = "es-listen-cena-sorpresa-q1", kind = "choice", prompt = "¿Quién organiza la cena?", options = listOf("Sus amigos", "Su familia", "Laura", "El camarero"), answers = listOf("Sus amigos"), explain = "Sus amigos organizan una cena de sorpresa."), Exercise(id = "es-listen-cena-sorpresa-q2", kind = "choice", prompt = "¿Qué hay en la carta?", options = listOf("Paella, gazpacho y tortilla", "Sopa y ensalada", "Pasta y pizza", "Solo postres"), answers = listOf("Paella, gazpacho y tortilla"), explain = "La carta tiene paella, gazpacho y tortilla."), Exercise(id = "es-listen-cena-sorpresa-q3", kind = "written", prompt = "¿Qué piden para beber?", options = listOf(), answers = listOf("dos jarras de agua", "jarras de agua", "agua"), explain = "Piden dos jarras de agua."), Exercise(id = "es-listen-cena-sorpresa-q4", kind = "choice", prompt = "¿Qué cree Marta al principio?", options = listOf("Que es una cena normal", "Que es su cumpleaños", "Que Laura no viene", "Que el restaurante está cerrado"), answers = listOf("Que es una cena normal"), explain = "Cree que es una cena normal con su amiga Laura."), Exercise(id = "es-listen-cena-sorpresa-q5", kind = "written", prompt = "¿A qué hora entra Marta?", options = listOf(), answers = listOf("a las nueve", "las nueve", "nueve"), explain = "A las nueve, Marta entra en el restaurante."), Exercise(id = "es-listen-cena-sorpresa-q6", kind = "choice", prompt = "¿Quién trae el pastel?", options = listOf("El camarero", "Laura", "Un amigo", "La madre de Marta"), answers = listOf("El camarero"), explain = "El camarero trae un pastel con velas.")), skills = listOf("listening:gist", "listening:detail", "vocab:food", "function:order-food")) }

object ListenData096 { val text = ListeningText(id = "es-listen-plan-cumpleanos", languageID = "es", title = "El plan del cumpleaños", level = "A2", topic = "planes", unitID = "es-foundations-u18", text = "Marta llama a Daniel para organizar el cumpleaños de su amiga Vega, que es el jueves. Marta va a reservar una mesa en un restaurante mexicano, pero prefiere preguntar primero si Vega puede ese día. Daniel se va a encargar del regalo: va a comprarle unos libros, porque Vega lee muchísimo. Van a quedar a las nueve en la puerta del restaurante, y Daniel va a llegar un poco antes con el regalo escondido en la mochila. Marta se ríe: si Vega pregunta por qué van al restaurante, van a decirle que es porque sí.", questions = listOf(Exercise(id = "es-listen-plan-cumpleanos-q1", kind = "choice", prompt = "¿De quién es el cumpleaños?", options = listOf("De Vega", "De Marta", "De Daniel", "De la madre de Marta"), answers = listOf("De Vega"), explain = "Es el cumpleaños de Vega, la amiga de Marta."), Exercise(id = "es-listen-plan-cumpleanos-q2", kind = "written", prompt = "¿Qué va a hacer Marta primero?", options = listOf(), answers = listOf("reservar una mesa", "reservar mesa", "va a reservar una mesa"), explain = "Marta va a reservar una mesa en un restaurante mexicano."), Exercise(id = "es-listen-plan-cumpleanos-q3", kind = "choice", prompt = "¿Qué va a comprarle Daniel?", options = listOf("Unos libros", "Una mochila", "Una mesa", "Un pastel"), answers = listOf("Unos libros"), explain = "Va a comprarle unos libros, porque Vega lee muchísimo."), Exercise(id = "es-listen-plan-cumpleanos-q4", kind = "choice", prompt = "¿Por qué elige Daniel libros?", options = listOf("Porque Vega lee muchísimo", "Porque son baratos", "Porque no hay tiendas", "Porque Vega lo pide"), answers = listOf("Porque Vega lee muchísimo"), explain = "«…porque Vega lee muchísimo»."), Exercise(id = "es-listen-plan-cumpleanos-q5", kind = "written", prompt = "¿A qué hora van a quedar?", options = listOf(), answers = listOf("a las nueve", "las nueve", "nueve"), explain = "Van a quedar a las nueve en la puerta del restaurante."), Exercise(id = "es-listen-plan-cumpleanos-q6", kind = "choice", prompt = "¿Dónde va a esconder Daniel el regalo?", options = listOf("En la mochila", "En el coche", "En el restaurante", "En casa de Marta"), answers = listOf("En la mochila"), explain = "Con el regalo escondido en la mochila.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to", "vocab:social-expressions")) }

object ListenData097 { val text = ListeningText(id = "es-listen-anecdota-verano", languageID = "es", title = "La anécdota del concierto", level = "B1", topic = "anécdotas", unitID = "es-foundations-u19", text = "Marcos cuenta su anécdota del verano. «Pues mira, fui a un concierto en Valencia con mi prima. Llegamos con mucha antelación y comimos en un bar cerca. De repente, mi prima gritó: ¡el ticket! Lo dejó en el bar, así que volvió corriendo mientras yo guardaba el sitio en la cola. Resultó que un camarero encontró el ticket y me lo trajo hasta el recinto. Al final, mi prima entró justo a tiempo y la banda estrenó su canción favorita. Cuando se lo conté a mi madre, no me creyó: dijo que esas cosas solo me pasan a mí».", questions = listOf(Exercise(id = "es-listen-anecdota-verano-q1", kind = "choice", prompt = "¿Dónde pasó la anécdota?", options = listOf("En Valencia", "En el bar", "En casa de su madre", "En un pueblo"), answers = listOf("En Valencia"), explain = "«Fui a un concierto en Valencia con mi prima»."), Exercise(id = "es-listen-anecdota-verano-q2", kind = "written", prompt = "¿Qué se dejó la prima en el bar?", options = listOf(), answers = listOf("el ticket", "El ticket", "la entrada"), explain = "«¡El ticket! Lo dejó en el bar»."), Exercise(id = "es-listen-anecdota-verano-q3", kind = "choice", prompt = "¿Quién encontró el ticket?", options = listOf("Un camarero", "La madre de Marcos", "Un guardia", "La prima"), answers = listOf("Un camarero"), explain = "«Resultó que un camarero encontró el ticket»."), Exercise(id = "es-listen-anecdota-verano-q4", kind = "choice", prompt = "¿Qué hizo Marcos mientras su prima volvía?", options = listOf("Guardó el sitio en la cola", "Volvió al bar", "Compró otro ticket", "Entró sin ticket"), answers = listOf("Guardó el sitio en la cola"), explain = "«Volvió corriendo mientras yo guardaba el sitio en la cola»."), Exercise(id = "es-listen-anecdota-verano-q5", kind = "written", prompt = "¿Qué canción sonó al final?", options = listOf(), answers = listOf("su canción favorita", "la canción favorita", "canción favorita"), explain = "«La banda estrenó su canción favorita»."), Exercise(id = "es-listen-anecdota-verano-q6", kind = "choice", prompt = "¿Cómo reaccionó la madre?", options = listOf("No le creyó", "Se enfadó", "Lloró", "Fue al concierto"), answers = listOf("No le creyó"), explain = "«No me creyó: esas cosas solo me pasan a mí».")), skills = listOf("listening:inference", "listening:detail", "grammar:past-simple-irregular", "grammar:connectors")) }

object ListenData098 { val text = ListeningText(id = "es-listen-debate-tacto", languageID = "es", title = "Discrepar sin romper", level = "C1", topic = "debate", unitID = "es-foundations-u10", text = "En el programa «Contrapunto», dos invitados debaten sobre prohibir los coches en el centro. «Creo que la medida es necesaria; la contaminación se ha doblado», arranca Elena. «Entiendo tu punto, pero la gente vive en el centro de paso: primero el transporte público», responde Juan. «Es discutible —matiza ella—, precisamente porque el bus ya duplica su frecuencia». El moderador interviene: «Veo por dónde van ambos: de acuerdo en el fondo, no en el calendario». Juan sonríe: «No lo veo así, pero prometo no volver a aparcar en la plaza». Elena remata: «Y yo prometo no dar nunca más por cerrado un debate a las diez de la noche».", questions = listOf(Exercise(id = "es-listen-debate-tacto-q1", kind = "choice", prompt = "¿Qué se debate?", options = listOf("Prohibir los coches en el centro", "El precio del bus", "La contaminación de la playa", "El calendario escolar"), answers = listOf("Prohibir los coches en el centro"), explain = "Debaten sobre prohibir los coches en el centro."), Exercise(id = "es-listen-debate-tacto-q2", kind = "choice", prompt = "¿Cuál es la postura de Elena?", options = listOf("La medida es necesaria", "Primero el transporte público", "No hay contaminación", "Es discutible"), answers = listOf("La medida es necesaria"), explain = "«La medida es necesaria; la contaminación se ha doblado»."), Exercise(id = "es-listen-debate-tacto-q3", kind = "choice", prompt = "¿Cómo responde Juan a Elena?", options = listOf("«Entiendo tu punto, pero…»", "«No me interesa tu opinión»", "«Estás equivocada por completo»", "«Cambiemos de tema»"), answers = listOf("«Entiendo tu punto, pero…»"), explain = "«Entiendo tu punto, pero la gente vive en el centro de paso»."), Exercise(id = "es-listen-debate-tacto-q4", kind = "written", prompt = "¿Por qué dice Elena que es discutible?", options = listOf(), answers = listOf("porque el bus ya duplica su frecuencia", "el bus ya duplica su frecuencia", "porque el bus duplica su frecuencia"), explain = "«Es discutible, precisamente porque el bus ya duplica su frecuencia»."), Exercise(id = "es-listen-debate-tacto-q5", kind = "choice", prompt = "¿En qué están de acuerdo ambos, según el moderador?", options = listOf("En el fondo, no en el calendario", "En nada", "En el precio del transporte", "En prohibir todo"), answers = listOf("En el fondo, no en el calendario"), explain = "«De acuerdo en el fondo, no en el calendario»."), Exercise(id = "es-listen-debate-tacto-q6", kind = "choice", prompt = "¿Qué tono tiene el debate al final?", options = listOf("Cordial, con humor", "Enfrentado", "Triste", "Indiferente"), answers = listOf("Cordial, con humor"), explain = "Las promesas con humor cierran el debate en tono cordial.")), skills = listOf("listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion")) }

object ListenData099 { val text = ListeningText(id = "es-listen-tertulia-viernes", languageID = "es", title = "La tertulia del viernes", level = "A1", topic = "visitas", unitID = "es-foundations-u20", text = "Los viernes, Paula visita a su vecina Carmen. Llama a la puerta y dice: «¿Puedo pasar?». Carmen responde: «¡Pasa, pasa!». Paula siempre trae un detalle: hoy trae unas magdalenas. Carmen pregunta: «¿Un café?». Paula dice que sí. Las dos hablan en el salón, junto a la ventana. A las nueve, Paula se despide: «Gracias por todo, Carmen. Hasta la próxima». Carmen le da un beso y contesta: «De nada. Nos vemos el viernes».", questions = listOf(Exercise(id = "es-listen-tertulia-viernes-q1", kind = "choice", prompt = "¿Quién visita a Carmen?", options = listOf("Paula", "Su vecina", "El hijo de Carmen", "Un camarero"), answers = listOf("Paula"), explain = "Los viernes, Paula visita a su vecina Carmen."), Exercise(id = "es-listen-tertulia-viernes-q2", kind = "choice", prompt = "¿Qué dice Paula en la puerta?", options = listOf("¿Puedo pasar?", "¿Dónde está el baño?", "Hasta la próxima", "¿Un café?"), answers = listOf("¿Puedo pasar?"), explain = "Llama a la puerta y dice: «¿Puedo pasar?»."), Exercise(id = "es-listen-tertulia-viernes-q3", kind = "written", prompt = "¿Qué trae Paula hoy?", options = listOf(), answers = listOf("unas magdalenas", "magdalenas", "magdalenas para Carmen"), explain = "Paula siempre trae un detalle: hoy trae unas magdalenas."), Exercise(id = "es-listen-tertulia-viernes-q4", kind = "choice", prompt = "¿Qué acepta Paula?", options = listOf("Un café", "Un té", "Un agua", "Un pastel"), answers = listOf("Un café"), explain = "Carmen pregunta: «¿Un café?». Paula dice que sí."), Exercise(id = "es-listen-tertulia-viernes-q5", kind = "written", prompt = "¿A qué hora se despide Paula?", options = listOf(), answers = listOf("a las nueve", "las nueve", "nueve"), explain = "A las nueve, Paula se despide."), Exercise(id = "es-listen-tertulia-viernes-q6", kind = "choice", prompt = "¿Qué contesta Carmen al final?", options = listOf("De nada. Nos vemos el viernes", "Hasta mañana", "Hoy no puedo", "El café es para Paula"), answers = listOf("De nada. Nos vemos el viernes"), explain = "Carmen contesta: «De nada. Nos vemos el viernes».")), skills = listOf("listening:gist", "listening:detail", "vocab:social-expressions", "grammar:can")) }

object ListenData100 { val text = ListeningText(id = "es-listen-reclamo-factura", languageID = "es", title = "El reclamo de la factura", level = "A2", topic = "reclamos", unitID = "es-foundations-u21", text = "Ayer Laura compró una lámpara nueva por internet. El pedido llegó el jueves, pero la factura venía con un error: cobraban dos lámparas y ella solo compró una. Laura decidió reclamar. Buscó el teléfono de la tienda y llamó por la mañana. «Buenas tardes, quiero reclamar una factura», dijo con calma. La dependienta le pidió el número de pedido y revisó los datos. «Tiene razón, es nuestro error», respondió. Le mandó una factura correcta por email y la tienda devolvió la diferencia al día siguiente. Laura colgó contenta: el problema se arregló en diez minutos.", questions = listOf(Exercise(id = "es-listen-reclamo-factura-q1", kind = "choice", prompt = "¿Qué compró Laura ayer?", options = listOf("Una lámpara", "Dos facturas", "Un teléfono", "Una mesa"), answers = listOf("Una lámpara"), explain = "Ayer Laura compró una lámpara nueva por internet."), Exercise(id = "es-listen-reclamo-factura-q2", kind = "choice", prompt = "¿Cuál era el error de la factura?", options = listOf("Cobraban dos lámparas", "No llegó el pedido", "El precio era más bajo", "Faltaba la dirección"), answers = listOf("Cobraban dos lámparas"), explain = "La factura venía con un error: cobraban dos lámparas y ella solo compró una."), Exercise(id = "es-listen-reclamo-factura-q3", kind = "written", prompt = "¿Cuándo llamó Laura a la tienda?", options = listOf(), answers = listOf("por la mañana", "la mañana", "por la manana"), explain = "Buscó el teléfono de la tienda y llamó por la mañana."), Exercise(id = "es-listen-reclamo-factura-q4", kind = "written", prompt = "¿Qué le pidió la dependienta?", options = listOf(), answers = listOf("el número de pedido", "el numero de pedido", "número de pedido"), explain = "La dependienta le pidió el número de pedido y revisó los datos."), Exercise(id = "es-listen-reclamo-factura-q5", kind = "choice", prompt = "¿Qué hizo la tienda con la diferencia?", options = listOf("La devolvió al día siguiente", "La guardó para otra compra", "No hizo nada", "Se la cobró a Laura"), answers = listOf("La devolvió al día siguiente"), explain = "La tienda devolvió la diferencia al día siguiente."), Exercise(id = "es-listen-reclamo-factura-q6", kind = "choice", prompt = "¿Cómo terminó el problema?", options = listOf("Se arregló en diez minutos", "Se arregló un mes después", "Laura volvió a la tienda", "Quedó sin solución"), answers = listOf("Se arregló en diez minutos"), explain = "Laura colgó contenta: el problema se arregló en diez minutos.")), skills = listOf("listening:gist", "listening:detail", "function:solve-problems", "grammar:past-simple-regular")) }

object ListenData101 { val text = ListeningText(id = "es-listen-entrevista-practica", languageID = "es", title = "La entrevista de práctica", level = "B1", topic = "entrevistas", unitID = "es-foundations-u22", text = "Nora prepara una entrevista con su amigo Sergio, que trabaja en recursos humanos. «Cuéntame tu experiencia», pide él. «He trabajado cinco años en una agencia; llevo dos proyectos grandes a mis espaldas», responde Nora. «¿Y tu punto fuerte?». «Destaco en el trabajo en equipo; además, me queda mucho por aprender, y eso me gusta». Sergio sonríe: «Eso último suena honesto, no lo dejes fuera». «¿Por eso te contrataron a ti?», pregunta ella. «Yo llegué aquí por exactamente esa frase», contesta él. Al despedirse, Sergio le da un consejo: «Buscan a alguien con experiencia, pero sobre todo a alguien con ganas».", questions = listOf(Exercise(id = "es-listen-entrevista-practica-q1", kind = "choice", prompt = "¿A qué se dedica Sergio?", options = listOf("Trabaja en recursos humanos", "Es candidato a un puesto", "Trabaja en una agencia", "Es el jefe de Nora"), answers = listOf("Trabaja en recursos humanos"), explain = "Sergio es su amigo y trabaja en recursos humanos."), Exercise(id = "es-listen-entrevista-practica-q2", kind = "written", prompt = "¿Cuántos años trabajó Nora en la agencia?", options = listOf(), answers = listOf("cinco años", "5 años", "cinco"), explain = "«He trabajado cinco años en una agencia»."), Exercise(id = "es-listen-entrevista-practica-q3", kind = "choice", prompt = "¿Cuál es el punto fuerte de Nora?", options = listOf("El trabajo en equipo", "Los idiomas", "La experiencia en ventas", "Hablar en público"), answers = listOf("El trabajo en equipo"), explain = "«Destaco en el trabajo en equipo»."), Exercise(id = "es-listen-entrevista-practica-q4", kind = "choice", prompt = "¿Qué le aconseja Sergio sobre admitir que le queda mucho por aprender?", options = listOf("Que suena honesto y no lo quite", "Que lo esconda en la entrevista", "Que lo cambie por idiomas", "Que lo repita varias veces"), answers = listOf("Que suena honesto y no lo quite"), explain = "«Eso último suena honesto, no lo dejes fuera»."), Exercise(id = "es-listen-entrevista-practica-q5", kind = "written", prompt = "Según Sergio, ¿por qué le contrataron a él?", options = listOf(), answers = listOf("por exactamente esa frase", "por esa frase", "porque dijo esa frase"), explain = "«Yo llegué aquí por exactamente esa frase»."), Exercise(id = "es-listen-entrevista-practica-q6", kind = "choice", prompt = "¿Qué buscan más las empresas, según el consejo de Sergio?", options = listOf("Experiencia y, sobre todo, ganas", "Solo experiencia", "Solo títulos e idiomas", "Candidatos con contactos"), answers = listOf("Experiencia y, sobre todo, ganas"), explain = "«Buscan a alguien con experiencia, pero sobre todo a alguien con ganas».")), skills = listOf("listening:inference", "listening:detail", "vocab:work", "function:talk-about-work")) }

object ListenData102 { val text = ListeningText(id = "es-listen-tono-podcast", languageID = "es", title = "Cuestión de tono", level = "C1", topic = "lenguaje", unitID = "es-foundations-u10", text = "En «Dicho y hecho», Marta y Diego debaten sobre las palabras que eligen los hablantes. «Hoy he oído \"extraño muchísimo mi pueblo\" en un anuncio y me ha sonado a postal», dice Marta. «¿Qué tendría que decir?», pregunta Diego. «Pues \"echo de menos\", que ya es decirlo con el cuerpo». «Yo diría que son equivalentes; una collocation no lleva pasaporte». «No obstante, fíjate: \"tomar una decisión\" pesa más que \"decidir\"; la fórmula larga ya avisa de que lo has pensado». «De acuerdo en parte: la lengua pinta tonos, pero el hablante elige el pincel». «Precisamente por eso insisto: no digas \"hacer una decisión\"». «Eso sí, ahí te doy toda la razón: esa sí que es un crimen».", questions = listOf(Exercise(id = "es-listen-tono-podcast-q1", kind = "choice", prompt = "¿Por qué el anuncio le suena «a postal» a Marta?", options = listOf("Por el uso de extrañar", "Porque es demasiado largo", "Porque dice echo de menos", "Porque no se entiende"), answers = listOf("Por el uso de extrañar"), explain = "«He oído extraño muchísimo mi pueblo… y me ha sonado a postal»."), Exercise(id = "es-listen-tono-podcast-q2", kind = "choice", prompt = "¿Qué piensa Diego de las dos formas de echar en falta?", options = listOf("Que son equivalentes", "Que extrañar es un error", "Que hay que usarlas juntas", "Que ninguna suena natural"), answers = listOf("Que son equivalentes"), explain = "«Yo diría que son equivalentes; una collocation no lleva pasaporte»."), Exercise(id = "es-listen-tono-podcast-q3", kind = "written", prompt = "Según Marta, ¿qué avisa ya la fórmula «tomar una decisión»?", options = listOf(), answers = listOf("que lo has pensado", "que lo has meditado", "avisa de que lo has pensado"), explain = "«La fórmula larga ya avisa de que lo has pensado»."), Exercise(id = "es-listen-tono-podcast-q4", kind = "written", prompt = "¿Qué expresión rechaza Marta y llama crimen?", options = listOf(), answers = listOf("hacer una decisión", "hacer una decision", "hacer una decisión "), explain = "«Precisamente por eso insisto: no digas hacer una decisión»."), Exercise(id = "es-listen-tono-podcast-q5", kind = "choice", prompt = "¿Cómo se cierra la conversación?", options = listOf("En acuerdo total sobre un punto", "En desacuerdo total", "Sin ninguna conclusión", "Con una discusión nueva"), answers = listOf("En acuerdo total sobre un punto"), explain = "«Eso sí, ahí te doy toda la razón: esa sí que es un crimen»."), Exercise(id = "es-listen-tono-podcast-q6", kind = "choice", prompt = "¿Cuál es la postura final de Diego sobre las collocations?", options = listOf("La lengua pinta tonos, pero elige el hablante", "La lengua decide siempre", "Las collocations no pintan nada", "Solo importan los diccionarios"), answers = listOf("La lengua pinta tonos, pero elige el hablante"), explain = "«La lengua pinta tonos, pero el hablante elige el pincel».")), skills = listOf("listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion")) }

object ListenData103 { val text = ListeningText(id = "fr-listen-cafe-morning", languageID = "fr", title = "Un café avant le travail", level = "A1", topic = "routine", unitID = "fr-foundations-u1", text = "Chaque matin, Marta marche jusqu'à un petit café près de chez elle. Le serveur connaît son nom, alors elle n'a jamais besoin de commander. Aujourd'hui, elle s'assoit près de la fenêtre avec un café et un croissant. Son bus part à huit heures et demie, mais elle ne s'inquiète pas. Le café est très calme à cette heure-là. Elle boit son café lentement et regarde la ville se réveiller.", questions = listOf(Exercise(id = "fr-listen-cafe-morning-q1", kind = "choice", prompt = "Où Marta va-t-elle chaque matin ?", options = listOf("Dans un petit café", "À son bureau", "À la gare routière", "Dans un parc"), answers = listOf("Dans un petit café"), explain = "Elle marche jusqu'à un petit café près de chez elle."), Exercise(id = "fr-listen-cafe-morning-q2", kind = "choice", prompt = "Qu'est-ce qu'elle prend ce matin ?", options = listOf("Un café et un croissant", "Un thé et des toasts", "Du jus d'orange", "Rien"), answers = listOf("Un café et un croissant"), explain = "Elle s'assoit avec un café et un croissant."), Exercise(id = "fr-listen-cafe-morning-q3", kind = "written", prompt = "À quelle heure part son bus ?", options = listOf(), answers = listOf("à huit heures et demie", "huit heures et demie", "huit heures et demi"), explain = "Son bus part à huit heures et demie."), Exercise(id = "fr-listen-cafe-morning-q4", kind = "choice", prompt = "Comment se sent-elle par rapport à l'heure ?", options = listOf("Elle ne s'inquiète pas", "Elle est très en retard", "Elle est fâchée", "Elle a sommeil"), answers = listOf("Elle ne s'inquiète pas"), explain = "Le texte dit qu'elle ne s'inquiète pas."), Exercise(id = "fr-listen-cafe-morning-q5", kind = "choice", prompt = "Qui connaît son nom ?", options = listOf("Le serveur", "Le conducteur du bus", "Son patron", "Un voisin"), answers = listOf("Le serveur"), explain = "Le serveur connaît son nom, alors elle n'a jamais besoin de commander."), Exercise(id = "fr-listen-cafe-morning-q6", kind = "written", prompt = "Où s'assoit-elle aujourd'hui ?", options = listOf(), answers = listOf("près de la fenêtre", "à côté de la fenêtre", "vers la fenêtre"), explain = "Aujourd'hui, elle s'assoit près de la fenêtre.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")) }

object ListenData104 { val text = ListeningText(id = "fr-listen-language-class", languageID = "fr", title = "Le cours de langue", level = "A1", topic = "présentations", unitID = "fr-foundations-u1", text = "Marta assiste à son premier cours de portugais dans un petit institut. Dans la classe, il y a six personnes et tout le monde veut parler. La professeure demande les présentations. « Je m'appelle Marta et je suis de Bolivie », dit une dame. « Moi, c'est Andrés, je suis du Pérou et je travaille dans un restaurant », dit un jeune homme. Marta se présente aussi : « Je suis Marta, je suis argentine et je suis infirmière. » La professeure est de Madrid et elle enseigne avec beaucoup d'humour. À la fin du cours, les étudiants échangent leurs numéros de téléphone. Ils ne sont pas encore amis, mais la semaine prochaine, ils vont prendre un café ensemble et pratiquer.", questions = listOf(Exercise(id = "fr-listen-language-class-q1", kind = "choice", prompt = "Combien de personnes y a-t-il dans la classe ?", options = listOf("Six", "Trois", "Dix", "Quatorze"), answers = listOf("Six"), explain = "Dans la classe, il y a six personnes."), Exercise(id = "fr-listen-language-class-q2", kind = "choice", prompt = "D'où vient Andrés ?", options = listOf("Du Pérou", "De Bolivie", "D'Argentine", "Du Mexique"), answers = listOf("Du Pérou"), explain = "Andrés vient du Pérou et il travaille dans un restaurant."), Exercise(id = "fr-listen-language-class-q3", kind = "choice", prompt = "Quel est le métier de Marta ?", options = listOf("Infirmière", "Professeure", "Serveuse", "Étudiante"), answers = listOf("Infirmière"), explain = "Marta est argentine et elle est infirmière."), Exercise(id = "fr-listen-language-class-q4", kind = "written", prompt = "De quelle ville est la professeure ?", options = listOf(), answers = listOf("madrid", "de madrid", "elle est de madrid"), explain = "La professeure est de Madrid."), Exercise(id = "fr-listen-language-class-q5", kind = "choice", prompt = "Que font-ils à la fin du cours ?", options = listOf("Ils échangent leurs numéros de téléphone", "Ils rentrent seuls", "Ils font un examen", "Ils dînent au restaurant"), answers = listOf("Ils échangent leurs numéros de téléphone"), explain = "Les étudiants échangent leurs numéros de téléphone."), Exercise(id = "fr-listen-language-class-q6", kind = "written", prompt = "Que vont-ils faire la semaine prochaine ?", options = listOf(), answers = listOf("prendre un café", "ils vont prendre un café", "prendre un café ensemble"), explain = "La semaine prochaine, ils vont prendre un café ensemble et pratiquer.")), skills = listOf("listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself")) }

object ListenData105 { val text = ListeningText(id = "fr-listen-little-sister", languageID = "fr", title = "Ma petite sœur", level = "A1", topic = "famille", unitID = "fr-foundations-u1", text = "Ma petite sœur s'appelle Carla et elle a neuf ans. Elle est très gentille et très bavarde. Carla n'est pas discrète : elle parle avec tout le monde, avec les voisins, avec les professeurs et avec les chiens du parc. Elle est blonde, comme notre mère, et elle a les yeux marron comme mon père. Elle n'est pas grande pour son âge, mais elle est très rapide et elle adore le football. Son équipe n'est pas très bonne, mais cela ne la dérange pas. « Je ne suis pas professionnelle », dit-elle, « moi, je suis juste heureuse avec le ballon ». Ma sœur est petite, mais sa joie est énorme.", questions = listOf(Exercise(id = "fr-listen-little-sister-q1", kind = "choice", prompt = "Quel âge a Carla ?", options = listOf("Neuf ans", "Dix-neuf ans", "Sept ans", "Dix ans"), answers = listOf("Neuf ans"), explain = "Carla a neuf ans."), Exercise(id = "fr-listen-little-sister-q2", kind = "choice", prompt = "Comment est Carla ?", options = listOf("Gentille et bavarde", "Timide et discrète", "Sérieuse", "Triste"), answers = listOf("Gentille et bavarde"), explain = "Elle est très gentille et très bavarde."), Exercise(id = "fr-listen-little-sister-q3", kind = "written", prompt = "De quelle couleur sont ses yeux ?", options = listOf(), answers = listOf("marron", "les yeux marron", "marron comme son père"), explain = "Elle a les yeux marron comme son père."), Exercise(id = "fr-listen-little-sister-q4", kind = "choice", prompt = "Comment sont ses cheveux ?", options = listOf("Blonds, comme sa mère", "Bruns, comme son père", "Roux", "Courts et noirs"), answers = listOf("Blonds, comme sa mère"), explain = "Elle est blonde, comme notre mère."), Exercise(id = "fr-listen-little-sister-q5", kind = "choice", prompt = "Qu'est-ce qu'elle adore ?", options = listOf("Le football", "La natation", "La musique", "Les jeux vidéo"), answers = listOf("Le football"), explain = "Elle est très rapide et elle adore le football."), Exercise(id = "fr-listen-little-sister-q6", kind = "written", prompt = "Comment est sa joie ?", options = listOf(), answers = listOf("énorme", "très grande", "grande"), explain = "Sa joie est énorme.")), skills = listOf("listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family")) }

object ListenData106 { val text = ListeningText(id = "fr-listen-new-flatmate", languageID = "fr", title = "Un nouveau colocataire", level = "A1", topic = "maison", unitID = "fr-foundations-u1", text = "Tom a un nouveau colocataire. Il s'appelle Léo et il a vingt-trois ans. Léo vient d'une petite ville du nord, mais il travaille maintenant en ville. Il a deux cartons, une guitare et un vélo. L'appartement a deux chambres et une cuisine très lumineuse. Tom espère que Léo aime cuisiner, parce que Tom, lui, déteste ça.", questions = listOf(Exercise(id = "fr-listen-new-flatmate-q1", kind = "choice", prompt = "Quel âge a Léo ?", options = listOf("Vingt-trois ans", "Trente-deux ans", "Vingt ans", "Trente ans"), answers = listOf("Vingt-trois ans"), explain = "Léo a vingt-trois ans."), Exercise(id = "fr-listen-new-flatmate-q2", kind = "choice", prompt = "Qu'est-ce que Léo n'a PAS ?", options = listOf("Une télévision", "Deux cartons", "Une guitare", "Un vélo"), answers = listOf("Une télévision"), explain = "Il a deux cartons, une guitare et un vélo — pas de télévision."), Exercise(id = "fr-listen-new-flatmate-q3", kind = "written", prompt = "Qu'est-ce que Tom déteste faire ?", options = listOf(), answers = listOf("cuisiner", "il déteste cuisiner", "tom déteste cuisiner"), explain = "Tom déteste cuisiner."), Exercise(id = "fr-listen-new-flatmate-q4", kind = "choice", prompt = "Comment est l'appartement ?", options = listOf("Deux chambres et une cuisine lumineuse", "Une chambre et un balcon", "Un jardin", "Deux salles de bain"), answers = listOf("Deux chambres et une cuisine lumineuse"), explain = "L'appartement a deux chambres et une cuisine très lumineuse."), Exercise(id = "fr-listen-new-flatmate-q5", kind = "choice", prompt = "Où Léo travaille-t-il maintenant ?", options = listOf("En ville", "Dans un petit village", "Dans le nord", "Il ne travaille pas"), answers = listOf("En ville"), explain = "Il vient d'une petite ville du nord, mais il travaille maintenant en ville."), Exercise(id = "fr-listen-new-flatmate-q6", kind = "written", prompt = "Quel instrument Léo a-t-il ?", options = listOf(), answers = listOf("une guitare", "la guitare", "guitare"), explain = "Léo a une guitare.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")) }

object ListenData107 { val text = ListeningText(id = "fr-listen-new-neighbour", languageID = "fr", title = "La nouvelle voisine", level = "A1", topic = "gens", unitID = "fr-foundations-u1", text = "Dans l'immeuble, il y a une nouvelle voisine. Elle s'appelle Amélie et elle est de France. Elle n'est pas étudiante ; elle est photographe. Elle ne travaille pas dans un bureau : elle travaille chez elle et elle voyage beaucoup. Les voisins sont curieux, mais ils sont aussi timides, alors ils ne lui parlent pas. Puis, un matin, Ben la rencontre à la porte. « C'est vous, la nouvelle voisine ? », demande-t-il. « Oui, c'est moi », répond-elle, « et je suis contente d'être ici. » Maintenant, ils sont amis, et elle n'est plus seule dans l'immeuble.", questions = listOf(Exercise(id = "fr-listen-new-neighbour-q1", kind = "choice", prompt = "D'où vient Amélie ?", options = listOf("De France", "D'Italie", "Du Japon", "Du Brésil"), answers = listOf("De France"), explain = "Amélie est de France."), Exercise(id = "fr-listen-new-neighbour-q2", kind = "choice", prompt = "Quel est son métier ?", options = listOf("Photographe", "Étudiante", "Employée de bureau", "Professeure"), answers = listOf("Photographe"), explain = "Elle n'est pas étudiante ; elle est photographe."), Exercise(id = "fr-listen-new-neighbour-q3", kind = "choice", prompt = "Travaille-t-elle dans un bureau ?", options = listOf("Non, elle travaille chez elle", "Oui, tous les jours", "Seulement en été", "Elle ne le dit pas"), answers = listOf("Non, elle travaille chez elle"), explain = "Elle ne travaille pas dans un bureau : elle travaille chez elle."), Exercise(id = "fr-listen-new-neighbour-q4", kind = "written", prompt = "Pourquoi les voisins ne lui parlent-ils pas ?", options = listOf(), answers = listOf("ils sont timides", "parce qu'ils sont timides", "timides"), explain = "Ils sont curieux, mais ils sont aussi timides."), Exercise(id = "fr-listen-new-neighbour-q5", kind = "choice", prompt = "Où Ben la rencontre-t-il ?", options = listOf("À la porte", "Dans l'ascenseur", "Dans la rue", "Au café"), answers = listOf("À la porte"), explain = "Un matin, Ben la rencontre à la porte."), Exercise(id = "fr-listen-new-neighbour-q6", kind = "written", prompt = "Comment Amélie se sent-elle à la fin ?", options = listOf(), answers = listOf("contente", "heureuse", "elle est contente"), explain = "Elle dit qu'elle est contente d'être ici.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")) }

object ListenData108 { val text = ListeningText(id = "fr-listen-sunday-market", languageID = "fr", title = "Le marché du dimanche", level = "A1", topic = "achats", unitID = "fr-foundations-u1", text = "Le dimanche, il y a un marché sur la place du village. Anna et son père y vont à neuf heures, avant que ce soit trop bondé. Ils achètent des fruits, du pain et des fleurs. Anna veut des fraises, mais son père dit qu'elles sont trop chères cette semaine. À la fin, ils rentrent avec un grand sac d'oranges et des roses blanches pour la table de la cuisine.", questions = listOf(Exercise(id = "fr-listen-sunday-market-q1", kind = "choice", prompt = "Quand Anna et son père vont-ils au marché ?", options = listOf("À neuf heures", "À midi", "Dans l'après-midi", "À six heures et demie"), answers = listOf("À neuf heures"), explain = "Ils y vont à neuf heures, avant que ce soit trop bondé."), Exercise(id = "fr-listen-sunday-market-q2", kind = "written", prompt = "Pourquoi Anna n'a-t-elle pas de fraises ?", options = listOf(), answers = listOf("elles sont trop chères", "trop chères", "parce qu'elles sont trop chères"), explain = "Son père dit qu'elles sont trop chères cette semaine."), Exercise(id = "fr-listen-sunday-market-q3", kind = "choice", prompt = "Qu'est-ce qu'ils ramènent à la maison ?", options = listOf("Des oranges et des roses", "Des fraises et du pain", "Des pommes et des tulipes", "Du pain et du fromage"), answers = listOf("Des oranges et des roses"), explain = "Ils rentrent avec des oranges et des roses blanches."), Exercise(id = "fr-listen-sunday-market-q4", kind = "choice", prompt = "Où est le marché ?", options = listOf("Sur la place du village", "Près de la rivière", "À la gare", "Dans un supermarché"), answers = listOf("Sur la place du village"), explain = "Il y a un marché sur la place du village le dimanche."), Exercise(id = "fr-listen-sunday-market-q5", kind = "choice", prompt = "Qu'est-ce qu'ils achètent ?", options = listOf("Des fruits, du pain et des fleurs", "Du poisson et des légumes", "Du fromage et de la viande", "Uniquement des fleurs"), answers = listOf("Des fruits, du pain et des fleurs"), explain = "Ils achètent des fruits, du pain et des fleurs."), Exercise(id = "fr-listen-sunday-market-q6", kind = "written", prompt = "Qu'est-ce qu'Anna veut ?", options = listOf(), answers = listOf("des fraises", "les fraises", "elle veut des fraises"), explain = "Anna veut des fraises.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")) }

object ListenData109 { val text = ListeningText(id = "fr-listen-appart-choisi", languageID = "fr", title = "L'appartement choisi", level = "A2", topic = "appartements", unitID = "fr-foundations-u4", text = "Camille et Théo cherchent un appartement. Le premier est moins cher, mais il est plus loin de la gare : quarante minutes à pied. Le second coûte cent euros de plus, mais il est plus lumineux et il a un balcon. Pour Camille, la lumière est le plus important, parce qu'elle travaille à la maison. Ils décident de demander une visite du second : il est plus cher, mais c'est le meilleur des deux pour eux.", questions = listOf(Exercise(id = "fr-listen-appart-choisi-q1", kind = "choice", prompt = "Combien d'appartements comparent-ils ?", options = listOf("Deux", "Trois", "Quatre"), answers = listOf("Deux"), explain = "Ils comparent deux appartements."), Exercise(id = "fr-listen-appart-choisi-q2", kind = "choice", prompt = "Quel est le problème du moins cher ?", options = listOf("Il est loin de la gare", "Il n'a pas de balcon", "Il est très cher", "Il est petit"), answers = listOf("Il est loin de la gare"), explain = "Quarante minutes à pied de la gare."), Exercise(id = "fr-listen-appart-choisi-q3", kind = "written", prompt = "Combien coûte le second en plus par mois ?", options = listOf(), answers = listOf("cent euros", "100 euros"), explain = "Cent euros de plus par mois."), Exercise(id = "fr-listen-appart-choisi-q4", kind = "choice", prompt = "Qu'est-ce qui est le plus important pour Camille ?", options = listOf("La lumière", "Le prix", "Le balcon", "La cuisine"), answers = listOf("La lumière"), explain = "Elle travaille à la maison."), Exercise(id = "fr-listen-appart-choisi-q5", kind = "choice", prompt = "Que décident-ils ?", options = listOf("Demander une visite du second", "Garder le premier", "Continuer à chercher", "Demander une réduction"), answers = listOf("Demander une visite du second"), explain = "C'est le meilleur des deux pour eux.")), skills = listOf("listening:gist", "listening:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")) }

object ListenData110 { val text = ListeningText(id = "fr-listen-samedi-organise", languageID = "fr", title = "Le samedi organisé", level = "A2", topic = "projets", unitID = "fr-foundations-u4", text = "Léa appelle son frère pour organiser samedi. Il propose la montagne, mais il va pleuvoir, alors Léa suggère le nouveau musée. Ils vont se retrouver à dix heures à l'entrée principale et déjeuner au marché à côté, qui est moins cher que les restaurants du centre. Le soir, ils n'ont pas de projet : ils vont décider sur place, quand ils connaîtront la météo.", questions = listOf(Exercise(id = "fr-listen-samedi-organise-q1", kind = "choice", prompt = "Qui propose la montagne ?", options = listOf("Le frère", "Léa", "Leur mère", "Un ami"), answers = listOf("Le frère"), explain = "Son frère propose la montagne."), Exercise(id = "fr-listen-samedi-organise-q2", kind = "choice", prompt = "Pourquoi pas la montagne ?", options = listOf("Il va pleuvoir", "Ils sont fatigués", "Le musée est gratuit", "La montagne est loin"), answers = listOf("Il va pleuvoir"), explain = "Il va pleuvoir, alors ils vont au musée."), Exercise(id = "fr-listen-samedi-organise-q3", kind = "written", prompt = "À quelle heure vont-ils se retrouver ?", options = listOf(), answers = listOf("a dix heures", "à dix heures", "dix heures"), explain = "À dix heures à l'entrée principale."), Exercise(id = "fr-listen-samedi-organise-q4", kind = "choice", prompt = "Où vont-ils déjeuner ?", options = listOf("Au marché à côté", "Dans un restaurant du centre", "Chez eux", "Au musée"), answers = listOf("Au marché à côté"), explain = "Moins cher que les restaurants du centre."), Exercise(id = "fr-listen-samedi-organise-q5", kind = "choice", prompt = "Que vont-ils faire le soir ?", options = listOf("Décider sur place", "Aller au cinéma", "Rentrer tôt", "Voir des amis"), answers = listOf("Décider sur place"), explain = "Ils vont décider selon la météo.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("grammar:future-forms")) }

object ListenData111 { val text = ListeningText(id = "fr-listen-jamais-fait", languageID = "fr", title = "Ce que je n'ai jamais fait", level = "B1", topic = "voyages", unitID = "fr-foundations-u6", text = "Dans la cuisine d'une auberge, trois voyageurs comparent leurs vies. Théo a visité vingt pays, mais il n'a jamais appris à nager : « Je sais, c'est ridicule ». Aïcha a déjà plongé deux fois avec des tortues, mais elle n'a jamais quitté l'Afrique avant ce voyage. Et Léa, qui est sur la route depuis six ans, n'a jamais pris l'avion : elle traverse les océans en bateau et les frontières en bus. « Jamais ? » demande Théo. « Jamais. La peur est plus vieille que moi. » Ils rient de ce qu'ils n'ont pas fait, et Léa dit quelque chose qui reste : « Il ne faut pas avoir tout fait. Il suffit de vouloir encore ».", questions = listOf(Exercise(id = "fr-listen-jamais-fait-q1", kind = "choice", prompt = "Qu'est-ce que Théo n'a jamais fait ?", options = listOf("Apprendre à nager", "Visiter vingt pays", "Traverser en bateau", "Quitter l'Afrique"), answers = listOf("Apprendre à nager"), explain = "Il a visité vingt pays, mais il n'a jamais appris à nager."), Exercise(id = "fr-listen-jamais-fait-q2", kind = "written", prompt = "Combien de fois Aïcha a-t-elle plongé ?", options = listOf(), answers = listOf("deux fois", "2 fois", "deux"), explain = "Aïcha a déjà plongé deux fois avec des tortues."), Exercise(id = "fr-listen-jamais-fait-q3", kind = "choice", prompt = "Comment Léa traverse-t-elle les océans ?", options = listOf("En bateau", "En avion", "En bus", "À pied"), answers = listOf("En bateau"), explain = "Elle traverse les océans en bateau et les frontières en bus."), Exercise(id = "fr-listen-jamais-fait-q4", kind = "choice", prompt = "Que dit Léa sur la peur ?", options = listOf("Elle est plus vieille qu'elle", "Elle est plus jeune", "C'est ridicule", "Elle est partie"), answers = listOf("Elle est plus vieille qu'elle"), explain = "La peur est plus vieille que moi."), Exercise(id = "fr-listen-jamais-fait-q5", kind = "written", prompt = "Qu'est-ce qui suffit, selon Léa ?", options = listOf(), answers = listOf("vouloir encore", "de vouloir encore"), explain = "Il suffit de vouloir encore.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")) }

object ListenData112 { val text = ListeningText(id = "fr-listen-ville-village", languageID = "fr", title = "De la ville au village", level = "B1", topic = "changements", unitID = "fr-foundations-u6", text = "Nicolas explique pourquoi il a quitté Paris. Avant, il vivait dans un petit appartement et travaillait onze heures par jour : « Je gagnais bien, mais je n'avais pas de vie ». Un hiver, il est tombé malade, et là il a compris qu'il fallait changer. Maintenant il habite dans un village de mille habitants, il travaille de chez lui le matin et cultive un potager l'après-midi. « Je gagne moins, mais j'ai du temps. » Au début, ses parents ne comprenaient pas ; maintenant ils viennent chaque mois. « Tu regrettes quelque chose ? » demande son amie. « De ne pas l'avoir fait plus tôt ».", questions = listOf(Exercise(id = "fr-listen-ville-village-q1", kind = "choice", prompt = "Où habitait Nicolas avant ?", options = listOf("À Paris", "Dans un village", "À Lyon", "Dans une auberge"), answers = listOf("À Paris"), explain = "Nicolas explique pourquoi il a quitté Paris."), Exercise(id = "fr-listen-ville-village-q2", kind = "written", prompt = "Combien d'heures travaillait-il par jour ?", options = listOf(), answers = listOf("onze heures", "11 heures", "onze"), explain = "Il travaillait onze heures par jour."), Exercise(id = "fr-listen-ville-village-q3", kind = "choice", prompt = "Qu'est-ce qui l'a fait changer ?", options = listOf("Il est tombé malade", "Il a perdu son travail", "Il a gagné à la loterie", "Il a rencontré quelqu'un"), answers = listOf("Il est tombé malade"), explain = "Un hiver, il est tombé malade, et là il a compris."), Exercise(id = "fr-listen-ville-village-q4", kind = "choice", prompt = "Que fait-il l'après-midi maintenant ?", options = listOf("Il cultive un potager", "Il travaille plus d'heures", "Il voyage chaque mois", "Il étudie"), answers = listOf("Il cultive un potager"), explain = "Il travaille le matin et cultive un potager l'après-midi."), Exercise(id = "fr-listen-ville-village-q5", kind = "written", prompt = "Que regrette Nicolas ?", options = listOf(), answers = listOf("de ne pas l'avoir fait plus tot", "de ne pas l'avoir fait plus tôt", "ne pas l'avoir fait plus tôt"), explain = "« De ne pas l'avoir fait plus tôt ».")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions")) }

object ListenData113 { val text = ListeningText(id = "fr-listen-marche-table", languageID = "fr", title = "Le marchandage de la table", level = "B2", topic = "négociation", unitID = "fr-foundations-u7", text = "Sur une app d'occasion, Camille veut une table en bois à 80 euros. « Et si on se retrouvait à 60 ? », propose-t-elle. Le vendeur refuse : « Seulement si vous la prenez aujourd'hui ». Camille réfléchit : « Je vous donnerais 65 si vous ajoutez la chaise ». « Impossible », rit-il, « mais je vous laisserais la table à 70 et je vous la monterais à l'étage ». Camille n'hésite pas : « Vous la monteriez tout seul ? ». « J'ai un diable », répond-il. « Marché conclu », dit-elle, et elle ajoute : « Si elle est aussi belle que sur la photo, je laisse cinq étoiles ».", questions = listOf(Exercise(id = "fr-listen-marche-table-q1", kind = "choice", prompt = "Combien le vendeur demande-t-il ?", options = listOf("80 euros", "60 euros", "70 euros", "65 euros"), answers = listOf("80 euros"), explain = "La table coûte 80 euros."), Exercise(id = "fr-listen-marche-table-q2", kind = "written", prompt = "Que propose Camille d'abord ?", options = listOf(), answers = listOf("60 euros", "soixante euros", "se retrouver a 60", "se retrouver à 60"), explain = "« Et si on se retrouvait à 60 ? »."), Exercise(id = "fr-listen-marche-table-q3", kind = "choice", prompt = "Quelle condition le vendeur pose-t-il ?", options = listOf("La prendre aujourd'hui", "Payer en espèces", "Laisser cinq étoiles", "Revenir demain"), answers = listOf("La prendre aujourd'hui"), explain = "« Seulement si vous la prenez aujourd'hui »."), Exercise(id = "fr-listen-marche-table-q4", kind = "choice", prompt = "Qu'offre le vendeur pour 70 ?", options = listOf("Monter la table à l'étage", "Ajouter la chaise", "Descendre à 60", "Prêter un diable"), answers = listOf("Monter la table à l'étage"), explain = "« Je vous la monterais à l'étage »."), Exercise(id = "fr-listen-marche-table-q5", kind = "written", prompt = "Que promet Camille si la table plaît ?", options = listOf(), answers = listOf("cinq etoiles", "cinq étoiles", "une note de cinq etoiles"), explain = "Cinq étoiles.")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors")) }

object ListenData114 { val text = ListeningText(id = "fr-listen-info-quartier", languageID = "fr", title = "L'info du quartier", level = "B2", topic = "actualité", unitID = "fr-foundations-u8", text = "Au marché, Anaïs et Marc commentent ce qu'on dit. « On dit qu'ils vont piétonniser la rue principale », raconte Anaïs. « Encore ? », rit Marc. « La nouvelle que j'ai lue dit que ça commence au printemps ». D'après la mairie, ce serait seulement le samedi, mais les commerçants, dont le chiffre d'affaires dépendrait du tourisme, ont déjà manifesté. « C'est vrai que le bruit baisserait », concède Marc, « mais, et le parking ? ». Anaïs défend la mesure : « D'un côté, plus de gens marcheraient ; de l'autre, les bus s'arrêteraient à la porte ». Ils ne trancheent pas, mais promettent d'en reparler quand le plan sera publié.", questions = listOf(Exercise(id = "fr-listen-info-quartier-q1", kind = "choice", prompt = "Que dit-on de la rue principale ?", options = listOf("Qu'on la piétonnisera", "Qu'on l'élargira", "Qu'on la fermera", "Qu'on la rebaptisera"), answers = listOf("Qu'on la piétonnisera"), explain = "« On dit qu'ils vont piétonniser la rue principale »."), Exercise(id = "fr-listen-info-quartier-q2", kind = "written", prompt = "Quand est-ce que ça commencerait ?", options = listOf(), answers = listOf("au printemps", "printemps"), explain = "« La nouvelle que j'ai lue dit que ça commence au printemps »."), Exercise(id = "fr-listen-info-quartier-q3", kind = "choice", prompt = "Que dit la mairie ?", options = listOf("Seulement le samedi", "Tous les jours", "Seulement en été", "Les jours fériés"), answers = listOf("Seulement le samedi"), explain = "D'après la mairie, ce serait seulement le samedi."), Exercise(id = "fr-listen-info-quartier-q4", kind = "choice", prompt = "Qui a manifesté ?", options = listOf("Les commerçants", "Les habitants", "Les taxi", "La mairie"), answers = listOf("Les commerçants"), explain = "Les commerçants ont déjà manifesté."), Exercise(id = "fr-listen-info-quartier-q5", kind = "written", prompt = "Que promettent Anaïs et Marc ?", options = listOf(), answers = listOf("d'en reparler", "en reparler", "reparler du plan"), explain = "Ils promettent d'en reparler quand le plan sera publié.")), skills = listOf("listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors")) }

object ListenData115 { val text = ListeningText(id = "fr-listen-debat-radio", languageID = "fr", title = "Débat à la radio", level = "C1", topic = "débats", unitID = "fr-foundations-u9", text = "« Bienvenue dans notre débat du soir : le télétravail a-t-il tué le bureau ? » Diane, consultante : « En quelque sorte, oui. D'une certaine manière, les open spaces ont perdu leur raison d'être : nos clients exigent désormais des résultats, pas une présence. » Marc, dirigeant d'une PME : « À mon sens, c'est plus subtil. Nous avons toutefois constaté une baisse de la créativité : les idées circulent moins bien en visioconférence. » Diane concède : « C'est un argument, néanmoins les salariés ne reviendront pas à plein temps. » Le présentateur reformule : « Autrement dit, le bureau deviendrait un lieu de rencontre plutôt qu'un lieu de production ? » Tous deux l'admettent, moyennant des locaux repensés. Le débat continue, mais l'essentiel est dit : la nuance a gagné la partie.", questions = listOf(Exercise(id = "fr-listen-debat-radio-q1", kind = "choice", prompt = "Quel est le sujet du débat ?", options = listOf("Le télétravail et le bureau", "La baisse des résultats", "Le prix des open spaces", "La visioconférence seule"), answers = listOf("Le télétravail et le bureau"), explain = "Dès l'ouverture : « le télétravail a-t-il tué le bureau ? »."), Exercise(id = "fr-listen-debat-radio-q2", kind = "written", prompt = "Quelle formule nuancée Diane utilise-t-elle en premier ?", options = listOf(), answers = listOf("en quelque sorte oui", "en quelque sorte, oui", "oui en quelque sorte"), explain = "« En quelque sorte, oui » : l'accord nuancé ouvre son intervention."), Exercise(id = "fr-listen-debat-radio-q3", kind = "choice", prompt = "Que constate Marc ?", options = listOf("Une baisse de la créativité", "Une hausse des résultats", "Une baisse de la présence", "Une hausse des loyers"), answers = listOf("Une baisse de la créativité"), explain = "« Nous avons toutefois constaté une baisse de la créativité »."), Exercise(id = "fr-listen-debat-radio-q4", kind = "choice", prompt = "Quelle formule le présentateur utilise-t-il pour reformuler ?", options = listOf("Autrement dit", "Par ailleurs", "Pour commencer", "En fait"), answers = listOf("Autrement dit"), explain = "« Autrement dit » annonce la reformulation."), Exercise(id = "fr-listen-debat-radio-q5", kind = "written", prompt = "Que demandent les deux invités à la fin ?", options = listOf(), answers = listOf("des locaux repenses", "des locaux repensés", "repenser les locaux"), explain = "Ils l'admettent « moyennant des locaux repensés ».")), skills = listOf("listening:inference", "function:express-opinion", "grammar:connectors", "vocab:collocations")) }

object ListenData116 { val text = ListeningText(id = "fr-listen-conference-cles", languageID = "fr", title = "Conférence : les trois clés", level = "C1", topic = "travail", unitID = "fr-foundations-u9", text = "« Mesdames et messieurs, permettez-moi de conclure par trois clés. Pour commencer, la clarté : une équipe sans objectifs précis confond activité et avancement. J'en viens ensuite à la confiance ; autrement dit, déléguer, c'est accepter que le travail soit fait autrement. Enfin, le feedback : dans nos enquêtes, les salariés qui reçoivent un retour chaque semaine se déclarent nettement plus engagés. En résumé, ni la surveillance ni la bienveillance aveugle ne suffisent ; à mon sens, la performance naît de la combinaison des trois clés. Si vous ne retenez qu'une phrase de cette conférence, retenez celle-ci : on ne gère pas des gens, on crée les conditions pour qu'ils réussissent. Je vous remercie de votre attention et je réponds à vos questions.", questions = listOf(Exercise(id = "fr-listen-conference-cles-q1", kind = "choice", prompt = "Combien de clés l'orateur présente-t-il ?", options = listOf("Trois", "Deux", "Quatre", "Cinq"), answers = listOf("Trois"), explain = "« Permettez-moi de conclure par trois clés »."), Exercise(id = "fr-listen-conference-cles-q2", kind = "choice", prompt = "Quelle est la première clé ?", options = listOf("La clarté", "La confiance", "Le feedback", "La rapidité"), answers = listOf("La clarté"), explain = "« Pour commencer, la clarté »."), Exercise(id = "fr-listen-conference-cles-q3", kind = "written", prompt = "D'après l'orateur, déléguer signifie quoi ?", options = listOf(), answers = listOf("accepter que le travail soit fait autrement", "accepter que ce soit fait autrement", "que le travail soit fait autrement"), explain = "« Déléguer, c'est accepter que le travail soit fait autrement »."), Exercise(id = "fr-listen-conference-cles-q4", kind = "choice", prompt = "Qu'est-ce qui rend les salariés plus engagés, selon les enquêtes ?", options = listOf("Un retour chaque semaine", "Une réunion chaque jour", "Un salaire plus élevé", "Des objectifs flous"), answers = listOf("Un retour chaque semaine"), explain = "Les salariés « qui reçoivent un retour chaque semaine se déclarent nettement plus engagés »."), Exercise(id = "fr-listen-conference-cles-q5", kind = "written", prompt = "Quel mot complète la phrase finale : « On ne gère pas des ___ , on crée les conditions pour qu'ils réussissent. »", options = listOf(), answers = listOf("gens", "personnes", "des gens"), explain = "« On ne gère pas des gens » : la phrase à retenir.")), skills = listOf("listening:connected-speech", "listening:detail", "vocab:work", "grammar:connectors")) }

object ListenData117 { val text = ListeningText(id = "fr-listen-podcast-nuances", languageID = "fr", title = "Podcast : l'art de nuancer", level = "C1", topic = "langue", unitID = "fr-foundations-u9", text = "Dans ce podcast, Léa reçoit M. Roussel, linguiste. Léa : « Est-ce vraiment poli de répondre seulement : j'ai bien reçu votre mail ? » M. Roussel : « C'est correct, mais neutre. À l'écrit professionnel, on préférera : je vous confirme la bonne réception de votre message. Le verbe confirmer élève le registre. » Léa : « Et à l'oral ? » M. Roussel : « À l'oral, le ton fait la moitié du travail ; néanmoins, certaines tournures restent marquées : je vous prie de bien vouloir sonne formel, voire guindé entre collègues proches. » Léa : « Donc tout est une question de contexte ? » M. Roussel : « En quelque sorte : nuancer, c'est choisir la bonne distance. Celui qui module gagne la confiance de son auditoire ; celui qui parle tout cru l'épuise. »", questions = listOf(Exercise(id = "fr-listen-podcast-nuances-q1", kind = "choice", prompt = "Quel est le thème du podcast ?", options = listOf("Le registre de langue au travail", "L'orthographe des e-mails", "L'histoire du français", "Les réunions à distance"), answers = listOf("Le registre de langue au travail"), explain = "Le dialogue porte sur les registres à l'écrit et à l'oral professionnel."), Exercise(id = "fr-listen-podcast-nuances-q2", kind = "choice", prompt = "Quelle tournure M. Roussel juge-t-elle guindée entre proches ?", options = listOf("Je vous prie de bien vouloir", "J'ai bien reçu votre mail", "Je vous confirme la réception", "Le verbe confirmer"), answers = listOf("Je vous prie de bien vouloir"), explain = "« Je vous prie de bien vouloir sonne formel, voire guindé entre collègues proches »."), Exercise(id = "fr-listen-podcast-nuances-q3", kind = "written", prompt = "Comment M. Roussel définit-il la nuance ?", options = listOf(), answers = listOf("choisir la bonne distance", "c'est choisir la bonne distance", "choisir la distance"), explain = "« Nuancer, c'est choisir la bonne distance »."), Exercise(id = "fr-listen-podcast-nuances-q4", kind = "choice", prompt = "Qu'est-ce qui fait la moitié du travail à l'oral ?", options = listOf("Le ton", "L'orthographe", "La longueur", "Le silence"), answers = listOf("Le ton"), explain = "« À l'oral, le ton fait la moitié du travail »."), Exercise(id = "fr-listen-podcast-nuances-q5", kind = "choice", prompt = "Que veut dire « celui qui module gagne la confiance » ?", options = listOf("Nuancer rend crédible", "Parler fort convainc", "Écrire court suffit", "Tout dire rassure"), answers = listOf("Nuancer rend crédible"), explain = "À opposer à « celui qui parle tout cru l'épuise » : la modulation crédibilise.")), skills = listOf("listening:inference", "listening:gist", "vocab:social-expressions")) }

object ListenData118 { val text = ListeningText(id = "fr-listen-nouvel-appart", languageID = "fr", title = "Un nouvel appart pour Léa", level = "A1", topic = "maison", unitID = "fr-foundations-u10", text = "Léa visite un nouvel appartement dans le quartier. Dans l'entrée, il y a un miroir. La cuisine est petite, mais il y a une fenêtre. Le salon donne sur la rue : il y a un canapé bleu et deux fauteuils. La chambre est à côté du salon ; le lit est sous la fenêtre. Il n'y a pas de garage, mais il y a un balcon. Le propriétaire dit : « C'est à dix minutes à pied de la gare. » Léa est contente : elle prend l'appartement.", questions = listOf(Exercise(id = "fr-listen-nouvel-appart-q1", kind = "choice", prompt = "Où est le lit ?", options = listOf("Sous la fenêtre", "Sur le balcon", "Dans l'entrée", "À côté de la cuisine"), answers = listOf("Sous la fenêtre"), explain = "Le lit est sous la fenêtre."), Exercise(id = "fr-listen-nouvel-appart-q2", kind = "choice", prompt = "Qu'est-ce qu'il y a dans le salon ?", options = listOf("Un canapé bleu et deux fauteuils", "Une grande table avec des chaises", "Un miroir et un balcon", "Un lit sous la fenêtre"), answers = listOf("Un canapé bleu et deux fauteuils"), explain = "Il y a un canapé bleu et deux fauteuils."), Exercise(id = "fr-listen-nouvel-appart-q3", kind = "written", prompt = "Qu'est-ce qu'il n'y a pas dans l'appartement ?", options = listOf(), answers = listOf("il n'y a pas de garage", "pas de garage"), explain = "Il n'y a pas de garage, mais il y a un balcon."), Exercise(id = "fr-listen-nouvel-appart-q4", kind = "choice", prompt = "À quelle distance est la gare ?", options = listOf("À dix minutes à pied", "À dix minutes en bus", "Tout près du salon", "Loin du quartier"), answers = listOf("À dix minutes à pied"), explain = "C'est à dix minutes à pied de la gare."), Exercise(id = "fr-listen-nouvel-appart-q5", kind = "written", prompt = "Qu'est-ce qu'il y a à côté du salon ?", options = listOf(), answers = listOf("la chambre", "c'est la chambre"), explain = "La chambre est à côté du salon."), Exercise(id = "fr-listen-nouvel-appart-q6", kind = "choice", prompt = "Comment est Léa à la fin ?", options = listOf("Contente", "Triste", "Fatiguée", "Fâchée"), answers = listOf("Contente"), explain = "Léa est contente : elle prend l'appartement.")), skills = listOf("listening:gist", "listening:detail", "grammar:there-is-are", "grammar:prepositions-place", "vocab:home")) }

object ListenData119 { val text = ListeningText(id = "fr-listen-balade-quartier", languageID = "fr", title = "Une balade dans le quartier", level = "A1", topic = "quartier", unitID = "fr-foundations-u11", text = "Karim est nouveau dans le quartier. Il demande à une voisine : « Pardon, est-ce qu'il y a une boulangerie près d'ici ? » La voisine répond : « Allez tout droit, tournez à gauche au feu ; c'est tout près. La boulangerie est à côté de la pharmacie. » Karim marche cinq minutes. Ensuite, il traverse le parc : il y a un marché. Le samedi, le marché vend des fruits : pommes, fraises et tomates. Karim achète un kilo de pommes. Il adore son quartier.", questions = listOf(Exercise(id = "fr-listen-balade-quartier-q1", kind = "choice", prompt = "Que cherche Karim ?", options = listOf("Une boulangerie", "Une pharmacie", "La gare", "Un marché"), answers = listOf("Une boulangerie"), explain = "Il demande s'il y a une boulangerie près d'ici."), Exercise(id = "fr-listen-balade-quartier-q2", kind = "choice", prompt = "Quelle est la direction ?", options = listOf("Tournez à gauche au feu", "Tournez à droite au feu", "Allez à gauche tout de suite", "Traversez le quartier"), answers = listOf("Tournez à gauche au feu"), explain = "Allez tout droit, tournez à gauche au feu."), Exercise(id = "fr-listen-balade-quartier-q3", kind = "written", prompt = "Où est la boulangerie ?", options = listOf(), answers = listOf("à côté de la pharmacie", "a cote de la pharmacie", "près de la pharmacie"), explain = "La boulangerie est à côté de la pharmacie."), Exercise(id = "fr-listen-balade-quartier-q4", kind = "choice", prompt = "Qu'est-ce qu'il y a dans le parc ?", options = listOf("Un marché", "Des voitures", "Une école", "Un cinéma"), answers = listOf("Un marché"), explain = "Il traverse le parc : il y a un marché."), Exercise(id = "fr-listen-balade-quartier-q5", kind = "written", prompt = "Qu'est-ce que Karim achète ?", options = listOf(), answers = listOf("un kilo de pommes", "1 kilo de pommes", "des pommes"), explain = "Karim achète un kilo de pommes."), Exercise(id = "fr-listen-balade-quartier-q6", kind = "choice", prompt = "Comment trouve-t-il le quartier ?", options = listOf("Il adore", "Il déteste", "Il oublie", "Il cherche"), answers = listOf("Il adore"), explain = "Il adore son quartier.")), skills = listOf("listening:gist", "listening:detail", "grammar:there-is-are", "function:ask-for-directions", "vocab:town")) }

object ListenData120 { val text = ListeningText(id = "fr-listen-appel-mamie", languageID = "fr", title = "Un appel à mamie", level = "A1", topic = "famille", unitID = "fr-foundations-u12", text = "Allô, mamie ? C'est Léa. Tu es là ? Oui, ma chérie ! Comment va la famille ? Très bien ! Maman est au travail, elle revient à six heures. Papa prépare le dîner : il cuisine toujours le samedi. Mon petit frère regarde la télé. Et mon oncle Paul ? Il arrive dimanche avec sa fille. Très bien ! Je rappelle plus tard, papa m'appelle pour le dîner. Gros bisous, mamie !", questions = listOf(Exercise(id = "fr-listen-appel-mamie-q1", kind = "choice", prompt = "Qui appelle Léa ?", options = listOf("Sa mamie", "Son papa", "Sa sœur", "Son oncle"), answers = listOf("Sa mamie"), explain = "Elle dit : Allô, mamie ? C'est Léa."), Exercise(id = "fr-listen-appel-mamie-q2", kind = "choice", prompt = "Où est maman ?", options = listOf("Au travail", "À la maison", "Au parc", "Au marché"), answers = listOf("Au travail"), explain = "Maman est au travail, elle revient à six heures."), Exercise(id = "fr-listen-appel-mamie-q3", kind = "choice", prompt = "Qui cuisine toujours le samedi ?", options = listOf("Papa", "Maman", "Léa", "Le petit frère"), answers = listOf("Papa"), explain = "Papa prépare le dîner : il cuisine toujours le samedi."), Exercise(id = "fr-listen-appel-mamie-q4", kind = "written", prompt = "Qui arrive dimanche ?", options = listOf(), answers = listOf("mon oncle Paul", "son oncle", "mon oncle paul"), explain = "Mon oncle Paul arrive dimanche avec sa fille."), Exercise(id = "fr-listen-appel-mamie-q5", kind = "choice", prompt = "Que fait le petit frère ?", options = listOf("Il regarde la télé", "Il cuisine", "Il travaille", "Il lit"), answers = listOf("Il regarde la télé"), explain = "Mon petit frère regarde la télé."), Exercise(id = "fr-listen-appel-mamie-q6", kind = "choice", prompt = "Que fait Léa à la fin ?", options = listOf("Elle rappelle plus tard", "Elle cuisine le dîner", "Elle va au travail", "Elle regarde la télé"), answers = listOf("Elle rappelle plus tard"), explain = "Je rappelle plus tard, dit Léa.")), skills = listOf("listening:gist", "listening:detail", "vocab:family", "vocab:daily-routine")) }

object ListenData121 { val text = ListeningText(id = "fr-listen-weekend-pluvieux", languageID = "fr", title = "Un week-end pluvieux", level = "A1", topic = "météo", unitID = "fr-foundations-u13", text = "Quel temps ! Il pleut sur Toulouse. Léa appelle son ami Karim : On va au parc ? Non, il pleut. Et il y a du vent. Le parc est désert ! Bon, je reste à la maison. Je lis toujours le samedi après-midi. En hiver, je ne sors jamais. Moi, j'aime la pluie. Je bois un chocolat chaud et je regarde un film. Alors, à demain ! Demain, il fait beau.", questions = listOf(Exercise(id = "fr-listen-weekend-pluvieux-q1", kind = "choice", prompt = "Quel temps fait-il ?", options = listOf("Il pleut", "Il neige", "Il fait beau", "Il fait chaud"), answers = listOf("Il pleut"), explain = "Il pleut sur Toulouse."), Exercise(id = "fr-listen-weekend-pluvieux-q2", kind = "choice", prompt = "Pourquoi Karim ne va pas au parc ?", options = listOf("Il pleut", "Il travaille", "Il est fatigué", "Il lit"), answers = listOf("Il pleut"), explain = "Non, il pleut. Et il y a du vent."), Exercise(id = "fr-listen-weekend-pluvieux-q3", kind = "choice", prompt = "Qu'est-ce que Léa fait toujours le samedi après-midi ?", options = listOf("Elle lit", "Elle cuisine", "Elle nage", "Elle dort"), answers = listOf("Elle lit"), explain = "Je lis toujours le samedi après-midi, dit Léa."), Exercise(id = "fr-listen-weekend-pluvieux-q4", kind = "written", prompt = "Qu'est-ce que Karim boit ?", options = listOf(), answers = listOf("un chocolat chaud", "du chocolat chaud"), explain = "Je bois un chocolat chaud, dit Karim."), Exercise(id = "fr-listen-weekend-pluvieux-q5", kind = "choice", prompt = "En hiver, quand est-ce que Karim sort ?", options = listOf("Jamais", "Toujours", "Souvent", "Parfois"), answers = listOf("Jamais"), explain = "En hiver, je ne sors jamais."), Exercise(id = "fr-listen-weekend-pluvieux-q6", kind = "choice", prompt = "Où est Léa ?", options = listOf("À la maison", "Au parc", "Au travail", "À la piscine"), answers = listOf("À la maison"), explain = "Bon, je reste à la maison, dit Léa.")), skills = listOf("listening:gist", "listening:detail", "vocab:weather", "vocab:daily-routine", "grammar:frequency-adverbs", "function:talk-about-weather")) }

object ListenData122 { val text = ListeningText(id = "fr-listen-metro-perdu", languageID = "fr", title = "Perdue dans le métro", level = "A1", topic = "transports", unitID = "fr-foundations-u14", text = "Léa est à Paris pour la première fois. Elle prend le métro tous les jours, mais aujourd'hui, elle est perdue. Elle demande à un agent : « Pardon, le train part à quelle heure ? » « À huit heures et quart. » « Et je prends quelle ligne ? » « La ligne 4. Le métro arrive à huit heures et demie à la gare. » « Merci ! D'habitude, je prends toujours le bus, mais le métro, c'est rapide ! » Elle est contente : à Paris, on va partout en métro.", questions = listOf(Exercise(id = "fr-listen-metro-perdu-q1", kind = "choice", prompt = "Pourquoi Léa demande de l'aide ?", options = listOf("Elle est perdue", "Elle est malade", "Elle est fatiguée", "Elle est en retard"), answers = listOf("Elle est perdue"), explain = "Aujourd'hui, elle est perdue dans le métro."), Exercise(id = "fr-listen-metro-perdu-q2", kind = "choice", prompt = "Le train part à quelle heure ?", options = listOf("À huit heures et quart", "À huit heures et demie", "À sept heures et quart", "À neuf heures"), answers = listOf("À huit heures et quart"), explain = "À huit heures et quart, dit l'agent."), Exercise(id = "fr-listen-metro-perdu-q3", kind = "choice", prompt = "Le métro arrive à quelle heure à la gare ?", options = listOf("À huit heures et demie", "À huit heures et quart", "À neuf heures et demie", "À sept heures"), answers = listOf("À huit heures et demie"), explain = "Le métro arrive à huit heures et demie à la gare."), Exercise(id = "fr-listen-metro-perdu-q4", kind = "written", prompt = "Quelle ligne est-ce que Léa prend ?", options = listOf(), answers = listOf("la ligne 4", "ligne 4", "la 4"), explain = "La ligne 4, dit l'agent."), Exercise(id = "fr-listen-metro-perdu-q5", kind = "choice", prompt = "Quel transport est-ce que Léa prend d'habitude ?", options = listOf("Le bus", "Le train", "Le vélo", "À pied"), answers = listOf("Le bus"), explain = "D'habitude, je prends toujours le bus."), Exercise(id = "fr-listen-metro-perdu-q6", kind = "choice", prompt = "Le métro, c'est comment, pour Léa ?", options = listOf("Rapide", "Cher", "Long", "Difficile"), answers = listOf("Rapide"), explain = "Le métro, c'est rapide, dit Léa.")), skills = listOf("listening:gist", "listening:detail", "vocab:transport", "function:tell-time")) }

object ListenData123 { val text = ListeningText(id = "fr-listen-pharmacie-samedi", languageID = "fr", title = "À la pharmacie, samedi", level = "A1", topic = "santé", unitID = "fr-foundations-u15", text = "Samedi matin, Hugo est malade. Il a mal à la tête et il a de la fièvre. Il va à la pharmacie. « Bonjour, je voudrais quelque chose pour la tête, s'il vous plaît. » « Vous avez une ordonnance ? » « Non, je n'ai pas d'ordonnance. » « Alors, voici des comprimés : deux fois par jour, matin et soir. Buvez toujours beaucoup d'eau ! » « Ça coûte combien ? » « Quatre euros. » Merci, bonne journée ! Hugo rentre : avec les comprimés et l'eau, il va être en forme.", questions = listOf(Exercise(id = "fr-listen-pharmacie-samedi-q1", kind = "choice", prompt = "Quel jour Hugo va à la pharmacie ?", options = listOf("Samedi", "Dimanche", "Lundi", "Vendredi"), answers = listOf("Samedi"), explain = "Samedi matin, Hugo est malade."), Exercise(id = "fr-listen-pharmacie-samedi-q2", kind = "choice", prompt = "Hugo a mal à… ?", options = listOf("À la tête", "Au ventre", "À la gorge", "Au dos"), answers = listOf("À la tête"), explain = "Il a mal à la tête et il a de la fièvre."), Exercise(id = "fr-listen-pharmacie-samedi-q3", kind = "written", prompt = "Qu'est-ce qu'Hugo demande à la pharmacie ?", options = listOf(), answers = listOf("quelque chose pour la tête", "quelque chose pour la tete", "il demande quelque chose pour la tête"), explain = "Je voudrais quelque chose pour la tête, dit Hugo."), Exercise(id = "fr-listen-pharmacie-samedi-q4", kind = "choice", prompt = "Hugo a une ordonnance ?", options = listOf("Non", "Oui", "Deux", "Peut-être"), answers = listOf("Non"), explain = "Non, je n'ai pas d'ordonnance, dit Hugo."), Exercise(id = "fr-listen-pharmacie-samedi-q5", kind = "choice", prompt = "Combien de fois par jour est-ce qu'il prend les comprimés ?", options = listOf("Deux fois", "Une fois", "Trois fois", "Jamais"), answers = listOf("Deux fois"), explain = "Deux fois par jour, matin et soir."), Exercise(id = "fr-listen-pharmacie-samedi-q6", kind = "choice", prompt = "Ça coûte combien ?", options = listOf("Quatre euros", "Six euros", "Quatorze euros", "Deux euros"), answers = listOf("Quatre euros"), explain = "Quatre euros, dit le pharmacien."), Exercise(id = "fr-listen-pharmacie-samedi-q7", kind = "choice", prompt = "Qu'est-ce qu'Hugo boit toujours ?", options = listOf("Beaucoup d'eau", "Du café", "Du jus", "Du lait"), answers = listOf("Beaucoup d'eau"), explain = "Buvez toujours beaucoup d'eau !")), skills = listOf("listening:gist", "listening:detail", "vocab:health", "grammar:frequency-adverbs")) }

object ListenData124 { val text = ListeningText(id = "fr-listen-diner-surprise", languageID = "fr", title = "Le dîner surprise", level = "A1", topic = "restaurant", unitID = "fr-foundations-u16", text = "C'est samedi. Karim invite Léa au restaurant, c'est une surprise. Ils prennent une table pour deux en terrasse. Léa veut une pizza, mais il n'y a pas de pizza : elle prend une quiche. Karim commande le poulet avec des frites. Comme boisson, ils prennent une carafe d'eau et un jus d'orange. Après le repas, Karim demande l'addition. Léa veut payer, mais c'est Karim qui paye : c'est son cadeau d'anniversaire. Léa est très contente.", questions = listOf(Exercise(id = "fr-listen-diner-surprise-q1", kind = "choice", prompt = "Où est-ce que Karim invite Léa ?", options = listOf("Au restaurant", "Au cinéma", "À la maison", "Au parc"), answers = listOf("Au restaurant"), explain = "Karim invite Léa au restaurant, c'est une surprise."), Exercise(id = "fr-listen-diner-surprise-q2", kind = "choice", prompt = "Qu'est-ce que Léa prend finalement ?", options = listOf("Une quiche", "Une pizza", "Une salade", "Le poulet"), answers = listOf("Une quiche"), explain = "Il n'y a pas de pizza, alors elle prend une quiche."), Exercise(id = "fr-listen-diner-surprise-q3", kind = "written", prompt = "Qu'est-ce que Karim commande comme plat ?", options = listOf(), answers = listOf("le poulet", "poulet", "le poulet avec des frites"), explain = "Karim commande le poulet avec des frites."), Exercise(id = "fr-listen-diner-surprise-q4", kind = "choice", prompt = "Qu'est-ce qu'ils prennent comme boisson ?", options = listOf("Une carafe d'eau et un jus d'orange", "Deux cafés", "Deux sodas", "Un thé et un café"), answers = listOf("Une carafe d'eau et un jus d'orange"), explain = "Ils prennent une carafe d'eau et un jus d'orange."), Exercise(id = "fr-listen-diner-surprise-q5", kind = "written", prompt = "Qui paye l'addition ?", options = listOf(), answers = listOf("karim", "c'est karim"), explain = "Léa veut payer, mais c'est Karim qui paye."), Exercise(id = "fr-listen-diner-surprise-q6", kind = "choice", prompt = "Pourquoi Karim paye ?", options = listOf("C'est son cadeau d'anniversaire", "Léa n'a pas d'argent", "Le repas est gratuit", "C'est Léa qui invite"), answers = listOf("C'est son cadeau d'anniversaire"), explain = "Le repas est le cadeau d'anniversaire de Léa.")), skills = listOf("listening:gist", "listening:detail", "vocab:food", "function:order-food")) }

object ListenData125 { val text = ListeningText(id = "fr-listen-plan-anniversaire", languageID = "fr", title = "Le plan anniversaire", level = "A2", topic = "invitations", unitID = "fr-foundations-u17", text = "Samedi, c'est l'anniversaire de Mai. Karim appelle Léa pour organiser la surprise. Il va acheter un livre sur les voyages, parce que Mai adore partir. Léa, elle, va lui offrir des fleurs et un gâteau au chocolat : elle va passer à la boulangerie vendredi soir. Ils vont se retrouver chez Karim à sept heures et décorer le salon avant son arrivée. Léa ne peut pas rester tard, parce qu'elle travaille tôt dimanche, mais elle va venir quand même. Mai ne sait rien : elle va arriver à sept heures et demie. Et là, surprise !", questions = listOf(Exercise(id = "fr-listen-plan-anniversaire-q1", kind = "choice", prompt = "C'est l'anniversaire de qui samedi ?", options = listOf("De Mai", "De Léa", "De Karim", "Du frère de Karim"), answers = listOf("De Mai"), explain = "Samedi, c'est l'anniversaire de Mai."), Exercise(id = "fr-listen-plan-anniversaire-q2", kind = "choice", prompt = "Qu'est-ce que Karim va acheter ?", options = listOf("Un livre sur les voyages", "Des fleurs", "Un gâteau au chocolat", "Des décorations"), answers = listOf("Un livre sur les voyages"), explain = "Il va acheter un livre sur les voyages, parce que Mai adore partir."), Exercise(id = "fr-listen-plan-anniversaire-q3", kind = "written", prompt = "Qu'est-ce que Léa va offrir ?", options = listOf(), answers = listOf("des fleurs et un gâteau", "des fleurs et un gâteau au chocolat", "des fleurs"), explain = "Léa va offrir des fleurs et un gâteau au chocolat."), Exercise(id = "fr-listen-plan-anniversaire-q4", kind = "choice", prompt = "Pourquoi Léa ne reste pas tard ?", options = listOf("Elle travaille tôt dimanche", "Elle n'aime pas les fêtes", "Elle est malade", "Elle habite loin"), answers = listOf("Elle travaille tôt dimanche"), explain = "Elle travaille tôt dimanche, mais elle vient quand même."), Exercise(id = "fr-listen-plan-anniversaire-q5", kind = "written", prompt = "À quelle heure Mai arrive-t-elle ?", options = listOf(), answers = listOf("sept heures et demie", "7h30"), explain = "Elle va arriver à sept heures et demie."), Exercise(id = "fr-listen-plan-anniversaire-q6", kind = "choice", prompt = "Où vont-ils décorer ?", options = listOf("Le salon de Karim", "La cuisine de Léa", "Le jardin", "Un restaurant"), answers = listOf("Le salon de Karim"), explain = "Ils vont se retrouver chez Karim et décorer le salon.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to", "vocab:social-expressions"), exposureSkills = listOf("grammar:future-forms")) }

object ListenData126 { val text = ListeningText(id = "fr-listen-anecdote-ete", languageID = "fr", title = "L'anecdote de l'été", level = "B1", topic = "récits", unitID = "fr-foundations-u18", text = "Cet été, Théo est allé à Marseille rendre visite à sa cousine. D'abord, tout s'est bien passé : ils ont visité le Vieux-Port et mangé des moules face à la mer. Ensuite, sur le chemin du retour, sa voiture est tombée en panne sur l'autoroute. Soudain, un camion s'est arrêté derrière lui, et un homme est descendu avec une grande boîte. Théo a cru qu'il allait lui vendre quelque chose. Mais il s'est avéré que cet homme réparait les voitures bénévolement le week-end : il a retrouvé Théo sur la route en vingt minutes. Au final, Théo est rentré plus tard que prévu, mais avec une belle histoire à raconter. « Sans blague ! », lui a dit sa cousine.", questions = listOf(Exercise(id = "fr-listen-anecdote-ete-q1", kind = "choice", prompt = "Pourquoi Théo est-il allé à Marseille ?", options = listOf("Pour rendre visite à sa cousine", "Pour travailler", "Pour voir un match", "Pour déménager"), answers = listOf("Pour rendre visite à sa cousine"), explain = "Il est allé à Marseille rendre visite à sa cousine."), Exercise(id = "fr-listen-anecdote-ete-q2", kind = "choice", prompt = "Qu'est-ce qui s'est passé sur le chemin du retour ?", options = listOf("Sa voiture est tombée en panne", "Il a perdu son téléphone", "Il a manqué le train", "Il a oublié son sac"), answers = listOf("Sa voiture est tombée en panne"), explain = "Sa voiture est tombée en panne sur l'autoroute."), Exercise(id = "fr-listen-anecdote-ete-q3", kind = "written", prompt = "Qu'est-ce que Théo a cru au début ?", options = listOf(), answers = listOf("qu'il allait lui vendre quelque chose", "que l'homme allait lui vendre quelque chose"), explain = "Théo a cru que l'homme allait lui vendre quelque chose."), Exercise(id = "fr-listen-anecdote-ete-q4", kind = "choice", prompt = "Que faisait l'homme du camion ?", options = listOf("Il réparait les voitures bénévolement", "Il vendait des pièces", "Il cherchait du travail", "Il faisait un contrôle"), answers = listOf("Il réparait les voitures bénévolement"), explain = "Il s'est avéré qu'il réparait les voitures bénévolement le week-end."), Exercise(id = "fr-listen-anecdote-ete-q5", kind = "written", prompt = "En combien de temps l'homme a-t-il retrouvé Théo sur la route ?", options = listOf(), answers = listOf("vingt minutes", "20 minutes", "vingt"), explain = "L'homme a retrouvé Théo sur la route en vingt minutes."), Exercise(id = "fr-listen-anecdote-ete-q6", kind = "choice", prompt = "Quelle a été la réaction de la cousine ?", options = listOf("Sans blague !", "Et puis ?", "Bonne idée !", "Avec plaisir !"), answers = listOf("Sans blague !"), explain = "« Sans blague ! », lui a dit sa cousine.")), skills = listOf("listening:inference", "listening:detail", "grammar:past-simple-irregular", "grammar:connectors"), exposureSkills = listOf("vocab:social-expressions")) }

object ListenData127 { val text = ListeningText(id = "fr-listen-debat-tacte", languageID = "fr", title = "Débat : le tact qui dispute", level = "C1", topic = "débats", unitID = "fr-foundations-u9", text = "Sur une chaîne d'information, un débat vif mais courtois oppose Nadia Belkacem, économiste, à Gérard Vasseur, chef d'entreprise : la semaine de quatre jours. Nadia ouvre : « Je comprends votre point : la productivité par heure progresse. Cela dit, nos données montrent que les gains restent inégalement répartis. » Gérard enchaîne : « Je vois les choses autrement. Sans pour autant nier la fatigue des salariés, je crains que la mesure ne pénalise les PME. » Le modérateur reformule : « Autrement dit, vous vous accordez sur le diagnostic, mais pas sur le remède ? » Tous deux le concèdent. Nadia tempère : « Je ne suis pas certaine que la comparaison internationale soit transposable, mais je resterai attentive à vos résultats. » Vingt minutes de désaccord poli, sans une once d'agressivité.", questions = listOf(Exercise(id = "fr-listen-debat-tacte-q1", kind = "choice", prompt = "Quel est le sujet du débat ?", options = listOf("La semaine de quatre jours", "Les salaires des PME", "La productivité par heure", "La comparaison internationale"), answers = listOf("La semaine de quatre jours"), explain = "Le débat porte sur la semaine de quatre jours."), Exercise(id = "fr-listen-debat-tacte-q2", kind = "written", prompt = "Avec quelle formule Nadia reconnaît-elle d'abord l'argument adverse ?", options = listOf(), answers = listOf("je comprends votre point", "je comprend votre point"), explain = "« Je comprends votre point » : la reconnaissance avant l'objection."), Exercise(id = "fr-listen-debat-tacte-q3", kind = "choice", prompt = "Que craint Gérard ?", options = listOf("Que la mesure pénalise les PME", "Que les salariés soient fatigués", "Que la productivité baisse par heure", "Que les données soient fausses"), answers = listOf("Que la mesure pénalise les PME"), explain = "Je crains que la mesure ne pénalise les PME."), Exercise(id = "fr-listen-debat-tacte-q4", kind = "choice", prompt = "Sur quoi les deux invités s'accordent-ils ?", options = listOf("Le diagnostic", "Le remède", "Le calendrier", "Les salaires"), answers = listOf("Le diagnostic"), explain = "Vous vous accordez sur le diagnostic, mais pas sur le remède."), Exercise(id = "fr-listen-debat-tacte-q5", kind = "written", prompt = "Quelle réserve finale Nadia formule-t-elle ?", options = listOf(), answers = listOf("la comparaison internationale n'est peut-être pas transposable", "je ne suis pas certaine que la comparaison soit transposable", "la comparaison n'est pas transposable"), explain = "« Je ne suis pas certaine que la comparaison internationale soit transposable »."), Exercise(id = "fr-listen-debat-tacte-q6", kind = "choice", prompt = "Comment le commentaire final décrit-il le débat ?", options = listOf("Poli et documenté", "Agressif", "Confus", "Superficiel"), answers = listOf("Poli et documenté"), explain = "Vingt minutes de désaccord poli, sans une once d'agressivité.")), skills = listOf("listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion")) }

object ListenData128 { val text = ListeningText(id = "fr-listen-soiree-vendredi", languageID = "fr", title = "La soirée du vendredi", level = "A1", topic = "amis", unitID = "fr-foundations-u19", text = "C'est vendredi soir. Léa arrive chez Mai pour dîner. Devant la porte, elle demande : « Je peux entrer ? » Mai ouvre : « Oui, bien sûr ! » Léa apporte des fleurs. Mai propose : « Tu veux un jus d'orange ? » Léa répond : « Volontiers ! » Le gâteau est délicieux : Léa prend deux morceaux. À dix heures, Léa dit : « Merci pour tout ! » Mai répond : « Bonne nuit ! » À la prochaine fois !", questions = listOf(Exercise(id = "fr-listen-soiree-vendredi-q1", kind = "choice", prompt = "Où est-ce que Léa va vendredi soir ?", options = listOf("Chez Mai", "Au restaurant", "Au cinéma", "Chez Karim"), answers = listOf("Chez Mai"), explain = "Léa arrive chez Mai pour le dîner."), Exercise(id = "fr-listen-soiree-vendredi-q2", kind = "choice", prompt = "Qu'est-ce que Léa demande devant la porte ?", options = listOf("Je peux entrer ?", "Vous allez bien ?", "Où est la fête ?", "Tu es seule ?"), answers = listOf("Je peux entrer ?"), explain = "Devant la porte, elle demande : « Je peux entrer ? »"), Exercise(id = "fr-listen-soiree-vendredi-q3", kind = "written", prompt = "Qu'est-ce que Léa apporte ?", options = listOf(), answers = listOf("des fleurs", "fleurs", "elle apporte des fleurs"), explain = "Léa apporte des fleurs pour Mai."), Exercise(id = "fr-listen-soiree-vendredi-q4", kind = "choice", prompt = "Qu'est-ce que Mai propose à boire ?", options = listOf("Un jus d'orange", "Un café", "Un thé", "De l'eau"), answers = listOf("Un jus d'orange"), explain = "Mai propose à boire : « Tu veux un jus d'orange ? »"), Exercise(id = "fr-listen-soiree-vendredi-q5", kind = "choice", prompt = "Comment est le gâteau ?", options = listOf("Il est délicieux", "Il est brûlé", "Il est trop sucré", "Il est petit"), answers = listOf("Il est délicieux"), explain = "Le gâteau de Mai est délicieux : Léa prend deux morceaux."), Exercise(id = "fr-listen-soiree-vendredi-q6", kind = "written", prompt = "Qu'est-ce que Léa dit à la fin de la soirée ?", options = listOf(), answers = listOf("merci pour tout", "merci pour tout !", "elle dit merci pour tout"), explain = "À dix heures, Léa se lève : « Merci pour tout ! »")), skills = listOf("listening:gist", "listening:detail", "vocab:social-expressions", "grammar:can")) }

object ListenData129 { val text = ListeningText(id = "fr-listen-reclamation-facture", languageID = "fr", title = "Au téléphone avec le magasin", level = "A2", topic = "réclamation", unitID = "fr-foundations-u20", text = "Bonjour, j'appelle au sujet d'une imprimante. Je l'ai achetée dans votre magasin la semaine dernière. Elle a bien marché deux jours, mais depuis hier elle ne s'allume plus. J'ai vérifié le câble et j'ai changé la prise, mais rien à faire. De plus, j'ai reçu deux factures pour le même article. Est-ce que je peux avoir un échange ? J'ai le ticket et la première facture sous la main. Le vendeur répond : « Bien sûr, apportez l'appareil au magasin avec les deux factures, et nous faisons l'échange tout de suite. » Le client est content : il passe cet après-midi.", questions = listOf(Exercise(id = "fr-listen-reclamation-facture-q1", kind = "choice", prompt = "Qu'est-ce que le client a acheté ?", options = listOf("Une imprimante", "Un vélo", "Un téléphone", "Une télévision"), answers = listOf("Une imprimante"), explain = "Bonjour, j'appelle au sujet d'une imprimante."), Exercise(id = "fr-listen-reclamation-facture-q2", kind = "choice", prompt = "Quand est-ce que le client l'a achetée ?", options = listOf("La semaine dernière", "Hier", "Le mois dernier", "L'année dernière"), answers = listOf("La semaine dernière"), explain = "Je l'ai achetée dans votre magasin la semaine dernière."), Exercise(id = "fr-listen-reclamation-facture-q3", kind = "written", prompt = "Depuis quand l'imprimante ne s'allume plus ?", options = listOf(), answers = listOf("depuis hier", "hier"), explain = "Elle a bien marché deux jours, mais depuis hier elle ne s'allume plus."), Exercise(id = "fr-listen-reclamation-facture-q4", kind = "choice", prompt = "Quel problème y a-t-il avec les factures ?", options = listOf("Il a reçu deux factures", "Il n'a pas de facture", "Il a perdu la facture", "La facture est illisible"), answers = listOf("Il a reçu deux factures"), explain = "De plus, j'ai reçu deux factures pour le même article."), Exercise(id = "fr-listen-reclamation-facture-q5", kind = "written", prompt = "Qu'est-ce que le client demande ?", options = listOf(), answers = listOf("un échange", "un echange", "il demande un échange"), explain = "Est-ce que je peux avoir un échange ? demande le client."), Exercise(id = "fr-listen-reclamation-facture-q6", kind = "choice", prompt = "Que doit apporter le client au magasin ?", options = listOf("L'appareil et les deux factures", "Seulement le ticket", "Une nouvelle facture", "Rien, tout se fait au téléphone"), answers = listOf("L'appareil et les deux factures"), explain = "Apportez l'appareil au magasin avec les deux factures, dit le vendeur.")), skills = listOf("listening:detail", "listening:gist", "function:solve-problems", "grammar:past-simple-regular")) }

object ListenData130 { val text = ListeningText(id = "fr-listen-entretien-blanc", languageID = "fr", title = "L'entretien blanc", level = "B1", topic = "travail", unitID = "fr-foundations-u21", text = "Léa fait passer un entretien blanc à Karim, qui postule dans une agence de voyage. Léa : « Parlez-moi de votre expérience. » Karim : « J'ai travaillé trois ans dans une agence à Lyon, où j'ai géré les réservations et j'ai formé deux stagiaires. » Léa : « Quels sont vos points forts ? » Karim : « Je suis organisé et je reste calme quand un client s'énerve ; par contre, je parle encore peu anglais, mais je prends des cours le soir. » Léa : « Et vos objectifs ? » Karim : « J'aimerais évoluer vers le conseil, et à terme coordonner une équipe. » Léa : « Merci. Vous citez une vraie faiblesse, c'est plutôt bon signe : un candidat honnête inspire confiance. »", questions = listOf(Exercise(id = "fr-listen-entretien-blanc-q1", kind = "choice", prompt = "Où Karim veut-il travailler ?", options = listOf("Dans une agence de voyage", "Dans un restaurant", "Dans une école", "Dans un hôpital"), answers = listOf("Dans une agence de voyage"), explain = "Karim postule dans une agence de voyage."), Exercise(id = "fr-listen-entretien-blanc-q2", kind = "written", prompt = "Combien d'années d'expérience Karim cite-t-il ?", options = listOf(), answers = listOf("trois ans", "3 ans"), explain = "J'ai travaillé trois ans dans une agence à Lyon, dit Karim."), Exercise(id = "fr-listen-entretien-blanc-q3", kind = "choice", prompt = "Quelle faiblesse Karim admet-il ?", options = listOf("Il parle peu anglais", "Il est désorganisé", "Il s'énerve vite", "Il n'a jamais formé personne"), answers = listOf("Il parle peu anglais"), explain = "Par contre, je parle encore peu anglais, mais je prends des cours le soir."), Exercise(id = "fr-listen-entretien-blanc-q4", kind = "choice", prompt = "Que fait Karim pour progresser en anglais ?", options = listOf("Il prend des cours le soir", "Il regarde des films", "Il a arrêté d'apprendre", "Il voyage chaque mois"), answers = listOf("Il prend des cours le soir"), explain = "Mais je prends des cours le soir, précise Karim."), Exercise(id = "fr-listen-entretien-blanc-q5", kind = "written", prompt = "Quel est l'objectif de long terme de Karim ?", options = listOf(), answers = listOf("coordonner une équipe", "coordonner une equipe", "à terme coordonner une équipe"), explain = "Et à terme coordonner une équipe, dit Karim."), Exercise(id = "fr-listen-entretien-blanc-q6", kind = "choice", prompt = "Pourquoi Léa juge-t-elle cet entretien bon signe ?", options = listOf("Karim est honnête sur sa faiblesse", "Karim parle parfaitement anglais", "Karim veut un salaire élevé", "Karim connaît déjà l'équipe"), answers = listOf("Karim est honnête sur sa faiblesse"), explain = "Vous citez une vraie faiblesse : un candidat honnête inspire confiance.")), skills = listOf("listening:inference", "listening:detail", "vocab:work", "function:talk-about-work")) }

object ListenData131 { val text = ListeningText(id = "fr-listen-ton-podcast", languageID = "fr", title = "Podcast : le ton juste", level = "C1", topic = "langue", unitID = "fr-foundations-u9", text = "Dans ce podcast, Léa interroge Mme Vasseur, rédactrice, sur le ton juste. Léa : « Un mail commence par je veux un délai : ça passe ? » Mme Vasseur : « Ça se comprend, mais ça sonne sec. On dira plutôt : j'aimerais qu'on envisage un délai supplémentaire. Le verbe envisager ouvre la discussion au lieu de la fermer. » Léa : « Et côté collocations ? » Mme Vasseur : « C'est là que ça se joue : on prend une décision, on tire une conclusion ; celui qui écrit faire une décision trahit une hâte. » Léa : « Donc le ton juste, c'est une affaire de mots choisis ? » Mme Vasseur : « Autant dire que oui : qui choisit ses verbes domine son sujet ; qui les subit paraît pressé, voire négligé. »", questions = listOf(Exercise(id = "fr-listen-ton-podcast-q1", kind = "choice", prompt = "Quel est le thème de l'émission ?", options = listOf("Le ton juste et les collocations", "L'orthographe des e-mails", "Le recrutement des rédacteurs", "La gestion du stress"), answers = listOf("Le ton juste et les collocations"), explain = "Léa interroge Mme Vasseur sur le ton juste, et la discussion porte sur les collocations."), Exercise(id = "fr-listen-ton-podcast-q2", kind = "choice", prompt = "Quel problème Mme Vasseur relève-t-elle dans « je veux un délai » ?", options = listOf("Ça sonne sec", "C'est trop long", "C'est incorrect", "Ça manque d'exemples"), answers = listOf("Ça sonne sec"), explain = "Ça se comprend, mais ça sonne sec, dit-elle."), Exercise(id = "fr-listen-ton-podcast-q3", kind = "written", prompt = "Quel verbe ouvre la discussion au lieu de la fermer ?", options = listOf(), answers = listOf("envisager", "le verbe envisager"), explain = "Le verbe envisager ouvre la discussion au lieu de la fermer."), Exercise(id = "fr-listen-ton-podcast-q4", kind = "choice", prompt = "Quelle paire de collocations Mme Vasseur donne-t-elle ?", options = listOf("Prendre une décision, tirer une conclusion", "Faire une décision, mettre une conclusion", "Prendre un choix, tirer une décision", "Faire un choix, prendre une conclusion"), answers = listOf("Prendre une décision, tirer une conclusion"), explain = "On prend une décision, on tire une conclusion."), Exercise(id = "fr-listen-ton-podcast-q5", kind = "choice", prompt = "Que veut dire « qui choisit ses verbes domine son sujet » ?", options = listOf("Bien choisir ses mots rend crédible", "Écrire vite impressionne", "Les verbes font peur", "Les sujets dominent les mots"), answers = listOf("Bien choisir ses mots rend crédible"), explain = "Qui choisit ses verbes domine son sujet ; qui les subit paraît pressé."), Exercise(id = "fr-listen-ton-podcast-q6", kind = "written", prompt = "Avec quelle formule Mme Vasseur conclut-elle ?", options = listOf(), answers = listOf("autant dire que oui", "autant dire que"), explain = "Autant dire que oui, conclut Mme Vasseur.")), skills = listOf("listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion")) }

object ListenData132 { val text = ListeningText(id = "it-listen-cafe-morning", languageID = "it", title = "Un caffè prima del lavoro", level = "A1", topic = "routine", unitID = "it-foundations-u1", text = "Ogni mattina, Marta cammina fino a un piccolo caffè vicino a casa sua. Il cameriere conosce il suo nome, così non deve mai ordinare. Oggi si siede vicino alla finestra con un caffè e un cornetto. Il suo autobus parte alle otto e mezza, ma non è preoccupata. Il caffè è molto tranquillo a quell'ora. Beve il caffè lentamente e guarda la città che si sveglia.", questions = listOf(Exercise(id = "it-listen-cafe-morning-q1", kind = "choice", prompt = "Dove va Marta ogni mattina?", options = listOf("In un piccolo caffè", "Al suo ufficio", "Alla stazione degli autobus", "In un parco"), answers = listOf("In un piccolo caffè"), explain = "Cammina fino a un piccolo caffè vicino a casa sua."), Exercise(id = "it-listen-cafe-morning-q2", kind = "choice", prompt = "Cosa fa colazione oggi?", options = listOf("Un caffè e un cornetto", "Tè e toast", "Succo d'arancia", "Niente"), answers = listOf("Un caffè e un cornetto"), explain = "Si siede vicino alla finestra con un caffè e un cornetto."), Exercise(id = "it-listen-cafe-morning-q3", kind = "written", prompt = "A che ora parte il suo autobus?", options = listOf(), answers = listOf("alle otto e mezza", "otto e mezza"), explain = "Il suo autobus parte alle otto e mezza."), Exercise(id = "it-listen-cafe-morning-q4", kind = "choice", prompt = "Come si sente per l'orario?", options = listOf("Non è preoccupata", "È in grandissimo ritardo", "È arrabbiata", "Ha sonno"), answers = listOf("Non è preoccupata"), explain = "Il testo dice che non è preoccupata."), Exercise(id = "it-listen-cafe-morning-q5", kind = "choice", prompt = "Chi conosce il suo nome?", options = listOf("Il cameriere", "L'autista dell'autobus", "Il suo capo", "Un vicino"), answers = listOf("Il cameriere"), explain = "Il cameriere conosce il suo nome, così non deve mai ordinare."), Exercise(id = "it-listen-cafe-morning-q6", kind = "written", prompt = "Dove si siede oggi?", options = listOf(), answers = listOf("vicino alla finestra", "accanto alla finestra", "alla finestra"), explain = "Oggi si siede vicino alla finestra.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")) }

object ListenData133 { val text = ListeningText(id = "it-listen-language-class", languageID = "it", title = "Il corso di lingua", level = "A1", topic = "presentazioni", unitID = "it-foundations-u1", text = "Marta partecipa alla sua prima lezione di portoghese in un piccolo istituto. In classe ci sono sei persone e tutti vogliono parlare. L'insegnante chiede le presentazioni. « Mi chiamo Marta e sono della Bolivia », dice una signora. « Io sono Andrés, sono del Perù e lavoro in un ristorante », dice un ragazzo. Marta si presenta anche lei: « Sono Marta, sono argentina e sono infermiera ». L'insegnante è di Madrid e insegna con molto humour. Alla fine della lezione, gli studenti si scambiano i numeri di telefono. Non sono ancora amici, ma la prossima settimana vanno a prendere un caffè insieme per praticare.", questions = listOf(Exercise(id = "it-listen-language-class-q1", kind = "choice", prompt = "Quante persone ci sono in classe?", options = listOf("Sei", "Tre", "Dieci", "Quattordici"), answers = listOf("Sei"), explain = "In classe ci sono sei persone."), Exercise(id = "it-listen-language-class-q2", kind = "choice", prompt = "Di dov'è Andrés?", options = listOf("Del Perù", "Della Bolivia", "Dell'Argentina", "Del Messico"), answers = listOf("Del Perù"), explain = "Andrés è del Perù e lavora in un ristorante."), Exercise(id = "it-listen-language-class-q3", kind = "choice", prompt = "Qual è il lavoro di Marta?", options = listOf("Infermiera", "Insegnante", "Cameriera", "Studentessa"), answers = listOf("Infermiera"), explain = "Marta è argentina ed è infermiera."), Exercise(id = "it-listen-language-class-q4", kind = "written", prompt = "Di che città è l'insegnante?", options = listOf(), answers = listOf("madrid", "di madrid", "è di madrid"), explain = "L'insegnante è di Madrid."), Exercise(id = "it-listen-language-class-q5", kind = "choice", prompt = "Cosa fanno alla fine della lezione?", options = listOf("Si scambiano i numeri di telefono", "Tornano a casa da soli", "Fanno un esame", "Cenano al ristorante"), answers = listOf("Si scambiano i numeri di telefono"), explain = "Gli studenti si scambiano i numeri di telefono."), Exercise(id = "it-listen-language-class-q6", kind = "written", prompt = "Cosa fanno la prossima settimana?", options = listOf(), answers = listOf("prendere un caffè", "vanno a prendere un caffè", "prendere un caffè insieme"), explain = "La prossima settimana vanno a prendere un caffè insieme per praticare.")), skills = listOf("listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself")) }

object ListenData134 { val text = ListeningText(id = "it-listen-little-sister", languageID = "it", title = "Mia sorella piccola", level = "A1", topic = "famiglia", unitID = "it-foundations-u1", text = "Mia sorella piccola si chiama Carla e ha nove anni. È molto simpatica e molto chiacchierona. Carla non è riservata: parla con tutti, con i vicini, con gli insegnanti e con i cani del parco. È bionda, come nostra madre, e ha gli occhi castani come mio padre. Non è alta per la sua età, ma è molto veloce e le piace tantissimo il calcio. La sua squadra non è molto buona, ma a lei non importa. « Non sono professionista », dice, « io sono solo felice con il pallone ». Mia sorella è piccola, ma la sua gioia è enorme.", questions = listOf(Exercise(id = "it-listen-little-sister-q1", kind = "choice", prompt = "Quanti anni ha Carla?", options = listOf("Nove", "Diciannove", "Sette", "Dieci"), answers = listOf("Nove"), explain = "Carla ha nove anni."), Exercise(id = "it-listen-little-sister-q2", kind = "choice", prompt = "Com'è Carla?", options = listOf("Simpatica e chiacchierona", "Timida e riservata", "Seria", "Triste"), answers = listOf("Simpatica e chiacchierona"), explain = "È molto simpatica e molto chiacchierona."), Exercise(id = "it-listen-little-sister-q3", kind = "written", prompt = "Di che colore sono i suoi occhi?", options = listOf(), answers = listOf("castani", "gli occhi castani", "castani come suo padre"), explain = "Ha gli occhi castani come suo padre."), Exercise(id = "it-listen-little-sister-q4", kind = "choice", prompt = "Che capelli ha?", options = listOf("Biondi, come sua madre", "Scuri, come suo padre", "Rossi", "Corti e neri"), answers = listOf("Biondi, come sua madre"), explain = "È bionda, come nostra madre."), Exercise(id = "it-listen-little-sister-q5", kind = "choice", prompt = "Che cosa le piace tantissimo?", options = listOf("Il calcio", "Il nuoto", "La musica", "I videogiochi"), answers = listOf("Il calcio"), explain = "È molto veloce e le piace tantissimo il calcio."), Exercise(id = "it-listen-little-sister-q6", kind = "written", prompt = "Com'è la sua gioia?", options = listOf(), answers = listOf("enorme", "molto grande", "grande"), explain = "La sua gioia è enorme.")), skills = listOf("listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family")) }

object ListenData135 { val text = ListeningText(id = "it-listen-new-flatmate", languageID = "it", title = "Un nuovo coinquilino", level = "A1", topic = "casa", unitID = "it-foundations-u1", text = "Tom ha un nuovo coinquilino. Si chiama Leo e ha ventitré anni. Leo viene da un piccolo paese del nord, ma ora lavora in città. Ha due scatole, una chitarra e una bicicletta. L'appartamento ha due camere e una cucina molto luminosa. Tom spera che a Leo piaccia cucinare, perché a Tom non piace per niente.", questions = listOf(Exercise(id = "it-listen-new-flatmate-q1", kind = "choice", prompt = "Quanti anni ha Leo?", options = listOf("Ventitré", "Trentadue", "Venti", "Trenta"), answers = listOf("Ventitré"), explain = "Leo ha ventitré anni."), Exercise(id = "it-listen-new-flatmate-q2", kind = "choice", prompt = "Cosa NON ha Leo?", options = listOf("Una televisione", "Due scatole", "Una chitarra", "Una bicicletta"), answers = listOf("Una televisione"), explain = "Ha due scatole, una chitarra e una bicicletta — niente televisione."), Exercise(id = "it-listen-new-flatmate-q3", kind = "written", prompt = "Cosa odia fare Tom?", options = listOf(), answers = listOf("cucinare", "odia cucinare", "tom odia cucinare"), explain = "A Tom non piace per niente cucinare."), Exercise(id = "it-listen-new-flatmate-q4", kind = "choice", prompt = "Com'è l'appartamento?", options = listOf("Due camere e una cucina luminosa", "Una camera e un balcone", "Un giardino", "Due bagni"), answers = listOf("Due camere e una cucina luminosa"), explain = "L'appartamento ha due camere e una cucina molto luminosa."), Exercise(id = "it-listen-new-flatmate-q5", kind = "choice", prompt = "Dove lavora Leo adesso?", options = listOf("In città", "In un piccolo paese", "Al nord", "Non lavora"), answers = listOf("In città"), explain = "Viene da un piccolo paese del nord, ma ora lavora in città."), Exercise(id = "it-listen-new-flatmate-q6", kind = "written", prompt = "Quale strumento ha Leo?", options = listOf(), answers = listOf("una chitarra", "la chitarra", "chitarra"), explain = "Leo ha una chitarra.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")) }

object ListenData136 { val text = ListeningText(id = "it-listen-new-neighbour", languageID = "it", title = "La nuova vicina", level = "A1", topic = "gente", unitID = "it-foundations-u1", text = "Nel palazzo c'è una nuova vicina. Si chiama Amélie ed è della Francia. Non è studentessa; è fotografa. Non lavora in ufficio: lavora a casa e viaggia molto. I vicini sono curiosi, ma sono anche timidi, quindi non le parlano. Poi, una mattina, Ben la incontra alla porta. « Sei tu la nuova vicina? », chiede lui. « Sì, sono io », risponde lei, « e sono contenta di essere qui ». Adesso sono amici, e lei non è più sola nel palazzo.", questions = listOf(Exercise(id = "it-listen-new-neighbour-q1", kind = "choice", prompt = "Di dov'è Amélie?", options = listOf("Della Francia", "Dell'Italia", "Del Giappone", "Del Brasile"), answers = listOf("Della Francia"), explain = "Amélie è della Francia."), Exercise(id = "it-listen-new-neighbour-q2", kind = "choice", prompt = "Qual è il suo lavoro?", options = listOf("È fotografa", "È studentessa", "Lavora in ufficio", "È insegnante"), answers = listOf("È fotografa"), explain = "Non è studentessa; è fotografa."), Exercise(id = "it-listen-new-neighbour-q3", kind = "choice", prompt = "Lavora in ufficio?", options = listOf("No, lavora a casa", "Sì, tutti i giorni", "Solo in estate", "Non lo dice"), answers = listOf("No, lavora a casa"), explain = "Non lavora in ufficio: lavora a casa."), Exercise(id = "it-listen-new-neighbour-q4", kind = "written", prompt = "Perché i vicini non le parlano?", options = listOf(), answers = listOf("sono timidi", "perché sono timidi", "timidi"), explain = "Sono curiosi, ma sono anche timidi."), Exercise(id = "it-listen-new-neighbour-q5", kind = "choice", prompt = "Dove la incontra Ben?", options = listOf("Alla porta", "All'ascensore", "Per strada", "Al caffè"), answers = listOf("Alla porta"), explain = "Una mattina, Ben la incontra alla porta."), Exercise(id = "it-listen-new-neighbour-q6", kind = "written", prompt = "Come si sente Amélie alla fine?", options = listOf(), answers = listOf("contenta", "felice", "è contenta"), explain = "Dice che è contenta di essere qui.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")) }

object ListenData137 { val text = ListeningText(id = "it-listen-sunday-market", languageID = "it", title = "Il mercato della domenica", level = "A1", topic = "acquisti", unitID = "it-foundations-u1", text = "La domenica c'è un mercato nella piazza del paese. Anna e suo padre vanno lì alle nove, prima che si riempia. Comprano frutta, pane e fiori. Anna vuole delle fragole, ma suo padre dice che questa settimana sono troppo care. Alla fine portano a casa un grande sacco di arance e delle rose bianche per il tavolo della cucina.", questions = listOf(Exercise(id = "it-listen-sunday-market-q1", kind = "choice", prompt = "Quando Anna e suo padre vanno al mercato?", options = listOf("Alle nove", "A mezzogiorno", "Nel pomeriggio", "Alle sei e mezza"), answers = listOf("Alle nove"), explain = "Vanno alle nove, prima che si riempia."), Exercise(id = "it-listen-sunday-market-q2", kind = "written", prompt = "Perché Anna non prende le fragole?", options = listOf(), answers = listOf("sono troppo care", "troppo care", "perché sono troppo care"), explain = "Suo padre dice che sono troppo care questa settimana."), Exercise(id = "it-listen-sunday-market-q3", kind = "choice", prompt = "Cosa portano a casa?", options = listOf("Arance e rose", "Fragole e pane", "Mele e tulipani", "Pane e formaggio"), answers = listOf("Arance e rose"), explain = "Portano a casa arance e rose bianche."), Exercise(id = "it-listen-sunday-market-q4", kind = "choice", prompt = "Dov'è il mercato?", options = listOf("Nella piazza del paese", "Vicino al fiume", "Alla stazione", "In un supermercato"), answers = listOf("Nella piazza del paese"), explain = "La domenica c'è un mercato nella piazza del paese."), Exercise(id = "it-listen-sunday-market-q5", kind = "choice", prompt = "Cosa comprano?", options = listOf("Frutta, pane e fiori", "Pesce e verdure", "Formaggio e carne", "Solo fiori"), answers = listOf("Frutta, pane e fiori"), explain = "Comprano frutta, pane e fiori."), Exercise(id = "it-listen-sunday-market-q6", kind = "written", prompt = "Cosa vuole Anna?", options = listOf(), answers = listOf("delle fragole", "fragole", "vuole delle fragole"), explain = "Anna vuole delle fragole.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")) }

object ListenData138 { val text = ListeningText(id = "it-listen-appartamento-scelto", languageID = "it", title = "L'appartamento scelto", level = "A2", topic = "appartamenti", unitID = "it-foundations-u4", text = "Giulia e Marco cercano appartamento su un annuncio. Il primo è meno costoso, ma è più lontano dalla stazione: quaranta minuti a piedi. Il secondo costa cento euro in più al mese, ma è più luminoso e ha il balcone. Per Giulia la luce è la cosa più importante, perché lavora da casa. Alla fine decidono di chiedere una visita del secondo: costa di più, ma è il migliore dei due per loro.", questions = listOf(Exercise(id = "it-listen-appartamento-scelto-q1", kind = "choice", prompt = "Quanti appartamenti confrontano ?", options = listOf("Due", "Tre", "Quattro"), answers = listOf("Due"), explain = "Confrontano due appartamenti."), Exercise(id = "it-listen-appartamento-scelto-q2", kind = "choice", prompt = "Qual è il problema del meno costoso ?", options = listOf("È lontano dalla stazione", "Non ha il balcone", "È molto costoso", "È piccolo"), answers = listOf("È lontano dalla stazione"), explain = "Quaranta minuti a piedi dalla stazione."), Exercise(id = "it-listen-appartamento-scelto-q3", kind = "written", prompt = "Quanto costa in più il secondo al mese ?", options = listOf(), answers = listOf("cento euro", "100 euro"), explain = "Cento euro in più al mese."), Exercise(id = "it-listen-appartamento-scelto-q4", kind = "choice", prompt = "Cos'è più importante per Giulia ?", options = listOf("La luce", "Il prezzo", "Il balcone", "La cucina"), answers = listOf("La luce"), explain = "Lavora da casa."), Exercise(id = "it-listen-appartamento-scelto-q5", kind = "choice", prompt = "Cosa decidono alla fine ?", options = listOf("Chiedere una visita del secondo", "Tenere il primo", "Continuare a cercare", "Chiedere uno sconto"), answers = listOf("Chiedere una visita del secondo"), explain = "È il migliore dei due per loro.")), skills = listOf("listening:gist", "listening:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")) }

object ListenData139 { val text = ListeningText(id = "it-listen-sabato-organizzato", languageID = "it", title = "Il sabato organizzato", level = "A2", topic = "progetti", unitID = "it-foundations-u4", text = "Sara chiama suo fratello per organizzare il sabato. Lui propone la montagna, ma pioverà, quindi Sara suggerisce il museo nuovo. Si vedranno alle dieci all'ingresso principale e pranzeranno al mercato accanto, che è meno caro dei ristoranti del centro. La sera non hanno programmi: decideranno sul posto, quando sapranno che tempo fa.", questions = listOf(Exercise(id = "it-listen-sabato-organizzato-q1", kind = "choice", prompt = "Chi propone la montagna ?", options = listOf("Il fratello", "Sara", "La loro madre", "Un amico"), answers = listOf("Il fratello"), explain = "Suo fratello propone la montagna."), Exercise(id = "it-listen-sabato-organizzato-q2", kind = "choice", prompt = "Perché non la montagna ?", options = listOf("Pioverà", "Sono stanchi", "Il museo è gratis", "La montagna è lontana"), answers = listOf("Pioverà"), explain = "Pioverà, quindi vanno al museo."), Exercise(id = "it-listen-sabato-organizzato-q3", kind = "written", prompt = "A che ora si vedranno ?", options = listOf(), answers = listOf("alle dieci", "dieci"), explain = "Alle dieci all'ingresso principale."), Exercise(id = "it-listen-sabato-organizzato-q4", kind = "choice", prompt = "Dove pranzeranno ?", options = listOf("Al mercato accanto", "In un ristorante del centro", "A casa", "Al museo"), answers = listOf("Al mercato accanto"), explain = "Meno caro dei ristoranti del centro."), Exercise(id = "it-listen-sabato-organizzato-q5", kind = "choice", prompt = "Cosa faranno la sera ?", options = listOf("Decideranno sul posto", "Andranno al cinema", "Torneranno presto", "Vedranno amici"), answers = listOf("Decideranno sul posto"), explain = "Decideranno secondo il tempo.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("grammar:future-forms")) }

object ListenData140 { val text = ListeningText(id = "it-listen-mai-fatto", languageID = "it", title = "Cose che non ho mai fatto", level = "B1", topic = "viaggi", unitID = "it-foundations-u6", text = "Nella cucina di un ostello, tre viaggiatori paragonano le loro vite. Luca ha visitato venti paesi, ma non ha mai imparato a nuotare: « Lo so, è ridicolo ». Sara ha già fatto snorkeling due volte con le tartarughe, ma non è mai uscita dall'Europa prima di questo viaggio. E Elena, che è in viaggio da sei anni, non ha mai preso l'aereo: attraversa gli oceani in nave e i confini in autobus. « Mai ? » chiede Luca. « Mai. La paura è più vecchia di me. » Ridono delle cose che non hanno fatto, ed Elena dice una frase che resta: « Non serve aver fatto tutto. Basta avere ancora voglia ».", questions = listOf(Exercise(id = "it-listen-mai-fatto-q1", kind = "choice", prompt = "Cosa non ha mai fatto Luca ?", options = listOf("Imparare a nuotare", "Visitare venti paesi", "Attraversare in nave", "Uscire dall'Europa"), answers = listOf("Imparare a nuotare"), explain = "Ha visitato venti paesi, ma non ha mai imparato a nuotare."), Exercise(id = "it-listen-mai-fatto-q2", kind = "written", prompt = "Quante volte ha fatto snorkeling Sara ?", options = listOf(), answers = listOf("due volte", "2 volte", "due"), explain = "Sara ha già fatto snorkeling due volte con le tartarughe."), Exercise(id = "it-listen-mai-fatto-q3", kind = "choice", prompt = "Come attraversa Elena gli oceani ?", options = listOf("In nave", "In aereo", "In autobus", "A piedi"), answers = listOf("In nave"), explain = "Attraversa gli oceani in nave e i confini in autobus."), Exercise(id = "it-listen-mai-fatto-q4", kind = "choice", prompt = "Cosa dice Elena della paura ?", options = listOf("È più vecchia di lei", "È più giovane", "È ridicola", "Se n'è andata"), answers = listOf("È più vecchia di lei"), explain = "La paura è più vecchia di me."), Exercise(id = "it-listen-mai-fatto-q5", kind = "written", prompt = "Cosa basta, secondo Elena ?", options = listOf(), answers = listOf("avere ancora voglia", "aver voglia"), explain = "Basta avere ancora voglia.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")) }

object ListenData141 { val text = ListeningText(id = "it-listen-citta-paese", languageID = "it", title = "Dalla città al paese", level = "B1", topic = "cambiamenti", unitID = "it-foundations-u6", text = "Marco racconta perché ha lasciato Milano. Prima viveva in un appartamento piccolo e lavorava undici ore al giorno: « Guadagnavo bene, ma non avevo vita ». Un inverno si è ammalato, e allora ha capito che doveva cambiare. Adesso vive in un paese di mille abitanti, lavora da casa la mattina e coltiva un orto nel pomeriggio. « Guadagno meno, ma mi avanza tempo. » All'inizio i suoi genitori non capivano; adesso vengono ogni mese. « Ti penti di qualcosa ? » gli chiede l'amica. « Di non averlo fatto prima ».", questions = listOf(Exercise(id = "it-listen-citta-paese-q1", kind = "choice", prompt = "Dove viveva Marco prima ?", options = listOf("A Milano", "In un paese", "A Roma", "In un ostello"), answers = listOf("A Milano"), explain = "Marco racconta perché ha lasciato Milano."), Exercise(id = "it-listen-citta-paese-q2", kind = "written", prompt = "Quante ore lavorava al giorno ?", options = listOf(), answers = listOf("undici ore", "11 ore", "undici"), explain = "Lavorava undici ore al giorno."), Exercise(id = "it-listen-citta-paese-q3", kind = "choice", prompt = "Cosa l'ha fatto cambiare ?", options = listOf("Si è ammalato", "Ha perso il lavoro", "Ha vinto alla lotteria", "Ha conosciuto qualcuno"), answers = listOf("Si è ammalato"), explain = "Un inverno si è ammalato, e allora ha capito."), Exercise(id = "it-listen-citta-paese-q4", kind = "choice", prompt = "Cosa fa nel pomeriggio adesso ?", options = listOf("Coltiva un orto", "Lavora più ore", "Viaggia ogni mese", "Studia"), answers = listOf("Coltiva un orto"), explain = "Lavora la mattina e coltiva un orto nel pomeriggio."), Exercise(id = "it-listen-citta-paese-q5", kind = "written", prompt = "Di cosa si pente Marco ?", options = listOf(), answers = listOf("di non averlo fatto prima", "non averlo fatto prima"), explain = "« Di non averlo fatto prima ».")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions")) }

object ListenData142 { val text = ListeningText(id = "it-listen-trattativa-tavolo", languageID = "it", title = "La trattativa del tavolo", level = "B2", topic = "negoziazione", unitID = "it-foundations-u7", text = "Su un'app di usato, Chiara vuole un tavolo di legno da 80 euro. « E se chiudessimo a 60 ? », propone. Il venditore rifiuta: « Solo se la ritiri oggi ». Chiara riflette: « Le darei 65 se aggiunge la sedia ». « Impossibile », ride lui, « ma le lascerei il tavolo a 70 e glielo salirei al piano ». Chiara non dubita: « Lo salirebbe da solo ? ». « Ho una carriola », risponde. « Affare fatto », dice lei, e aggiunge: « Se è bello come in foto, le lascio cinque stelle ».", questions = listOf(Exercise(id = "it-listen-trattativa-tavolo-q1", kind = "choice", prompt = "Quanto chiede il venditore ?", options = listOf("80 euro", "60 euro", "70 euro", "65 euro"), answers = listOf("80 euro"), explain = "Il tavolo costa 80 euro."), Exercise(id = "it-listen-trattativa-tavolo-q2", kind = "written", prompt = "Cosa propone Chiara all'inizio ?", options = listOf(), answers = listOf("60 euro", "sessanta euro", "chiudere a 60"), explain = "« E se chiudessimo a 60 ? »."), Exercise(id = "it-listen-trattativa-tavolo-q3", kind = "choice", prompt = "Che condizione mette il venditore ?", options = listOf("Ritirarla oggi", "Pagare in contanti", "Lasciare cinque stelle", "Tornare domani"), answers = listOf("Ritirarla oggi"), explain = "« Solo se la ritiri oggi »."), Exercise(id = "it-listen-trattativa-tavolo-q4", kind = "choice", prompt = "Cosa offre il venditore per 70 ?", options = listOf("Salire il tavolo al piano", "Aggiungere la sedia", "Scendere a 60", "Prestare la carriola"), answers = listOf("Salire il tavolo al piano"), explain = "« Glielo salirei al piano »."), Exercise(id = "it-listen-trattativa-tavolo-q5", kind = "written", prompt = "Cosa promette Chiara se il tavolo le piace ?", options = listOf(), answers = listOf("cinque stelle", "5 stelle", "una recensione di cinque stelle"), explain = "Cinque stelle.")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors")) }

object ListenData143 { val text = ListeningText(id = "it-listen-notizia-quartiere", languageID = "it", title = "La notizia del quartiere", level = "B2", topic = "notizie", unitID = "it-foundations-u8", text = "Al mercato, Giulia e Paolo commentano quello che si dice. « Si dice che pedonalizzeranno la via principale », racconta Giulia. « Di nuovo ? », ride Paolo. « La notizia che ho letto dice che partono in primavera ». Secondo il comune, sarebbe solo il sabato, ma i negozianti, il cui fatturato dipenderebbe dal turismo, sono già scesi in piazza. « È vero che il rumore calerebbe », ammette Paolo, « ma, e il parcheggio ? ». Giulia difende la misura: « Da un lato, più gente camminerebbe; dall'altro, gli autobus arriverebbero all'angolo ». Non la decidono, ma promettono di riparlarne quando uscirà il piano.", questions = listOf(Exercise(id = "it-listen-notizia-quartiere-q1", kind = "choice", prompt = "Cosa si dice della via principale ?", options = listOf("Che la pedonalizzeranno", "Che la allargheranno", "Che la chiuderanno", "Che cambierà nome"), answers = listOf("Che la pedonalizzeranno"), explain = "« Si dice che pedonalizzeranno la via principale »."), Exercise(id = "it-listen-notizia-quartiere-q2", kind = "written", prompt = "Quando partirebbe ?", options = listOf(), answers = listOf("in primavera", "primavera"), explain = "« La notizia che ho letto dice che partono in primavera »."), Exercise(id = "it-listen-notizia-quartiere-q3", kind = "choice", prompt = "Cosa dice il comune ?", options = listOf("Solo il sabato", "Tutti i giorni", "Solo d'estate", "I festivi"), answers = listOf("Solo il sabato"), explain = "Secondo il comune, sarebbe solo il sabato."), Exercise(id = "it-listen-notizia-quartiere-q4", kind = "choice", prompt = "Chi è sceso in piazza ?", options = listOf("I negozianti", "I residenti", "I tassisti", "Il comune"), answers = listOf("I negozianti"), explain = "I negozianti sono già scesi in piazza."), Exercise(id = "it-listen-notizia-quartiere-q5", kind = "written", prompt = "Cosa promettono Giulia e Paolo ?", options = listOf(), answers = listOf("di riparlarne", "ripdirlo", "riparlarne quando uscira il piano"), explain = "Promettono di riparlarne quando uscirà il piano.")), skills = listOf("listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors")) }

object ListenData144 { val text = ListeningText(id = "it-listen-dibattito-radio", languageID = "it", title = "Dibattito alla radio", level = "C1", topic = "dibattito", unitID = "it-foundations-u9", text = "Studi aperti, torniamo sulla viabilità. Con noi Mara Bianchi, urbanista, e Sandro Lenzi, portavoce dei commercianti. Mara, la parola è Sua. « Grazie. A mio avviso, limitare il traffico non è una battaglia ideologica: è una questione di salute pubblica. In un certo senso, tutti ne guadagnerebbero, commercianti compresi ». Lenzi interviene: « Permettetemi di dissentire. È vero che il centro va ridisegnato, però senza parcheggi di scambio qualsiasi misura resta, per così dire, di facciata ». La conduttrice lancia i dati: « Secondo il comune, gli spostamenti a piedi sono cresciuti del dodici per cento ». « Proprio per questo », replica Bianchi, « conviene procedere per tappe ». « Purché le tappe non diventino eterne », chiude Lenzi.", questions = listOf(Exercise(id = "it-listen-dibattito-radio-q1", kind = "choice", prompt = "Qual è la posizione di Mara Bianchi?", options = listOf("Limitare il traffico è una questione di salute", "Una battaglia puramente ideologica", "Il traffico non è un problema", "Serve fermare ogni misura"), answers = listOf("Limitare il traffico è una questione di salute"), explain = "« Non è una battaglia ideologica: è una questione di salute pubblica »."), Exercise(id = "it-listen-dibattito-radio-q2", kind = "choice", prompt = "Come definisce Lenzi una misura senza parcheggi di scambio?", options = listOf("Di facciata", "Eterna", "Salutare", "Impossibile"), answers = listOf("Di facciata"), explain = "« Resta, per così dire, di facciata »."), Exercise(id = "it-listen-dibattito-radio-q3", kind = "written", prompt = "Di quanto sono cresciuti gli spostamenti a piedi?", options = listOf(), answers = listOf("12%", "12 %", "del dodici per cento", "dodici per cento"), explain = "Cresciuti del dodici per cento."), Exercise(id = "it-listen-dibattito-radio-q4", kind = "choice", prompt = "Che metodo propone Bianchi?", options = listOf("Procedere per tappe", "Un referendum immediato", "Chiudere tutto subito", "Attendere i fondi"), answers = listOf("Procedere per tappe"), explain = "« Conviene procedere per tappe »."), Exercise(id = "it-listen-dibattito-radio-q5", kind = "written", prompt = "Con quale condizione Lenzi accetta le tappe?", options = listOf(), answers = listOf("purche non diventino eterne", "purché le tappe non diventino eterne", "purché non diventino eterne"), explain = "« Purché le tappe non diventino eterne »."), Exercise(id = "it-listen-dibattito-radio-q6", kind = "choice", prompt = "Che funzione ha « Permettetemi di dissentire »?", options = listOf("Marcare il disaccordo in forma cortese", "Chiedere un rinvio", "Aprire l'intervento", "Chiudere il dibattito"), answers = listOf("Marcare il disaccordo in forma cortese"), explain = "Disaccordo esplicito ma cortese.")), skills = listOf("listening:connected-speech", "listening:inference", "function:express-opinion", "grammar:connectors")) }

object ListenData145 { val text = ListeningText(id = "it-listen-intervento-chiavi", languageID = "it", title = "Intervento in riunione", level = "C1", topic = "lavoro", unitID = "it-foundations-u9", text = "Ultimo punto dell'ordine del giorno: il passaggio del progetto Lumen al team di Milano. Chiara Sarti ha cinque minuti. « Per iniziare, una rassicurazione: nessun cliente resterà senza referente. Il dossier che ho preparato contiene contratti, scadenze e contatti; pertanto chi subentrerà avrà tutto in mano. Venendo ai rischi, ne vedo due: la gara della biblioteca, che scade a marzo, e il rinnovo del fornitore di stampa, per così dire ancora a metà trattativa. In sintesi, il progetto è sano ma esige continuità. Per concludere, due richieste: nominare entro venerdì il nuovo referente e, se possibile, tenere il cliente pilota nel nostro gruppo. Sono certa che, sotto certi aspetti, il cambio sarà un'opportunità. Grazie dell'attenzione ».", questions = listOf(Exercise(id = "it-listen-intervento-chiavi-q1", kind = "choice", prompt = "Cosa garantisce Chiara per iniziare?", options = listOf("Nessun cliente resterà senza referente", "Il progetto sarà rinnovato", "La gara sarà vinta", "Il budget sarà aumentato"), answers = listOf("Nessun cliente resterà senza referente"), explain = "« Nessun cliente resterà senza referente »."), Exercise(id = "it-listen-intervento-chiavi-q2", kind = "written", prompt = "Quando scade la gara della biblioteca?", options = listOf(), answers = listOf("a marzo", "marzo", "in marzo"), explain = "Scade a marzo."), Exercise(id = "it-listen-intervento-chiavi-q3", kind = "choice", prompt = "Com'è la trattativa col fornitore di stampa?", options = listOf("Ancora a metà", "Conclusa", "Annullata", "Rinviata a settembre"), answers = listOf("Ancora a metà"), explain = "« Per così dire ancora a metà trattativa »."), Exercise(id = "it-listen-intervento-chiavi-q4", kind = "written", prompt = "Che cosa chiede entro venerdì?", options = listOf(), answers = listOf("nominare il nuovo referente", "nominare entro venerdì il nuovo referente", "nominare entro venerdi il nuovo referente"), explain = "Chiede di nominare il nuovo referente."), Exercise(id = "it-listen-intervento-chiavi-q5", kind = "choice", prompt = "Che funzione ha « Venendo ai rischi »?", options = listOf("Annuncia il cambio di punto", "Chiude l'intervento", "Sintetizza i contenuti", "Ringrazia i colleghi"), answers = listOf("Annuncia il cambio di punto"), explain = "Transizione annunciata verso un nuovo punto."), Exercise(id = "it-listen-intervento-chiavi-q6", kind = "choice", prompt = "Com'è il progetto in sintesi?", options = listOf("Sano ma esige continuità", "Chiuso e archiviato", "In perdita", "Sospeso"), answers = listOf("Sano ma esige continuità"), explain = "« Il progetto è sano ma esige continuità ».")), skills = listOf("listening:detail", "listening:gist", "vocab:work", "grammar:connectors")) }

object ListenData146 { val text = ListeningText(id = "it-listen-podcast-sfumature", languageID = "it", title = "Podcast: l'arte della sfumatura", level = "C1", topic = "linguaggio", unitID = "it-foundations-u9", text = "Benvenuti a « Parole al lavoro », la puntata in cui ascoltiamo come si suona un'opinione in ufficio. Vi racconto un episodio vissuto. In una riunione, il nuovo responsabile avrebbe potuto dire: « Questa idea non funziona ». Invece ha detto: « A mio avviso, qui c'è ancora lavoro da fare ». Stesso fondo, musica diversa: nessuno si è messo sulla difensiva e la discussione è proseguita. Notate le mosse: prima la sfumatura, poi il punto, infine la proposta. « In un certo senso », « per così dire », « direi che » non sono giri di parole: sono la cortesia della precisione. Per così dire, naturalmente. Nella prossima puntata analizziamo il linguaggio delle email: ci vediamo lì.", questions = listOf(Exercise(id = "it-listen-podcast-sfumature-q1", kind = "choice", prompt = "Che alternativa ha proposto il responsabile al giudizio netto?", options = listOf("Qui c'è ancora lavoro da fare", "L'idea è inutile", "Cambiate subito team", "Non dico niente"), answers = listOf("Qui c'è ancora lavoro da fare"), explain = "« A mio avviso, qui c'è ancora lavoro da fare »."), Exercise(id = "it-listen-podcast-sfumature-q2", kind = "choice", prompt = "Che effetto ha prodotto la formula sfumata?", options = listOf("Nessuno si è messo sulla difensiva", "La riunione è finita prima", "Il capo si è arrabbiato", "L'idea è stata approvata subito"), answers = listOf("Nessuno si è messo sulla difensiva"), explain = "Nessuno in difesa, la discussione è proseguita."), Exercise(id = "it-listen-podcast-sfumature-q3", kind = "written", prompt = "Quale sequenza indica l'autore per costruire un rilievo?", options = listOf(), answers = listOf("prima la sfumatura poi il punto infine la proposta", "sfumatura punto proposta", "la sfumatura poi il punto e la proposta"), explain = "Prima la sfumatura, poi il punto, infine la proposta."), Exercise(id = "it-listen-podcast-sfumature-q4", kind = "choice", prompt = "Come definisce l'autore locuzioni come « direi che »?", options = listOf("La cortesia della precisione", "Un giro di parole da evitare", "Un segno di insicurezza", "Un tratto regionale"), answers = listOf("La cortesia della precisione"), explain = "« Non sono giri di parole: sono la cortesia della precisione »."), Exercise(id = "it-listen-podcast-sfumature-q5", kind = "choice", prompt = "Di cosa parlerà la prossima puntata?", options = listOf("Del linguaggio delle email", "Delle riunioni efficienti", "Del telegiornale", "Del nuovo responsabile"), answers = listOf("Del linguaggio delle email"), explain = "« Analizziamo il linguaggio delle email »."), Exercise(id = "it-listen-podcast-sfumature-q6", kind = "choice", prompt = "Che registro ha questo podcast?", options = listOf("Divulgativo e colloquiale", "Legale", "Burocratico", "Accademico e freddo"), answers = listOf("Divulgativo e colloquiale"), explain = "Tono divulgativo, con episodi vissuti e battute.")), skills = listOf("listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion")) }

object ListenData147 { val text = ListeningText(id = "it-listen-appartamento-nuovo", languageID = "it", title = "Un appartamento nuovo", level = "A1", topic = "casa", unitID = "it-foundations-u10", text = "Anna ha un appartamento nuovo. « È piccolo, ma mi piace. La porta è gialla. C'è una cucina piccola e luminosa: ci sono un tavolo, due sedie e un frigo nuovo. Il soggiorno è grande: c'è un divano blu e ci sono due finestre. La camera da letto è tranquilla: il letto è sotto la finestra e c'è un armadio bianco. Il bagno è piccolo ma pulito. Il mio gatto dorme sul divano. La mia casa è piccola, ma è la mia casa. »", questions = listOf(Exercise(id = "it-listen-appartamento-nuovo-q1", kind = "choice", prompt = "Com'è l'appartamento ?", options = listOf("Piccolo, ma ad Anna piace", "Grande e moderno", "Molto costoso", "Senza cucina"), answers = listOf("Piccolo, ma ad Anna piace"), explain = "« È piccolo, ma mi piace »."), Exercise(id = "it-listen-appartamento-nuovo-q2", kind = "choice", prompt = "Cosa c'è nella cucina ?", options = listOf("Un tavolo, due sedie e un frigo", "Un divano blu", "Un armadio bianco", "Niente"), answers = listOf("Un tavolo, due sedie e un frigo"), explain = "« Ci sono un tavolo, due sedie e un frigo nuovo »."), Exercise(id = "it-listen-appartamento-nuovo-q3", kind = "written", prompt = "Dove sta il letto ?", options = listOf(), answers = listOf("sotto la finestra", "sotto la finestra della camera"), explain = "« Il letto è sotto la finestra »."), Exercise(id = "it-listen-appartamento-nuovo-q4", kind = "choice", prompt = "Com'è il bagno ?", options = listOf("Piccolo ma pulito", "Grande e luminoso", "Giallo", "Non c'è"), answers = listOf("Piccolo ma pulito"), explain = "« Il bagno è piccolo ma pulito »."), Exercise(id = "it-listen-appartamento-nuovo-q5", kind = "written", prompt = "Dove dorme il gatto ?", options = listOf(), answers = listOf("sul divano", "sopra il divano", "sul divano blu"), explain = "« Il mio gatto dorme sul divano »."), Exercise(id = "it-listen-appartamento-nuovo-q6", kind = "choice", prompt = "Quante finestre ci sono nel soggiorno ?", options = listOf("Due", "Una", "Tre", "Nessuna"), answers = listOf("Due"), explain = "« Ci sono due finestre ».")), skills = listOf("listening:gist", "listening:detail", "grammar:there-is-are", "grammar:prepositions-place", "vocab:home")) }

object ListenData148 { val text = ListeningText(id = "it-listen-passeggiata-quartiere", languageID = "it", title = "Una passeggiata nel quartiere", level = "A1", topic = "quartiere", unitID = "it-foundations-u11", text = "Marco è nuovo nel quartiere. Oggi fa una passeggiata. « Scusi, c'è un supermercato qui vicino ? » chiede a una signora. « Sì, vada sempre dritto e alla piazza giri a sinistra. È lì, accanto alla farmacia ». Marco cammina cinque minuti. Il supermercato è piccolo ma c'è di tutto. Dopo entra nel parco: ci sono alberi, panchine e un chiosco. Torna a casa con le mele e due arance. Il suo quartiere è tranquillo e lui è contento.", questions = listOf(Exercise(id = "it-listen-passeggiata-quartiere-q1", kind = "choice", prompt = "Cosa chiede Marco alla signora ?", options = listOf("Dov'è un supermercato", "L'ora", "Il suo nome", "Il prezzo delle mele"), answers = listOf("Dov'è un supermercato"), explain = "« Scusi, c'è un supermercato qui vicino ? »."), Exercise(id = "it-listen-passeggiata-quartiere-q2", kind = "written", prompt = "Che cosa deve fare alla piazza ?", options = listOf(), answers = listOf("giri a sinistra", "gira a sinistra", "andare a sinistra"), explain = "« Alla piazza giri a sinistra »."), Exercise(id = "it-listen-passeggiata-quartiere-q3", kind = "choice", prompt = "Dov'è il supermercato ?", options = listOf("Accanto alla farmacia", "Dietro il parco", "In piazza", "Vicino alla stazione"), answers = listOf("Accanto alla farmacia"), explain = "« È lì, accanto alla farmacia »."), Exercise(id = "it-listen-passeggiata-quartiere-q4", kind = "written", prompt = "Quanto cammina Marco ?", options = listOf(), answers = listOf("cinque minuti", "5 minuti"), explain = "« Marco cammina cinque minuti »."), Exercise(id = "it-listen-passeggiata-quartiere-q5", kind = "choice", prompt = "Cosa c'è nel parco ?", options = listOf("Alberi, panchine e un chiosco", "Un supermercato", "Una farmacia", "Niente"), answers = listOf("Alberi, panchine e un chiosco"), explain = "« Ci sono alberi, panchine e un chiosco »."), Exercise(id = "it-listen-passeggiata-quartiere-q6", kind = "written", prompt = "Com'è il quartiere ?", options = listOf(), answers = listOf("tranquillo", "è tranquillo", "e tranquillo"), explain = "« Il suo quartiere è tranquillo ».")), skills = listOf("listening:gist", "listening:detail", "grammar:prepositions-place", "function:ask-for-directions", "vocab:town")) }

object ListenData149 { val text = ListeningText(id = "it-listen-chiamata-nonna", languageID = "it", title = "Una chiamata alla nonna", level = "A1", topic = "famiglia", unitID = "it-foundations-u12", text = "Luca telefona alla nonna. « Pronto, nonna ! Sono Luca. C'è il nonno ? » « Sì, è in giardino con il gatto. E tu, come va ? » « Bene, nonna. La mattina lavoro e la sera cucino sempre con Sara. » « Molto bene ! E Giulia, com'è ? » « Giulia è simpatica, ma è un po' timida. Domenica vengo a trovare voi. » « D'accordo, a domenica ! Ora chiamo il nonno. »", questions = listOf(Exercise(id = "it-listen-chiamata-nonna-q1", kind = "choice", prompt = "Chi telefona alla nonna ?", options = listOf("Luca", "Marco", "Il nonno", "Sara"), answers = listOf("Luca"), explain = "« Pronto, nonna ! Sono Luca »."), Exercise(id = "it-listen-chiamata-nonna-q2", kind = "choice", prompt = "Dov'è il nonno ?", options = listOf("In giardino", "Al lavoro", "In cucina", "A letto"), answers = listOf("In giardino"), explain = "« Sì, è in giardino con il gatto »."), Exercise(id = "it-listen-chiamata-nonna-q3", kind = "written", prompt = "Cosa fa Luca la sera, sempre ?", options = listOf(), answers = listOf("cucino con Sara", "cucina con Sara", "cucino"), explain = "« La sera cucino sempre con Sara »."), Exercise(id = "it-listen-chiamata-nonna-q4", kind = "choice", prompt = "Com'è Giulia ?", options = listOf("Simpatica ma un po' timida", "Timida e seria", "Sempre allegra", "Molto lavoratrice"), answers = listOf("Simpatica ma un po' timida"), explain = "« Giulia è simpatica, ma è un po' timida »."), Exercise(id = "it-listen-chiamata-nonna-q5", kind = "written", prompt = "Quando va dai nonni Luca ?", options = listOf(), answers = listOf("Domenica", "domenica", "La domenica"), explain = "« Domenica vengo a trovare voi »."), Exercise(id = "it-listen-chiamata-nonna-q6", kind = "choice", prompt = "Cosa dice la nonna alla fine ?", options = listOf("Richiama il nonno", "Esce con il gatto", "Cucina con Sara", "Guarda la TV"), answers = listOf("Richiama il nonno"), explain = "« Ora chiamo il nonno ».")), skills = listOf("listening:gist", "listening:detail", "vocab:family", "vocab:daily-routine", "grammar:frequency-adverbs")) }

object ListenData150 { val text = ListeningText(id = "it-listen-weekend-piovoso", languageID = "it", title = "Un weekend piovoso", level = "A1", topic = "meteo", unitID = "it-foundations-u13", text = "È sabato e piove. Anna guarda la finestra: che tempo fa ? Fa freddo e piove ancora. Marco telefona: « Che noia, non usciamo ! » « D'accordo, » dice Anna. « Di solito il sabato corro al parco, ma oggi no. Quando piove, qualche volta leggo. E tu ? » « Io guardo spesso dei film, » risponde Marco. « Domenica fa bel tempo: andiamo al parco ! »", questions = listOf(Exercise(id = "it-listen-weekend-piovoso-q1", kind = "choice", prompt = "Che tempo fa sabato ?", options = listOf("Piove e fa freddo", "C'è il sole", "Nevica", "Fa caldo"), answers = listOf("Piove e fa freddo"), explain = "« Fa freddo e piove ancora »."), Exercise(id = "it-listen-weekend-piovoso-q2", kind = "written", prompt = "Cosa fa di solito Anna il sabato ?", options = listOf(), answers = listOf("corro al parco", "corre al parco", "correre al parco"), explain = "« Di solito il sabato corro al parco »."), Exercise(id = "it-listen-weekend-piovoso-q3", kind = "choice", prompt = "Cosa fa Anna qualche volta quando piove ?", options = listOf("Legge", "Corre", "Guarda i film", "Dorme"), answers = listOf("Legge"), explain = "« Quando piove, qualche volta leggo »."), Exercise(id = "it-listen-weekend-piovoso-q4", kind = "written", prompt = "Cosa fa spesso Marco ?", options = listOf(), answers = listOf("guardo dei film", "guarda dei film", "guarda film"), explain = "« Io guardo spesso dei film »."), Exercise(id = "it-listen-weekend-piovoso-q5", kind = "choice", prompt = "Cosa decidono per domenica ?", options = listOf("Andare al parco", "Stare a casa", "Andare al mare", "Cucinare"), answers = listOf("Andare al parco"), explain = "« Domenica fa bel tempo: andiamo al parco »."), Exercise(id = "it-listen-weekend-piovoso-q6", kind = "choice", prompt = "Perché Anna non corre al parco oggi ?", options = listOf("Perché piove", "Perché lavora", "Perché legge", "Perché è stanca"), answers = listOf("Perché piove"), explain = "Oggi no: piove e fa freddo.")), skills = listOf("listening:gist", "listening:detail", "vocab:weather", "vocab:daily-routine", "grammar:frequency-adverbs", "function:talk-about-weather")) }

object ListenData151 { val text = ListeningText(id = "it-listen-metro-perso", languageID = "it", title = "Perso in metro", level = "A1", topic = "trasporti", unitID = "it-foundations-u14", text = "Marco va al lavoro in metro. Ogni mattina prende la metro alle otto e un quarto alla stazione Garibaldi. Stamattina guarda i messaggi sul telefono e non sente l'annuncio: « Prossima fermata: Duomo ». Marco non scende e la metro parte. Arriva a San Babila e chiede: « Scusi, come vado al Duomo ? » « Facile: prendi la metro in direzione opposta, due fermate e sei a posto ! » Marco prende l'altra metro ed è in ufficio alle nove e dieci. « Scusate il ritardo ! »", questions = listOf(Exercise(id = "it-listen-metro-perso-q1", kind = "choice", prompt = "Come va al lavoro Marco ?", options = listOf("In metro", "A piedi", "In bici", "In treno"), answers = listOf("In metro"), explain = "« Marco va al lavoro in metro »."), Exercise(id = "it-listen-metro-perso-q2", kind = "choice", prompt = "A che ora prende la metro ?", options = listOf("Alle otto e un quarto", "Alle otto e mezza", "Alle nove e dieci", "Alle sette"), answers = listOf("Alle otto e un quarto"), explain = "« Prende la metro alle otto e un quarto »."), Exercise(id = "it-listen-metro-perso-q3", kind = "written", prompt = "Perché non scende al Duomo ?", options = listOf(), answers = listOf("Guarda i messaggi sul telefono", "Perché guarda il telefono", "Guarda il telefono", "Perche guarda il telefono"), explain = "« Guarda i messaggi sul telefono e non sente l'annuncio »."), Exercise(id = "it-listen-metro-perso-q4", kind = "written", prompt = "A che ora è in ufficio ?", options = listOf(), answers = listOf("Alle nove e dieci", "Nove e dieci", "Alle 9:10"), explain = "« È in ufficio alle nove e dieci »."), Exercise(id = "it-listen-metro-perso-q5", kind = "choice", prompt = "Quante fermate per tornare al Duomo ?", options = listOf("Due", "Tre", "Quattro", "Una"), answers = listOf("Due"), explain = "« Due fermate e sei a posto »."), Exercise(id = "it-listen-metro-perso-q6", kind = "choice", prompt = "Cosa dice Marco in ufficio ?", options = listOf("Scusate il ritardo", "Grazie mille", "A domani", "Buongiorno"), answers = listOf("Scusate il ritardo"), explain = "« Scusate il ritardo ! ».")), skills = listOf("listening:gist", "listening:detail", "vocab:transport", "function:tell-time")) }

object ListenData152 { val text = ListeningText(id = "it-listen-farmacia-sabato", languageID = "it", title = "Sabato in farmacia", level = "A1", topic = "salute", unitID = "it-foundations-u15", text = "È sabato mattina. Anna non si sente bene: ha la febbre e la testa le fa male. In casa non ci sono medicine: Anna non le compra mai. Va in farmacia. « Buongiorno, ho la febbre e ho mal di testa. » « Da quanti giorni ? » « Da due giorni. » « Ecco questo: due compresse al giorno, una la mattina e una la sera. Bevi molta acqua. » « Quanto costano ? » « Sette euro. » « Grazie, buona giornata ! »", questions = listOf(Exercise(id = "it-listen-farmacia-sabato-q1", kind = "choice", prompt = "Come si sente Anna ?", options = listOf("Ha la febbre e mal di testa", "Ha mal di pancia", "Ha la tosse", "È solo stanca"), answers = listOf("Ha la febbre e mal di testa"), explain = "« Ho la febbre e ho mal di testa »."), Exercise(id = "it-listen-farmacia-sabato-q2", kind = "written", prompt = "Quante compresse al giorno prende Anna ?", options = listOf(), answers = listOf("Due", "2", "Due compresse"), explain = "« Due compresse al giorno »."), Exercise(id = "it-listen-farmacia-sabato-q3", kind = "choice", prompt = "Quando prende le compresse ?", options = listOf("La mattina e la sera", "Solo la mattina", "Solo la sera", "A mezzogiorno"), answers = listOf("La mattina e la sera"), explain = "« Una la mattina e una la sera »."), Exercise(id = "it-listen-farmacia-sabato-q4", kind = "written", prompt = "Quanto costano le medicine ?", options = listOf(), answers = listOf("Sette euro", "7 euro", "Sette"), explain = "« Sette euro »."), Exercise(id = "it-listen-farmacia-sabato-q5", kind = "choice", prompt = "Cosa non fa mai Anna ?", options = listOf("Compra le medicine", "Beve l'acqua", "Va in farmacia", "Dorme otto ore"), answers = listOf("Compra le medicine"), explain = "« Anna non le compra mai »."), Exercise(id = "it-listen-farmacia-sabato-q6", kind = "choice", prompt = "Che altro deve bere Anna ?", options = listOf("Molta acqua", "Il caffè", "Il latte", "Il tè freddo"), answers = listOf("Molta acqua"), explain = "« Bevi anche molta acqua ».")), skills = listOf("listening:gist", "listening:detail", "vocab:health", "grammar:frequency-adverbs")) }

object ListenData153 { val text = ListeningText(id = "it-listen-cena-sorpresa", languageID = "it", title = "Una cena a sorpresa", level = "A1", topic = "ristorante", unitID = "it-foundations-u16", text = "È sabato sera. Marco porta Anna al ristorante: è il suo compleanno, la cena è una sorpresa. Il cameriere chiede: « Che cosa prende ? ». Marco prende le tagliatelle, Anna preferisce la pizza. Per bere ordinano un’acqua naturale e un vino rosso. Il cameriere porta anche il tiramisù, il dolce preferito di Anna. Marco chiede il conto: « Quanto fa ? » « Venticinque euro. » Paga in contanti e lascia la mancia: « Tenga il resto ! ». Anna sorride: « Che bella sorpresa ! »", questions = listOf(Exercise(id = "it-listen-cena-sorpresa-q1", kind = "choice", prompt = "Dove sono Marco e Anna ?", options = listOf("Al ristorante", "A casa", "Al bar", "In pizzeria"), answers = listOf("Al ristorante"), explain = "Marco porta Anna al ristorante."), Exercise(id = "it-listen-cena-sorpresa-q2", kind = "choice", prompt = "Cosa prende Anna ?", options = listOf("La pizza", "Le tagliatelle", "Il pesce", "Il vino"), answers = listOf("La pizza"), explain = "Anna preferisce la pizza."), Exercise(id = "it-listen-cena-sorpresa-q3", kind = "written", prompt = "Per bere, cosa ordinano ?", options = listOf(), answers = listOf("un'acqua naturale e un vino rosso", "acqua naturale e vino rosso", "acqua e vino rosso"), explain = "Ordinano un’acqua naturale e un vino rosso."), Exercise(id = "it-listen-cena-sorpresa-q4", kind = "choice", prompt = "Quanto fa il conto ?", options = listOf("Venticinque euro", "Quindici euro", "Trenta euro", "Cinque euro"), answers = listOf("Venticinque euro"), explain = "« Quanto fa ? » « Venticinque euro. »"), Exercise(id = "it-listen-cena-sorpresa-q5", kind = "choice", prompt = "Come paga Marco ?", options = listOf("In contanti", "Con la carta", "Con il telefono", "Non paga"), answers = listOf("In contanti"), explain = "Paga in contanti e lascia la mancia."), Exercise(id = "it-listen-cena-sorpresa-q6", kind = "choice", prompt = "Perché Marco porta Anna al ristorante ?", options = listOf("È il compleanno di Anna", "È il compleanno di Marco", "È sabato", "Anna invita Marco"), answers = listOf("È il compleanno di Anna"), explain = "È il suo compleanno: la cena è una sorpresa.")), skills = listOf("listening:gist", "listening:detail", "vocab:food", "function:order-food")) }

object ListenData154 { val text = ListeningText(id = "it-listen-piano-compleanno", languageID = "it", title = "Il piano per il compleanno", level = "A2", topic = "inviti", unitID = "it-foundations-u17", text = "Sabato è il compleanno di Giulia, e lei non sa niente. Sara chiama Marco per organizzare la sorpresa. « Cosa le andiamo a regalare ? » chiede Marco. « Le piace la fotografia: vado a cercare un libro di foto », risponde Sara. « Io vado a preparare la torta: al cioccolato, la sua preferita. » « Perfetto. E la festa ? » « È una sorpresa: alle otto, da Luca. Io porto i fiori, tu la musica. » « D’accordo. Peccato: sabato lavoro fino alle sei. » « Nessun problema: la festa comincia dopo. » « Va bene. Sarà una bella festa ! »", questions = listOf(Exercise(id = "it-listen-piano-compleanno-q1", kind = "choice", prompt = "Di chi è il compleanno ?", options = listOf("Di Giulia", "Di Sara", "Di Marco", "Di Luca"), answers = listOf("Di Giulia"), explain = "Sabato è il compleanno di Giulia."), Exercise(id = "it-listen-piano-compleanno-q2", kind = "choice", prompt = "Cosa va a cercare Sara ?", options = listOf("Un libro di foto", "Una torta", "I fiori", "La musica"), answers = listOf("Un libro di foto"), explain = "Le piace la fotografia: vado a cercare un libro di foto."), Exercise(id = "it-listen-piano-compleanno-q3", kind = "written", prompt = "Che torta va a preparare Marco ?", options = listOf(), answers = listOf("al cioccolato", "torta al cioccolato", "di cioccolato"), explain = "Vado a preparare la torta: al cioccolato."), Exercise(id = "it-listen-piano-compleanno-q4", kind = "choice", prompt = "A che ora è la festa ?", options = listOf("Alle otto", "Alle nove", "Alle sette", "Alle dieci"), answers = listOf("Alle otto"), explain = "È una sorpresa: alle otto, da Luca."), Exercise(id = "it-listen-piano-compleanno-q5", kind = "choice", prompt = "Dov’è la festa ?", options = listOf("Da Luca", "Da Sara", "Da Marco", "A casa di Giulia"), answers = listOf("Da Luca"), explain = "Alle otto, da Luca."), Exercise(id = "it-listen-piano-compleanno-q6", kind = "written", prompt = "Chi porta i fiori ?", options = listOf(), answers = listOf("sara", "sara li porta"), explain = "« Io porto i fiori », risponde Sara.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to", "function:make-suggestions")) }

object ListenData155 { val text = ListeningText(id = "it-listen-aneddoto-estate", languageID = "it", title = "L'aneddoto dell'estate", level = "B1", topic = "racconti", unitID = "it-foundations-u18", text = "Al bar, Martina racconta l’aneddoto dell’estate. « Quest’estate, in Sardegna, è successa una cosa incredibile. Prima ho perso il traghetto della sera, poi ho dormito in auto, al campeggio. All’improvviso è arrivato un ragazzo con una torcia: si è scoperto che era il gestore. Mi ha offerto un posto nella tavola calda… » « Non mi dire ! » « E poi sono rimasta una settimana: ho lavorato, ho nuotato e ho fatto amicizia con sua sorella. » « E poi ? Sei tornata a casa ? » « Certo, ma meno male che il traghetto è ripartito: l’auto non partiva più ! » Martina ride: « Che disastro, ma che bella estate ».", questions = listOf(Exercise(id = "it-listen-aneddoto-estate-q1", kind = "choice", prompt = "Cosa è successo prima ?", options = listOf("Ha perso il traghetto", "Ha dormito in auto", "Ha fatto amicizia", "È rimasta una settimana"), answers = listOf("Ha perso il traghetto"), explain = "« Prima ho perso il traghetto della sera »."), Exercise(id = "it-listen-aneddoto-estate-q2", kind = "written", prompt = "Dove ha dormito la prima notte ?", options = listOf(), answers = listOf("in auto", "nella sua auto", "in macchina"), explain = "Poi ho dormito in auto, al campeggio."), Exercise(id = "it-listen-aneddoto-estate-q3", kind = "choice", prompt = "Chi è il ragazzo con la torcia ?", options = listOf("Il gestore del campeggio", "Un turista", "Un suo amico", "Un poliziotto"), answers = listOf("Il gestore del campeggio"), explain = "Si è scoperto che era il gestore."), Exercise(id = "it-listen-aneddoto-estate-q4", kind = "choice", prompt = "Quanto è rimasta in Sardegna ?", options = listOf("Una settimana", "Un mese", "Due giorni", "Tutta l’estate"), answers = listOf("Una settimana"), explain = "« Sono rimasta una settimana »."), Exercise(id = "it-listen-aneddoto-estate-q5", kind = "choice", prompt = "Com’è finita l’estate, per Martina ?", options = listOf("Un disastro, ma bella", "Terribile e noiosa", "Da dimenticare", "Solo lavoro"), answers = listOf("Un disastro, ma bella"), explain = "« Che disastro, ma che bella estate »."), Exercise(id = "it-listen-aneddoto-estate-q6", kind = "choice", prompt = "Che reazione ha l’amico durante la storia ?", options = listOf("Sorpresa e curiosità", "Noia", "Paura", "Delusione"), answers = listOf("Sorpresa e curiosità"), explain = "« Non mi dire ! » e « E poi ? » chiedono il seguito.")), skills = listOf("listening:inference", "listening:detail", "grammar:past-simple-irregular", "grammar:connectors")) }

object ListenData156 { val text = ListeningText(id = "it-listen-dibattito-tatto", languageID = "it", title = "Il dibattito con tatto", level = "C1", topic = "opinioni", unitID = "it-foundations-u9", text = "Apertura in studio: la questione del ritorno in ufficio. Con noi Elena Ricci, responsabile delle risorse umane, e Tommaso Galli, delegato dei dipendenti. Signora Ricci, Lei propone tre giorni in presenza. « Sì. Capisco il punto di chi ama la casa, però la collaborazione si impara di persona: i nuovi, in particolare, si formano meglio in ufficio ». Galli dissentisce con tatto: « Pur condividendo l’obiettivo, i dati del settore dicono altro: la produttività non è calata. Sono d’accordo in parte sulla formazione; quanto al resto, preferisco fidarmi dei team ». Ricci conclude: « Proviamo allora con due giorni, e tra sei mesi valutiamo insieme ». « Su questo », risponde Galli, « troviamo subito un punto comune ».", questions = listOf(Exercise(id = "it-listen-dibattito-tatto-q1", kind = "choice", prompt = "Che proposta fa Ricci ?", options = listOf("Tre giorni in presenza", "Solo lavoro da casa", "Ritorno completo a tempo pieno", "Eliminare l’ufficio"), answers = listOf("Tre giorni in presenza"), explain = "« Lei propone tre giorni in presenza »."), Exercise(id = "it-listen-dibattito-tatto-q2", kind = "choice", prompt = "Chi, secondo Ricci, si forma meglio in ufficio ?", options = listOf("I nuovi assunti", "I dirigenti", "I team esperti", "I delegati"), answers = listOf("I nuovi assunti"), explain = "« I nuovi, in particolare, si formano meglio in ufficio »."), Exercise(id = "it-listen-dibattito-tatto-q3", kind = "written", prompt = "Che dicono i dati del settore, secondo Galli ?", options = listOf(), answers = listOf("la produttività non è calata", "la produttivita non e calata", "la produttivita non e calata"), explain = "« I dati del settore dicono altro: la produttività non è calata »."), Exercise(id = "it-listen-dibattito-tatto-q4", kind = "choice", prompt = "Su cosa Galli è d’accordo in parte ?", options = listOf("Sulla formazione", "Sui trasporti", "Sui computer", "Sui team"), answers = listOf("Sulla formazione"), explain = "« Sono d’accordo in parte sulla formazione »."), Exercise(id = "it-listen-dibattito-tatto-q5", kind = "written", prompt = "Che compromesso propone Ricci alla fine ?", options = listOf(), answers = listOf("due giorni", "provare con due giorni", "due giorni e valutiamo tra sei mesi"), explain = "« Proviamo allora con due giorni »."), Exercise(id = "it-listen-dibattito-tatto-q6", kind = "choice", prompt = "Che tono ha il dibattito ?", options = listOf("Cortese e costruttivo", "Aspro e velato", "Indifferente", "Umoristico"), answers = listOf("Cortese e costruttivo"), explain = "« Capisco il punto », « punto comune »: dissenso con tatto.")), skills = listOf("listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion")) }

object ListenData157 { val text = ListeningText(id = "it-listen-aperitivo-venerdi", languageID = "it", title = "L’aperitivo del venerdì", level = "A1", topic = "aperitivo", unitID = "it-foundations-u19", text = "È venerdì sera. Luca suona il citofono: è l’aperitivo da Sara. « Posso entrare ? » chiede Luca. « Certo, entra ! ». Luca entra e mette sul tavolo una bottiglia di vino. « Grazie ! Prendi un caffè ? ». « Volentieri ! ». Sul tavolo ci sono olive e biscotti. Parlano del weekend. Alle nove Luca guarda l’orologio: « È tardi, devo andare. Grazie per l’aperitivo ! ». « Grazie a te per il vino ! A presto ! ». « Ciao, alla prossima ! ».", questions = listOf(Exercise(id = "it-listen-aperitivo-venerdi-q1", kind = "choice", prompt = "Chi va da Sara ?", options = listOf("Luca", "Marco", "Anna", "Paolo"), answers = listOf("Luca"), explain = "Luca suona il citofono: è l’aperitivo da Sara."), Exercise(id = "it-listen-aperitivo-venerdi-q2", kind = "written", prompt = "Cosa mette Luca sul tavolo ?", options = listOf(), answers = listOf("una bottiglia di vino", "una bottiglia di vino rosso"), explain = "Luca mette sul tavolo una bottiglia di vino."), Exercise(id = "it-listen-aperitivo-venerdi-q3", kind = "choice", prompt = "Cosa offre Sara a Luca ?", options = listOf("Un caffè", "Un tè", "Un succo", "Una birra"), answers = listOf("Un caffè"), explain = "« Prendi un caffè ? » « Volentieri ! »."), Exercise(id = "it-listen-aperitivo-venerdi-q4", kind = "choice", prompt = "Cosa c’è anche sul tavolo ?", options = listOf("Olive e biscotti", "Torta e frutta", "Vino e formaggio", "Panini"), answers = listOf("Olive e biscotti"), explain = "Sul tavolo ci sono anche olive e biscotti."), Exercise(id = "it-listen-aperitivo-venerdi-q5", kind = "written", prompt = "Perché Luca deve andare ?", options = listOf(), answers = listOf("è tardi", "e tardi", "perché è tardi", "perche e tardi"), explain = "Alle nove: « È tardi, devo andare »."), Exercise(id = "it-listen-aperitivo-venerdi-q6", kind = "choice", prompt = "Come salutano alla fine ?", options = listOf("Alla prossima", "A domani", "Buonanotte", "A lunedì"), answers = listOf("Alla prossima"), explain = "« Ciao, alla prossima ! ».")), skills = listOf("listening:gist", "listening:detail", "vocab:social-expressions", "grammar:can")) }

object ListenData158 { val text = ListeningText(id = "it-listen-reclamo-fattura", languageID = "it", title = "Un reclamo al telefono", level = "A2", topic = "reclami", unitID = "it-foundations-u20", text = "Martedì Anna telefona al negozio. « Buongiorno, vorrei segnalare un problema: ho ricevuto la fattura sbagliata ». « Mi dispiace. Che cosa è successo ? ». « Ho comprato una stampante venerdì, ma nella fattura ci sono due stampanti. E la macchina non funziona bene: si è spenta due volte ». « Capisco. Devo chiedere scusa: c’è stato un errore nostro. Manda la fattura per email e mandiamo subito la fattura giusta. Per la stampante: può portarla in negozio ? ». « Certo, vengo domani mattina ». « Grazie per la pazienza. Buona giornata ! ».", questions = listOf(Exercise(id = "it-listen-reclamo-fattura-q1", kind = "choice", prompt = "Che problema segnala Anna ?", options = listOf("La fattura sbagliata", "Il ritardo della consegna", "Il prezzo alto", "Un computer rotto"), answers = listOf("La fattura sbagliata"), explain = "« Ho ricevuto la fattura sbagliata »."), Exercise(id = "it-listen-reclamo-fattura-q2", kind = "choice", prompt = "Quante stampanti ci sono nella fattura ?", options = listOf("Due", "Una", "Tre", "Nessuna"), answers = listOf("Due"), explain = "« Nella fattura ci sono due stampanti »."), Exercise(id = "it-listen-reclamo-fattura-q3", kind = "written", prompt = "Che cosa è successo alla stampante ?", options = listOf(), answers = listOf("si è spenta due volte", "si e spenta due volte"), explain = "« La macchina non funziona bene: si è spenta due volte »."), Exercise(id = "it-listen-reclamo-fattura-q4", kind = "written", prompt = "Che cosa deve mandare Anna per email ?", options = listOf(), answers = listOf("la fattura", "la fattura sbagliata"), explain = "« Manda la fattura per email »."), Exercise(id = "it-listen-reclamo-fattura-q5", kind = "choice", prompt = "Quando va Anna in negozio ?", options = listOf("Domani mattina", "Domani sera", "Stasera", "Venerdì"), answers = listOf("Domani mattina"), explain = "« Certo, vengo domani mattina ».")), skills = listOf("listening:gist", "listening:detail", "function:solve-problems", "vocab:social-expressions")) }

object ListenData159 { val text = ListeningText(id = "it-listen-colloquio-finto", languageID = "it", title = "Il colloquio finto", level = "B1", topic = "colloqui", unitID = "it-foundations-u21", text = "Il colloquio finto di oggi è con Sara, che si prepara a un’azienda di comunicazione. « Raccontaci la sua esperienza ». « Ho lavorato quattro anni in un’agenzia: prima mi occupavo dei social, poi ho gestito due clienti importanti ». « E i suoi punti di forza ? ». « Sono una persona organizzata e calma sotto pressione. Imparo in fretta ». « Perché vuole cambiare ? ». « Cerco una nuova sfida: vorrei occuparmi di progetti internazionali ». « Dove si vede tra cinque anni ? ». « Mi piacerebbe guidare un piccolo team ». « Ha domande ? ». « Sì: come sono gli orari, e c’è possibilità di lavoro ibrido ? ».", questions = listOf(Exercise(id = "it-listen-colloquio-finto-q1", kind = "choice", prompt = "Dove vuole lavorare Sara ?", options = listOf("In un’azienda di comunicazione", "In una scuola", "In un ospedale", "In una banca"), answers = listOf("In un’azienda di comunicazione"), explain = "Si prepara a un’azienda di comunicazione."), Exercise(id = "it-listen-colloquio-finto-q2", kind = "choice", prompt = "Che cosa ha gestito nell’agenzia ?", options = listOf("Due clienti importanti", "I social dell’agenzia", "Un piccolo team", "Il budget annuale"), answers = listOf("Due clienti importanti"), explain = "« Poi ho gestito due clienti importanti »."), Exercise(id = "it-listen-colloquio-finto-q3", kind = "written", prompt = "Che punti di forza dice Sara ?", options = listOf(), answers = listOf("organizzata e calma sotto pressione", "sono organizzata e calma"), explain = "« Sono una persona organizzata e calma sotto pressione »."), Exercise(id = "it-listen-colloquio-finto-q4", kind = "written", prompt = "Perché vuole cambiare lavoro ?", options = listOf(), answers = listOf("cerca una nuova sfida", "per una nuova sfida"), explain = "« Cerco una nuova sfida »."), Exercise(id = "it-listen-colloquio-finto-q5", kind = "choice", prompt = "Dove si vede tra cinque anni ?", options = listOf("A guidare un piccolo team", "All’estero", "In un’altra città", "Da freelance"), answers = listOf("A guidare un piccolo team"), explain = "« Mi piacerebbe guidare un piccolo team »."), Exercise(id = "it-listen-colloquio-finto-q6", kind = "choice", prompt = "Che cosa chiede alla fine ?", options = listOf("Orari e lavoro ibrido", "Lo stipendio esatto", "Le ferie", "Il nome del capo"), answers = listOf("Orari e lavoro ibrido"), explain = "« Come sono gli orari, e c’è possibilità di lavoro ibrido ? ».")), skills = listOf("listening:inference", "listening:detail", "vocab:work", "function:talk-about-work")) }

object ListenData160 { val text = ListeningText(id = "it-listen-tono-podcast", languageID = "it", title = "Podcast: il tono esatto", level = "C1", topic = "registri", unitID = "it-foundations-u9", text = "Benvenuti a « Parole al lavoro », il podcast di chi scrive per mestiere. Oggi: il tono esatto. Scrivere bene non è questione di parole rare, ma di scelte precise: si prende una decisione, non la si fa; si ha voglia di leggere, non la voglia. Le collocazioni sono le coppie che la lingua ci consegna già pronte. E i verbi del dire pesano: sostenere una tesi è neutro, asserire suona distante, rivendicare suona da battaglia. Il consiglio di oggi ? Leggete ad alta voce: dove il fiato manca, la frase è troppo lunga; dove il tono sale, forse la parola è sbagliata. In definitiva, esprimere un’opinione è decidere: parola per parola.", questions = listOf(Exercise(id = "it-listen-tono-podcast-q1", kind = "choice", prompt = "Che tema ha il podcast di oggi ?", options = listOf("Il tono esatto", "Le parole rare", "La lettura veloce", "I podcast letterari"), answers = listOf("Il tono esatto"), explain = "« Oggi: il tono esatto »."), Exercise(id = "it-listen-tono-podcast-q2", kind = "choice", prompt = "Quale collocazione cita come esatta ?", options = listOf("Prendere una decisione", "Fare una decisione", "Dare una decisione", "Mettere una decisione"), answers = listOf("Prendere una decisione"), explain = "« Si prende una decisione, non la si fa »."), Exercise(id = "it-listen-tono-podcast-q3", kind = "written", prompt = "Che effetto ha « asserire », secondo il relatore ?", options = listOf(), answers = listOf("suona distante", "un tono distante"), explain = "« asserire suona distante »."), Exercise(id = "it-listen-tono-podcast-q4", kind = "choice", prompt = "Che effetto ha « rivendicare » ?", options = listOf("Suona da battaglia", "Suona neutro", "Suona gentile", "Suona antico"), answers = listOf("Suona da battaglia"), explain = "« rivendicare suona da battaglia »."), Exercise(id = "it-listen-tono-podcast-q5", kind = "written", prompt = "Che consiglio pratico dà il relatore ?", options = listOf(), answers = listOf("leggere ad alta voce", "leggete ad alta voce", "leggere a voce alta"), explain = "« Leggete ad alta voce »."), Exercise(id = "it-listen-tono-podcast-q6", kind = "choice", prompt = "Come definisce l’opinione alla fine ?", options = listOf("Decidere parola per parola", "Un gioco di caso", "Una questione di musica", "Un lavoro solitario"), answers = listOf("Decidere parola per parola"), explain = "« Esprimere un’opinione è decidere: parola per parola ».")), skills = listOf("listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion")) }

object ListenData161 { val text = ListeningText(id = "pt-listen-cafe-morning", languageID = "pt", title = "Um café antes do trabalho", level = "A1", topic = "rotina", unitID = "pt-foundations-u1", text = "Todas as manhãs, Marta caminha até uma cafeteria pequena perto do apartamento dela. O garçom sabe o nome dela, então ela nunca precisa pedir. Hoje ela senta perto da janela com um café e um pão de queijo. O ônibus dela sai às oito e meia, mas ela não está preocupada. A cafeteria é muito tranquila nessa hora. Ela bebe o café devagar e vê a cidade acordar.", questions = listOf(Exercise(id = "pt-listen-cafe-morning-q1", kind = "choice", prompt = "Para onde a Marta vai todas as manhãs?", options = listOf("Para uma cafeteria pequena", "Para o escritório dela", "Para o ponto de ônibus", "Para um parque"), answers = listOf("Para uma cafeteria pequena"), explain = "Ela caminha até uma cafeteria pequena perto do apartamento dela."), Exercise(id = "pt-listen-cafe-morning-q2", kind = "choice", prompt = "O que ela toma no café da manhã hoje?", options = listOf("Um café e um pão de queijo", "Chá e torradas", "Suco de laranja", "Nada"), answers = listOf("Um café e um pão de queijo"), explain = "Ela senta perto da janela com um café e um pão de queijo."), Exercise(id = "pt-listen-cafe-morning-q3", kind = "written", prompt = "A que horas sai o ônibus dela?", options = listOf(), answers = listOf("às oito e meia", "oito e meia"), explain = "O ônibus dela sai às oito e meia."), Exercise(id = "pt-listen-cafe-morning-q4", kind = "choice", prompt = "Como ela se sente com o horário?", options = listOf("Não está preocupada", "Está muito atrasada", "Está com raiva", "Está com sono"), answers = listOf("Não está preocupada"), explain = "O texto diz que ela não está preocupada."), Exercise(id = "pt-listen-cafe-morning-q5", kind = "choice", prompt = "Quem sabe o nome dela?", options = listOf("O garçom", "O motorista do ônibus", "O chefe dela", "Um vizinho"), answers = listOf("O garçom"), explain = "O garçom sabe o nome dela, então ela nunca precisa pedir."), Exercise(id = "pt-listen-cafe-morning-q6", kind = "written", prompt = "Onde ela senta hoje?", options = listOf(), answers = listOf("perto da janela", "ao lado da janela", "na janela"), explain = "Hoje ela senta perto da janela.")), skills = listOf("listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine")) }

object ListenData162 { val text = ListeningText(id = "pt-listen-language-class", languageID = "pt", title = "A aula de idiomas", level = "A1", topic = "apresentações", unitID = "pt-foundations-u1", text = "Marta participa da primeira aula de português para estrangeiros em um instituto pequeno. Na turma há seis pessoas e todas querem conversar. A professora pede as apresentações. “Meu nome é Marta e sou da Bolívia”, diz uma senhora. “Eu sou o Andrés, sou do Peru e trabalho em um restaurante”, diz um rapaz. Marta também se apresenta: “Sou a Marta, sou argentina e sou enfermeira”. A professora é de Madri e ensina com muito bom humor. No final da aula, os alunos trocam os números de telefone. Ainda não são amigos, mas na próxima semana vão tomar um café juntos e praticar.", questions = listOf(Exercise(id = "pt-listen-language-class-q1", kind = "choice", prompt = "Quantas pessoas há na turma?", options = listOf("Seis", "Três", "Dez", "Quatorze"), answers = listOf("Seis"), explain = "Na turma há seis pessoas."), Exercise(id = "pt-listen-language-class-q2", kind = "choice", prompt = "De onde é o Andrés?", options = listOf("Do Peru", "Da Bolívia", "Da Argentina", "Do México"), answers = listOf("Do Peru"), explain = "O Andrés é do Peru e trabalha em um restaurante."), Exercise(id = "pt-listen-language-class-q3", kind = "choice", prompt = "Qual é o trabalho da Marta?", options = listOf("Enfermeira", "Professora", "Garçonete", "Estudante"), answers = listOf("Enfermeira"), explain = "A Marta é argentina e é enfermeira."), Exercise(id = "pt-listen-language-class-q4", kind = "written", prompt = "De onde é a professora?", options = listOf(), answers = listOf("madril", "de madri", "madri", "madrid", "de madrid"), explain = "A professora é de Madri."), Exercise(id = "pt-listen-language-class-q5", kind = "choice", prompt = "O que eles fazem no final da aula?", options = listOf("Trocam os números de telefone", "Voltam para casa sozinhos", "Fazem uma prova", "Jantam em um restaurante"), answers = listOf("Trocam os números de telefone"), explain = "Os alunos trocam os números de telefone."), Exercise(id = "pt-listen-language-class-q6", kind = "written", prompt = "O que eles vão fazer na próxima semana?", options = listOf(), answers = listOf("tomar um café", "vão tomar um café", "tomar um café juntos"), explain = "Na próxima semana vão tomar um café juntos e praticar.")), skills = listOf("listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself")) }

object ListenData163 { val text = ListeningText(id = "pt-listen-little-sister", languageID = "pt", title = "Minha irmã mais nova", level = "A1", topic = "família", unitID = "pt-foundations-u1", text = "Minha irmã mais nova se chama Carla e tem nove anos. É muito simpática e muito falante. Carla não é tímida: fala com todo mundo, com os vizinhos, com os professores e com os cachorros do parque. É loira, como a nossa mãe, e tem olhos castanhos como o meu pai. Não é alta para a idade dela, mas é muito rápida e adora futebol. O time dela não é muito bom, mas isso não é importante para ela. “Não sou profissional”, diz ela, “só sou feliz com a bola”. Minha irmã é pequena, mas a alegria dela é enorme.", questions = listOf(Exercise(id = "pt-listen-little-sister-q1", kind = "choice", prompt = "Quantos anos a Carla tem?", options = listOf("Nove", "Dezenove", "Sete", "Dez"), answers = listOf("Nove"), explain = "A Carla tem nove anos."), Exercise(id = "pt-listen-little-sister-q2", kind = "choice", prompt = "Como é a Carla?", options = listOf("Simpática e falante", "Tímida e calada", "Séria", "Triste"), answers = listOf("Simpática e falante"), explain = "É muito simpática e muito falante."), Exercise(id = "pt-listen-little-sister-q3", kind = "written", prompt = "De que cor são os olhos dela?", options = listOf(), answers = listOf("castanhos", "olhos castanhos", "castanhos como o pai dela"), explain = "Ela tem olhos castanhos como o pai dela."), Exercise(id = "pt-listen-little-sister-q4", kind = "choice", prompt = "Como é o cabelo dela?", options = listOf("Loiro, como o da mãe", "Escuro, como o do pai", "Ruivo", "Curto e preto"), answers = listOf("Loiro, como o da mãe"), explain = "É loira, como a nossa mãe."), Exercise(id = "pt-listen-little-sister-q5", kind = "choice", prompt = "O que ela adora?", options = listOf("Futebol", "Natação", "Música", "Videogame"), answers = listOf("Futebol"), explain = "É muito rápida e adora futebol."), Exercise(id = "pt-listen-little-sister-q6", kind = "written", prompt = "Como é a alegria dela?", options = listOf(), answers = listOf("enorme", "muito grande", "grande"), explain = "A alegria dela é enorme.")), skills = listOf("listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family")) }

object ListenData164 { val text = ListeningText(id = "pt-listen-new-flatmate", languageID = "pt", title = "Um novo colega de apartamento", level = "A1", topic = "casa", unitID = "pt-foundations-u1", text = "Tom tem um colega de apartamento novo. O nome dele é Leo e ele tem vinte e três anos. Leo vem de uma cidade pequena do interior, mas agora trabalha na capital. Ele tem duas caixas, um violão e uma bicicleta. O apartamento tem dois quartos e uma cozinha clara. Tom espera que Leo goste de cozinhar, porque o Tom não gosta nem um pouco.", questions = listOf(Exercise(id = "pt-listen-new-flatmate-q1", kind = "choice", prompt = "Quantos anos o Leo tem?", options = listOf("Vinte e três", "Trinta e dois", "Vinte", "Trinta"), answers = listOf("Vinte e três"), explain = "O Leo tem vinte e três anos."), Exercise(id = "pt-listen-new-flatmate-q2", kind = "choice", prompt = "O que o Leo NÃO tem?", options = listOf("Uma televisão", "Duas caixas", "Um violão", "Uma bicicleta"), answers = listOf("Uma televisão"), explain = "Ele tem duas caixas, um violão e uma bicicleta — sem televisão."), Exercise(id = "pt-listen-new-flatmate-q3", kind = "written", prompt = "O que o Tom odeia fazer?", options = listOf(), answers = listOf("cozinhar", "ele odeia cozinhar", "tom odeia cozinhar"), explain = "O Tom não gosta nem um pouco de cozinhar."), Exercise(id = "pt-listen-new-flatmate-q4", kind = "choice", prompt = "Como é o apartamento?", options = listOf("Dois quartos e uma cozinha clara", "Um quarto e uma varanda", "Um jardim", "Dois banheiros"), answers = listOf("Dois quartos e uma cozinha clara"), explain = "O apartamento tem dois quartos e uma cozinha clara."), Exercise(id = "pt-listen-new-flatmate-q5", kind = "choice", prompt = "Onde o Leo trabalha agora?", options = listOf("Na capital", "Em uma cidade pequena", "No interior", "Ele não trabalha"), answers = listOf("Na capital"), explain = "Ele vem de uma cidade pequena do interior, mas agora trabalha na capital."), Exercise(id = "pt-listen-new-flatmate-q6", kind = "written", prompt = "Que instrumento o Leo tem?", options = listOf(), answers = listOf("um violão", "o violão", "violão"), explain = "O Leo tem um violão.")), skills = listOf("listening:gist", "listening:detail", "grammar:have-got", "vocab:home")) }

object ListenData165 { val text = ListeningText(id = "pt-listen-new-neighbour", languageID = "pt", title = "A nova vizinha", level = "A1", topic = "pessoas", unitID = "pt-foundations-u1", text = "No prédio há uma vizinha nova. Ela se chama Amélie e é da França. Não é estudante; é fotógrafa. Não trabalha em um escritório: trabalha em casa e viaja muito. Os vizinhos são curiosos, mas também são tímidos, por isso não falam com ela. Então, uma manhã, Ben a encontra na porta. “Você é a vizinha nova?”, pergunta ele. “Sim, sou eu”, responde ela, “e estou contente de estar aqui”. Agora são amigos, e ela não está mais sozinha no prédio.", questions = listOf(Exercise(id = "pt-listen-new-neighbour-q1", kind = "choice", prompt = "De onde é a Amélie?", options = listOf("Da França", "Da Itália", "Do Japão", "Do Brasil"), answers = listOf("Da França"), explain = "A Amélie é da França."), Exercise(id = "pt-listen-new-neighbour-q2", kind = "choice", prompt = "Qual é o trabalho dela?", options = listOf("É fotógrafa", "É estudante", "Trabalha em um escritório", "É professora"), answers = listOf("É fotógrafa"), explain = "Não é estudante; é fotógrafa."), Exercise(id = "pt-listen-new-neighbour-q3", kind = "choice", prompt = "Ela trabalha em um escritório?", options = listOf("Não, trabalha em casa", "Sim, todos os dias", "Só no verão", "Ela não diz"), answers = listOf("Não, trabalha em casa"), explain = "Não trabalha em um escritório: trabalha em casa."), Exercise(id = "pt-listen-new-neighbour-q4", kind = "written", prompt = "Por que os vizinhos não falam com ela?", options = listOf(), answers = listOf("são tímidos", "porque são tímidos", "tímidos"), explain = "São curiosos, mas também são tímidos."), Exercise(id = "pt-listen-new-neighbour-q5", kind = "choice", prompt = "Onde o Ben a encontra?", options = listOf("Na porta", "No elevador", "Na rua", "No café"), answers = listOf("Na porta"), explain = "Uma manhã, o Ben a encontra na porta."), Exercise(id = "pt-listen-new-neighbour-q6", kind = "written", prompt = "Como a Amélie se sente no final?", options = listOf(), answers = listOf("contente", "feliz", "está contente"), explain = "Ela diz que está contente de estar aqui.")), skills = listOf("listening:gist", "listening:detail", "function:describe-people")) }

object ListenData166 { val text = ListeningText(id = "pt-listen-sunday-market", languageID = "pt", title = "A feira de domingo", level = "A1", topic = "compras", unitID = "pt-foundations-u1", text = "Aos domingos tem uma feira na praça do bairro. A Ana e o pai dela vão para lá às nove horas, antes de ficar cheio. Eles compram fruta, pão e flores. A Ana quer morangos, mas o pai dela diz que estão muito caros nesta semana. No final, eles levam para casa um saco grande de laranjas e rosas brancas para a mesa da cozinha.", questions = listOf(Exercise(id = "pt-listen-sunday-market-q1", kind = "choice", prompt = "Quando a Ana e o pai dela vão à feira?", options = listOf("Às nove horas", "Ao meio-dia", "À tarde", "Às seis e meia"), answers = listOf("Às nove horas"), explain = "Eles vão às nove horas, antes de ficar cheio."), Exercise(id = "pt-listen-sunday-market-q2", kind = "written", prompt = "Por que a Ana não leva os morangos?", options = listOf(), answers = listOf("estão muito caros", "muito caros", "porque estão muito caros"), explain = "O pai diz que estão muito caros nesta semana."), Exercise(id = "pt-listen-sunday-market-q3", kind = "choice", prompt = "O que eles levam para casa?", options = listOf("Laranjas e rosas", "Morangos e pão", "Maçãs e tulipas", "Pão e queijo"), answers = listOf("Laranjas e rosas"), explain = "Eles levam laranjas e rosas brancas."), Exercise(id = "pt-listen-sunday-market-q4", kind = "choice", prompt = "Onde fica a feira?", options = listOf("Na praça do bairro", "Perto do rio", "Na estação", "Num supermercado"), answers = listOf("Na praça do bairro"), explain = "Aos domingos tem uma feira na praça do bairro."), Exercise(id = "pt-listen-sunday-market-q5", kind = "choice", prompt = "O que eles compram?", options = listOf("Fruta, pão e flores", "Peixe e legumes", "Queijo e carne", "Somente flores"), answers = listOf("Fruta, pão e flores"), explain = "Eles compram fruta, pão e flores."), Exercise(id = "pt-listen-sunday-market-q6", kind = "written", prompt = "O que a Ana quer?", options = listOf(), answers = listOf("morangos", "quer morangos"), explain = "A Ana quer morangos.")), skills = listOf("listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping")) }

object ListenData167 { val text = ListeningText(id = "pt-listen-apartamento-escolhido", languageID = "pt", title = "O apartamento escolhido", level = "A2", topic = "apartamentos", unitID = "pt-foundations-u4", text = "Bia e Rafa procuram apartamento no aplicativo. O primeiro é mais barato, mas fica mais longe da estação: quarenta minutos a pé. O segundo custa cem reais a mais por mês, mas é mais claro e tem varanda. Para a Bia, a luz é o mais importante, porque ela trabalha de casa. No final, decidem pedir uma visita ao segundo: é mais caro, mas é o melhor dos dois para eles.", questions = listOf(Exercise(id = "pt-listen-apartamento-escolhido-q1", kind = "choice", prompt = "Quantos apartamentos eles comparam ?", options = listOf("Dois", "Três", "Quatro"), answers = listOf("Dois"), explain = "Comparam dois apartamentos no aplicativo."), Exercise(id = "pt-listen-apartamento-escolhido-q2", kind = "choice", prompt = "Qual é o problema do mais barato ?", options = listOf("Fica longe da estação", "Não tem varanda", "É muito caro", "É pequeno"), answers = listOf("Fica longe da estação"), explain = "Quarenta minutos a pé da estação."), Exercise(id = "pt-listen-apartamento-escolhido-q3", kind = "written", prompt = "Quanto custa a mais o segundo por mês ?", options = listOf(), answers = listOf("cem reais", "100 reais"), explain = "Cem reais a mais por mês."), Exercise(id = "pt-listen-apartamento-escolhido-q4", kind = "choice", prompt = "O que é mais importante para a Bia ?", options = listOf("A luz", "O preço", "A varanda", "A cozinha"), answers = listOf("A luz"), explain = "Ela trabalha de casa."), Exercise(id = "pt-listen-apartamento-escolhido-q5", kind = "choice", prompt = "O que eles decidem no final ?", options = listOf("Pedir visita ao segundo", "Ficar com o primeiro", "Continuar procurando", "Pedir desconto"), answers = listOf("Pedir visita ao segundo"), explain = "É o melhor dos dois para eles.")), skills = listOf("listening:gist", "listening:inference", "grammar:comparatives"), exposureSkills = listOf("grammar:superlatives")) }

object ListenData168 { val text = ListeningText(id = "pt-listen-sabado-organizado", languageID = "pt", title = "O sábado organizado", level = "A2", topic = "planos", unitID = "pt-foundations-u4", text = "Lu liga para o irmão para organizar o sábado. Ele sugere a montanha, mas vai chover, então Lu propõe o museu novo. Vão se encontrar às dez na entrada principal e almoçar na feira ao lado, que é mais barata que os restaurantes do centro. À noite não têm plano: vão decidir lá, quando souberem como vai estar o tempo.", questions = listOf(Exercise(id = "pt-listen-sabado-organizado-q1", kind = "choice", prompt = "Quem sugere a montanha ?", options = listOf("O irmão", "Lu", "A mãe", "Um amigo"), answers = listOf("O irmão"), explain = "O irmão sugere a montanha."), Exercise(id = "pt-listen-sabado-organizado-q2", kind = "choice", prompt = "Por que não a montanha ?", options = listOf("Vai chover", "Estão cansados", "O museu é grátis", "A montanha é longe"), answers = listOf("Vai chover"), explain = "Vai chover, então vão ao museu."), Exercise(id = "pt-listen-sabado-organizado-q3", kind = "written", prompt = "A que horas vão se encontrar ?", options = listOf(), answers = listOf("as dez", "às dez", "dez horas"), explain = "Às dez na entrada principal."), Exercise(id = "pt-listen-sabado-organizado-q4", kind = "choice", prompt = "Onde vão almoçar ?", options = listOf("Na feira ao lado", "Num restaurante do centro", "Em casa", "No museu"), answers = listOf("Na feira ao lado"), explain = "Mais barata que os restaurantes do centro."), Exercise(id = "pt-listen-sabado-organizado-q5", kind = "choice", prompt = "O que vão fazer à noite ?", options = listOf("Decidir lá", "Ir ao cinema", "Voltar cedo", "Encontrar amigos"), answers = listOf("Decidir lá"), explain = "Dependendo do tempo.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("grammar:future-forms")) }

object ListenData169 { val text = ListeningText(id = "pt-listen-nunca-fez", languageID = "pt", title = "Coisas que nunca fiz", level = "B1", topic = "viagens", unitID = "pt-foundations-u6", text = "Na cozinha de um hostel, três viajantes comparam as vidas. Caio já visitou vinte países, mas nunca aprendeu a nadar: « Eu sei, é ridículo ». Marina já mergulhou duas vezes com tartarugas, mas não tinha saído do Brasil antes desta viagem. E Beatriz, que está na estrada há seis anos, nunca pegou avião: ela atravessa os oceanos de navio e as fronteiras de ônibus. « Nunca ? » pergunta Caio. « Nunca. O medo é mais velho do que eu. » Eles riem das coisas que não fizeram, e Beatriz diz uma frase que fica: « Não precisa ter feito tudo. Basta ainda querer ».", questions = listOf(Exercise(id = "pt-listen-nunca-fez-q1", kind = "choice", prompt = "O que Caio nunca fez ?", options = listOf("Aprender a nadar", "Visitar vinte países", "Atravessar de navio", "Sair do Brasil"), answers = listOf("Aprender a nadar"), explain = "Já visitou vinte países, mas nunca aprendeu a nadar."), Exercise(id = "pt-listen-nunca-fez-q2", kind = "written", prompt = "Quantas vezes Marina mergulhou ?", options = listOf(), answers = listOf("duas vezes", "2 vezes", "duas"), explain = "Marina já mergulhou duas vezes com tartarugas."), Exercise(id = "pt-listen-nunca-fez-q3", kind = "choice", prompt = "Como Beatriz atravessa os oceanos ?", options = listOf("De navio", "De avião", "De ônibus", "A pé"), answers = listOf("De navio"), explain = "Ela atravessa os oceanos de navio e as fronteiras de ônibus."), Exercise(id = "pt-listen-nunca-fez-q4", kind = "choice", prompt = "O que Beatriz diz sobre o medo ?", options = listOf("É mais velho do que ela", "É mais jovem", "É ridículo", "Se foi"), answers = listOf("É mais velho do que ela"), explain = "O medo é mais velho do que eu."), Exercise(id = "pt-listen-nunca-fez-q5", kind = "written", prompt = "O que basta, segundo Beatriz ?", options = listOf(), answers = listOf("ainda querer", "basta ainda querer"), explain = "Basta ainda querer.")), skills = listOf("listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"), exposureSkills = listOf("grammar:relative-clauses")) }

object ListenData170 { val text = ListeningText(id = "pt-listen-cidade-interior", languageID = "pt", title = "Da cidade para o interior", level = "B1", topic = "mudanças", unitID = "pt-foundations-u6", text = "Pedro conta por que saiu de São Paulo. Antes ele morava num apartamento pequeno e trabalhava onze horas por dia: « Eu ganhava bem, mas não tinha vida ». Num inverno ele adoeceu, e aí entendeu que precisava mudar. Agora mora num vilarejo de mil habitantes, trabalha de casa pela manhã e cuida de uma horta à tarde. « Ganho menos, mas sobra tempo. » No começo os pais não entendiam; agora vêm todo mês. « Você se arrepende de algo ? », pergunta a amiga. « De não ter feito isso antes ».", questions = listOf(Exercise(id = "pt-listen-cidade-interior-q1", kind = "choice", prompt = "Onde Pedro morava antes ?", options = listOf("Em São Paulo", "Num vilarejo", "No Rio de Janeiro", "Num hostel"), answers = listOf("Em São Paulo"), explain = "Pedro conta por que saiu de São Paulo."), Exercise(id = "pt-listen-cidade-interior-q2", kind = "written", prompt = "Quantas horas ele trabalhava por dia ?", options = listOf(), answers = listOf("onze horas", "11 horas", "onze"), explain = "Trabalhava onze horas por dia."), Exercise(id = "pt-listen-cidade-interior-q3", kind = "choice", prompt = "O que o fez mudar ?", options = listOf("Ele adoeceu", "Perdeu o emprego", "Ganhou na loteria", "Conheceu alguém"), answers = listOf("Ele adoeceu"), explain = "Num inverno ele adoeceu, e aí entendeu."), Exercise(id = "pt-listen-cidade-interior-q4", kind = "choice", prompt = "O que ele faz à tarde agora ?", options = listOf("Cuida de uma horta", "Trabalha mais horas", "Viaja todo mês", "Estuda"), answers = listOf("Cuida de uma horta"), explain = "Trabalha pela manhã e cuida de uma horta à tarde."), Exercise(id = "pt-listen-cidade-interior-q5", kind = "written", prompt = "De que Pedro se arrepende ?", options = listOf(), answers = listOf("de nao ter feito isso antes", "de não ter feito isso antes", "nao ter feito antes", "não ter feito antes"), explain = "« De não ter feito isso antes ».")), skills = listOf("listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions")) }

object ListenData171 { val text = ListeningText(id = "pt-listen-pechincha-mesa", languageID = "pt", title = "A pechincha da mesa", level = "B2", topic = "negociação", unitID = "pt-foundations-u7", text = "Num aplicativo de usados, Bia quer uma mesa de madeira por 80 reais. « E se combinarmos em 60 ? », propõe ela. O vendedor recusa: « Só se você levar hoje ». Bia pensa: « Eu lhe daria 65 se incluir a cadeira ». « Impossível », ri ele, « mas eu deixaria a mesa por 70 e a subitaria para você ». Bia não hesita: « Você a subiria sozinho ? ». « Tenho um carrinho », responde. « Fechado », diz ela, e acrescenta: « Se ela for tão bonita quanto na foto, você ganha cinco estrelas ».", questions = listOf(Exercise(id = "pt-listen-pechincha-mesa-q1", kind = "choice", prompt = "Quanto o vendedor pede ?", options = listOf("80 reais", "60 reais", "70 reais", "65 reais"), answers = listOf("80 reais"), explain = "A mesa custa 80 reais."), Exercise(id = "pt-listen-pechincha-mesa-q2", kind = "written", prompt = "O que Bia propõe primeiro ?", options = listOf(), answers = listOf("60 reais", "sessenta reais", "combinar em 60"), explain = "« E se combinarmos em 60 ? »."), Exercise(id = "pt-listen-pechincha-mesa-q3", kind = "choice", prompt = "Que condição o vendedor põe ?", options = listOf("Levar hoje", "Pagar à vista", "Dar cinco estrelas", "Voltar amanhã"), answers = listOf("Levar hoje"), explain = "« Só se você levar hoje »."), Exercise(id = "pt-listen-pechincha-mesa-q4", kind = "choice", prompt = "O que o vendedor oferece por 70 ?", options = listOf("Subir a mesa", "Incluir a cadeira", "Baixar para 60", "Emprestar o carrinho"), answers = listOf("Subir a mesa"), explain = "« Eu a subitaria para você »."), Exercise(id = "pt-listen-pechincha-mesa-q5", kind = "written", prompt = "O que Bia promete se gostar ?", options = listOf(), answers = listOf("cinco estrelas", "5 estrelas"), explain = "Cinco estrelas.")), skills = listOf("listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors")) }

object ListenData172 { val text = ListeningText(id = "pt-listen-noticia-bairro", languageID = "pt", title = "A notícia do bairro", level = "B2", topic = "notícias", unitID = "pt-foundations-u8", text = "Na feira, Camila e Rafael comentam o que se diz. « Dizem que vão peatonalizar a rua principal », conta Camila. « De novo ? », ri Rafael. « A notícia que li diz que começa na primavera ». Segundo a prefeitura, seria só aos sábados, mas os comerciantes, cujo faturamento dependeria do turismo, já se manifestaram. « É verdade que o barulho cairia », admite Rafael, « mas, e o estacionamento ? ». Camila defende a medida: « Por um lado, mais gente caminharia; por outro, os ônibus parariam na porta ». Eles não decidem nada, mas prometem voltar a falar disso quando o plano sair.", questions = listOf(Exercise(id = "pt-listen-noticia-bairro-q1", kind = "choice", prompt = "O que dizem da rua principal ?", options = listOf("Que será peatonalizada", "Que será alargada", "Que será fechada", "Que mudará de nome"), answers = listOf("Que será peatonalizada"), explain = "« Dizem que vão peatonalizar a rua principal »."), Exercise(id = "pt-listen-noticia-bairro-q2", kind = "written", prompt = "Quando começaria ?", options = listOf(), answers = listOf("na primavera", "primavera"), explain = "« A notícia que li diz que começa na primavera »."), Exercise(id = "pt-listen-noticia-bairro-q3", kind = "choice", prompt = "O que diz a prefeitura ?", options = listOf("Só aos sábados", "Todos os dias", "Só no verão", "Nos feriados"), answers = listOf("Só aos sábados"), explain = "Seria só aos sábados."), Exercise(id = "pt-listen-noticia-bairro-q4", kind = "choice", prompt = "Quem se manifestou ?", options = listOf("Os comerciantes", "Os moradores", "Os taxistas", "A prefeitura"), answers = listOf("Os comerciantes"), explain = "Os comerciantes já se manifestaram."), Exercise(id = "pt-listen-noticia-bairro-q5", kind = "written", prompt = "O que Camila e Rafael prometem ?", options = listOf(), answers = listOf("voltar a falar disso", "falar disso de novo"), explain = "Prometem voltar a falar disso quando o plano sair.")), skills = listOf("listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors")) }

object ListenData173 { val text = ListeningText(id = "pt-listen-debate-radio", languageID = "pt", title = "Debate no rádio", level = "C1", topic = "debate", unitID = "pt-foundations-u9", text = "No debate desta quinta, a economista Helena Vaz defendeu a semana de quatro dias: « A produtividade não cai; ela se redistribui », afirmou, « e as equipes relatam menos afastamentos ». O apresentador contrapôs: « Mas e as pequenas empresas, que já operam no limite ? ». Helena matizou: « De certa forma, o senhor tem razão; por isso defendo um programa piloto, e não uma lei para todos ». O empresário Rui Costa, convidado ao estúdio, resumiu sua posição: « Para começar, preciso de dados do meu setor; para encerrar, digo que apoio a experiência — com exceções ». O mediador fechou o bloco lembrando que o relatório final sai em novembro e que o debate continua na próxima semana, com a participação de sindicalistas.", questions = listOf(Exercise(id = "pt-listen-debate-radio-q1", kind = "choice", prompt = "Qual é a proposta central do debate ?", options = listOf("Semana de quatro dias", "Salário mínimo por hora", "Fim do home office", "Mais horas extras"), answers = listOf("Semana de quatro dias"), explain = "Helena defende a semana de quatro dias."), Exercise(id = "pt-listen-debate-radio-q2", kind = "written", prompt = "Segundo Helena, o que acontece com a produtividade ?", options = listOf(), answers = listOf("ela se redistribui", "nao cai ela se redistribui", "se redistribui"), explain = "« A produtividade não cai; ela se redistribui »."), Exercise(id = "pt-listen-debate-radio-q3", kind = "choice", prompt = "O que Helena defende como caminho ?", options = listOf("Um programa piloto", "Uma lei imediata", "Nenhuma mudança", "Um referendo"), answers = listOf("Um programa piloto"), explain = "« Defendo um programa piloto, e não uma lei para todos »."), Exercise(id = "pt-listen-debate-radio-q4", kind = "choice", prompt = "O que Rui pede antes de apoiar ?", options = listOf("Dados do seu setor", "Mais reuniões", "Um aumento", "Novos sócios"), answers = listOf("Dados do seu setor"), explain = "« Para começar, preciso de dados do meu setor »."), Exercise(id = "pt-listen-debate-radio-q5", kind = "written", prompt = "Quando sai o relatório final ?", options = listOf(), answers = listOf("em novembro", "novembro"), explain = "O relatório final sai em novembro."), Exercise(id = "pt-listen-debate-radio-q6", kind = "choice", prompt = "Quem participa do debate da próxima semana ?", options = listOf("Sindicalistas", "A diretoria", "Estudantes", "Ninguém"), answers = listOf("Sindicalistas"), explain = "« O debate continua na próxima semana, com a participação de sindicalistas ».")), skills = listOf("listening:inference", "listening:connected-speech", "function:express-opinion", "grammar:connectors")) }

object ListenData174 { val text = ListeningText(id = "pt-listen-palestra-chaves", languageID = "pt", title = "Palestra: três chaves", level = "C1", topic = "palestra", unitID = "pt-foundations-u9", text = "Na abertura do congresso, a consultora Marta Reis fez uma pergunta ao plenário: « Quantas reuniões vocês suportaram esta semana ? ». Risos. « É disso que quero tratar: da fala que respeita quem ouve ». Ela organizou a palestra em três chaves. « Para começar, anuncie o destino: se o ouvinte não souber aonde você quer chegar, ele viaja com medo. Depois, dê um dado por ponto — números demais enterram a mensagem. E, para encerrar, peça algo concreto: um voto, um prazo, um apoio ». Ao sintetizar, Marta voltou à pergunta inicial: « Resumindo: quem estrutura bem fala menos — e decide mais ». A plateia respondeu de pé, e a fala dela virou referência interna das equipes.", questions = listOf(Exercise(id = "pt-listen-palestra-chaves-q1", kind = "choice", prompt = "Como Marta abre a palestra ?", options = listOf("Com uma pergunta ao plenário", "Com uma estatística", "Com um vídeo", "Com um silêncio"), answers = listOf("Com uma pergunta ao plenário"), explain = "« Quantas reuniões vocês suportaram esta semana ? »."), Exercise(id = "pt-listen-palestra-chaves-q2", kind = "choice", prompt = "Quantas chaves ela apresenta ?", options = listOf("Três", "Duas", "Quatro", "Cinco"), answers = listOf("Três"), explain = "« Ela organizou a palestra em três chaves »."), Exercise(id = "pt-listen-palestra-chaves-q3", kind = "written", prompt = "O que ela recomenda anunciar primeiro ?", options = listOf(), answers = listOf("o destino", "o destino da fala", "onde a fala quer chegar"), explain = "« Para começar, anuncie o destino »."), Exercise(id = "pt-listen-palestra-chaves-q4", kind = "choice", prompt = "Por que ela evita números demais ?", options = listOf("Enterram a mensagem", "Faltam dados", "Confundem o orçamento", "Cansam o orador"), answers = listOf("Enterram a mensagem"), explain = "« Números demais enterram a mensagem »."), Exercise(id = "pt-listen-palestra-chaves-q5", kind = "written", prompt = "O que se deve pedir ao encerrar, segundo Marta ?", options = listOf(), answers = listOf("algo concreto", "um pedido concreto", "um voto um prazo um apoio"), explain = "« Peça algo concreto: um voto, um prazo, um apoio »."), Exercise(id = "pt-listen-palestra-chaves-q6", kind = "choice", prompt = "Qual é a síntese da palestra ?", options = listOf("Quem estrutura bem fala menos", "Quem fala mais lidera", "Reuniões devem ser longas", "Dados valem mais que palavras"), answers = listOf("Quem estrutura bem fala menos"), explain = "« Quem estrutura bem fala menos — e decide mais ».")), skills = listOf("listening:detail", "listening:gist", "vocab:work")) }

object ListenData175 { val text = ListeningText(id = "pt-listen-podcast-matices", languageID = "pt", title = "Podcast: matizando", level = "C1", topic = "podcast", unitID = "pt-foundations-u9", text = "No episódio de hoje, Lívia e Tomás discutem o aviso da empresa: três dias presenciais por semana. « Eu vejo com bons olhos », diz Tomás, « o escritório me dá ritmo ». Lívia não concorda de todo: « De certa forma, faz sentido para quem mora perto; no meu caso, eram três horas de metrô por dia ». Tomás reconhece o ponto: « É verdade que o time ficou mais rápido em casa; tiramos conclusões apressadas sobre presença ». « Pois é », resume Lívia, « por assim dizer, virou questão de logística — e de confiança ». Eles fecham o episódio com uma pergunta aos ouvintes: regime fixo ou flexível ? As respostas viram pauta do próximo programa.", questions = listOf(Exercise(id = "pt-listen-podcast-matices-q1", kind = "choice", prompt = "Qual é o novo regime da empresa ?", options = listOf("Três dias presenciais", "Trabalho cem por cento remoto", "Só reuniões online", "Horário livre"), answers = listOf("Três dias presenciais"), explain = "O aviso manda três dias presenciais por semana."), Exercise(id = "pt-listen-podcast-matices-q2", kind = "choice", prompt = "Como Tomás reage ao aviso ?", options = listOf("Vê com bons olhos", "Rejeita de pronto", "Pede demissão", "Fica neutro"), answers = listOf("Vê com bons olhos"), explain = "« Eu vejo com bons olhos »."), Exercise(id = "pt-listen-podcast-matices-q3", kind = "written", prompt = "Qual era o custo do deslocamento de Lívia ?", options = listOf(), answers = listOf("tres horas de metro por dia", "três horas de metrô por dia", "tres horas de metro"), explain = "« Eram três horas de metrô por dia »."), Exercise(id = "pt-listen-podcast-matices-q4", kind = "choice", prompt = "Que conclusão apressada o time admite ter tirado ?", options = listOf("Sobre a presença", "Sobre o salário", "Sobre o orçamento", "Sobre o produto"), answers = listOf("Sobre a presença"), explain = "« Tiramos conclusões apressadas sobre presença »."), Exercise(id = "pt-listen-podcast-matices-q5", kind = "written", prompt = "Como Lívia resume a questão ?", options = listOf(), answers = listOf("questao de logistica e de confianca", "de logística e de confiança", "logística e confiança"), explain = "« Virou questão de logística — e de confiança »."), Exercise(id = "pt-listen-podcast-matices-q6", kind = "choice", prompt = "O que os ouvintes vão responder ?", options = listOf("Regime fixo ou flexível", "O próximo convidado", "O nome do podcast", "O dia do encontro"), answers = listOf("Regime fixo ou flexível"), explain = "A pergunta do fecho: regime fixo ou flexível ?")), skills = listOf("listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion")) }

object ListenData176 { val text = ListeningText(id = "pt-listen-apartamento-novo", languageID = "pt", title = "O apartamento novo da Bia", level = "A1", topic = "casa", unitID = "pt-foundations-u10", text = "A Bia muda para um apartamento novo no centro. O apartamento é pequeno, mas é claro. Tem dois quartos, uma cozinha ampla e uma varanda com plantas. Na sala tem um sofá velho da avó dela e uma estante cheia de livros. Os livros ficam em cima da estante e as chaves ficam na gaveta. Não tem garagem, mas tem uma bicicletaria no térreo. O melhor é o bairro: tem padaria, farmácia e uma praça aqui perto.", questions = listOf(Exercise(id = "pt-listen-apartamento-novo-q1", kind = "choice", prompt = "Como é o apartamento da Bia?", options = listOf("Pequeno, mas claro", "Grande e escuro", "Velho e vazio", "Longe do centro"), answers = listOf("Pequeno, mas claro"), explain = "O texto diz: o apartamento é pequeno, mas é claro."), Exercise(id = "pt-listen-apartamento-novo-q2", kind = "choice", prompt = "O que tem na sala?", options = listOf("Um sofá e uma estante", "Uma mesa e seis cadeiras", "Uma cama grande", "Uma televisão nova"), answers = listOf("Um sofá e uma estante"), explain = "Na sala tem um sofá velho da avó dela e uma estante cheia de livros."), Exercise(id = "pt-listen-apartamento-novo-q3", kind = "choice", prompt = "Onde ficam as chaves?", options = listOf("Na gaveta", "Em cima da estante", "Embaixo da cama", "Na cozinha"), answers = listOf("Na gaveta"), explain = "As chaves ficam na gaveta."), Exercise(id = "pt-listen-apartamento-novo-q4", kind = "choice", prompt = "O que o apartamento não tem?", options = listOf("Garagem", "Varanda", "Quartos", "Cozinha"), answers = listOf("Garagem"), explain = "Não tem garagem, mas tem uma bicicletaria no térreo."), Exercise(id = "pt-listen-apartamento-novo-q5", kind = "written", prompt = "O que tem na varanda?", options = listOf(), answers = listOf("plantas", "tem plantas", "as plantas"), explain = "Tem dois quartos, uma cozinha ampla e uma varanda com plantas."), Exercise(id = "pt-listen-apartamento-novo-q6", kind = "written", prompt = "O que tem aqui perto no bairro? Dê duas coisas.", options = listOf(), answers = listOf("padaria e farmácia", "padaria e farmacia", "padaria, farmácia e praça", "padaria, farmacia e praca"), explain = "Tem padaria, farmácia e uma praça aqui perto.")), skills = listOf("listening:detail", "grammar:there-is-are", "grammar:prepositions-place", "vocab:home")) }

object ListenData177 { val text = ListeningText(id = "pt-listen-passeio-bairro", languageID = "pt", title = "Um passeio pelo bairro", level = "A1", topic = "bairro", unitID = "pt-foundations-u11", text = "Hoje o Leo quer conhecer o bairro novo. Ele para um vizinho na rua: « Desculpe, tem um mercado aqui perto ? ». O vizinho responde: « Tem, sim. Siga em frente duas quadras e vire à esquerda. O mercado fica na esquina, ao lado da farmácia ». O Leo agradece e caminha. No caminho ele vê uma praça com crianças e um ponto de ônibus. O mercado é pequeno, mas tem de tudo. E é perto: em cinco minutos ele está em casa com as compras.", questions = listOf(Exercise(id = "pt-listen-passeio-bairro-q1", kind = "choice", prompt = "O que o Leo quer saber?", options = listOf("Onde tem um mercado", "Que horas abre a praça", "Onde mora o vizinho", "Como vai ao trabalho"), answers = listOf("Onde tem um mercado"), explain = "Ele pergunta: tem um mercado aqui perto ?"), Exercise(id = "pt-listen-passeio-bairro-q2", kind = "choice", prompt = "O que o vizinho manda fazer primeiro?", options = listOf("Siga em frente duas quadras", "Vire à direita", "Pegue um ônibus", "Espere na praça"), answers = listOf("Siga em frente duas quadras"), explain = "Siga em frente duas quadras e vire à esquerda."), Exercise(id = "pt-listen-passeio-bairro-q3", kind = "choice", prompt = "Onde o mercado fica?", options = listOf("Na esquina, ao lado da farmácia", "Em frente à praça", "Perto do ponto de ônibus", "Dentro do centro"), answers = listOf("Na esquina, ao lado da farmácia"), explain = "O mercado fica na esquina, ao lado da farmácia."), Exercise(id = "pt-listen-passeio-bairro-q4", kind = "choice", prompt = "O que o Leo vê no caminho?", options = listOf("Uma praça com crianças", "Uma escola grande", "Um cinema novo", "Um mercado enorme"), answers = listOf("Uma praça com crianças"), explain = "No caminho ele vê uma praça com crianças e um ponto de ônibus."), Exercise(id = "pt-listen-passeio-bairro-q5", kind = "written", prompt = "Como é o mercado?", options = listOf(), answers = listOf("é pequeno", "e pequeno", "pequeno", "pequeno mas tem de tudo"), explain = "O mercado é pequeno, mas tem de tudo."), Exercise(id = "pt-listen-passeio-bairro-q6", kind = "written", prompt = "Em quanto tempo o Leo chega em casa?", options = listOf(), answers = listOf("em cinco minutos", "cinco minutos", "5 minutos"), explain = "Em cinco minutos ele está em casa com as compras.")), skills = listOf("listening:gist", "function:ask-for-directions", "vocab:town")) }

object ListenData178 { val text = ListeningText(id = "pt-listen-ligacao-avo", languageID = "pt", title = "Uma ligação para a avó", level = "A1", topic = "família", unitID = "pt-foundations-u12", text = "Hoje é domingo e a Ana liga para a avó. A avó atende: « Alô ? ». A Ana pergunta: « Está tudo bem ? ». A avó responde: « Está, sim. Moro sozinha, mas nunca fico triste. Às vezes os primos vêm almoçar ». A avó conta a rotina: acorda às seis, caminha no parque e sempre almoça às doze. A Ana diz: « Que bom ! Eu ligo mais tarde para o meu tio ». A avó sorri: « Beijo, minha neta ».", questions = listOf(Exercise(id = "pt-listen-ligacao-avo-q1", kind = "choice", prompt = "Quem liga para quem?", options = listOf("A Ana liga para a avó", "A avó liga para a Ana", "O tio liga para a Ana", "A Ana liga para o tio"), answers = listOf("A Ana liga para a avó"), explain = "Hoje é domingo e a Ana liga para a avó."), Exercise(id = "pt-listen-ligacao-avo-q2", kind = "choice", prompt = "Com quem a avó mora?", options = listOf("Sozinha", "Com a neta", "Com o tio", "Com os primos"), answers = listOf("Sozinha"), explain = "Moro sozinha, mas nunca fico triste."), Exercise(id = "pt-listen-ligacao-avo-q3", kind = "choice", prompt = "O que a avó nunca faz?", options = listOf("Fica triste", "Caminha no parque", "Almoça às doze", "Acorda às seis"), answers = listOf("Fica triste"), explain = "Moro sozinha, mas nunca fico triste."), Exercise(id = "pt-listen-ligacao-avo-q4", kind = "choice", prompt = "O que a avó faz às seis?", options = listOf("Acorda", "Almoça", "Liga", "Vem"), answers = listOf("Acorda"), explain = "Acorda às seis, caminha no parque e sempre almoça às doze."), Exercise(id = "pt-listen-ligacao-avo-q5", kind = "choice", prompt = "Quem vem almoçar às vezes?", options = listOf("Os primos", "Os pais", "As amigas", "Os vizinhos"), answers = listOf("Os primos"), explain = "Às vezes os primos vêm almoçar."), Exercise(id = "pt-listen-ligacao-avo-q6", kind = "written", prompt = "Para quem a Ana liga mais tarde?", options = listOf(), answers = listOf("para o meu tio", "para o tio", "o tio"), explain = "Eu ligo mais tarde para o meu tio.")), skills = listOf("listening:gist", "listening:detail", "vocab:family", "vocab:daily-routine", "grammar:frequency-adverbs")) }

object ListenData179 { val text = ListeningText(id = "pt-listen-fim-de-semana-chuvoso", languageID = "pt", title = "Fim de semana chuvoso", level = "A1", topic = "clima", unitID = "pt-foundations-u13", text = "É sábado de manhã e chove. O Leo olha pela janela: « Que tempo faz ? ». A Bia responde: « Está frio e chove muito ». O plano é caminhar no parque, mas com chuva não dá. Então eles ficam em casa: preparam um chocolate quente e assistem a um filme. O Leo diz: « Eu gosto de chuva, mas só às vezes ». Chove sempre na primavera, diz a Bia, e no verão faz calor.", questions = listOf(Exercise(id = "pt-listen-fim-de-semana-chuvoso-q1", kind = "choice", prompt = "Como está o tempo no sábado?", options = listOf("Chove e está frio", "Faz calor", "Neva", "Está ensolarado"), answers = listOf("Chove e está frio"), explain = "Está frio e chove muito."), Exercise(id = "pt-listen-fim-de-semana-chuvoso-q2", kind = "choice", prompt = "Qual é o plano do grupo?", options = listOf("Caminhar no parque", "Nadar na praia", "Ir à feira", "Dormir a manhã toda"), answers = listOf("Caminhar no parque"), explain = "O plano é caminhar no parque, mas com chuva não dá."), Exercise(id = "pt-listen-fim-de-semana-chuvoso-q3", kind = "choice", prompt = "O que eles fazem em casa?", options = listOf("Tomam chocolate quente e veem um filme", "Jogam futebol", "Ligam para a avó", "Preparam o almoço"), answers = listOf("Tomam chocolate quente e veem um filme"), explain = "Preparam um chocolate quente e assistem a um filme."), Exercise(id = "pt-listen-fim-de-semana-chuvoso-q4", kind = "choice", prompt = "Quando o Leo gosta de chuva?", options = listOf("Só às vezes", "Sempre", "Nunca", "Todas as manhãs"), answers = listOf("Só às vezes"), explain = "Eu gosto de chuva, mas só às vezes."), Exercise(id = "pt-listen-fim-de-semana-chuvoso-q5", kind = "written", prompt = "Quando chove sempre?", options = listOf(), answers = listOf("na primavera", "primavera"), explain = "Chove sempre na primavera."), Exercise(id = "pt-listen-fim-de-semana-chuvoso-q6", kind = "written", prompt = "Como está o tempo no verão?", options = listOf(), answers = listOf("faz calor", "no verão faz calor", "no verao faz calor"), explain = "No verão faz calor.")), skills = listOf("listening:gist", "listening:detail", "vocab:weather", "function:talk-about-weather", "grammar:frequency-adverbs")) }

object ListenData180 { val text = ListeningText(id = "pt-listen-metro-perdido", languageID = "pt", title = "O metrô perdido", level = "A1", topic = "transporte", unitID = "pt-foundations-u14", text = "Hoje o Leo vai ao centro de metrô. Ele pega o metrô na estação São João. O trem sai às oito e chega às oito e vinte. O Leo quer ir ao museu, mas sai na estação errada. Ele pergunta a uma funcionária: « A que horas vem o próximo trem ? ». A funcionária responde: « O trem sai às oito e meia ». O Leo pega o trem certo e chega ao museu às nove. « Eu sempre viajo de metrô », diz ele.", questions = listOf(Exercise(id = "pt-listen-metro-perdido-q1", kind = "choice", prompt = "Como o Leo vai ao centro ?", options = listOf("De metrô", "De ônibus", "A pé", "De carro"), answers = listOf("De metrô"), explain = "Hoje o Leo vai ao centro de metrô."), Exercise(id = "pt-listen-metro-perdido-q2", kind = "choice", prompt = "A que horas chega o trem da manhã ?", options = listOf("Às oito e vinte", "Às oito", "Às oito e meia", "Às nove"), answers = listOf("Às oito e vinte"), explain = "O trem sai às oito e chega às oito e vinte."), Exercise(id = "pt-listen-metro-perdido-q3", kind = "choice", prompt = "Qual é o problema do Leo ?", options = listOf("Ele sai na estação errada", "Ele não encontra a estação", "Ele perde a passagem", "Ele esquece o museu"), answers = listOf("Ele sai na estação errada"), explain = "O Leo quer ir ao museu, mas sai na estação errada."), Exercise(id = "pt-listen-metro-perdido-q4", kind = "choice", prompt = "A que horas sai o próximo trem ?", options = listOf("Às oito e meia", "Às oito", "Às nove e vinte", "Às nove"), answers = listOf("Às oito e meia"), explain = "« O trem sai às oito e meia », diz a funcionária."), Exercise(id = "pt-listen-metro-perdido-q5", kind = "choice", prompt = "A que horas o Leo chega ao museu ?", options = listOf("Às nove", "Às oito e meia", "Às nove e vinte", "Às dez"), answers = listOf("Às nove"), explain = "O Leo pega o trem certo e chega ao museu às nove."), Exercise(id = "pt-listen-metro-perdido-q6", kind = "written", prompt = "O que o Leo sempre faz ?", options = listOf(), answers = listOf("viaja de metrô", "viaja de metro", "viajo de metro"), explain = "« Eu sempre viajo de metrô », diz o Leo.")), skills = listOf("listening:gist", "listening:detail", "vocab:transport", "function:tell-time")) }

object ListenData181 { val text = ListeningText(id = "pt-listen-farmacia-sabado", languageID = "pt", title = "Sábado na farmácia", level = "A1", topic = "saúde", unitID = "pt-foundations-u15", text = "É sábado de manhã e a Ana não se sente bem. Ela está com dor de cabeça e está com febre. O Leo diz: « Vamos à farmácia ». Na farmácia, a Ana fala com o farmacêutico: « Estou com dor de cabeça ». O farmacêutico dá um remédio: « Você toma um comprimido de manhã e um à noite ». Custa dez reais. A Ana nunca toma remédio, mas hoje é preciso. Ela toma o remédio e dorme um pouco. À tarde, está melhor.", questions = listOf(Exercise(id = "pt-listen-farmacia-sabado-q1", kind = "choice", prompt = "Como está a Ana no sábado ?", options = listOf("Não se sente bem", "Muito feliz", "Com fome", "Muito cansada"), answers = listOf("Não se sente bem"), explain = "É sábado de manhã e a Ana não se sente bem."), Exercise(id = "pt-listen-farmacia-sabado-q2", kind = "choice", prompt = "Quais são os sintomas da Ana ?", options = listOf("Dor de cabeça e febre", "Tosse e febre", "Dor de cabeça e tosse", "Febre e dor de barriga"), answers = listOf("Dor de cabeça e febre"), explain = "Ela está com dor de cabeça e está com febre."), Exercise(id = "pt-listen-farmacia-sabado-q3", kind = "choice", prompt = "Quando a Ana toma o comprimido ?", options = listOf("De manhã e à noite", "Só de manhã", "Só à noite", "Só à tarde"), answers = listOf("De manhã e à noite"), explain = "« Você toma um comprimido de manhã e um à noite »."), Exercise(id = "pt-listen-farmacia-sabado-q4", kind = "choice", prompt = "Quanto custa o remédio ?", options = listOf("Dez reais", "Doze reais", "Três reais", "Treze reais"), answers = listOf("Dez reais"), explain = "Custa dez reais."), Exercise(id = "pt-listen-farmacia-sabado-q5", kind = "written", prompt = "O que a Ana nunca faz ?", options = listOf(), answers = listOf("toma remédio", "toma remedio", "nunca toma remedio"), explain = "A Ana nunca toma remédio, mas hoje é preciso."), Exercise(id = "pt-listen-farmacia-sabado-q6", kind = "written", prompt = "Como está a Ana à tarde ?", options = listOf(), answers = listOf("melhor", "está melhor", "esta melhor"), explain = "À tarde, está melhor.")), skills = listOf("listening:gist", "listening:detail", "vocab:health", "grammar:frequency-adverbs")) }

object ListenData182 { val text = ListeningText(id = "pt-listen-jantar-surpresa", languageID = "pt", title = "O jantar de surpresa", level = "A1", topic = "restaurante", unitID = "pt-foundations-u16", text = "É sexta-feira. A Ana e o Leo esperam a Bia num restaurante. É um jantar de surpresa pelo aniversário dela. A Ana pede uma pizza margherita e um suco de laranja. O Leo quer a lasanha e uma água sem gelo. « Mais alguma coisa ? », pergunta o garçom. « Só o pudim, por favor », diz a Ana. A Bia chega às oito e vê as velas na sobremesa. Ela chora de alegria. No fim, o Leo pede a conta e cada um deixa a gorjeta.", questions = listOf(Exercise(id = "pt-listen-jantar-surpresa-q1", kind = "choice", prompt = "O que a Ana pede ?", options = listOf("Uma pizza e um suco", "Uma lasanha e uma água", "Um pudim", "Uma água com gelo"), answers = listOf("Uma pizza e um suco"), explain = "A Ana pede uma pizza margherita e um suco de laranja."), Exercise(id = "pt-listen-jantar-surpresa-q2", kind = "choice", prompt = "O que o Leo quer ?", options = listOf("A lasanha", "A pizza", "O pudim", "O suco"), answers = listOf("A lasanha"), explain = "O Leo quer a lasanha e uma água sem gelo."), Exercise(id = "pt-listen-jantar-surpresa-q3", kind = "written", prompt = "A que horas a Bia chega ?", options = listOf(), answers = listOf("as oito", "às oito", "oito horas"), explain = "A Bia chega às oito."), Exercise(id = "pt-listen-jantar-surpresa-q4", kind = "choice", prompt = "O que a Bia vê na sobremesa ?", options = listOf("As velas", "A conta", "O cardápio", "A gorjeta"), answers = listOf("As velas"), explain = "Vê as velas na sobremesa e chora de alegria."), Exercise(id = "pt-listen-jantar-surpresa-q5", kind = "written", prompt = "O que o Leo pede no fim ?", options = listOf(), answers = listOf("a conta", "pede a conta", "a conta por favor"), explain = "No fim, o Leo pede a conta."), Exercise(id = "pt-listen-jantar-surpresa-q6", kind = "choice", prompt = "Como é o jantar ?", options = listOf("De surpresa", "De trabalho", "Com o garçom", "Em casa"), answers = listOf("De surpresa"), explain = "É um jantar de surpresa pelo aniversário da Bia.")), skills = listOf("listening:gist", "listening:detail", "vocab:food", "function:order-food")) }

object ListenData183 { val text = ListeningText(id = "pt-listen-plano-aniversario", languageID = "pt", title = "O plano de aniversário", level = "A2", topic = "planos", unitID = "pt-foundations-u17", text = "A Duda liga para o Téo para combinar a festa de aniversário da Bia, que vai ser no sábado. « Vamos fazer uma surpresa ? », pergunta a Duda. O Téo aceita, mas não pode de manhã, porque vai almoçar com a avó. Então vão se encontrar às três na casa da Duda: ela vai fazer o bolo, e o Téo vai comprar as bebidas e as velas. A Lu vai levar o presente e vai embrulhar com papel colorido. A Bia não pode saber de nada. « Que horas ela chega ? », pergunta o Téo. « Oito, mas vamos estar prontos às sete », responde a Duda.", questions = listOf(Exercise(id = "pt-listen-plano-aniversario-q1", kind = "choice", prompt = "Para quem é a festa ?", options = listOf("Para a Bia", "Para a Duda", "Para a avó", "Para a Lu"), answers = listOf("Para a Bia"), explain = "A festa de aniversário da Bia."), Exercise(id = "pt-listen-plano-aniversario-q2", kind = "choice", prompt = "Por que o Téo não pode de manhã ?", options = listOf("Vai almoçar com a avó", "Vai viajar", "Vai trabalhar", "Vai ao médico"), answers = listOf("Vai almoçar com a avó"), explain = "Não pode de manhã, porque vai almoçar com a avó."), Exercise(id = "pt-listen-plano-aniversario-q3", kind = "written", prompt = "A que horas vão se encontrar ?", options = listOf(), answers = listOf("as tres", "às três", "tres horas"), explain = "Vão se encontrar às três na casa da Duda."), Exercise(id = "pt-listen-plano-aniversario-q4", kind = "written", prompt = "O que o Téo vai comprar ?", options = listOf(), answers = listOf("as bebidas e as velas", "bebidas e velas"), explain = "O Téo vai comprar as bebidas e as velas."), Exercise(id = "pt-listen-plano-aniversario-q5", kind = "choice", prompt = "O que a Lu vai fazer com o presente ?", options = listOf("Vai embrulhar com papel colorido", "Vai comprar outro", "Vai esconder na casa dela", "Vai entregar antes"), answers = listOf("Vai embrulhar com papel colorido"), explain = "A Lu vai embrulhar o presente com papel colorido."), Exercise(id = "pt-listen-plano-aniversario-q6", kind = "written", prompt = "A que horas a Bia chega ?", options = listOf(), answers = listOf("as oito", "às oito", "oito"), explain = "« Oito », responde a Duda.")), skills = listOf("listening:gist", "listening:detail", "grammar:going-to"), exposureSkills = listOf("vocab:social-expressions")) }

object ListenData184 { val text = ListeningText(id = "pt-listen-episodio-verao", languageID = "pt", title = "O episódio do verão", level = "B1", topic = "histórias", unitID = "pt-foundations-u18", text = "Deixa eu contar o episódio do verão. Fui passar uma semana na casa da minha tia em Paraty. No segundo dia, resolvi conhecer as praias de barco, mas perdi o último horário. Fiquei na praça, sem plano. De repente, um senhor que vendia coco me chamou: ele tinha um barquinho e ofereceu um passeio. Desconfiei no começo, mas acabei que aceitei. E não é que foi o melhor passeio da viagem ? Ele me levou a uma praia deserta, só com tartarugas e vento. Quando voltei, contei tudo para a minha tia. « Não me diga ! », ela gritou. « Sozinha com um estranho ? Aí eu passei mal ». No fim, demos risada até chorar.", questions = listOf(Exercise(id = "pt-listen-episodio-verao-q1", kind = "choice", prompt = "O que aconteceu no segundo dia ?", options = listOf("Perdeu o último horário do barco", "Choveu o dia todo", "A tia ficou doente", "O barco quebrou"), answers = listOf("Perdeu o último horário do barco"), explain = "Resolvi conhecer as praias de barco, mas perdi o último horário."), Exercise(id = "pt-listen-episodio-verao-q2", kind = "choice", prompt = "Quem ofereceu o passeio ?", options = listOf("Um senhor que vendia coco", "A tia dela", "Um guia da praia", "Ninguém"), answers = listOf("Um senhor que vendia coco"), explain = "Um senhor que vendia coco tinha um barquinho e ofereceu um passeio."), Exercise(id = "pt-listen-episodio-verao-q3", kind = "written", prompt = "Como a narradora reagiu no começo ?", options = listOf(), answers = listOf("ficou desconfiada", "desconfiou", "desconfiada"), explain = "Desconfiei no começo, mas acabei que aceitei."), Exercise(id = "pt-listen-episodio-verao-q4", kind = "written", prompt = "O que tinha na praia deserta ?", options = listOf(), answers = listOf("tartarugas e vento", "tartarugas"), explain = "Uma praia deserta, só com tartarugas e vento."), Exercise(id = "pt-listen-episodio-verao-q5", kind = "choice", prompt = "Como a tia reage à história ?", options = listOf("Se assusta e não acredita", "Diz que já sabia", "Quer ir no barquinho", "Ri na hora"), answers = listOf("Se assusta e não acredita"), explain = "« Não me diga ! Sozinha com um estranho ? Aí eu passei mal »."), Exercise(id = "pt-listen-episodio-verao-q6", kind = "choice", prompt = "Como a história termina ?", options = listOf("Rindo até chorar", "Brigando com a tia", "Voltando ao barco", "Ficando na praça"), answers = listOf("Rindo até chorar"), explain = "No fim, demos risada até chorar.")), skills = listOf("listening:inference", "listening:detail", "grammar:past-simple-irregular", "grammar:connectors")) }

object ListenData185 { val text = ListeningText(id = "pt-listen-debate-jeito", languageID = "pt", title = "Debate: discordar com jeito", level = "C1", topic = "debate", unitID = "pt-foundations-u9", text = "No programa de hoje, Helena e Caio debatem a proposta de proibir celulares nas escolas. Helena abre: « Eu vejo com simpatia a medida; a distração custa caro ». Caio não vai por aí: « Entendo o seu ponto, mas proibir não ensina a usar ». Helena concede um terreno: « Até certo ponto; por outro lado, ninguém aprende algoritmo em sala de aula ». Caio pesa: « Por um lado, os dados te dão razão; por outro, proibição vira má fama do colégio ». No fim, não há vencedor: « Concordo em discordar », resume Helena. O mediador agradece e adianta a pauta da próxima semana: tela ou caderno, o que forma melhor leitor ?", questions = listOf(Exercise(id = "pt-listen-debate-jeito-q1", kind = "choice", prompt = "Qual é a proposta em debate ?", options = listOf("Proibir celulares na escola", "Proibir provas", "Aumentar as férias", "Mudar o uniforme"), answers = listOf("Proibir celulares na escola"), explain = "A proposta em debate: proibir celulares nas escolas."), Exercise(id = "pt-listen-debate-jeito-q2", kind = "choice", prompt = "Como Helena abre o debate ?", options = listOf("Vê com simpatia a medida", "Rejeita a proposta", "Muda de assunto", "Pede dados"), answers = listOf("Vê com simpatia a medida"), explain = "« Eu vejo com simpatia a medida »."), Exercise(id = "pt-listen-debate-jeito-q3", kind = "written", prompt = "Qual é o contra-argumento do Caio ?", options = listOf(), answers = listOf("proibir não ensina a usar", "proibir nao ensina a usar", "proibição não ensina"), explain = "« Entendo o seu ponto, mas proibir não ensina a usar »."), Exercise(id = "pt-listen-debate-jeito-q4", kind = "choice", prompt = "O que Helena concede ao Caio ?", options = listOf("Até certo ponto ele tem razão", "Que a distração não existe", "Que celulares ensinam tudo", "Que a proposta é perfeita"), answers = listOf("Até certo ponto ele tem razão"), explain = "« Até certo ponto; por outro lado… »."), Exercise(id = "pt-listen-debate-jeito-q5", kind = "written", prompt = "Como o debate termina ?", options = listOf(), answers = listOf("concordo em discordar", "sem vencedor", "não há vencedor", "nao ha vencedor"), explain = "« Concordo em discordar »: não há vencedor."), Exercise(id = "pt-listen-debate-jeito-q6", kind = "choice", prompt = "Qual é a pauta da próxima semana ?", options = listOf("Tela ou caderno", "Salário dos professores", "A reforma da escola", "Notas e exames"), answers = listOf("Tela ou caderno"), explain = "O mediador adianta: tela ou caderno, o que forma melhor leitor ?")), skills = listOf("listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion")) }

object ListenData186 { val text = ListeningText(id = "pt-listen-roda-sexta", languageID = "pt", title = "A roda de sexta", level = "A1", topic = "visita", unitID = "pt-foundations-u19", text = "É sexta à noite e tem uma roda de conversa na casa da Bia. A Ana chega com uma lembrancinha: « Trago um bolo ». A Bia abre a porta: « Entre, pode deixar o bolo na mesa ». « Posso tirar os sapatos ? — Pode sim », trocam na porta. Na sala, a Bia oferece café: « Aceita um café ? — Aceito, obrigada ! ». No fim, a Ana agradece: « Obrigada por tudo ». « Volte sempre ! », responde a Bia.", questions = listOf(Exercise(id = "pt-listen-roda-sexta-q1", kind = "choice", prompt = "Onde é a roda de conversa ?", options = listOf("Na casa da Bia", "No trabalho", "Num café", "Na rua"), answers = listOf("Na casa da Bia"), explain = "É sexta à noite e tem uma roda de conversa na casa da Bia."), Exercise(id = "pt-listen-roda-sexta-q2", kind = "choice", prompt = "O que a Ana traz ?", options = listOf("Um bolo", "Um café", "Um livro", "Doces"), answers = listOf("Um bolo"), explain = "« Trago um bolo », diz a Ana ao chegar."), Exercise(id = "pt-listen-roda-sexta-q3", kind = "written", prompt = "O que a Ana pede para tirar ?", options = listOf(), answers = listOf("os sapatos", "sapatos"), explain = "« Posso tirar os sapatos ? — Pode sim »."), Exercise(id = "pt-listen-roda-sexta-q4", kind = "choice", prompt = "A Bia deixa tirar os sapatos ?", options = listOf("Pode sim", "Não pode", "Talvez", "De jeito nenhum"), answers = listOf("Pode sim"), explain = "A resposta na porta é « Pode sim »."), Exercise(id = "pt-listen-roda-sexta-q5", kind = "written", prompt = "O que a Bia oferece na sala ?", options = listOf(), answers = listOf("um café", "um cafe", "café", "cafe"), explain = "Na sala, a Bia oferece café: « Aceita um café ? »."), Exercise(id = "pt-listen-roda-sexta-q6", kind = "choice", prompt = "Como a Bia se despede ?", options = listOf("Volte sempre !", "Até nunca !", "Feche a porta !", "Sem café !"), answers = listOf("Volte sempre !"), explain = "A despedida da Bia é « Volte sempre ! ».")), skills = listOf("listening:gist", "listening:detail", "vocab:social-expressions", "grammar:can")) }

object ListenData187 { val text = ListeningText(id = "pt-listen-reclamacao-nota", languageID = "pt", title = "A reclamação na nota", level = "A2", topic = "problemas", unitID = "pt-foundations-u20", text = "— Boa tarde ! Em que posso ajudar ? — Boa tarde. Comprei um liquidificador aqui na semana passada, mas ele está com defeito: liga e para na hora. — Sinto muito. Você trouxe a nota fiscal ? — Trouxe, está aqui. — O senhor quer trocar por outro igual ou prefere o dinheiro de volta ? — Prefiro outro igual, o vermelho. — Claro: a compra é recente, ainda tem garantia. — Preciso fazer mais alguma coisa ? — Só assinar aqui na nota. Pronto, está trocado. Obrigado pela paciência !", questions = listOf(Exercise(id = "pt-listen-reclamacao-nota-q1", kind = "choice", prompt = "O que o cliente comprou ?", options = listOf("Um liquidificador", "Um fone", "Uma torneira", "Um ventilador"), answers = listOf("Um liquidificador"), explain = "Comprei um liquidificador aqui na semana passada."), Exercise(id = "pt-listen-reclamacao-nota-q2", kind = "written", prompt = "Quando ele comprou o produto ?", options = listOf(), answers = listOf("na semana passada", "semana passada"), explain = "Comprei um liquidificador aqui na semana passada."), Exercise(id = "pt-listen-reclamacao-nota-q3", kind = "choice", prompt = "Qual é o defeito ?", options = listOf("Liga e para na hora", "Não liga nada", "Faz muito barulho", "Vaza água"), answers = listOf("Liga e para na hora"), explain = "Ele está com defeito: liga e para na hora."), Exercise(id = "pt-listen-reclamacao-nota-q4", kind = "written", prompt = "O que o cliente trouxe para provar a compra ?", options = listOf(), answers = listOf("a nota fiscal", "a nota", "nota fiscal"), explain = "Você trouxe a nota fiscal ? — Trouxe, está aqui."), Exercise(id = "pt-listen-reclamacao-nota-q5", kind = "choice", prompt = "O que o cliente prefere como solução ?", options = listOf("Trocar por outro igual", "O dinheiro de volta", "Consertar em casa", "Esperar o técnico"), answers = listOf("Trocar por outro igual"), explain = "Prefiro outro igual, o vermelho."), Exercise(id = "pt-listen-reclamacao-nota-q6", kind = "choice", prompt = "O que o cliente faz no fim ?", options = listOf("Assina a nota", "Volta na sexta", "Chama o técnico", "Pede desconto"), answers = listOf("Assina a nota"), explain = "Só assinar aqui na nota. Pronto, está trocado.")), skills = listOf("listening:gist", "listening:detail", "function:solve-problems", "vocab:social-expressions")) }

object ListenData188 { val text = ListeningText(id = "pt-listen-entrevista-ensaio", languageID = "pt", title = "O ensaio da entrevista", level = "B1", topic = "trabalho", unitID = "pt-foundations-u21", text = "— Ana, vamos ensaiar a entrevista ? Imagina que eu sou o recrutador. — Fechado. — Conte um pouco da sua experiência. — Trabalho com atendimento há cinco anos e já coordenei uma equipe pequena. — E qual é o seu ponto forte ? — Sou organizada e aprendo rápido. Falar em público ainda é difícil, mas estou fazendo um curso. — Por que você quer mudar de empresa ? — Quero novos desafios e eu gostaria de trabalhar com projetos maiores. — E a meta para este ano ? — Até dezembro, quero assumir uma liderança e melhorar os indicadores do time. — Muito bom. Só um conselho: deixe o tema do salário para o final.", questions = listOf(Exercise(id = "pt-listen-entrevista-ensaio-q1", kind = "choice", prompt = "Qual é o papel do Leo no ensaio ?", options = listOf("O recrutador imaginário", "O gerente da loja", "Um colega de trabalho", "O professor de inglês"), answers = listOf("O recrutador imaginário"), explain = "Imagina que eu sou o recrutador."), Exercise(id = "pt-listen-entrevista-ensaio-q2", kind = "written", prompt = "Há quanto tempo a Ana trabalha com atendimento ?", options = listOf(), answers = listOf("cinco anos", "há cinco anos", "ha cinco anos", "5 anos"), explain = "Trabalho com atendimento há cinco anos."), Exercise(id = "pt-listen-entrevista-ensaio-q3", kind = "choice", prompt = "Qual é o ponto forte da Ana ?", options = listOf("É organizada", "Fala bem em público", "Gerencia equipes grandes", "Negocia salários"), answers = listOf("É organizada"), explain = "Sou organizada e aprendo rápido."), Exercise(id = "pt-listen-entrevista-ensaio-q4", kind = "choice", prompt = "Por que a Ana quer mudar de empresa ?", options = listOf("Quer novos desafios", "O salário é baixo", "Não gosta do time", "Vai morar fora"), answers = listOf("Quer novos desafios"), explain = "Quero novos desafios e eu gostaria de trabalhar com projetos maiores."), Exercise(id = "pt-listen-entrevista-ensaio-q5", kind = "written", prompt = "Qual é a meta da Ana até dezembro ?", options = listOf(), answers = listOf("assumir uma liderança", "assumir uma lideranca", "uma liderança", "uma lideranca"), explain = "Até dezembro, quero assumir uma liderança."), Exercise(id = "pt-listen-entrevista-ensaio-q6", kind = "choice", prompt = "O que o conselho final do Leo sugere ?", options = listOf("Deixar o salário para o final", "Chegar cedo à entrevista", "Enviar o currículo antes", "Estudar inglês mais"), answers = listOf("Deixar o salário para o final"), explain = "Só um conselho: deixe o tema do salário para o final.")), skills = listOf("listening:inference", "listening:detail", "vocab:work", "function:talk-about-work")) }

object ListenData189 { val text = ListeningText(id = "pt-listen-tom-podcast", languageID = "pt", title = "Podcast: o tom exato", level = "C1", topic = "tom", unitID = "pt-foundations-u9", text = "« Fala, gente ! No podcast de hoje: por que o tom importa mais do que a palavra ? Marina, você revisa texto — abre o jogo. — Abro, sim: ninguém vê, mas todo mundo sente as colocações trocadas. « Tomar uma decisão » flui; « fazer uma decisão » range. — E no e-mail da diretoria ? — Lá cada conector pesa: « no entanto » eleva o registro; « mas » abaixa na hora. Eu, pessoalmente, pondero os prós e os contras antes de escolher o verbo. — Eu já mandei um « te dou um retorno » para a diretoria. — E aí, que sensação ficou ? — Aquela, sabe ? Saudade do tom exato, por assim dizer. — Fecho com chave de ouro: quem domina as colocações domina a conversa. Até a próxima !", questions = listOf(Exercise(id = "pt-listen-tom-podcast-q1", kind = "choice", prompt = "Qual é o tema do episódio ?", options = listOf("O tom e as colocações", "A gramática do subjuntivo", "Como escrever e-mails longos", "O sotaque no trabalho"), answers = listOf("O tom e as colocações"), explain = "No podcast de hoje: por que o tom importa mais do que a palavra ?"), Exercise(id = "pt-listen-tom-podcast-q2", kind = "choice", prompt = "O que a Marina diz de « fazer uma decisão » ?", options = listOf("Não flui; o certo é tomar", "É a forma formal", "É uso regional aceito", "É sinônimo exato de tomar"), answers = listOf("Não flui; o certo é tomar"), explain = "« Tomar uma decisão » flui; « fazer uma decisão » range."), Exercise(id = "pt-listen-tom-podcast-q3", kind = "written", prompt = "Que colocação a Marina usa antes de escolher o verbo ?", options = listOf(), answers = listOf("pondero os prós e os contras", "pondero os pros e os contras", "os prós e os contras", "os pros e os contras"), explain = "Eu, pessoalmente, pondero os prós e os contras antes de escolher o verbo."), Exercise(id = "pt-listen-tom-podcast-q4", kind = "choice", prompt = "O que « abaixa na hora » sugere sobre o « mas » ?", options = listOf("Reduz o registro da frase", "Nega a frase anterior", "Acelera a leitura", "Soa antiquado"), answers = listOf("Reduz o registro da frase"), explain = "« No entanto » eleva o registro; « mas » abaixa na hora: o contraste coloquial."), Exercise(id = "pt-listen-tom-podcast-q5", kind = "choice", prompt = "O que a brincadeira com a « saudade do tom exato » revela ?", options = listOf("Arrependimento do recado informal", "Orgulho do recado", "Vontade de demitir", "Alívio com o e-mail"), answers = listOf("Arrependimento do recado informal"), explain = "O « te dou um retorno » ficou informal para a diretoria; a saudade do tom exato mostra arrependimento."), Exercise(id = "pt-listen-tom-podcast-q6", kind = "written", prompt = "Qual fórmula de suavização aparece no episódio ?", options = listOf(), answers = listOf("por assim dizer", "assim dizer"), explain = "« Saudade do tom exato, por assim dizer »: a fórmula suaviza a afirmação.")), skills = listOf("listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion")) }

